-- KaniGani N5 & N4 Indonesian Mnemonics Update Migration
-- Generated automatically
BEGIN;
UPDATE items SET meaning_mnemonic = 'Kosa kata yang hanya terdiri dari satu kanji saja tanpa okurigana (hiragana yang melekat pada kanji) biasanya memiliki arti yang sama persis dengan kanji yang menjadi bahan pembuatannya. Jadi dengan begitu kalian sudah tahu kalau arti vocab ini adalah gunung.', reading_mnemonic = 'Jika kosakatanya hanya berupa kanji tunggal tanpa okurigana (hiragana melekat pada kanji), biasanya yang digunakan adalah pembacaan kun''yomi, yang tidak Anda pelajari saat mempelajari kanji. Untuk mengingat bacaan kata ini kita akan menggunakan mnemonik.

Apa yang kamu lakukan saat mendaki gunung? Anda sedang berburu ubi (やま). Silakan, bayangkan diri Anda melakukan hal itu, mendaki gunung (ini kerja keras!) dan kemudian menggali tanah dengan tangan Anda, lalu menarik ubi yang manis dan lezat itu! Hmm!' WHERE id = 'de960434-b833-48a5-994a-9ddee1751384'; -- 山 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sebuah kosakata terdiri dari satu kanji tanpa okurigana (hiragana yang melekat pada kanji), biasanya maknanya sama dengan kanji asalnya. Nah dari situ kalian tahu kalau kata ini artinya sungai.', reading_mnemonic = 'Anda beruntung - bacaan yang Anda pelajari dengan kanji sama dengan yang harus Anda pelajari untuk kosakata ini!' WHERE id = '4ad2dea3-69b5-4e5e-a33f-89574ec7c46f'; -- 川 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika kosakatanya sendirian seperti ini tanpa okurigana (hiragana yang melekat pada kanji) maka cenderung mencuri makna dari kanji asalnya. Artinya kosakata ini juga berarti sepuluh.', reading_mnemonic = 'Kalau vocabnya sendiri dan terdiri dari satu kanji seperti ini, biasanya menggunakan bacaan kun''yomi untuk kanjinya. Namun, angka merupakan pengecualian dan menggunakan pembacaan on''yomi (yang Anda pelajari saat mempelajari kanji). Artinya kamu sudah tahu bahwa bacaan kata ini adalah じゅう.' WHERE id = '0fe0081f-bd7f-4512-b69f-4770354e4504'; -- 十 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika kosakatanya berupa kanji tunggal dan sendirian seperti ini, biasanya maknanya dicuri dari kanji induknya. Begitu juga dengan kata ini, sehingga arti dari kata ini adalah tiga.', reading_mnemonic = 'Jika kosakatanya sendirian seperti ini tanpa okurigana (hiragana yang melekat pada kanji) biasanya menggunakan bacaan kun''yomi-nya. Namun angka merupakan pengecualian, dan gunakan pembacaan on''yomi. Anda mempelajari bacaan on''yomi saat mempelajari kanji ini, jadi Anda sudah tahu bahwa bacaan untuk vocab ini adalah さん.' WHERE id = 'c6db80e4-2014-4b37-b5b4-faf79a946fd2'; -- 三 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika sebuah kata vocab berbentuk kanji tunggal tanpa okurigana (hiragana yang melekat pada kanji), biasanya kata tersebut memiliki arti yang sama dengan kanji asal kata tersebut. Jika Anda mengetahui arti kanjinya, Anda juga akan mengetahui arti vocabnya. Ini dua!', reading_mnemonic = 'Jika suatu kata vocab berbentuk kanji tunggal tanpa okurigana, biasanya menggunakan bacaan kun''yomi. Angka merupakan pengecualian dalam hal ini. Angka menggunakan bacaan on''yomi, yang telah Anda pelajari dengan mempelajari bacaan kanji! Bagus sekali!' WHERE id = 'f74b93c6-fbe0-4295-a877-70333ccd53bf'; -- 二 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "おはよう" memiliki arti "Selamat Pagi". Kombinasi kanji dalam kata ini melambangkan konsep selamat pagi.', reading_mnemonic = 'Cara membaca kosakata "おはよう" adalah "おはよう".' WHERE id = '9fdf6da2-b9be-4e66-bd36-4843ebc20c46'; -- おはよう (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "ホテル" memiliki arti "Hotel". Kombinasi kanji dalam kata ini melambangkan konsep hotel.', reading_mnemonic = 'Cara membaca kosakata "ホテル" adalah "ホテル".' WHERE id = 'c2544fd7-f233-4238-9adc-cd02411fc495'; -- ホテル (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Perhatikan bahwa kata ini berarti "matahari" dan "siang". Mengapa? karena matahari membutuhkan waktu satu hari untuk berputar dan kembali!', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Berikut ini mnemonik untuk membantu Anda mengingatnya: 

Apa yang kamu rasakan dari matahari? Anda merasakan panasnya (ひ).' WHERE id = '0f9ea419-dde9-4806-aae2-055ec49eb353'; -- 日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Biasanya satu kanji yang menyusun kata seperti ini artinya akan menggunakan bacaan kun''yomi. Namun, angka pada umumnya merupakan pengecualian, yang berarti kata ini menggunakan bacaan on''yomi. Jika Anda mempelajari kanji, Anda pasti sudah mengetahuinya!' WHERE id = '146baf86-5b71-463b-be09-0680d70a0363'; -- 千 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda berada di tengah kumpulan air, kemungkinan besar Anda berada di bawah air.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '24a6f3e1-55ee-4962-acaf-49e4313462f3'; -- 水中 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "リンゴ" memiliki arti "Panggilan itu". Kombinasi kanji dalam kata ini melambangkan konsep panggilan itu.', reading_mnemonic = 'Cara membaca kosakata "リンゴ" adalah "リンゴ".' WHERE id = 'c348042d-8453-44d9-bb38-78867da13680'; -- リンゴ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "コーヒー" memiliki arti "Kopi". Kombinasi kanji dalam kata ini melambangkan konsep kopi.', reading_mnemonic = 'Cara membaca kosakata "コーヒー" adalah "コーヒー".' WHERE id = 'd53d6ec5-9ce3-4f81-a715-0597b480f5a3'; -- コーヒー (vocabulary)
UPDATE items SET meaning_mnemonic = 'Berbaring di tanah adalah sesuatu yang terlihat seperti tanah, angka Satu. Mengapa Dia berbaring? Itu telah ditembak oleh orang nomor dua. Ia tergeletak di sana, mengeluarkan darah dan sekarat. Orang nomor satu tidak akan hidup lama lagi.', reading_mnemonic = 'Bagaimana cara membaca kanji **satu** (一)? Ingat saja bahwa **いち** sangat menyukai satu! Hubungan erat ini akan membantu Anda mengingat bunyi **いち**.' WHERE id = '665c306f-8717-4c2e-83df-545da5b2d509'; -- 一 (kanji)
UPDATE items SET meaning_mnemonic = 'Seseorang yang menjadi teman hanyalah friend!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Semua temanmu adalah remaja yang mengenakan jeans (ゆうじん)! Setiap orang. Jika ada teman Anda yang bukan remaja yang mengenakan jeans, saya khawatir mereka bukan teman Anda.' WHERE id = 'e19ea17a-f2c9-438a-99af-1a3eb636365b'; -- 友人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "こんにちは" memiliki arti "Selamat Siang". Kombinasi kanji dalam kata ini melambangkan konsep selamat siang.', reading_mnemonic = 'Cara membaca kosakata "こんにちは" adalah "こんにちは".' WHERE id = '8272d9e2-6b7e-4be6-88e8-fe2a2d23f1ff'; -- こんにちは (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "これ" memiliki arti "Ini". Kombinasi kanji dalam kata ini melambangkan konsep ini.', reading_mnemonic = 'Cara membaca kosakata "これ" adalah "これ".' WHERE id = 'ebbd83a4-d071-4439-be38-64bdc7d2deed'; -- これ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "する" memiliki arti "Melakukan". Kombinasi kanji dalam kata ini melambangkan konsep melakukan.', reading_mnemonic = 'Cara membaca kosakata "する" adalah "する".' WHERE id = '640da099-0280-4ca0-b17a-435faa85256b'; -- する (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bila Anda memiliki dua sepuluh ribu, Anda memiliki dua puluh ribu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '0db0816b-11c0-4f93-a34c-b995ab317cb3'; -- 二万 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "いつ" memiliki arti "Kapan". Kombinasi kanji dalam kata ini melambangkan konsep kapan.', reading_mnemonic = 'Cara membaca kosakata "いつ" adalah "いつ".' WHERE id = '07af8351-c64d-4f1b-9ba3-367f198cdb59'; -- いつ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji ini memiliki bentuk dan arti yang sama dengan kanji radikal, sehingga sangat mudah untuk diingat.', reading_mnemonic = 'Untuk mengingat cara baca kanji **seribu** (千), bayangkan Anda sedang membawa **Senter/Semen** untuk ditaruh di atas seribu. Kejadian unik ini mengingatkan Anda pada bunyi **せん**!' WHERE id = '4fa5acfd-8111-4134-958a-65dfebe017b4'; -- 千 (kanji)
UPDATE items SET meaning_mnemonic = 'Seperti apa sikap radikal ini? Hmm, tidak banyak. Bagaimana jika Anda membalikkannya? Sekarang apakah terlihat seperti angka 7 dengan garis melewatinya? Cukup dekat untuk membantu Anda mengingat bahwa radikal ini adalah tujuh, bukan? Ingat saja, ketika Anda melihat radikal ini, balikkan dan lihat seperti apa angkanya. Jika Anda bisa melakukan itu, Anda bisa mengingat maknanya!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1c9a03ec-d956-492a-8d50-c9b8840a64d7'; -- 七 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal untuk enter terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini artinya masuk juga.', reading_mnemonic = 'Ketika Anda sedang melihat **masuk** (入), tiba-tiba muncul sesosok **Nila/Nikel** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **にゅう**.' WHERE id = '51a7c0a5-9f4e-4c5f-8326-56cbfb30627b'; -- 入 (kanji)
UPDATE items SET meaning_mnemonic = 'hari kesembilan atau hari kesembilan. Tidak peduli bagaimana Anda melihatnya, kata ini sangat masuk akal.', reading_mnemonic = 'Kata-kata yang menghitung hari menggunakan bacaan yang luar biasa. Meskipun ini adalah kata jukugo, namun menggunakan pembacaan kun''yomi untuk kedua kanjinya. Anda mempelajari bacaan ini untuk 九 ketika Anda mempelajari 九つ, jadi Anda seharusnya bisa membaca yang ini juga!' WHERE id = '4da46b9d-86fa-4566-a7b0-8d533c1f893c'; -- 九日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti orang lebar yang terdiri dari dua huruf X yang bertumpuk. Wanita umumnya memiliki dua kromosom XX, dan dulu mereka dipuji karena pinggul mereka yang lebar dan dapat melahirkan anak. Kita mungkin tidak lagi menganggap perempuan seperti itu lagi, tapi dulu ketika Jepang masih ada, hal ini membuat mereka berpikir tentang perempuan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a821f6e4-b0c2-49a1-a822-a825945bbe61'; -- 女 (radical)
UPDATE items SET meaning_mnemonic = 'Jika Anda melihat radikal ini dengan cara yang benar, Anda akan melihat bahwa ini terlihat seperti huruf "n" dan "i" ("i" berasal dari guratan kecil di sisi kanan). Huruf "n" dan "i" mulai dieja apa? Wah, kata sembilan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'f6a036bd-ee27-4e90-bf25-0f5a6f84ab02'; -- 九 (radical)
UPDATE items SET meaning_mnemonic = 'sirip yang jatuh ke pedang saya diiris menjadi dua bagian.', reading_mnemonic = 'Bagaimana cara membaca kanji **bagian** (分)? Ingat saja bahwa **Bunga/Buku** sangat menyukai bagian! Hubungan erat ini akan membantu Anda mengingat bunyi **ぶん**.' WHERE id = 'f60091c7-6d76-4ccb-9076-d37cbdbc9d78'; -- 分 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal besar dan kanji besar sama persis!', reading_mnemonic = 'Bagaimana cara membaca kanji **besar** (大)? Ingat saja bahwa **Dadu/Dahi** sangat menyukai besar! Hubungan erat ini akan membantu Anda mengingat bunyi **だい**.' WHERE id = '8135f833-57bc-4db4-8fb9-eddf11684d3e'; -- 大 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini:

Lihatlah bulan yang besar dan terang itu. Anda harus membukanya dan mengambil apa yang ada di dalamnya. Untuk melakukan itu, Anda diharuskan memiliki dua kunci (つき), dan keduanya harus diputar secara bersamaan. Bayangkan Anda dan seorang teman memutar kunci di sisi berlawanan bulan untuk membuka bagian tengahnya.' WHERE id = 'fca79a83-ec58-447b-b0bb-a2e92a1a039c'; -- 月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sudah tampak seperti sungai. Lihat tepian sungai di samping dan aliran sungai di tengah? Bahkan ada sedikit belokan di sungai juga. Jadi ketika Anda melihat radikal ini, Anda harus berpikir "sungai".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '510f6fdf-d4e9-4069-ba9b-e021d11912cc'; -- 川 (radical)
UPDATE items SET meaning_mnemonic = 'Bagus! Kanji ini sama dengan radikal yang bentuknya persis seperti itu (bahkan sampai ke maknanya!). Radikalnya adalah sembilan dan kanjinya adalah sembilan, sehingga arti dari kanji ini sangat mudah diingat asalkan Anda mengetahui radikalnya terlebih dahulu.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **sembilan** (九) tiba-tiba berbicara dan meminta **Kura-kura**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **きゅう**.' WHERE id = '48f33cce-025f-42f8-bd4d-cd5a322d4183'; -- 九 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda melihat radikal ini, ia tampak seperti bagian bawah sebuah pedang—lebih khusus lagi gagangnya. Radikal ini juga sangat mirip dengan radikal kekuasaan (力), jadi jangan bingung. Tidak ada inti kecil di atas, karena 90% kekuatan berasal dari pedang untuk menebas musuh Anda (itulah sebabnya radikal pedang adalah 90% dari radikal kekuatan).', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9f7e3060-eb93-482c-92d0-cbda1a35bfcd'; -- 刀 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal saat ini terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti sekarang.', reading_mnemonic = 'Untuk mengingat cara baca kanji **sekarang** (今), bayangkan Anda sedang membawa **Kopi/Koki** untuk ditaruh di atas sekarang. Kejadian unik ini mengingatkan Anda pada bunyi **こん**!' WHERE id = 'd50c2ab6-5799-4426-a488-275b2842a125'; -- 今 (kanji)
UPDATE items SET meaning_mnemonic = 'Beruntung bagi Anda (seperti halnya dengan banyak kanji berguratan rendah), kanji ini sama dengan kanji radikal yang telah Anda pelajari. Radikal yang membentuk kanji ini adalah tujuh dan kanjinya (yang persis sama) juga tujuh. Jadi, kalau kamu tahu radikalnya, kamu pasti tahu arti kanjinya juga.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **tujuh** (七) tiba-tiba berbicara dan meminta **しち**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **しち**.' WHERE id = '40c53ce5-5ed2-4fd6-977a-f98f5fd85281'; -- 七 (kanji)
UPDATE items SET meaning_mnemonic = 'Apakah Anda melihat pohon di sini? Ia memiliki cabang-cabang, dan dedaunannya turun secara diagonal, menyebar seperti pohon. Itu sebabnya radikal ini adalah sebuah pohon.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'addb690a-c560-4893-9c83-5be6b12cab42'; -- 木 (radical)
UPDATE items SET meaning_mnemonic = 'bulan sebenarnya terbuat dari matahari, namun memiliki kaki-kaki kecil yang condong ke kiri. Mengapa? Karena bulan selalu menjauhi matahari secepat mungkin. Ia tidak ingin terbakar, jadi ia harus berlari agar tetap berada di depan!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6d3dee75-0474-41b2-bd5d-412e818f1df4'; -- 月 (radical)
UPDATE items SET meaning_mnemonic = 'Ada tanda salib yang tergambar di tanah, membuat kotoran ini. Anda dapat menggambar apa saja di tanah, kali ini kebetulan berupa salib. Bayangkan menggambar salib di tanah dengan jari Anda. Rasakan kotoran tersangkut di bawah kuku Anda dan jangan pernah lupa.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '98b666ec-223f-4e65-bf6d-4d2dc98777c4'; -- 土 (radical)
UPDATE items SET meaning_mnemonic = 'Jika ada satu orang, apakah mereka? Ya, mereka bisa jadi hanya satu orang atau sendirian.', reading_mnemonic = 'Pembacaan kosakata ini tidak mengikuti aturan apa pun yang Anda pelajari sebelumnya. Ini pengecualian, artinya Anda juga harus mempelajari bacaannya secara terpisah. Luangkan beberapa saat untuk mencoba mengingat kata ini, mengalihkan pandangan selama 10 detik, dan kemudian mencoba mengingat kembali bacaannya. Bisakah kamu melakukannya? Coba lagi, kali ini dalam tiga puluh detik. Apakah kamu melakukannya lagi? Oke, lanjutkan dan lanjutkan. Anda mungkin mengetahuinya sekarang, namun Anda harus mengingatnya lagi dalam 5-10 menit berikutnya jika ingin mengingatnya selamanya.

Atau, jika Anda mengetahui cara membaca kosakata 一つ (pada level yang sama dengan kata ini), Anda dapat mengetahui bahwa kata tersebut menggunakan bacaan yang sama!' WHERE id = '3d83d5ed-0ae0-453f-b7b0-4ddfbd20eece'; -- 一人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Terdapat sirip yang menutupi harta penyusun radikal ini. Anda menarik siripnya dan mulai menggali di mana letak X (karena "X" menandai di mana harta karun itu berada, bukan?). Saat Anda menggali, alih-alih menemukan harta karun, Anda malah menemukan ayah Anda. Kejutan dalam imajinasi Anda akan membantu Anda mengingat makna radikal ini!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'f95169c0-80bf-4282-bde9-c8babd406a65'; -- 父 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji lain yang sama dengan radikal. pohon dan pohon keduanya sama dalam tampilan dan makna.', reading_mnemonic = 'Untuk membaca kanji 木 (pohon), bayangkan di setiap pohon ada **Muka** (もく) raksasa yang menatap Anda!' WHERE id = '59841d07-c3bd-4cbd-a2ab-690081c3cad9'; -- 木 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika sebuah vocab berdiri sendiri tanpa okurigana (itulah hiragana yang melekat pada kanji) biasanya memiliki arti yang sama dengan kanji juga. Hal ini juga berlaku untuk kata ini. Jadi, jika Anda mengetahui arti kanjinya (tujuh) Anda juga akan mengetahui arti vocabnya (tujuh).', reading_mnemonic = 'Kebanyakan kosakata kanji tunggal seperti ini menggunakan bacaan kun''yomi. Angka merupakan pengecualian terhadap aturan ini. Meskipun demikian, empat dan tujuh merupakan pengecualian terhadap pengecualian aturan ini (karena pembacaan on''yomi terdengar terlalu mirip dengan kata "kematian"). Anda harus mempelajari kedua bacaan untuk kata ini, meskipun kita akan menggunakan なな untuk yang utama di sini. Anda dapat mengingatnya karena Anda memiliki tujuh nanas setelah Anda.' WHERE id = '61cead38-0ced-48fc-8659-4348b1f4c89c'; -- 七 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda memiliki dua dan orang lalu menyatukannya, apa yang Anda dapatkan? Anda mendapatkan sepasang atau dua orang.', reading_mnemonic = 'Pembacaan kata ini cukup aneh. Jika Anda mengetahui bacaan 二つ, Anda dapat menggunakannya untuk mengingat bagian 二 (ふた). Namun, り yaitu 人 merupakan pengecualian total, sesuatu yang tidak akan terlalu sering Anda lihat (walaupun Anda mungkin pernah melihatnya di 一人). Jika Anda bisa menggunakan bacaan 一人 (alias jika Anda sudah mempelajarinya) maka gunakanlah itu. Jika tidak, lakukan yang terbaik untuk mengingat bacaan Anda sendiri. Ini adalah hal yang aneh dan tidak berhubungan dengan banyak hal lainnya.' WHERE id = 'e3299a04-4b81-4cbd-88fa-ccd33f067c35'; -- 二人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dua dan dua radikal adalah hal yang sama persis. Oleh karena itu, Anda sudah mengetahui kanji untuk dua orang!', reading_mnemonic = 'Bagaimana cara membaca kanji **dua** (二)? Ingat saja bahwa **Nila/Nikel** sangat menyukai dua! Hubungan erat ini akan membantu Anda mengingat bunyi **に**.' WHERE id = '8a37adec-92fc-45f9-91d1-ac623b42aa74'; -- 二 (kanji)
UPDATE items SET meaning_mnemonic = 'Ingatkah versi radikal dari kanji ini yang berarti orang karena ini adalah orang yang berjalan dari samping dengan tangan ke bawah? Ini adalah orang juga!', reading_mnemonic = 'Tahukah Anda bahwa **orang** (人) ini sebenarnya dibuat dari tumpukan **Ninja/Nasi**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **にん**.' WHERE id = 'a0104464-15f7-4b40-b1b9-5645ff71c312'; -- 人 (kanji)
UPDATE items SET meaning_mnemonic = 'Tengah radikal dan kanji Tengah keduanya sama. Jadi jika Anda mengetahui yang satu, Anda mengetahui yang lainnya.', reading_mnemonic = 'Bagaimana cara membaca kanji **tengah** (中)? Ingat saja bahwa **Cumi/Cubit** sangat menyukai tengah! Hubungan erat ini akan membantu Anda mengingat bunyi **ちゅう**.' WHERE id = '13926bdd-8f78-4137-b663-13f322c89bea'; -- 中 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji anak dan kanji anak sama persis.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **anak** (子) tiba-tiba berbicara dan meminta **Singa/Silet**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **し**.' WHERE id = '62a9fb3c-211e-4d4e-9b88-811124908b58'; -- 子 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah bentuk kata sifat dari besar. Meskipun memiliki arti yang sama, itu adalah kata untuk menggambarkan. Kata-kata yang diakhiri dengan い sering kali merupakan kata sifat, ingatlah hal itu juga untuk kata-kata berikutnya. Jadi, asal kamu tahu arti dari kanji ini, kamu bisa mentransfernya ke arti kata ini. Itu adalah kata sifat big, atau large.', reading_mnemonic = 'Apa yang Anda lakukan saat melihat sesuatu yang sangat-sangat besar? Anda mengucapkan おお karena Anda tidak dapat mempercayai mata Anda. Bayangkan sesuatu yang sangat besar dan ucapkan おお dengan lantang untuk membantu menyegel memori di otak Anda.' WHERE id = '659952ca-b341-4e0b-9adf-ab90ac93aaf8'; -- 大きい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika sebuah kosakata berupa satu kanji, biasanya kosakata tersebut juga mencuri makna dari kanjinya. Hal yang sama berlaku untuk kata vocab ini. Artinya delapan.', reading_mnemonic = 'Kalau vocabnya kanji tunggal dan sendirian seperti ini, biasanya akan menggunakan kun''yomi. Tapi, karena ini angka (pengecualian) maka yang digunakan adalah on''yomi, artinya kamu sudah tahu bacaannya sejak kamu mempelajari kanjinya!' WHERE id = '85bc36ca-1678-40b6-ba50-d214f2f0dcfe'; -- 八 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal air dan kanji air adalah sama.', reading_mnemonic = 'Untuk mengingat cara baca kanji **air** (水), bayangkan Anda sedang membawa **すい** untuk ditaruh di atas air. Kejadian unik ini mengingatkan Anda pada bunyi **すい**!' WHERE id = 'e8033e3a-f982-48dd-b7de-fe636f64fce0'; -- 水 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini tidak persis sama dengan radikal fins, tapi hampir sama. Kadang-kadang hal ini akan terjadi (di mana kita harus menggunakan versi asli yang sedikit "dimodifikasi secara radikal"), jadi ada baiknya untuk memahaminya sekarang, sejak dini. Dalam hal ini, kita memiliki sirip. Berapa banyak sirip? Delapan sirip. Bagaimana kamu tahu itu? Karena Anda menangkap empat ikan dengan masing-masing dua sirip.', reading_mnemonic = 'Bagaimana cara membaca kanji **delapan** (八)? Ingat saja bahwa **はち** sangat menyukai delapan! Hubungan erat ini akan membantu Anda mengingat bunyi **はち**.' WHERE id = '56081f0d-3fee-45ff-a2d2-0c7207f2e4e4'; -- 八 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika sebuah kata vocab berbentuk kanji tunggal tanpa okurigana (hiragana yang melekat pada kanji), biasanya kata tersebut memiliki arti yang sama dengan kanji asal kata tersebut. Jika Anda mengetahui arti kanjinya, Anda juga akan mengetahui arti vocabnya. Itu sepuluh ribu!', reading_mnemonic = 'Jika suatu kata vocab berbentuk kanji tunggal tanpa okurigana, biasanya menggunakan bacaan kun''yomi. Angka merupakan pengecualian dalam hal ini. Angka menggunakan bacaan on''yomi, yang telah Anda pelajari dengan mempelajari bacaan kanji! Bagus sekali!' WHERE id = 'ec057699-a830-44ee-8396-c2e0bdb95881'; -- 万 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji ini memiliki hiragana yang ditempelkan dan diakhiri dengan bunyi い. Itu berarti itu mungkin sebuah kata sifat (dan memang demikian!). Jadi, jika Anda mengambil kanji 小 dan artinya (kecil), Anda dapat mengetahui versi kata sifatnya. Apa versi kata sifat dari "kecil?" Sebenarnya sama saja: kecil.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajarinya dengan kanji ini, jadi inilah mnemonik untuk membantu Anda mengingat bagian ちい: 

Saat kamu memikirkan kata kecil, coba pikirkan toko keju (ちい) ini. Anda masuk ke dalam, dan semua keju mereka sangat kecil. Mereka memberi Anda kaca pembesar untuk melihat semua keju. Anda melihatnya dan berseru: "Mengapa keju ini begitu kecil???"' WHERE id = '058e24fc-f81a-4892-8ce6-f2c3fdfa6eae'; -- 小さい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti karakter katakana ナ (na), yang akan kita sebut sebagai singkatan dari narwhal. Ditambah lagi, jenis radikal ini terlihat seperti narwhal, bukan? Tubuh dan kepala di bawah, dan satu tanduk narwhal yang megah muncul di atas, melesat keluar dari air dan ke udara. Oh, dan jangan bingung membedakan radikal ini dengan harta karun. Garis samping untuk narwhal (ナ) berbentuk horizontal, garis samping untuk harta karun lebih mengarah ke bawah (メ), seperti tanda "X".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'f01c920e-91ed-43cc-acbe-5b80606ccfe2'; -- ナ (radical)
UPDATE items SET meaning_mnemonic = 'Bagian アメリカ cukup mudah asalkan Anda tahu katakana. Itu adalah kata untuk "Amerika". Anda tahu bahwa 人 berarti "orang", sehingga Anda dapat mengetahui bahwa Amerika + Orang = Amerika.', reading_mnemonic = 'Seringkali, ketika dua kanji bersatu membentuk gabungan kanji (atau jukugo), Anda menggunakan pembacaan on''yomi. Ini mirip dengan itu, meskipun bukan kanji lain yang digunakan adalah kata asing. Pola ini juga berlaku di hampir semua negara. Cukup tambahkan 人 ke nama negara dan Anda sudah mendeskripsikan orang-orang yang tinggal di sana. Anda akan melihat lebih banyak lagi sebelum Anda selesai di sini.

Dan karena 人 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan: 

Orang Amerika sangat menyukai jeans mereka (じん), ini adalah fakta yang sudah diketahui umum!' WHERE id = 'ca6e836a-6eaf-4c6c-bd03-3a881ff7bc82'; -- アメリカ人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Karena kata ini terdiri dari kanji dengan hiragana di tengahnya, Anda dapat menebaknya seperti menggabungkan dua kata terpisah yang telah Anda pelajari menjadi satu kata. Hiragana ini adalah の, sebuah partikel yang membuat sesuatu menjadi posesif. Dalam hal ini, 子 adalah dari 女. Pada dasarnya hal ini mengisyaratkan bahwa perempuan tersebut adalah seorang anak-anak alias girl.', reading_mnemonic = 'Karena ada hiragana di sini, bisa dipastikan kanji ini akan menggunakan pembacaan kun''yomi. Anda sudah mengetahui bacaan kun''yomi untuk 女. Satu-satunya hal yang harus saya pastikan Anda mengetahuinya adalah 子. Saat kamu perlu mengingat bacaan kun''yomi dari 子, bayangkan saja kamu berkelahi dengan seorang anak kecil (tampaknya kamu brengsek!). Saat Anda memukul wajahnya, dia terbang ke lantai, dan wasit berteriak "KO!" karena kamu baru saja menjatuhkan anak malang itu.' WHERE id = 'c1519c05-b808-4122-a8d6-5e2a12da19e6'; -- 女の子 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dalam bahasa Jepang, さ di akhir kata sering kali setara dengan "-ness" dalam bahasa Inggris. Dengan kata lain, jika Anda mengganti い di akhir kata sifat い dengan さ, Anda memiliki sebuah kata benda. Dalam hal ini, kata sifatnya adalah 大きい (besar) dan kata benda 大きさ berarti "kebesaran", alias ukuran.', reading_mnemonic = 'Jika sebuah kosakata memiliki okurigana (hiragana yang melekat pada kanji), kemungkinan besar itu adalah bacaan kun''yomi. Karena Anda mempelajari pembacaan on''yomi dengan kanji 大, kita harus menggunakan mnemonik untuk mengingat kata ini.

Saat kamu melihat ukurannya (pilih sesuatu yang mengejutkan), kamu berkata "おお *#$@!" Benar-benar membayangkan sesuatu yang mengejutkan. Ucapkan juga bagian おお dengan lantang. Pikirkan juga ukuran apa pun yang Anda lihat, dan seberapa besar ukurannya.' WHERE id = '1c25d1a8-0289-4fec-8a13-f7564f4fa0d4'; -- 大きさ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda menggambar orang hanya dengan guratan seperti yang Anda lihat di kanji, Anda akan membuat figur tongkat, mungkin seperti ini: 大. Tapi ini hanyalah seseorang, bukan seseorang yang mengulurkan tangannya untuk menunjukkan betapa besarnya mereka. Jadi lengannya diturunkan, sehingga terlihat seperti batang tubuh dengan sepasang kaki. Mungkin mereka juga sedang berjalan, makanya kaki mereka direntangkan seperti itu. Anda dapat melihat orang itu sekarang, bukan?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '72984862-4b29-4910-b0d2-2ed8f76328f9'; -- 人 (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini berarti mendaki. Anda dapat mengetahui bahwa kata ini adalah kata kerja karena diakhiri dengan bunyi う (dalam kasus ini, る). Maknanya mirip dengan kanji 上, yaitu "di atas". Jadi kata ini berarti bergerak "di atas" sesuatu (dengan kata lain, memanjat!)', reading_mnemonic = '上る terdiri dari kanji yang dibubuhi hiragana, sehingga akan menggunakan pembacaan kanji kun''yomi. Untuk 上, ada beberapa bacaan kun''yomi, dan Anda belum mempelajarinya, jadi inilah mnemonik untuk membantu Anda: 

Kamu ingin mendaki gunung tersebut, namun seorang lelaki tua yang kasar meraih bahumu dan berkata, "Tidak nak, kamu tidak akan mendaki gunung itu, tidak hari ini." Jika Anda bukan laki-laki, pikirkan betapa anehnya dia menyebut Anda laki-laki. Jika Anda sudah dewasa, pikirkan betapa Anda berharap dia memanggil Anda "dude" atau semacamnya, bukan "boy". Jika Anda laki-laki, ya... pikirkan betapa pantasnya dia mengatakan "tidak, laki-laki".' WHERE id = 'c14486fe-c1ae-45d9-87e4-239ae03577b0'; -- 上る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini memiliki arti yang sama dengan yang Anda pelajari dengan kanji: part, atau portion. Lebih jauh lagi, ini juga bisa berarti content, seperti dalam "kandungan alkohol" karena itulah porsi alkohol dalam minuman.

Kata ini juga digunakan untuk pecahan, seperti sepertiga atau seperempat. Sekali lagi, Anda dapat melihat bagaimana tautan ini ke "bagian" dan "bagian", bukan?', reading_mnemonic = 'Kata ini biasanya digabungkan dengan kata lain, mungkin itulah sebabnya kata kosakata kanji tunggal ini menggunakan on''yomi dan bukan kun''yomi. Kalau kalian tahu bacaan kanjinya pasti tahu juga bacaan vocab ini, namun bacaannya berbeda-beda tergantung artinya:

Kalau yang dimaksud adalah part atau portion, dibaca ぶん. Mungkin karena **Bunga/Buku** Anda terdiri dari dua bagian. Ohoho.' WHERE id = 'de7b977e-96db-4378-8993-ffa5fb28b424'; -- 分 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika kosakata berupa kanji tunggal tanpa okurigana (itulah hiragana yang melekat pada kanji), maka kosakata tersebut cenderung mencuri makna dari kanji asalnya. Jadi, yang ini di bawah atau down.', reading_mnemonic = 'Jika kosakatanya berupa kanji tunggal dan sendirian maka cenderung menggunakan bacaan kun''yomi. Anda telah mempelajari bacaan on''yomi untuk kanji ini, jadi sekarang saatnya mempelajari bacaan kun''yomi untuk mempelajari kosakata ini.

Apa di bawah Anda? Apa yang ada di bawah kakimu? Oh tidak. Hal terburuk yang mungkin terjadi: Ini した.' WHERE id = '83b5726f-a0ca-4a61-a017-b2c4f1fc787c'; -- 下 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika suatu kata vocab hanya berupa satu kanji dan tersendiri, maka cenderung mencuri arti dari kanji tersebut. Hal yang sama juga berlaku untuk yang satu ini. Artinya di atas atau naik.', reading_mnemonic = 'Jika sebuah kata vocab berbentuk kanji tunggal dan tidak memiliki okurigana (hiragana yang melekat pada kanjinya), biasanya akan menggunakan kun''yomi. Karena Anda telah mempelajari pembacaan kanji on''yomi, kita perlu menggunakan mnemonik untuk mempelajari pembacaan kosakata ini. 

Di atas Anda memiliki beban yang sangat berat. Anda menahannya dan meronta (ini berat!). Kamu melihat ke atas dan mencoba menjulurkan lehermu untuk melihat berapa beratnya (うえ), tapi kamu tidak dapat melihat angka di sampingnya. Berapa lama Anda bisa menahannya di atas kepala seperti ini?' WHERE id = '3fe5f065-78e7-47d8-ae7f-113f21d7cc48'; -- 上 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda menemukan jari kaki di tanah. Aneh, karena letaknya di atas tanah, bukan di tempat jari kaki berada.', reading_mnemonic = 'Bagaimana cara membaca kanji **di atas** (上)? Ingat saja bahwa **Joni/Jenderal** sangat menyukai di atas! Hubungan erat ini akan membantu Anda mengingat bunyi **じょう**.' WHERE id = 'f73512bf-937c-4470-96f1-4430efba0c06'; -- 上 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada jari kaki di bawah tanah.', reading_mnemonic = 'Tahukah Anda bahwa **di bawah** (下) ini sebenarnya dibuat dari tumpukan **Kaki/Kaca**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **か**.' WHERE id = '8b35a640-3651-4d9f-8417-bc4937d41779'; -- 下 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal kecil dan kanji kecil sama persis.', reading_mnemonic = 'Ketika Anda sedang melihat **kecil** (小), tiba-tiba muncul sesosok **Sopir/Soto** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **しょう**.' WHERE id = '82b72a90-97b6-4bc7-a997-cd2eeffe7920'; -- 小 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji gunung dan kanji gunung adalah sama.', reading_mnemonic = 'Untuk mengingat cara baca kanji **gunung** (山), bayangkan Anda sedang membawa **さん** untuk ditaruh di atas gunung. Kejadian unik ini mengingatkan Anda pada bunyi **さん**!' WHERE id = '013725b8-fe0f-43d8-973b-f36b03d4e0d8'; -- 山 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memotong daun dengan pedang Anda menjadi sepuluh ribu keping!', reading_mnemonic = 'Untuk mengingat cara baca kanji **sepuluh ribu** (万), bayangkan Anda sedang membawa **まん** untuk ditaruh di atas sepuluh ribu. Kejadian unik ini mengingatkan Anda pada bunyi **まん**!' WHERE id = '07d98856-b528-443b-8952-213b56b4bd49'; -- 万 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal dan kanji untuk ayah adalah sama.', reading_mnemonic = 'Bagaimana cara membaca kanji **ayah** (父)? Ingat saja bahwa **Feri/Foto** sangat menyukai ayah! Hubungan erat ini akan membantu Anda mengingat bunyi **ふ**.' WHERE id = '3009fd12-d6f3-4531-b859-2871d25c3308'; -- 父 (kanji)
UPDATE items SET meaning_mnemonic = 'Seekor narwhal yang duduk di bangku adalah teman Anda.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **teman** (友) tiba-tiba berbicara dan meminta **Yuda**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ゆう**.' WHERE id = 'd6a22abe-ce82-460a-8833-1a3be4b6137e'; -- 友 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal surga sama dengan kanji surga, menjadikannya kanji yang mudah dihafal.', reading_mnemonic = 'Untuk mengingat cara baca kanji **surga** (天), bayangkan Anda sedang membawa **てん** untuk ditaruh di atas surga. Kejadian unik ini mengingatkan Anda pada bunyi **てん**!' WHERE id = 'fdb7df9f-0ada-4cf6-a57d-59a624b13c59'; -- 天 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini mempunyai dua arti yang berbeda. Satu hari dan hari pertama. Tidak peduli bagaimana Anda melihat kata ini, maknanya sangat masuk akal.', reading_mnemonic = 'Arti pertama adalah suatu hari, dan bacaannya sama dengan kanji yang kamu pelajari, jadi kamu pasti sudah tahu bacaan ini.

Namun, pembacaan untuk hari pertama merupakan pengecualian besar. Tidak memerlukan bacaan on''yomi atau kun''yomi, dan mempunyai bacaan khusus (aneh). Berikut ini mnemonik untuk membantu Anda mengingat yang satu ini:

Pada hari pertama suatu hubungan baru, Anda cukup men-tweet kalimat murahan (ついたち) satu sama lain. Kamu begitu jatuh cinta sehingga kamu tidak dapat berbicara dengan normal, jadi kamu hanya menggunakan panggilan burung dan kalimat murahan untuk berkomunikasi.' WHERE id = 'fa3018e6-18c2-4f1b-aca3-ea9beb025a8d'; -- 一日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini:

Anda melihat seorang anak dan berjalan ke arahnya. Lalu, kamu meninju wajahnya (oh tidak, bagaimana bisa!!?). Dia terbang di udara, dan dia tersingkir. Wasit di dekatnya berteriak bahwa itu adalah "KO!" (こ). Itu adalah KO.

Pastikan Anda mempelajari bacaan ini dengan cukup baik juga. Kedua bacaan untuk 子 akan sering muncul, dan inilah cara Anda mempelajari kun''yomi.' WHERE id = 'eae0f5ce-15ba-4d10-ad97-98b4f47a6106'; -- 子 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika sebuah kosakata hanya berupa satu kanji saja, biasanya maknanya sama dengan induk kanjinya. Hal ini juga berlaku untuk kosakata ini. Orang adalah orang.', reading_mnemonic = 'Jika kosakatanya berupa kanji tunggal tanpa okurigana (hiragana yang melekat pada kanji), biasanya menggunakan bacaan kun''yomi. Karena Anda belum mengetahui bacaan kun''yomi untuk kanji ini, mari gunakan mnemonik untuk mempelajarinya.

Apa yang paling dibenci oleh seseorang? Mereka benci panas ekstrem (ひと). Anda selalu dapat mengenakan lebih banyak pakaian agar tetap hangat, tetapi jika suhu menjadi terlalu tinggi, Anda hanya dapat melepas pakaian sebanyak itu.' WHERE id = 'adb7e3c6-db31-4b71-8a09-c326ec8c689e'; -- 人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, biasanya menggunakan bacaan kun''yomi. Namun, kanji yang membentuk kata ini hanya memiliki satu bacaan penting, yaitu on''yomi. Sejak Anda mempelajari cara membaca on''yomi untuk kanji ini, Anda juga telah mempelajari cara membaca kata ini.' WHERE id = '1d7fc86b-f008-468f-984b-92bf97fdfebd'; -- 天 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji ini terdiri dari kata radikal dasar (yang juga merupakan kanji untuk "satu") dan kata radikal untuk dua. Gabungkan satu dan dua bersama-sama dan apa yang Anda dapatkan? Tiga!', reading_mnemonic = 'Ketika Anda sedang melihat **tiga** (三), tiba-tiba muncul sesosok **さん** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **さん**.' WHERE id = 'f4a6f337-80bd-4c98-b9db-34c63076d869'; -- 三 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini adalah bentuk ayah yang sopan dan rendah hati. Anda menggunakan ini ketika Anda berbicara tentang ayah Anda sendiri kepada orang lain, terutama jika Anda tidak terlalu dekat dengan mereka.', reading_mnemonic = 'Pembacaan kata ini sama dengan yang Anda pelajari saat mempelajari kanji.' WHERE id = '37386c56-fadf-47a9-95d0-b38469e189cd'; -- 父 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada sebatang tongkat menembus tengah mulut seseorang! Bayangkan mulut itu menjadi milik Anda. Ukur penempatan tongkat. Sejajar sempurna, tepat di tengah. Itu luar biasa, meski sejujurnya, Anda mungkin menghadapi masalah yang lebih besar daripada mengukur lokasi tongkat ini di mulut Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5cd8234f-a3ff-4c53-b8fc-d344472ae9fb'; -- 中 (radical)
UPDATE items SET meaning_mnemonic = 'Ini dimulai dengan kata katakana lain, sehingga Anda dapat berasumsi bahwa itu adalah kata pinjaman. Yang ini juga berasal dari bahasa Inggris. Bisakah Anda mengetahui apa artinya? Itu benar, "tempat tidur". Kemudian muncul partikel の, yang menggabungkan dua kata benda. Terakhir, ada 下, yang Anda pelajari berarti "turun" atau "di bawah". Gabungkan elemen-elemen ini dan Anda akan mendapatkan di bawah tempat tidur, di bawah tempat tidur, atau di bawah tempat tidur. Apa yang ada di bawah tempat tidurmu?', reading_mnemonic = '下 adalah kata yang berdiri sendiri di sini, sehingga menggunakan bacaan yang sama seperti yang Anda pelajari saat mempelajari kosakatanya.' WHERE id = '917fcd0a-05b6-445f-9530-75f253314be5'; -- ベッドの下 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Berikut ini mnemonik untuk membantu Anda mengingatnya: 

Anda melihat melalui tanah. Anda mencoba menemukan sesuatu. Saat Anda menggali dan menyaring, yang Anda temukan bukan hanya satu melainkan dua keju (つち). Tarik keluar dari tanah dan masukkan ke dalam mulut Anda. Bagaimana rasa dan perbandingan kedua keju tersebut?' WHERE id = '49193465-02f9-46b3-af15-13cc10120628'; -- 土 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji untuk "bulan" dan "bulan" adalah sama, mungkin karena siklus bulan terjadi sekitar satu bulan. Jadi, apa siklus bulan kesepuluh dalam setahun? Itu akan menjadi bulan yang luar biasa Oktober!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 月 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Oktober memberi Anda permata nyali (じゅうがつ). Pada bulan Oktober, nyali Anda secara ajaib menghasilkan permata, yang Anda kumpulkan untuk membuat beberapa kostum Halloween yang sangat mengagumkan.' WHERE id = '06e5dcda-0e1b-4514-a41a-2b2bdb3f3360'; -- 十月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika Anda memiliki satu sepuluh ribu Anda hanya memiliki sepuluh ribu. Namun dalam bahasa Jepang, Anda menentukan berapa sepuluh ribu yang Anda miliki (yang aneh dalam bahasa Inggris, tapi seharusnya masuk akal jika Anda memikirkannya).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '093ee7fd-fc13-4fa2-9238-43e6f109adfa'; -- 一万 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hati-Hati! Ini bukan orangnya radikal, tapi hal lain. Apa bedanya? Sisi kanan lebih panjang dari sisi kiri. Dan pada komputer, biasanya ada bagian tambahan yang menonjol di bagian atas. Ini terlihat seperti penutup yang membuka ke teepee. Dan apa yang Anda lakukan dengan pembukaan? Anda memasukkannya! Itu sebabnya radikal ini masuk.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a659a26a-83e6-4f7a-af4b-f0dc1d997590'; -- 入 (radical)
UPDATE items SET meaning_mnemonic = 'Satu baris ditambah baris lainnya sama dengan dua baris. Radikal ini mewakili nomor dua. Cukup sederhana, bukan? Bisakah kamu menebak seperti apa ketiganya? Saya yakin Anda bisa...', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a3f51dde-38e4-4880-8c79-4c0414cb32f6'; -- 二 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini tampak seperti silang. Maksudku, lihat saja. Dua batang saling bersilangan = sebuah salib!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '76015da3-0637-4db1-9b5d-6fa507357fb8'; -- 十 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini tampak seperti figur tongkat—lebih khusus lagi, seorang pria yang sangat besar dengan tangan terentang bagus dan besar. Kalau melihat radikal ini, berpikirlah besar saja, karena orang ini BESAR banget!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'fdd8490b-b492-41f5-8125-8641a25a9400'; -- 大 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji bulan terdiri dari radikal bulan. Kanji ini juga digunakan untuk mengartikan bulan.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **bulan** (月) tiba-tiba berbicara dan meminta **げつ**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **げつ**.' WHERE id = 'f008df79-05c5-453f-9350-b2528a725ac0'; -- 月 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji sungai dan kanji sungai sama satu sama lain!', reading_mnemonic = 'Tahukah Anda bahwa **sungai** (川) ini sebenarnya dibuat dari tumpukan **Senter/Semen**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **せん**.' WHERE id = 'df69763a-9633-45c7-9d64-24ca26a63e1d'; -- 川 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki sirip dan Anda memiliki duri. Ikan yang durinya bisa ditusukkan seluruhnya seperti ini harus benar-benar kecil, karena duri tersebut menembus seluruh tubuh ikan (yang dapat Anda bayangkan dengan mendasarkan tubuhnya pada ukuran sirip dibandingkan dengan duri yang sudah kecil.)', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '34f177b4-bee6-46e1-b0c0-cce0ea367d49'; -- 小 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah gunung. Anda harus menambahkan garis-garis yang membentuk puncak gunung jika ingin lebih "seperti gunung". Juga sesuatu yang mungkin bisa membantu: terkadang gunung memiliki beberapa puncak kecil yang juga muncul di sisi puncak utama. Hubungkan titik-titiknya dan ciptakan gunung dalam pikiran Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a5a5f389-c1f8-4df3-939d-cea2c6b4d8d4'; -- 山 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "daun". Perhatikan bentuk karakter "丆" dan asosiasikan bentuk goresannya dengan "daun".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '32afb049-ca09-4e3f-a6b5-4e0e24d7f263'; -- 丆 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah topi di atas katakana untuk "ra". Bayangkan Ra, dewa Mesir. Kapan Ra memakai topi? Sekarang juga sekarang! Selalu begitu sekarang, karena dia tidak pernah melepasnya. Tidak juga, lihatlah, itu benar.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '3a3835a5-b38e-407e-a14e-a67d1480a46a'; -- 今 (radical)
UPDATE items SET meaning_mnemonic = 'Ini tampak seperti bangku yang dapat dilipat, bukan?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'de277848-c10b-4987-92ce-de3b39670e0f'; -- 又 (radical)
UPDATE items SET meaning_mnemonic = 'Ada tetesan cairan yang keluar dari kedua sisi duri ini. Bisa dibayangkan durinya ditancapkan ke tanah lalu dicabut. Saat itu terjadi, air keluar dari kedua sisi! Itu sebabnya radikal ini adalah air.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'e5edc475-6589-4add-8a47-9bbb4d4e822c'; -- 水 (radical)
UPDATE items SET meaning_mnemonic = 'Karena tidak ada lingkaran dalam karakter Jepang, terkadang persegi panjang atau persegi harus digunakan. Dalam hal ini, persegi panjang besar ini adalah matahari. Garis tengah yang melalui pusat secara horizontal adalah garis khatulistiwa. Atau mungkin itu awan yang bergerak melintasi matahari. Bayangkan saja, tapi jangan menatap matahari dan membuat mata Anda terbakar!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7272eebc-f950-4fab-b1a2-f9c8941def1e'; -- 日 (radical)
UPDATE items SET meaning_mnemonic = 'Anda berada di sebuah ruangan, dikelilingi oleh perosotan. Turun dari perosotan berjatuhan salib demi salib demi salib. Mereka memantul dan memukul wajah Anda, lengan, di mana-mana... Dengan setiap umpan silang terdengar suara yang berteriak, "SATU! DUA! TIGA RATUS! LIMA RATUS!" dan sebagainya. Anda khawatir hal itu tidak akan pernah berakhir, karena Anda mulai tenggelam dalam salib. Kemudian suara itu meneriakkan SATU RIBU dan mereka berhenti. Tetap saja, kamu tidak bisa bergerak. Pikirkan tentang semua nomor yang dipanggil, dan teruslah bertanya-tanya apakah itu nomor terakhir. Rasakan kelegaan yang akan kamu rasakan jika berhenti di angka seribu, karena kamu tidak akan terkubur lagi. Seribu salib menutupi seluruh tubuhmu, menutupi kepalamu, tapi karena itu salib, kamu masih bisa bernapas.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '08a7acd2-fce2-4a84-ac22-0d513b52c2e8'; -- 千 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji sun dan sun itu sama, huzzah! Selain itu, jika Anda ingin mengingat hari juga, Anda bisa memikirkan bagaimana satu hari adalah waktu yang dibutuhkan matahari untuk melintasi langit.', reading_mnemonic = 'Untuk mengingat cara baca kanji **hari** (日), bayangkan Anda sedang membawa **にち** untuk ditaruh di atas hari. Kejadian unik ini mengingatkan Anda pada bunyi **にち**!' WHERE id = '34eace5a-d2e0-478c-9f91-f38adcbdcd07'; -- 日 (kanji)
UPDATE items SET meaning_mnemonic = 'Saat Anda melihat ini pada sebuah angka, misalnya ７人 atau ３人, Anda menggunakannya untuk menghitung orang. Ingat saja, 一人 dan 二人 memiliki bacaan alternatif. Dari 3 ke atas tinggal angka plus にん saja, seperti ini. ５人 adalah ごにん, １０人 adalah じゅうにん, dll. Ini adalah penghitung untuk orang, yang membuat kata ini menjadi jumlah orang.', reading_mnemonic = 'Ini adalah counter, yang biasanya berarti pembacaan on''yomi dari kanji. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Bayangkan saja jumlah orang di Nintendo (にん). Ini pasti sangat besar. Ini sebenarnya hanyalah counter untuk orang-orang yang bekerja di Nintendo.' WHERE id = 'e7cba4de-cde3-47a9-9654-fe671b7a43f1'; -- 〜人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'した adalah bentuk lampau dari する (yang berarti "melakukan"). Jadi, pada dasarnya kata ini adalah "berhasil besar". Apa yang dimaksud dengan "berhasil besar"? Itu adalah sesuatu yang hebat atau cukup besar.', reading_mnemonic = 'Bacaan bagian 大 sebenarnya adalah bacaan on''yomi yang dipelajari saat mempelajari kanji ini. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Jika ada sesuatu yang hebat dan penting, sebaiknya Anda mengenakan dasi (たい) untuk itu. Dilarang muncul tanpa ada kaitannya dengan apa pun yang merupakan masalah besar, oke?' WHERE id = '9982138b-805d-43e3-af42-9a3b8291ce2a'; -- 大した (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada dua orang radikal dan satu orang radikal. Tingkat pertama kehidupan seseorang adalah di bumi. Tingkat kedua (tingkat ini, itulah sebabnya ada dua radikal di sini) ada di surga. Jadi ketika Anda melihat seseorang di level 2, Anda tahu dia ada di surga.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0edb1f64-a7ee-4263-9f55-ba59aebace30'; -- 天 (radical)
UPDATE items SET meaning_mnemonic = 'Anda memiliki kanji untuk tiga dan orang. Akal sehat akan memberi tahu Anda apa kata ini. Itu tiga orang.', reading_mnemonic = 'Ini adalah kata jukugo (kanji majemuk), yang biasanya berarti pembacaan on''yomi dari kanji. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Tampaknya, ada tiga orang yang bekerja sebagai Santa-san di Nintendo (さんにん)! Ini perusahaan besar, jadi jelas mereka membutuhkan tiga Santa.' WHERE id = '34cc672c-2016-468e-8d31-6d64e3341b73'; -- 三人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari satu guratan horizontal. Berapakah pukulan horizontal tunggal terbesar? Itulah landasan. Lihatlah ke bawah, lihat ke arah radikal ini, sekarang lihatlah ke bawah lagi. Sama saja kan?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1c4a5562-92f4-4abb-9b6a-2b10a9f874bb'; -- 一 (radical)
UPDATE items SET meaning_mnemonic = 'Ketika sebuah kosakata terdiri dari satu kanji tanpa okurigana (hiragana yang melekat pada kanji), sering kali kosakata tersebut memiliki arti yang sama dengan kanji yang mendasarinya. Hal yang sama juga berlaku untuk kata 九. Ini memiliki arti yang sama dengan kanjinya.', reading_mnemonic = 'Jika sebuah kosakata terdiri dari satu kanji tanpa okurigana (hiragana yang melekat pada kanji), biasanya menggunakan bacaan kun''yomi. Angka adalah pengecualian, seperti yang mungkin sudah Anda ketahui. Saat mereka sendirian tanpa okurigana, mereka membaca on''yomi, yang seharusnya sudah Anda ketahui dari mempelajari kanji yang membentuk kata ini.' WHERE id = 'c2bbde62-9fe5-4d6c-9c3b-f5988502c5dc'; -- 九 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini mengikuti pola "bilangan benda" yang mana terdapat kanji untuk bilangan ditambah つ di akhir. Setiap kali Anda melihat ini, Anda tahu kata itu berarti "____ benda". Mengetahui hal itu, selama Anda mengetahui kanji (yang Anda gunakan), Anda dapat mengetahui berapa banyak benda yang ada di dalamnya. Untuk yang ini, kanjinya adalah tiga ditambah つ. Jadi, yang satu ini adalah tiga hal.', reading_mnemonic = 'Karena semua kata "bilangan benda" mengikuti pola yang sama (angka ditambah つ), Anda hanya perlu mengingat bagian sebelum つ (lalu ingat bahwa つ ada di semua ini). Semua bacaannya adalah bacaan kun''yomi, artinya kita harus menggunakan mnemonik untuk mengingatnya (Anda tahu bacaan on''yomi di bagian kanji).

Benda apa yang kamu punya bertiga? tiga hal yang Anda miliki sebenarnya adalah tiga versi diri Anda sendiri. "Siapa yang sebenarnya?" kamu bertanya pada dirimu sendiri. "Ini aku!" "Tunggu, tidak, ini aku!" Ingatlah bahwa kalian bertiga, dan mereka semua mengatakan "aku, aku, aku" untuk mencoba membuktikan bahwa merekalah dirimu yang sebenarnya.' WHERE id = 'b7c51513-4338-49ae-8c1a-06332e2200e0'; -- 三つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hari ketujuh atau hari ketujuh. Tidak peduli bagaimana Anda melihatnya, kata ini sangat masuk akal.', reading_mnemonic = 'Kata-kata yang menghitung hari menggunakan bacaan yang luar biasa. Meskipun ini adalah kata jukugo, namun menggunakan pembacaan kun''yomi untuk kedua kanjinya. Pikirkan tentang kata ini seperti ini:

Anda terjebak dalam pekerjaan selama tujuh hari dan hari ini Anda akhirnya mendapat hari libur. Temanmu bertanya apakah kamu ingin pergi jalan-jalan, tetapi kamu berkata, "Tidak, tidak ada mobil hari ini" (なのか), karena kamu sudah cukup lama terkurung. Tujuh hari terlalu lama untuk berada di dalam.' WHERE id = '77ea0d36-ba7f-49cd-ab36-4c6364b3e412'; -- 七日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hari kesepuluh atau hari sepuluh. Tidak peduli bagaimana Anda melihatnya, kata ini sangat masuk akal.', reading_mnemonic = 'Kata-kata yang menghitung hari menggunakan bacaan yang luar biasa. Meskipun ini adalah kata jukugo, namun menggunakan pembacaan kun''yomi untuk kedua kanjinya. Pikirkan tentang kata ini seperti ini:

Pada hari kesepuluh, mereka akan menderek mobilmu (とおか). Mereka akan membiarkannya di sana selama sepuluh hari, tapi lebih dari itu mereka akan menariknya, jadi berhati-hatilah.' WHERE id = '8e694346-c64a-4119-a40a-6db0c9f618d3'; -- 十日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji 月 berarti bulan dan bulan (karena siklus bulan mungkin memakan waktu sekitar satu bulan). Jadi, berapakah angka dua bulannya? Ini bukan bulan Januari... ini bukan bulan Maret... ini Februari!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. 月 memiliki dua bacaan on''yomi, tetapi selalu menggunakan bacaan がつ pada nama bulan, jadi inilah mnemonik untuk membantu Anda mengingatnya:

Februari adalah bulan ketika seseorang membuat Anda bertekuk lutut (にがつ). Orang asing datang setiap bulan Februari hanya untuk membuat Anda berlutut. Aduh! Itu sebabnya Februari adalah bulan yang paling tidak Anda sukai.' WHERE id = '18cab80d-2aa5-493f-87f2-fe6dbcb6baa7'; -- 二月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hari ketiga atau hari ketiga. Tidak peduli bagaimana Anda melihatnya, kata ini sangat masuk akal.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Namun, menghitung hari merupakan pengecualian (setidaknya hingga sepuluh). Anda perlu menggunakan bacaan kun''yomi untuk membaca kata ini. Anda sudah mengetahui bacaan kun''yomi untuk 三 sejak Anda mempelajari kata 三つ. Berikut cara mengingat bacaan 日:

Pada hari ketiga kamu harus mengantarku (み) dengan mobilmu (か). Aku tidak punya mobil sendiri, jadi jangan lupakan aku, oke?' WHERE id = '44e24b4c-7499-4880-8f3c-9f0f19f96e26'; -- 三日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'イギリス berarti "Inggris Raya" atau "Britania Raya". Jadi apa yang dimaksud dengan "orang Inggris Raya?" Anda dapat menebaknya — Orang Inggris, atau Brit.', reading_mnemonic = 'Seringkali, ketika dua kanji bersatu membentuk gabungan kanji (atau jukugo), Anda menggunakan pembacaan on''yomi. Ini mirip dengan itu, meskipun bukan kanji lain yang digunakan adalah kata asing. Pola ini juga berlaku di hampir semua negara. Cukup tambahkan 人 ke nama negara dan Anda sudah mendeskripsikan orang-orang yang tinggal di sana. Anda akan melihat lebih banyak lagi sebelum Anda selesai di sini.

Dan karena 人 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan: 

Seperti semua kata untuk kebangsaan, 人 di sini diucapkan じん. Semua warga negara, termasuk Inggris, menyukai jeans (じん)!' WHERE id = '21464a85-b587-4fe2-95cc-9d79e4e66058'; -- イギリス人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 山 berarti gunung. Tambahkan hiragana びこ di akhir dan ini memberi Anda echo. Itu karena anak-anak lebah (lebah 子) menyukai gema, terutama gema gunung! Bayangkan bayi lebah berdengung sekeras yang mereka bisa dan mendengar suara mereka bergema melalui pegunungan.

Seperti yang disarankan dalam kanji, 山びこ umumnya digunakan untuk menggambarkan gema yang Anda dapatkan jika Anda berteriak di pegunungan. Untuk mendeskripsikan jenis gema lainnya, Anda dapat menggunakan kata katakana エコー.

Ngomong-ngomong, sebenarnya ada kanji untuk bagian kedua kata ini, tapi sangat jarang yang biasanya ditulis dengan kana!', reading_mnemonic = 'Anda mempelajari pembacaan kanji ini ketika Anda mempelajari kosakata 山.' WHERE id = 'f5b4315f-254c-47a6-9f91-1c274ca2b3ad'; -- 山びこ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana Anda mengetahui bahwa 大人 berarti "dewasa?" Ini adalah versi kata sifat dari itu. Kata sifat I (lihat akhirannya い?). Kata sifat apa yang orang dewasa ingin gunakan untuk anak-anak mereka sendiri? Mereka ingin mengatakan bahwa mereka adalah anak-anak yang taat, pendiam!', reading_mnemonic = 'Anda sudah mempelajari bacaan ini saat mempelajari 大人! Anda juga harus bisa membaca ini!' WHERE id = 'c543ff33-ee36-45d5-acda-d8250bc7f89f'; -- 大人しい (vocabulary)
UPDATE items SET meaning_mnemonic = 'sekarang bulan sebenarnya adalah bulan ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 月 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Hanya bulan ini, condor peliharaanmu dapat (こんげつ) tidur di kasurmu. Biasanya Anda menyimpannya di dalam sangkar, tapi setahun sekali, Anda membuat pengecualian. Dan itu bulan ini. Lucu sekali!' WHERE id = '91a9dd08-f71b-43f5-b627-4559a2744a8b'; -- 今月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'フランス adalah "Prancis." Jadi apa yang dimaksud dengan "orang Prancis?" Itu adalah Orang Perancis.', reading_mnemonic = 'Seringkali, ketika dua kanji bersatu membentuk gabungan kanji (atau jukugo), Anda menggunakan pembacaan on''yomi. Ini mirip dengan itu, meskipun bukan kanji lain yang digunakan adalah kata asing. Pola ini juga berlaku di hampir semua negara. Cukup tambahkan 人 ke nama negara dan Anda sudah mendeskripsikan orang-orang yang tinggal di sana. Anda akan melihat lebih banyak lagi sebelum Anda selesai di sini.

Dan karena 人 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan: 

Seperti semua kata untuk kebangsaan, 人 di sini diucapkan じん. Seperti orang-orang dari negara lain, Orang Prancis juga menyukai jeans mereka (じん)!' WHERE id = '4e556b94-3dae-49a3-be1a-9d1513d73b5f'; -- フランス人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Partikel の menjadikan 人 milik 女. Pada dasarnya, ini secara harfiah berarti "seorang wanita" atau "seorang wanita". Namun, ini cara yang lebih sopan untuk mengatakan wanita tua biasa, jadi yang harus Anda ingat hanyalah itu.', reading_mnemonic = 'Kata ini sebenarnya adalah dua kata terpisah yang digabungkan dengan sebuah partikel. Jadi, karena Anda memperlakukannya seperti kata-kata yang terpisah, Anda membacanya masing-masing dengan pembacaan kun''yomi (keduanya merupakan kata-kata kanji tunggal). Meskipun demikian, di level 1 Anda belajar tentang pembacaan kosakata untuk kata-kata terpisah ini, jadi gunakan pengetahuan tersebut untuk mengingat bacaan kata ini juga.' WHERE id = '4c5f8973-69fc-43bc-ba0b-e5968f42377f'; -- 女の人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bayangkan seekor ikan. Sekarang bayangkan ikannya sedikit lebih buruk, seperti gambar ikan anak-anak. Sekarang hapus tubuh ikannya dan... Anda akan mendapatkan dua sirip! Apakah Anda melihat kedua sirip ini? Ya, Anda melihatnya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8272a678-d7ae-4e29-8a00-65dd2989e813'; -- ハ (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Apa yang akan kamu minum sekarang? Aku mau Zima, ima.

Ucapkan "ZIMA IMA" sepuluh kali dengan cepat.' WHERE id = 'b3c27dea-3cba-4b69-b7ad-bc1e231206d3'; -- 今 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji kotoran dan kanji kotoran adalah sama!', reading_mnemonic = 'Bagaimana cara membaca kanji **tanah** (土)? Ingat saja bahwa **ど** sangat menyukai tanah! Hubungan erat ini akan membantu Anda mengingat bunyi **ど**.' WHERE id = '61bb2e5d-6949-43a5-af9e-bfc57f66dbb7'; -- 土 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal untuk wanita dan kanji untuk wanita sama persis.', reading_mnemonic = 'Tahukah Anda bahwa **wanita** (女) ini sebenarnya dibuat dari tumpukan **Joni/Jenderal**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **じょ**.' WHERE id = 'c35609c8-692d-406d-8c39-ffa4146ac7ce'; -- 女 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini mengikuti pola "bilangan benda" yang mana terdapat kanji untuk bilangan ditambah つ di akhir. Setiap kali Anda melihat ini, Anda tahu kata itu berarti "____ benda". Mengetahui hal itu, selama Anda mengetahui kanji (yang Anda gunakan), Anda dapat mengetahui berapa banyak benda yang ada di dalamnya. Untuk yang ini, kanjinya adalah tujuh ditambah つ. Jadi, yang satu ini adalah tujuh hal.', reading_mnemonic = 'Karena semua kata "bilangan benda" mengikuti pola yang sama (angka ditambah つ), Anda hanya perlu mengingat bagian sebelum つ (lalu ingat bahwa つ ada di semua ini). Semua bacaannya adalah bacaan kun''yomi, artinya kita harus menggunakan mnemonik untuk mengingatnya (Anda tahu bacaan on''yomi di bagian kanji).

Tujuh benda apa yang kamu punya? tujuh hal yang Anda miliki adalah tujuh Nana (なな). Ini adalah nenekmu, hasil kloning. Bayangkan saja, "Untungnya punya tujuh nanas. Mereka semua bisa memasakkan makanan favoritku untukku!" Terlebih lagi, Anda memiliki satu nana untuk setiap hari dalam seminggu, sehingga Anda akan mendapatkan makanan favorit Anda setiap hari.' WHERE id = '2b83a383-4abb-46bc-83a4-aa3123552314'; -- 七つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Karena kanji 月 berarti bulan dan bulan (karena siklus bulan diperkirakan sekitar satu bulan), berapakah jumlah satu bulan? Dalam bahasa Inggris kami mempunyai nama sebenarnya untuk itu, dan nama itu adalah January.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. 月 memiliki dua bacaan on''yomi, tetapi selalu menggunakan bacaan がつ pada nama bulan, jadi inilah mnemonik untuk membantu Anda mengingatnya:

Januari selalu membuat perut gatal (いちがつ). Ini adalah penyakit aneh yang muncul setiap bulan Januari dan membuat perut Anda sangat gatal. Mungkin karena terlalu memanjakan diri di tahun baru.' WHERE id = '61669991-3228-4658-8971-f2fa5884a824'; -- 一月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari dua duri dan satu radikal dasar. Jika terdapat duri di tanah, siapa (terutama) yang ingin Anda hindari di area tersebut? Anda ingin anak Anda menghindarinya, karena anak-anak sangat ceroboh dan sering tidak memakai sepatu. Bayangkan betapa buruknya perasaan Anda jika Anda membiarkan seorang anak berjalan-jalan di atas duri-duri ini! Cukup buruk, menurutku.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '82f300ad-f592-4e9e-b41b-6deaa6602928'; -- 子 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "jempol kaki". Perhatikan bentuk karakter "卜" dan asosiasikan bentuk goresannya dengan "jempol kaki".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '3a00f184-d1d8-475b-ad89-2597ec5d2193'; -- 卜 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat saja kata ini. Menurut Anda apa maksudnya? Benar - itu adalah nama (Fuji) ditambah kanji untuk gunung. Gabungkan semuanya, dan Anda akan mendapatkan Gunung Fuji. Dalam bahasa Inggris, bagian "Mount(ain)" didahulukan. Dalam bahasa Jepang, namanya muncul di akhir, seperti nama ender さん, ちゃん, dan seterusnya. Anda juga dapat menambahkan 山 di akhir nama gunung mana pun, tidak hanya Gunung Fuji.', reading_mnemonic = 'Biasanya ふじ menggunakan kanji, tapi saya ingin Anda melihat penggunaan kanji ini karena lebih berguna daripada hanya digunakan di Gunung Fuji. Ini diperlakukan seperti kata jukugo (kombinasi kata kanji). Dalam kasus jukugo, biasanya digunakan bacaan on''yomi, artinya Anda hanya perlu mengingat bacaan on''yomi 山. Untungnya, Anda mempelajarinya saat mempelajari kanji, jadi Anda pasti sudah mengetahuinya!' WHERE id = 'dfb9983a-596b-44d3-b928-95bfcedf4c49'; -- ふじ山 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini:

Ada suara yang datang dari di dalam dinding. Kedengarannya seperti suara ketukan, ketukan, ketukan. Anda merobohkan tembok, dan ada pria menyeramkan berdiri di dalam. Dia adalah pengetuknya (なか).' WHERE id = '2dd7e3de-6689-4747-82f1-7e923bbf1092'; -- 中 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Pertama kita memiliki kata katakana, jadi dapat diasumsikan bahwa itu adalah kata pinjaman. Seperti banyak kata pinjaman lainnya, kata ini berasal dari bahasa Inggris. Katakan dengan lantang dan apa yang Anda punya? Itu benar, "meja". Kemudian muncul partikel の, yang menggabungkan dua kata benda. Terakhir ada 上, yang Anda pelajari berarti "naik" atau "di atas". Gabungkan semua bagian ini dan kita akan mendapatkan sebuah frase yang berarti di atas meja atau tabletop!', reading_mnemonic = 'Dalam frasa ini, 上 adalah kata yang berdiri sendiri, sehingga menggunakan bacaan yang sama seperti yang Anda pelajari saat mempelajari kosakatanya. Mudah untuk tetap di atas yang satu itu, bukan?' WHERE id = '8146e478-de7f-40e4-a08c-6bc07302a7af'; -- テーブルの上 (vocabulary)
UPDATE items SET meaning_mnemonic = 'silang ini adalah simbol dari angka sepuluh. Cara yang baik untuk mengingat hal ini adalah dengan memikirkan semua agama yang memiliki persilangan dan juga kumpulan puluhan yang penting.', reading_mnemonic = 'Bagaimana cara membaca kanji **sepuluh** (十)? Ingat saja bahwa **じゅう** sangat menyukai sepuluh! Hubungan erat ini akan membantu Anda mengingat bunyi **じゅう**.' WHERE id = 'f43953e0-7a2f-429b-8cc4-c6906e5cb449'; -- 十 (kanji)
UPDATE items SET meaning_mnemonic = 'Hari kedua atau hari kedua. Tidak peduli bagaimana Anda melihat kombinasi kanji ini, arti kata tersebut sangat masuk akal!', reading_mnemonic = 'Kata-kata yang menghitung hari menggunakan bacaan yang luar biasa. Meskipun ini adalah kata jukugo, namun menggunakan pembacaan kun''yomi untuk kedua kanjinya. Pikirkan tentang kata ini seperti ini:

Sirkus ada di kota akhir pekan ini dan Anda tidak sabar untuk sampai ke sana. Kamu ingin memamerkan mobil kaki barumu (ふつか) kepada semua badut sirkus. Namun Anda harus menggunakan kaki Anda untuk mencapainya dan hal itu akan memakan waktu dua hari! Sialan mobil kuno ini!' WHERE id = '4e41b329-44be-4bf8-a48e-08fdd951d390'; -- 二日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'wanita anak hanyalah perempuan!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '68c129bf-cb38-4afb-bcdb-c54de7626707'; -- 女子 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seperti halnya kebanyakan kosakata yang terdiri dari satu kanji, kosakata ini mempunyai arti yang sama dengan kanji yang sejajar dengannya, yaitu satu.', reading_mnemonic = 'Ketika sebuah kata vocab berdiri sendiri dan tidak memiliki okurigana (hiragana yang melekat pada kanji) yang terhubung dengannya, biasanya menggunakan bacaan kun''yomi. Namun angka merupakan pengecualian. Ketika sebuah angka berdiri sendiri, tanpa kanji atau okurigana, itu akan menjadi pembacaan on''yomi, yang Anda pelajari dengan kanji.  Ingatlah pengecualian ini untuk angka-angka saja dan Anda akan dapat membaca kosakata terkait angka di masa depan.' WHERE id = 'c6cf4ca6-1db4-48e3-b523-7b16c6a5df36'; -- 一 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika sebuah kanji berdiri sendiri dan tidak memiliki okurigana (hiragana yang melekat pada kanji), biasanya maknanya akan sama dengan kanji asalnya. Jadi dalam hal ini, Anda tahu bahwa kata tersebut berarti wanita.', reading_mnemonic = 'Jika sebuah kata berupa kanji tunggal tanpa okurigana (hiragana yang melekat pada kanji) maka cenderung menggunakan bacaan kun''yomi. Anda tidak mempelajari bacaan kun''yomi saat mempelajari kanji itu sendiri, jadi mari gunakan mnemonik untuk mengingat kosakatanya.

Ada seorang wanita di depanmu. Siapa dia? Dia adalah wanita yang tinggal di Jalan Kesembilan (おんな)!' WHERE id = 'f8436069-0a09-464e-8e5c-2285068e6dca'; -- 女 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Pastikan Anda selalu membawa air saat mengunjungi me zoo (みず). Itu kebun binatang dengan deretan kandang... aku. Dan aku haus!' WHERE id = '6e140148-cb40-47b6-9a75-3d39df32f18f'; -- 水 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sepuluh sepuluh ribu sama dengan seratus ribu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f889386c-7b11-4146-8f04-7e575db10730'; -- 十万 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Untuk membaca kanji 木 (pohon), bayangkan di setiap pohon ada **Muka** (もく) raksasa yang menatap Anda!' WHERE id = '54eebe13-d30d-408c-abe8-6917f70c3346'; -- 木 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hari kedelapan atau hari kedelapan. Tidak peduli bagaimana Anda melihatnya, kata ini sangat masuk akal.', reading_mnemonic = 'Kata-kata yang menghitung hari menggunakan bacaan yang luar biasa. Meskipun ini adalah kata jukugo, namun menggunakan pembacaan kun''yomi untuk kedua kanjinya. Pikirkan tentang kata ini seperti ini:

Setiap hari kedelapan kamu harus membeli yogurt untuk bahan bakar mobilmu (ようか). Mobil Anda menggunakan yogurt, namun perlu diisi ulang setiap delapan hari agar tetap berjalan. Sungguh merepotkan karena hanya SATU hari lebih dari seminggu. Dan seminggu terasa lebih baik. Oh baiklah.' WHERE id = '6a87db30-add6-4761-ba70-defecaa96d5f'; -- 八日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini diawali dengan kata kehormatan (お), sehingga kata apa pun yang muncul setelahnya menjadi lebih mulia. Lalu ada 父, yang lho artinya ayah. Terakhir, kita mempunyai nama kehormatan ender さん. Jadi ini cara yang bagus untuk mengucapkan ayah. Anda menggunakannya saat Anda berbicara dengan ayah Anda sendiri atau membicarakan dia dengan teman. Anda juga dapat menggunakan ini ketika berbicara tentang ayah teman Anda.

Dalam suasana yang lebih formal, Anda dapat menggunakan 父 (diucapkan ちち) untuk membicarakan ayah Anda sendiri dan お父様 untuk membicarakan ayah orang lain. Jangan khawatir, Anda akan mempelajari kanji terakhir dalam beberapa pelajaran. Sampai saat itu, diucapkan, おとうさま.', reading_mnemonic = 'Bagian yang harus Anda pelajari membaca adalah bagian 父. Ini menggunakan kun''yomi, yang tidak Anda pelajari saat membuat kanji. 

Bayangkan Anda membawa ayah Anda yang terhormat ke とうきょう. Dia selalu ingin pergi dan ini adalah perjalanan seumur hidup! Bayangkan berjalan-jalan di Tokyo bersama ayahmu, menikmati semua pemandangan.' WHERE id = '8c76f2f0-4e90-42ec-a73f-5b66b51bceaa'; -- お父さん (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini mengikuti pola "bilangan benda" yang mana terdapat kanji untuk bilangan ditambah つ di akhir. Setiap kali Anda melihat ini, Anda tahu kata itu berarti "____ benda". Mengetahui hal itu, selama Anda mengetahui kanji (yang Anda gunakan), Anda dapat mengetahui berapa banyak benda yang ada di dalamnya. Untuk yang ini, kanjinya adalah dua ditambah つ. Jadi, yang satu ini adalah dua hal.', reading_mnemonic = 'Karena semua kata "bilangan benda" mengikuti pola yang sama (angka ditambah つ), Anda hanya perlu mengingat bagian sebelum つ (lalu ingat bahwa つ ada di semua ini). Semua bacaannya adalah bacaan kun''yomi, artinya kita harus menggunakan mnemonik untuk mengingatnya (Anda tahu bacaan on''yomi di bagian kanji).

Jadi, barang apa yang kamu punya dua? dua hal yang Anda miliki terdiri dari satu kaki dan satu kaki lainnya (ふた). Ingat dari on''yomi bagaimana Anda memiliki dua lutut (untuk bacaan に)? Sekarang lihat lebih jauh ke bawah kaki Anda pada satu kaki lalu ke kaki lainnya. Dua kaki!' WHERE id = 'dc1f8a97-18db-4680-ab51-25662c0b3431'; -- 二つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini mengikuti pola "bilangan benda" yang mana terdapat kanji untuk bilangan ditambah つ di akhir. Setiap kali Anda melihat ini, Anda tahu kata itu berarti "____ benda". Mengetahui hal itu, selama Anda mengetahui kanji (yang Anda gunakan), Anda dapat mengetahui berapa banyak benda yang ada di dalamnya. Untuk yang ini, kanjinya adalah sembilan ditambah つ. Jadi, yang satu ini adalah sembilan hal.', reading_mnemonic = 'Karena semua kata "bilangan benda" mengikuti pola yang sama (angka ditambah つ), Anda hanya perlu mengingat bagian sebelum つ (lalu ingat bahwa つ ada di semua ini). Semua bacaannya adalah bacaan kun''yomi, artinya kita harus menggunakan mnemonik untuk mengingatnya (Anda tahu bacaan on''yomi di bagian kanji).

Benda apa yang kamu punya sembilan? sembilan hal yang anda miliki adalah sembilan buah kelapa (ここの). Bayangkan diri Anda menyulap sembilan buah kelapa di udara. Cobalah menghitungnya saat Anda melakukan ini, sampai pada sembilan hal. Setelah Anda selesai menyulapnya, susunlah menjadi persegi di tanah. Tiga buah kelapa kali tiga buah kelapa. Sekarang Anda harus mengingat cara membaca sembilan hal.' WHERE id = '4d44dce3-36da-4ef6-93c5-a4cb040f6c38'; -- 九つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji ini menggabungkan besar dan orang. Jika Anda masih anak-anak, bagaimana pendapat Anda tentang orang dewasa? Anda hanya menganggap mereka seperti orang besar. Itu sebabnya kombinasi kanji ini berarti adult, dan jika digunakan seperti kata sifat, artinya matang.', reading_mnemonic = '"Aku sudah dewasa, artinya aku mempunyai tanggung jawab sebagai orang dewasa. Oh, Toner (おとな)? Aku memerlukannya untuk printerku yang buruk..." ... sekarang aku merasa sangat sedih karena kamu memiliki printer yang sangat buruk yang kehabisan toner setiap hari. Ohhh Toner!' WHERE id = '9620020b-b772-4a72-b76f-0f3c34b36e5d'; -- 大人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa kanji 下 berarti turun dan さい terdengar seperti kata "sigh". Anda perlu meminta sesuatu kepada seseorang, jadi Anda menunduk, menghela nafas, dan berkata tolong berikan saya benda itu. Kamu malu karena harus bertanya. Tapi Anda masih membutuhkannya. Tolong, tolong berikan padaku!

Kami hanya menggunakan ください versi kanji ini ketika kami meminta sesuatu, itu sebabnya "tolong beri aku". Jika Anda hanya mengatakan "tolong", Anda tidak memerlukan kanji sama sekali!', reading_mnemonic = 'Bacaan kata ini merupakan bacaan yang luar biasa. Anda hanya perlu mengingat bagian くだ (karena さい sudah ada dalam bentuk hiragana). Jadi, pikirkan kenapa kamu harus bersikap sopan pada anak nakal ini. Ternyata, jika Anda tidak melakukan hal ini, dia mempunyai kekuatan untuk memulai Kudeta terhadap Anda dan keluarga Anda, yang menjalankan pemerintahan. Bayangkan saja diri Anda berpikir berulang kali, "Oke... Saya harus bersikap baik kepada anak ini. Jika tidak... dia akan memulai Kudeta... dan itu akan menghancurkan keluarga saya..." Anda berjalan di atas es tipis, di sini.' WHERE id = '184f3971-0d33-4d34-b342-030dc45059bc'; -- 下さい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Vocab ini memiliki okurigana, yaitu bagian hiragana yang muncul setelah kanji. Ketika okurigana suatu kosakata mengeluarkan bunyi "う/oo" (dalam hal ini, kita memiliki る), sering kali itu akan menjadi kata kerja. Jadi dalam hal ini, kanji 入 adalah enter. Kosakata 入る adalah untuk dimasukkan. Kami hanya mengambil kanji dan menggunakannya dalam kata kerja!', reading_mnemonic = 'Jika kosakatanya berupa kanji tunggal dengan okurigana, kemungkinan besar itu adalah bacaan kun''yomi, yang biasanya tidak Anda pelajari dalam kanji (biasanya Anda mempelajari bacaan on''yomi). Jadi, mari kita pelajari bacaan kun''yomi untuk kata ini beserta artinya.

Ketika Anda memasuki ruangan, apa yang Anda lakukan? Anda mengucapkan "Hai" (はい) kepada semua orang sampai pada titik yang tidak masuk akal. "Halo. Oh hai Frank. Oh hai Susan. Oh hai lampu."' WHERE id = '40e810c1-efb9-403d-9ec9-60919dc0d3f4'; -- 入る (vocabulary)
UPDATE items SET meaning_mnemonic = 'sekarang hari adalah hari apa? Oh, ini hari ini.', reading_mnemonic = 'Pembacaan kata ini merupakan pengecualian, meskipun kata itu sendiri sangat umum dan berguna. Saat Anda memikirkan "hari ini", pikirkan tentang apa yang harus Anda lakukan hari ini untuk bekerja.

Anda harus bekerja di salah satu kios mall tersebut (きょう). Coba pikirkan betapa sedihnya Anda harus melakukan ini hari ini. Hari yang buruk. Di luar cerah dan Anda terjebak di mal yang menjaga kios kelomang ini.

Catatan: Mnemonik pembacaan ini cukup jauh dari pembacaan sebenarnya, sejauh menyangkut mnemonik membaca. Gunakan ini untuk mendekatkan diri Anda, dan kemudian gunakan otak Anda sendiri untuk melanjutkan perjalanan ke sana. Yang ini tidak akan semudah kebanyakan yang lain, tapi lakukanlah hafalan kuno yang baik dan Anda akan baik-baik saja. Untungnya, saya tidak akan meminta Anda melakukan sebanyak ini. :)' WHERE id = '6d2aa38a-7a07-4512-9219-e73902c56ad4'; -- 今日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini mengikuti pola "bilangan benda" yang mana terdapat kanji untuk bilangan ditambah つ di akhir. Setiap kali Anda melihat ini, Anda tahu kata itu berarti "____ benda". Mengetahui hal itu, selama Anda mengetahui kanji (yang Anda gunakan), Anda dapat mengetahui berapa banyak benda yang ada di dalamnya. Untuk yang ini, kanjinya adalah delapan ditambah つ. Jadi, yang satu ini adalah delapan hal.', reading_mnemonic = 'Karena semua kata "bilangan benda" mengikuti pola yang sama (angka ditambah つ), Anda hanya perlu mengingat bagian sebelum つ (lalu ingat bahwa つ ada di semua ini). Semua bacaannya adalah bacaan kun''yomi, artinya kita harus menggunakan mnemonik untuk mengingatnya (Anda tahu bacaan on''yomi di bagian kanji).

Jadi delapan hal apa yang Anda miliki? Anda memiliki delapan kapal pesiar (やっつ). Silakan menghitungnya. Mereka cantik. Juga, pastikan untuk tidak bingung dengan mnemonik bacaan khusus ini. Ini mencakup つ, meskipun つ berada di luar bacaan yang perlu Anda pelajari (hanya membuat segalanya lebih mudah bagi Anda secara keseluruhan). Karena Anda dapat melihat つ di luar, hal ini tidak akan terlalu sulit bagi Anda.' WHERE id = '156f25a9-ea82-4023-b519-6c790aa0b39d'; -- 八つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti di bawah jadi versi kata kerjanya adalah ketika Anda meletakkan sesuatu di bawah Anda. Itu adalah untuk menurunkan sesuatu. Bisa juga berarti menggantung sesuatu, seperti lampu di langit-langit.

Ini adalah kata kerja transitif, artinya kata kerja tersebut dilakukan oleh satu entitas ke entitas lainnya. Dengan kata lain, Anda menurunkan sesuatu. Seperti ekspektasi Anda yang terlalu tinggi terhadap diri Anda sendiri. Tenang saja!', reading_mnemonic = 'Karena kata ini memiliki okurigana (hiragana yang melekat pada kanji), Anda tahu bahwa kemungkinan besar itu adalah pembacaan kun''yomi, yang tidak Anda pelajari dengan kanji. Berikut ini mnemonik untuk membantu Anda:

Anda ingin menurunkan sesuatu. Dalam hal ini, itu adalah pohon, jadi kamu memerlukan gergaji (さ). Turunkan pohon ke tanah dengan hati-hati sambil Anda melihatnya perlahan-lahan!' WHERE id = '74e16724-5105-4b56-a7b6-aabeec287990'; -- 下げる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti di atas dan kata kerja ini terkait dengan makna tersebut. Artinya mengangkat sesuatu atau mengangkat sesuatu. Ini adalah kata kerja transitif, artinya Anda melakukan sesuatu terhadap hal lain. Anda meningkatkan sesuatu. Seperti tanganmu!', reading_mnemonic = 'Karena kata ini memiliki okurigana (hiragana yang melekat pada kanji), Anda tahu bahwa kata tersebut mungkin akan menggunakan pembacaan kun''yomi, yang tidak Anda pelajari dengan kanji. Berikut ini mnemonik untuk membantu Anda:

Anda ingin mengangkat sesuatu, dan sesuatu itu aardvark (あ) di atas kepala Anda. Mengapa? Karena meski lidahnya panjang, aardvark tidak bisa menjangkau semut yang ada di pepohonan. Namun saat Anda memelihara aardvark ini, ia bisa menyerang semut-semut lezat itu!' WHERE id = 'd00b8489-e07a-4920-b4d2-f6a8e128479f'; -- 上げる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini mengikuti pola "bilangan benda" yang mana terdapat kanji untuk bilangan ditambah つ di akhir. Setiap kali Anda melihat ini, Anda tahu kata itu berarti "____ benda". Mengetahui hal itu, selama Anda mengetahui kanji (yang Anda gunakan), Anda dapat mengetahui berapa banyak benda yang ada di dalamnya. Untuk yang ini, kanjinya adalah satu ditambah つ. Jadi, yang satu ini adalah satu hal.', reading_mnemonic = 'Karena semua kata "bilangan benda" mengikuti pola yang sama (angka ditambah つ), Anda hanya perlu mengingat bagian sebelum つ (lalu ingat bahwa つ ada di semua ini). Semua bacaannya adalah bacaan kun''yomi, artinya kita harus menggunakan mnemonik untuk mengingatnya (Anda tahu bacaan on''yomi di bagian kanji).

Jadi, Anda punya satu hal. Satu hal apa yang kamu punya? Anda memiliki salah satu He-Man''s Toes, alias satu He-Toe (ひと). Jadi barang apa yang hanya kamu punya satu saja? Anda punya satu He-Toe. Bayangkan He-Man berjalan-jalan dengan salah satu jari kakinya hilang, mencoba menemukan Anda sehingga dia bisa mendapatkannya kembali. Setidaknya kamu bisa berlari lebih cepat darinya sekarang.' WHERE id = '4b3d2f1f-1094-4262-b2e7-b6fd40087455'; -- 一つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tanda お membuat kata tersebut lebih sopan. Kamu mengangkat gelar "kakak perempuan" karena kamu adalah adik yang baik. Kalau tidak, arti kata ini sama dengan kanji - hanya perasaannya saja yang berbeda. Anda juga dapat menggunakan kata ini untuk merujuk pada wanita berpenampilan muda yang tidak Anda kenal, seperti dalam "Permisi miss!"', reading_mnemonic = 'Bacaannya juga berbeda. Ada beberapa hiragana yang melekat padanya, yang merupakan petunjuk bahwa ini menggunakan pembacaan kun''yomi. Mari gunakan mnemonik untuk mempelajari bacaan itu. 

Bayangkan kakak perempuan Anda (meskipun Anda tidak memilikinya). Dia, untuk beberapa alasan, adalah seekor kuda. Bayangkan mengelusnya, memberinya wortel, dan melakukan hal-hal lain yang berhubungan dengan kuda bersamanya. Apa kata kuda? Mereka bilang nehhhh (ねえ).' WHERE id = '711830bf-31e8-471d-b4d8-9d1245f68243'; -- お姉さん (vocabulary)
UPDATE items SET meaning_mnemonic = 'Setelah Anda melepas lentera dari tenda, kami akan siap untuk keberangkatan. Kita tidak bisa meninggalkan lentera di dalam tenda; itu bahaya kebakaran. Sebaiknya kami membawanya sebelum keberangkatan. Apakah kamu tidak setuju?', reading_mnemonic = 'Untuk mengingat cara baca kanji **Keberangkatan** (発), bayangkan Anda sedang membawa **Hari/Harta** untuk ditaruh di atas keberangkatan. Kejadian unik ini mengingatkan Anda pada bunyi **はつ**!' WHERE id = '4b11e285-2c7b-40ce-8d1c-dc9b15eea18b'; -- 発 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada serangga meluncurdi bawah meja Anda, tertiup oleh angin. Anda mencoba meraih serangga itu tetapi serangga itu terus meluncur melewati tangan Anda karena angin yang sangat kencang. Ini juga akan mulai membuat Anda terpesona!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Angin** (風), bayangkan Anda sedang membawa **Puyuh/Fosil** untuk ditaruh di atas angin. Kejadian unik ini mengingatkan Anda pada bunyi **ふう**!' WHERE id = 'fdaecbbd-e695-4093-8ba2-70f12f7d6c87'; -- 風 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda akan melihatnya melekat pada kata lain... seperti "daging" atau "ikan". Saat Anda melihat ini, Anda akan mengetahui bahwa ini adalah ___ store, sehingga kata ini berarti store (sama seperti kanji).', reading_mnemonic = 'Bacaannya adalah bacaan kun''yomi. Jangan mengetik 〜 saat menulis jawabannya. Itu hanya untuk memberi tahu Anda bahwa biasanya ada sesuatu yang melekat pada kata ini.' WHERE id = 'e35b69bb-a1b0-45b0-bc46-b65e0daf27fe'; -- 〜屋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Biji-bijian terlihat seperti berapi di musim gugur. Semuanya berubah menjadi merah, oranye, dan coklat, warna api. Menyenangkan juga membakar biji-bijian di musim gugur, karena cuaca semakin dingin.', reading_mnemonic = 'Tahukah Anda bahwa **Musim gugur** (秋) ini sebenarnya dibuat dari tumpukan **あき**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **あき**.' WHERE id = 'b969a549-ccf0-40e8-bb6d-77d83f9d5986'; -- 秋 (kanji)
UPDATE items SET meaning_mnemonic = 'Orang yang berkeliaran di sekitar kuil mungkin hanya mencoba untuk menunggu. Mereka tidak bermaksud terlihat seperti sedang merencanakan sesuatu yang tidak baik, tetapi sulit untuk menunggu tanpa terlihat curiga saat Anda menunggu di luar kuil.', reading_mnemonic = 'Bagaimana cara membaca kanji **Tunggu** (待)? Ingat saja bahwa **Tali/Tari** sangat menyukai tunggu! Hubungan erat ini akan membantu Anda mengingat bunyi **たい**.' WHERE id = 'fbd67782-0b46-40d8-b965-442611010a20'; -- 待 (kanji)
UPDATE items SET meaning_mnemonic = 'Satu-satunya wanita di kota ini adalah kakak perempuan Anda. Dia satu-satunya wanita yang dikelilingi oleh sekelompok pria, tapi dia mengejar mimpinya di kota besar.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kakak Perempuan** (姉), bayangkan Anda sedang membawa **Singa/Silet** untuk ditaruh di atas kakak perempuan. Kejadian unik ini mengingatkan Anda pada bunyi **し**!' WHERE id = '784e2a30-6fa1-4bbb-b719-9f381b929111'; -- 姉 (kanji)
UPDATE items SET meaning_mnemonic = 'hati serigala> berada di penjara, jadi Anda harus cepat untuk membebaskannya. Namun jangan terlalu mendadak, atau jantungnya tidak akan bertahan. Dan kematian serigala akan menimpamu.', reading_mnemonic = 'Bagaimana cara membaca kanji **Cepat** (急)? Ingat saja bahwa **Kura-kura** sangat menyukai cepat! Hubungan erat ini akan membantu Anda mengingat bunyi **きゅう**.' WHERE id = '688007ab-616f-4f11-ac69-e74e9a9a1663'; -- 急 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji, あき.' WHERE id = '9df50609-4251-4b54-bee0-ac0b1c6f9d0a'; -- 秋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Lihat bendera di radikal ini? Ada sebuah tiang dengan bendera di ujungnya, tertiup angin. Pada dasarnya, radikal ini terlihat seperti sebuah bendera.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7d28f16a-ffde-4134-a39f-3d10b0d77a98'; -- 尸 (radical)
UPDATE items SET meaning_mnemonic = 'matahari di pusat langit memancarkan cahayanya, yang memantulkan segala sesuatu di sekitarnya.', reading_mnemonic = 'Tahukah Anda bahwa **Merenungkan** (映) ini sebenarnya dibuat dari tumpukan **Ember/Elang**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **えい**.' WHERE id = '8583e778-cc4a-4a2f-8e73-73190b71cfd2'; -- 映 (kanji)
UPDATE items SET meaning_mnemonic = 'suara yang keluar dari mulut Anda adalah Anda sedang berbicara. Bayangkan diri Anda mengucapkan sesuatu dan kata-kata yang keluar dari mulut Anda. Mereka dibengkokkan dengan cara berbeda dan memiliki warna berbeda, menyorot pengucapan Anda pada kata dan frasa tertentu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ce222b7e-155f-4b52-a04e-9b9430b48ded'; -- 発音 (vocabulary)
UPDATE items SET meaning_mnemonic = 'suara dibacaing. Apa ini...? Tunggu sebentar, pikirkan bahasa Jepang dan kanji. Bacaan apa yang menggunakan bunyi-bunyian dari tempat lain, khususnya Tiongkok? Itulah bacaan Cina alias on''yomi. Kedengarannya familier?', reading_mnemonic = 'Bacaan untuk 音 adalah 音読み. 読み menggunakan kun''yomi, anehnya. Cara untuk mengacaukan satu kata yang seharusnya menjadi on''yomi, Jepang. Jalan. Ke. Pergi.' WHERE id = 'b662c80a-8bf7-4db2-984e-c59a1a1b04d3'; -- 音読み (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji berat dan kanji berat adalah sama.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Berat** (重), bayangkan Anda sedang membawa **じゅう** untuk ditaruh di atas berat. Kejadian unik ini mengingatkan Anda pada bunyi **じゅう**!' WHERE id = 'b401f4fd-5fa3-4789-b55c-afeb84890183'; -- 重 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda keluar lalu melakukan keberangkatan. Ini hanyalah sebuah keberangkatan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. しゅつ dipersingkat dan はつ berubah menjadi ぱつ. Pantas saja Anda ingin berangkat, ingin lepas dari bacaan gila seperti ini.' WHERE id = 'ec8dcbae-ab16-4d98-864f-cfc9f9bb244b'; -- 出発 (vocabulary)
UPDATE items SET meaning_mnemonic = 'matahari terbit dari tanah, dan di atasnya terdapat udang raksasa. Ia tidak melakukan apa pun kecuali setiap hari tepat pada siang, saat ia memberi tahu Anda waktunya. "Hei teman-teman, ini siang, mmk?"', reading_mnemonic = 'Ketika Anda sedang melihat **Siang** (昼), tiba-tiba muncul sesosok **ひる** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **ひる**.' WHERE id = 'a210c5a5-c45b-49b2-99b4-1b244cf978a6'; -- 昼 (kanji)
UPDATE items SET meaning_mnemonic = 'sesuatu yang Anda bangun adalah bangunan. Tidak banyak hal lain yang Anda bangun, setidaknya tidak sampai sejauh ini.', reading_mnemonic = 'Bacaannya agak aneh. Ini adalah bacaan kun''yomi secara keseluruhan, yang berarti pengetahuan Anda tentang 建てる semoga dapat berperan di sini. Sebuah bangunan adalah sesuatu yang Anda bangun, jadi bagaimana Anda mengatakan "membangun"? Itu 建てる (たてる). Karena itu adalah sesuatu yang Anda buat, itu adalah たてもの. Bacaan ini agak membingungkan, tapi semoga suatu saat nanti Anda akan mengerti jika terlalu sering salah! Mungkin jika Anda memikirkan bangunan tempat Anda berada dan menyebutnya 建物 beberapa kali, bangunan itu akan lebih meresap?' WHERE id = '41797880-6724-42f5-81f2-dfa5588c4768'; -- 建物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda sudah mempelajari kanji 市, yang artinya kota. Kami juga memperlakukannya sebagai radikal, karena ini muncul di banyak kanji lainnya. Jika digunakan sebagai kata radikal, tetap berarti kota.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1123c6d2-df83-441c-8c70-9b3690ef4b8d'; -- 市 (radical)
UPDATE items SET meaning_mnemonic = 'Seekor domba mengendarai tsunami dalam gaya Barat klasik. Yang saya maksud dengan gaya Barat adalah domba yang mengenakan pakaian koboi dan memasang pelana di atas gelombang tsunami untuk menungganginya. Itu adalah rodeo tsunami dan domba gila ini mengendarai gelombang tsunami dengan gaya klasik Barat. 

Kanji ini juga berarti lautan, karena konon orang-orang dari "Barat" yang memiliki "Gaya Barat" berasal dari seberang lautan. Mereka adalah “Manusia Laut” dalam pengertian ini. Anda pasti ingin memahami arti kosakata ini nanti.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Gaya Barat** (洋), bayangkan Anda sedang membawa **Yoga** untuk ditaruh di atas gaya barat. Kejadian unik ini mengingatkan Anda pada bunyi **よう**!' WHERE id = 'ee941b70-396e-4a52-a8e8-e02125aac2c0'; -- 洋 (kanji)
UPDATE items SET meaning_mnemonic = 'Saat kamu mempunyai perasaan (気持ち) yang いい (yang artinya "baik", kamu mempunyai perasaan yang baik.', reading_mnemonic = 'Pembacaannya berasal dari kosakata 気持ち, jadi jika Anda mengetahuinya (atau kosakata 気 dan 持ち) Anda boleh saja yang satu ini. Mungkin bahkan merasa senang tentang hal itu?' WHERE id = '0f0fb56e-ce1e-4a78-9144-ef574df11449'; -- 気持ちいい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Satu-satunya tindakan yang harus Anda lakukan di rumah saya adalah pekerjaan rumah dan tugas saya. Ini bukan hotel. Bergeraklah! Bersihkan piringku!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'c97ca745-c2a5-4a31-93c6-33a8a8fd5fd4'; -- 家事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda menjumpai malaikat mengenakan topi yang ditutupi dengan bunga. Jadi, Anda melakukan satu-satunya hal yang wajar. Ambil malaikat ini, potong kecil-kecil, dan keringkan. Kemudian, Anda membuat teh dari semua potongan malaikat yang sudah dikeringkan. Tapi kamu memakai topi itu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Teh** (茶), bayangkan Anda sedang membawa **ちゃ** untuk ditaruh di atas teh. Kejadian unik ini mengingatkan Anda pada bunyi **ちゃ**!' WHERE id = '0d7f8c33-ef38-4053-8c75-79604c984584'; -- 茶 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda ingin barang berangkat dari toko Anda sehingga Anda harus menjual. Anda menjual semua ini untuk dijual. Anda menjual item ini.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '5d0d1e78-685d-4bb4-9784-aaea03f8fd50'; -- 発売 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa yang terjadi jika Anda meletakkan permukaan datar di atas sepasang kaki? Anda mendapatkan tabel.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5c84d8fd-049a-475a-815c-fe81e071db07'; -- 几 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

adikmu sangat menyukai emote (いもうと). Carilah kata ini jika Anda bukan seorang gadis remaja. Bayangkan saja dia mengirimi Anda ini di ponsel Anda berulang kali. Kamu bilang ke adik perempuanmu: "HEI, BERHENTI KIRIM EMOTES AKU."' WHERE id = '5d6bb009-b0c9-4c4e-8857-460d5357d230'; -- 妹 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda memiliki dua berat benda, Anda memiliki double dan dual yang berat (setidaknya dibandingkan dengan satu). 

Kata ini merupakan awalan yang ditempelkan pada kata lain untuk menunjukkan bahwa ia bersifat "ganda". 二重 waktu kanji!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ebfbb8d5-0146-45a5-977e-b56f6353145f'; -- 二重 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dengan 待ち Anda tahu bahwa Anda sedang menunggu, tapi apa itu ぼうけ? Ternyata itu versi panjang dari ボケ yang artinya idiot. Pada dasarnya, dalam hal ini Anda adalah seorang idiot yang menunggu. Mengapa? karena kamu berdiri.', reading_mnemonic = 'Pembacaan 待ち berasal langsung dari 待つ. Anda sudah tahu latihannya sekarang.' WHERE id = '5e10b6c8-3f61-4408-aa01-95b4c26c5aae'; -- 待ちぼうけ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada sesuatu yang pribadi di mulutmu. Anda merahasiakannya karena Anda tidak ingin orang lain menghakimi Anda. Mengapa? Karena itu adalah serangga. Anda suka makan serangga, tetapi masyarakat sepertinya menganggapnya salah. Jangan khawatir, teman. Suatu hari nanti seluruh dunia akan menerima makan serangga seperti Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'e5137206-140c-4345-a13c-989ef04067b2'; -- 虫 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah domba dan Anda melihatnya dari atas. Lihat kedua telinga dan tubuh domba menghadap ke belakang (dengan seluruh bulunya menyembul ke samping) dan kemudian ekor kecil mencuat ke belakang. Domba yang lucu!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7eaaf6bc-578d-4b8f-9bf5-8374a9bb9e02'; -- 羊 (radical)
UPDATE items SET meaning_mnemonic = 'Saat Anda membuat menggambar dari pengukuran yang ingin Anda lakukan di papan tulis, Anda sedang menyusun rencana untuk melakukan sesuatu. Segala sesuatu memerlukan semacam pengukuran, jadi menyusun pengukuran itu adalah rencana Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Bacaan untuk 画 adalah bacaan sekunder (かく), jadi perhatikanlah itu.' WHERE id = '14a7f30c-cbe7-4de8-85ee-bd72fa5d848e'; -- 計画 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini hanyalah biru langit (alias langit biru!).', reading_mnemonic = 'Anda mungkin berpikir bahwa kata ini akan menggunakan bacaan on''yomi untuk membacanya, tetapi ternyata tidak (mengacungkan tangan marah itu pada dewa kanji!). Sebaliknya, ini adalah kun''yomi ganda, mungkin karena kata ini benar-benar seperti dua kata terpisah yang disatukan, "biru" dan "langit". Di level sebelumnya Anda membuka kunci dua kata terpisah ini, mempelajari bacaannya. Artinya, Anda juga harus bisa membaca ini. 

Satu catatan singkatnya adalah fiksi rendaku dari 空 juga. Menjadi ぞら.' WHERE id = '7c52342e-5d9f-4aed-b222-7db83a9bfaab'; -- 青空 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saya akui, semacam tenda yang aneh, tapi tenda yang akan melindungi Anda dari benda-benda yang mencoba masuk (itulah sebabnya tenda ini memiliki semua paku). Itu yang terbaik yang dapat Anda lakukan, mengingat Anda berada di dalam bangunan kain/plastik.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a7295854-9e5c-44e6-a89f-852b7ed0e5f8'; -- 癶 (radical)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 映る adalah "untuk direfleksikan". Sekarang Anda sedang melakukan refleksi, yang sebenarnya memproyeksikan (cahaya). Itu sebabnya kata ini memproyeksikan.', reading_mnemonic = 'Bacaannya sama dengan 映る. Selama kamu tahu bacaan 映る kamu pasti bisa membaca yang ini juga.' WHERE id = '35944b9d-f242-4800-86de-8856a88cae20'; -- 映す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 思う artinya berpikir (jadi 思い adalah sebuah pemikiran). Anda juga tahu bahwa 出す berarti menghapus. Jadi, ketika Anda menghilangkan sebuah pikiran, Anda sedang mengingat sesuatu. Ini adalah kata kerja, jadi bentuk kata kerja mengingat sesuatu adalah mengingat.', reading_mnemonic = 'Bacaan kata ini adalah bacaan kun''yomi. Anda seharusnya mengetahui kata 思う dan 出す serta bacaannya, jadi Anda seharusnya bisa membaca kata ini jika Anda mengetahui kata-kata tersebut.' WHERE id = '65435859-1ba4-48b9-97f6-e100e5632881'; -- 思い出す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini terlihat seperti seseorang yang mengambil langkah besar dan meregangkan tubuhnya. Apakah itu terdengar seperti sesuatu yang Anda tahu? Seharusnya begitu, karena itulah yang Anda lakukan dalam yoga. Regangkan kaki dan lengan Anda sampai Anda terlihat radikal. Besar! Anda sedang melakukan yoga sekarang!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'f3e8d3a4-4a35-45a9-aa97-114af91de63b'; -- 廴 (radical)
UPDATE items SET meaning_mnemonic = 'Pakaian gaya Barat Pakaian hanyalah Pakaian Barat (atau Pakaian gaya Barat). Namun saat ini, karena orang Jepang selalu memakai pakaian Barat, kami menggunakannya hanya untuk mengartikan pakaian. Kami membicarakan hal-hal selain kimono, dll.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '877256a0-8066-4ac5-9240-5bffb7ef14fe'; -- 洋服 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda perlu menggerakkan jari Anda di sekitar kuil jika Anda ingin memegang itu. Apakah kuilnya terlalu besar? Ada juga kuil-kuil kecil yang bisa Anda beli di toko suvenir kuil.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Tunggu** (持), bayangkan Anda sedang membawa **Juri/Jalan** untuk ditaruh di atas tunggu. Kejadian unik ini mengingatkan Anda pada bunyi **じ**!' WHERE id = '41630936-df8f-4972-bfd4-d03503307c39'; -- 持 (kanji)
UPDATE items SET meaning_mnemonic = 'bangku yurt selalu ditempatkan pada derajat tertentu. Derajatnya berubah bergantung pada kejadian tertentu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Derajat** (度), bayangkan Anda sedang membawa **ど** untuk ditaruh di atas derajat. Kejadian unik ini mengingatkan Anda pada bunyi **ど**!' WHERE id = '0d6a927b-b81a-48eb-9ad6-eca2e289c754'; -- 度 (kanji)
UPDATE items SET meaning_mnemonic = 'Semua sawah dimasukkanke dalam dunia.', reading_mnemonic = 'Bagaimana cara membaca kanji **Dunia** (界)? Ingat saja bahwa **Kail/Kain** sangat menyukai dunia! Hubungan erat ini akan membantu Anda mengingat bunyi **かい**.' WHERE id = 'e922fc78-d5c4-42dc-938a-d758e852e91c'; -- 界 (kanji)
UPDATE items SET meaning_mnemonic = 'Untuk beberapa alasan, Anda berdiriberada di atas matahari. Ini jelas sangat panas, tapi hal yang paling Anda perhatikan adalah suara Anda terbakar.', reading_mnemonic = 'Tahukah Anda bahwa **Suara** (音) ini sebenarnya dibuat dari tumpukan **Onta/Obor**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **おん**.' WHERE id = 'b3cc1beb-bcec-47cf-a0ca-843bc906056d'; -- 音 (kanji)
UPDATE items SET meaning_mnemonic = 'tsunami akan datang, jadi arahkan senjata Anda ke luar jendela ke arah tsunami tersebut. "Sebaiknya kau kembali, laut, atau aku akan menembak!"', reading_mnemonic = 'Bagaimana cara membaca kanji **Laut** (海)? Ingat saja bahwa **Kail/Kain** sangat menyukai laut! Hubungan erat ini akan membantu Anda mengingat bunyi **かい**.' WHERE id = '6034ce0d-13b2-4a67-8ee9-3929271f7ca2'; -- 海 (kanji)
UPDATE items SET meaning_mnemonic = 'Di tanah Anda telah membuat atap di atas tanah tempat Anda dapat berada dalam pribadi. Ini adalah ruangan Anda! Hanya itu saja sebuah ruangan, kau tahu? Tempat tertutup dan pribadi di mana Anda dapat memiliki waktu sendiri.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Menyukai** (室), bayangkan Anda sedang membawa **Silet/Singa** untuk ditaruh di atas menyukai. Kejadian unik ini mengingatkan Anda pada bunyi **しつ**!' WHERE id = '2896f5bc-7f14-44ea-bb53-1adbc0ee50f1'; -- 室 (kanji)
UPDATE items SET meaning_mnemonic = 'yoga brush ajaib Anda memungkinkan Anda membangun apa yang ada dalam pikiran Anda.', reading_mnemonic = 'Tahukah Anda bahwa **Membangun** (建) ini sebenarnya dibuat dari tumpukan **Kendi/Kencir**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **けん**.' WHERE id = '1b2c4b31-02d3-4649-9a03-63c4f867664e'; -- 建 (kanji)
UPDATE items SET meaning_mnemonic = 'batu lentera adalah cara terbaik untuk menajamkan apa pun, bahkan dalam kegelapan. Pisaumu, garpumu, sendokmu, dan bahkan pedangmu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Pertajam** (研), bayangkan Anda sedang membawa **Kendi/Kencir** untuk ditaruh di atas pertajam. Kejadian unik ini mengingatkan Anda pada bunyi **けん**!' WHERE id = '444afba2-a4e4-447d-8e80-0296fca6614e'; -- 研 (kanji)
UPDATE items SET meaning_mnemonic = 'Saat Anda melihat musim semi matahari Anda tahu bahwa ini akhirnya adalah musim musim semi.', reading_mnemonic = 'Tahukah Anda bahwa **Musim semi** (春) ini sebenarnya dibuat dari tumpukan **はる**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **はる**.' WHERE id = '13832f40-886f-4950-af11-4a417e28513f'; -- 春 (kanji)
UPDATE items SET meaning_mnemonic = 'Di bawah atap ini ada babi. Babimu, karena itu adalah rumahmu! Anda menyimpan babi Anda di dalam tempat yang nyaman dan hangat. Dia adalah anggota keluargamu, jadi dia berhak tinggal di rumahmu juga.', reading_mnemonic = 'Bagaimana cara membaca kanji **Rumah** (家)? Ingat saja bahwa **Kaki/Kaca** sangat menyukai rumah! Hubungan erat ini akan membantu Anda mengingat bunyi **か**.' WHERE id = '0c5449bc-67db-4653-9b37-1b0d3be05cf4'; -- 家 (kanji)
UPDATE items SET meaning_mnemonic = 'kakak perempuanmu dan adik perempuanmu. Ini adalah saudara perempuan Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'af43a8e6-a451-48d1-8f5d-77f635a8eb2e'; -- 姉妹 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda mengunjungi laut. Anehnya, ia menanyakan siapa yang berkunjung. Anda begitu penuh dengan diri sendiri (bahkan di depan laut/samudera) sehingga Anda menjawab: "um, saya?" (うみ). Bayangkan diri Anda merasa sepuas ini.' WHERE id = '0818692d-addf-4cd0-9bb3-8dd236f25a39'; -- 海 (vocabulary)
UPDATE items SET meaning_mnemonic = 'di luar laut adalah suatu tempat di luar negeri. Bisa juga asing atau abroad jika kata-kata tersebut lebih mudah Anda ingat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'aa67a689-2d32-466b-8742-f710e33a5a51'; -- 海外 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa warna dari teh? Anda mungkin mengira warnanya hijau, dengan asumsi itu bahasa Jepang... tapi kata ini berasal dari Tiongkok. Apa warna teh Cina? Cenderung lebih coklat. Pikirkan teh Oolong, misalnya.', reading_mnemonic = 'Bacaan kedua kanji tersebut adalah bacaan yang Anda pelajari dengan kanji tersebut, artinya Anda seharusnya sudah bisa membacanya.' WHERE id = '37ddac37-596a-462b-b5a9-aa811c6aa834'; -- 茶色 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Apa yang Anda lakukan di rumah Anda? Kamu makan telur (いえ), itulah yang terjadi. Anda makan telur tiga kali sehari, setiap hari. Anda sangat suka makan telur di rumah Anda!' WHERE id = '1d06972c-7cb1-4467-b3e2-1d78b0243088'; -- 家 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dalam sekarang kejadian Anda akan mempelajari kanji Anda, bukan? Kata ini berarti kali ini. Meskipun "kali ini", namun ada perasaan next time. Ini seperti mengatakan "oke, kali ini kita akan mendapatkannya" dimana "kali ini" sebenarnya berarti "lain kali", membuatnya sedikit berbeda dari 今回.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'b0457fb6-e5df-49a3-b9da-251adc5de64b'; -- 今度 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sesuatu terjadi setiap kejadian dan setiap derajat, itu adalah sesuatu yang sering. Itu terjadi setiap kali.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '10d2e96b-dde9-428a-8348-cf18553a4f97'; -- 毎度 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti tunggu jadi versi kata kerjanya adalah menunggu.', reading_mnemonic = 'Kamu harus menunggu ibumu (ま) sepanjang waktu. Anda ingin keluar? Kamu harus menunggu mama mengantarmu. Ingin makan malam? Kamu harus menunggu mama membuatkanmu makanan. Hmm. Mungkin semua penantian ini benar-benar menjadi masalahmu.' WHERE id = '362f8fee-1221-4b8f-9fd5-19e7be6f5fa0'; -- 待つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda memegang emas Anda adalah orang kaya.', reading_mnemonic = 'Apakah Anda ingat kata お金? Ini adalah 金 dalam kata ini. Pembacaan 持ち adalah も yang Anda pelajari dengan 持つ. Jadi, gabungkan かね dari お金 dan 持ち dan Anda akan membaca kata ini. Alternatifnya, Anda juga bisa mengucapkan kata ini dengan お金持ち.' WHERE id = 'e6efce58-f31c-440c-b1f3-a39a45739406'; -- 金持ち (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seberapa berat tubuh Anda? Cari tahu dan Anda akan mendapatkan berat badan Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'dc20b25c-74b9-46df-8960-e69bc810f253'; -- 体重 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 風 bisa berarti "gaya" seperti dalam 和風? Nah, ini sekarang adalah Gaya Barat gaya, lebih sederhananya disebut sebagai Gaya Barat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '9c5f20ad-d89f-41e6-ae50-99029f2ae6ea'; -- 洋風 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Barat makan adalah Makanan Barat. Mmmm, itu hamburger.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e37969d1-e86e-428d-b6d6-82d1520d27c5'; -- 洋食 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ruanggaya Barat adalah Ruang bergaya Barat. Kita sedang membicarakan sesuatu yang bukan ruangan yang dipenuhi tikar tatami. Senang mengetahui kata ini jika Anda menginap di hotel atau ryokan dan memilih untuk tidak tidur di futon, dll.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f02db5de-5125-4f2f-ad94-540b59e115f4'; -- 洋室 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Tahukah Anda kata "kamikaze" dari sejarah Perang Dunia II? Artinya "angin ilahi". Bagian "kaze" adalah bagian angin, dan kata ini menggunakan bacaan yang sama, menjadikannya かぜ juga.' WHERE id = 'c7799672-d771-4b09-93e7-0838e625b566'; -- 風 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apakah Anda ingat kata 思う? Artinya "berpikir". Apa yang pikirkaning adalah keluar—itu keluar dari pikiran Anda! Anda mengingat suatu kenangan dan/atau kenangan.', reading_mnemonic = 'Bacaannya sama-sama kun''yomi, namun berdasarkan pengalaman sebelumnya dengan dua kata terpisah yang membentuk kata ini, Anda seharusnya bisa membacanya. Ingatlah bahwa itu kun''yomi. Salah satu petunjuknya adalah hiragana yang menonjol di 思.' WHERE id = '261e0f59-e3f1-41df-9051-5b2235ee2987'; -- 思い出 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah gambar yang menggunakan ion pantulan untuk memproyeksikan gambarnya. Dan, gambarnya bergerak! Sungguh menakjubkan! Apa ini? Ini adalah film.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7a3a3549-45ae-45f5-a21b-7384c0f25c01'; -- 映画 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Pembacaan kata ini sama dengan yang Anda pelajari dengan kanji. Ah, indahnya musim semi! Err... はる, maksudku.' WHERE id = '919acbd4-9300-4c5f-bc82-8eedc1ffb553'; -- 春 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda membuat sebuah produk, itu sebenarnya bukan sebuah produk lagi, melainkan sebuah karya. Ini adalah karya seni atau sastra Anda, atau mungkin produksi teater.

Ini bisa berupa kreasi artistik apa pun: buku, komposisi, lukisan, film, drama... Ini tidak berarti "produk" (Anda akan mempelajari kata itu nanti!) tetapi dapat digunakan untuk suatu produk ketika Anda ingin menonjolkan bakat artistik di baliknya.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '06e52c38-1122-478b-a515-2787c3d84a21'; -- 作品 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang terjadi tiba-tiba terjadi tiba-tiba, segera, atau tiba-tiba.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Tiba-tiba Anda dapat membaca kata baru!' WHERE id = '32f506dd-d809-4ba6-b6ef-e59464728a17'; -- 急に (vocabulary)
UPDATE items SET meaning_mnemonic = 'mendadak kematian menghasilkan hal itu, kematian mendadak.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ec25c83e-521b-40c3-a525-fca20040b443'; -- 急死 (vocabulary)
UPDATE items SET meaning_mnemonic = 'buku toko adalah toko yang menjual buku. toko buku.', reading_mnemonic = 'Bacaannya adalah yang Anda pelajari dengan kanji.' WHERE id = '4977fd3a-ae83-4257-98fd-ac3fd408e33a'; -- 本屋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Maknanya diambil dari bagian mendadak dalam kanji, artinya mendadak, mendesak, atau darurat!', reading_mnemonic = 'Bacaannya sama dengan kanji yang Anda pelajari, artinya Anda tahu bacaannya!' WHERE id = '12e979f1-b555-4071-a421-3faafd49b878'; -- 急 (vocabulary)
UPDATE items SET meaning_mnemonic = 'mesin yang memompa angin dapat mengalami kegagalan fungsi dan menghasilkan terlalu banyak, sehingga menyebabkan topan. Ini adalah mesin yang sangat kuat untuk mampu menggerakkan angin sebanyak itu.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Daripada だい untuk 台, ini menggunakan bacaan たい. Ingatlah seperti ini:

Saat topan datang, kamu harus mengikat (たい) semua barang-barangmu. Atau lho, kalau sudah tahu kata topan juga tidak masalah.' WHERE id = '21f3ef72-3e02-4829-a03b-cdd77fc7caaa'; -- 台風 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana Anda mengetahui bahwa 休み berarti "istirahat?" Saat Anda istirahat di siang, itulah istirahat makan siang Anda! Atau, jika Anda tidak lapar, istirahat siang sebagai gantinya.', reading_mnemonic = 'Bacaan kata ini sama-sama bacaan kun''yomi. Anda sudah mempelajarinya, jadi Anda harus bisa membacanya juga!' WHERE id = '667ab294-f50b-4cfa-84d3-7535689d49ed'; -- 昼休み (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 建てる adalah "membangun". Ini mirip dengan itu, tetapi ini adalah versi di mana Anda tidak melakukan pembangunannya. Sesuatu baru saja dibangun. Itu sebabnya kata ini harus didirikan dan harus dibangun. Anda dapat mengenalinya karena つ, yang memberi tahu Anda bahwa dua (つ) orang sedang membangun gedung sementara Anda menonton. Jadi Anda tidak melakukannya, mereka melakukannya, dan itu terjadi begitu saja.', reading_mnemonic = 'Kata tersebut dibagikan kepada 建てる, jadi jika Anda mengetahui 建てる maka Anda seharusnya dapat membaca kata ini juga.' WHERE id = 'f3434e4e-3adf-44f2-81f1-0ac8b497d832'; -- 建つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada daun yang tumbuh dari benda persegi (biasanya berupa mulut, tapi kali ini tidak). Daunnya tumbuh dari batu. Maksudku, tentu saja, karena daun tidak tumbuh dari mulut. Saya harap. Bayangkan sebuah batu di tengah alam dengan daun yang tumbuh di atasnya atau tepat di belakangnya dan Anda tidak akan pernah melupakan hal radikal ini!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '30114c45-609d-48a6-8961-08d312d08e0b'; -- 石 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari seribu desa. Jika Anda mencoba mengangkatnya, apakah itu? Berat! Dan mungkin gila. Tapi ingatlah betapa beratnya seribu desa.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '032fe3b4-282f-4096-8f43-64e13a1c65cc'; -- 重 (radical)
UPDATE items SET meaning_mnemonic = 'Ini memang aneh, tapi hanya pada pandangan pertama. Anda membuat sebuah rumah. Anda mungkin mengira ini berarti sesuatu seperti "membangun rumah" atau "konstruksi" atau semacamnya. Sebaliknya, itu berarti penulis. Anggap saja seperti ini: Seorang author membuat (menulis dan menciptakan karya) di rumah mereka. Penulis tidak membuat kata-kata mereka ajaib di kantor perusahaan!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena pembacaan さく dari 作 menjadi さっ di sini, kami telah membuatkan mnemonik agar Anda dapat mengingat bacaan ini:

Penuliskecintaan pada sepak bola (さっか). Faktanya, bermain sepak bola adalah cara penulis mendapatkan inspirasi. Cobalah bermain sepak bola, mungkin Anda akan menjadi novelist juga!' WHERE id = '5cd35e1c-c874-4c77-a028-91c92e3b9cc8'; -- 作家 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang biru di tahunnya. Hal ini masuk akal jika Anda mengetahui bahwa bayi Asia sering kali dilahirkan dengan bokong berwarna biru, yang dapat Anda kaitkan dengan usia muda. Jadi, Biru = Muda (tidak hanya pada kata ini, tapi juga pada kata lain). Seseorang yang usianya biru adalah muda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '2de571df-82ea-4631-a59e-cb5f5034e70f'; -- 青年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti berpikir sehingga versi kata kerjanya adalah to think.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda telah mempelajarinya dengan kanji ini, namun berikut ini pengingat mnemonik untuk berjaga-jaga: 

Anda harus mengingat bagian おも untuk membaca kata ini. Namun, untuk melakukan hal ini, Anda harus berpikir tentang orang itu... hmm... siapa namanya? Dia ada di The Simpsons... dia bartendernya? Menurut saya? Oh! Moe (おも) adalah namanya! Terima kasih. Sekarang saya ingat.

Jika Anda belum tahu Moe dari Simpsons gunakan Moe yang berbeda, mungkin yang dari Three Stooges? Anda harus bisa memikirkannya.' WHERE id = 'c6ce1a4f-5743-4f24-9fe1-09c46feccf56'; -- 思う (vocabulary)
UPDATE items SET meaning_mnemonic = 'generasi (dan masyarakat!) yang membentuk dunia menciptakan dunia kita. Jadi inilah Dunia, society, atau Alam Semesta.　

Kata ini lebih sering digunakan seperti "anjing terbesar di dunia" atau "kucing paling gemuk di dunia". Misalnya, Anda akan sering mendengar kata-kata seperti 世界一番 (nomor satu di dunia).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '712bd47a-1255-4b17-970d-109e7a8c9b4e'; -- 世界 (vocabulary)
UPDATE items SET meaning_mnemonic = 'produk benda adalah semua jenis barang umum. Ini sespesifik mungkin ketika Anda membicarakan hal seperti ini.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji kun''yomi. Anda seharusnya bisa membacanya sendiri, tapi jangan tertipu dengan menggunakan on''yomis! Ini bukan ひんぶつ — bukan, ini しなもの!' WHERE id = '8d82afb0-012e-4a25-ab8f-1778e8a7f133'; -- 品物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Laut tengah bumi adalah Laut Mediterania. Mungkin tidak terlihat seperti berada di tengah bumi, namun dahulu kala itulah yang dipikirkan orang. Ini adalah laut antara Eropa Selatan dan Afrika Utara.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '4921b141-433e-40b7-9350-95207d06dee7'; -- 地中海 (vocabulary)
UPDATE items SET meaning_mnemonic = 'daging toko adalah tempat yang menjual daging. Siapa yang menjual daging? toko daging.', reading_mnemonic = 'Untuk 肉 Anda menggunakan bacaan にく (yang Anda pelajari dengan kanji). Untuk 屋 Anda menggunakan kun''yomi, yang Anda pelajari dengan kanji. Pada dasarnya, jika Anda mempelajari pembacaan kanji, Anda dapat membaca kata ini!' WHERE id = '7b1fa2da-b701-421b-a308-39576b28490e'; -- 肉屋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini tampak seperti kuil di atas bukit, bukan? Dengan semua lapisannya, apa lagi? Bayangkan saja garis horizontal pertama sebagai dasar candi berornamen yang menyeimbangkan bukit di bawahnya dan Anda tidak akan kesulitan mengingat garis radikal ini.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '63c00bc1-7621-4461-9d72-88a77ef81058'; -- 寺 (radical)
UPDATE items SET meaning_mnemonic = 'Ada kanopi dengan meja kecil dan kursi di dalamnya. Ini adalah yurt! Awalnya mungkin terlihat seperti kanopi, tetapi saat Anda masuk ke dalamnya, terdapat banyak furnitur bagus untuk Anda bersantai.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'd6e5ff31-7b77-41ef-91d0-646c10166db6'; -- [Yurt] (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Musim semi". Perhatikan bentuk karakter "[Musim semi]" dan asosiasikan bentuk goresannya dengan "musim semi".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '3abdc14a-225d-4baf-9b70-51585fba0d11'; -- [Musim semi] (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Topi". Perhatikan bentuk karakter "[Topi]" dan asosiasikan bentuk goresannya dengan "topi".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '4057fb17-8cb5-4db0-a63f-6a03f27c9eda'; -- [Topi] (radical)
UPDATE items SET meaning_mnemonic = 'Pertama, ada tanda silang di tengah, yang otomatis menjadikan ini radikal berbasis agama. Salib itu adalah kerangka tubuh seseorang dan yang keluar darinya adalah sayap. Ini adalah malaikat.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '28f8f1cb-dd32-47a3-9717-48c8303e91ee'; -- ホ (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini memiliki kepala kecil dan beberapa kaki udang yang mencuat keluar. Itu karena itu adalah udang!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '546020c2-1aff-4896-8a67-d2ee2e191df3'; -- 尺 (radical)
UPDATE items SET meaning_mnemonic = 'Ini tampak seperti semacam kandang - itulah mengapa ini disebut penjara. Ia membungkus dirinya sendiri di sekitar benda-benda dan menguncinya di sana. Penjara cukup menakutkan, bahkan sebelum Anda membayangkan penjara perlahan-lahan melayang turun dari langit untuk menjebak Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'afe8cbaa-ac8a-47e3-9202-eadb65c1f5db'; -- 勹 (radical)
UPDATE items SET meaning_mnemonic = 'Tanda お membuat kata tersebut lebih sopan. Karena teh sangat penting di Jepang, teh mendapat お. Jika tidak, Anda seharusnya bisa memahami artinya karena sama dengan kanjinya.', reading_mnemonic = 'Bacaannya adalah bacaan on''yomi, sama seperti yang Anda pelajari dengan kanji.' WHERE id = '0476d57c-ff02-456e-b677-b2fb57a384ef'; -- お茶 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mudah-mudahan Anda sudah mengetahui kata 見る dan 送る. Di sini Anda "melihat" "pengiriman". Anda mengantar seseorang pergi, jadi kata kerja ini adalah mengantar. Ini juga bisa berarti menunda atau mewariskan, karena ini seolah-olah Anda hanya secara pasif melihat seseorang (atau sesuatu) pergi daripada mengambil tindakan dan pergi bersama mereka.', reading_mnemonic = 'Bacaannya berasal dari vocab kata 見る dan 送る. Pastikan Anda mengetahuinya dan Anda akan mengetahui bacaan kata ini juga.' WHERE id = 'd19bd2bc-395f-4309-b354-1e004d66837a'; -- 見送る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti mengirim, dan versi kata kerjanya adalah to send Something. Jika objek dari verba ini adalah orang, artinya “mengutus” dalam arti mengantar seseorang, mungkin ke stasiun, atau ke pintu.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda perlu mengirimkan seluruh pohon ek (おく) melalui pos, tetapi ukurannya terlalu besar. Bayangkan diri Anda menyeretnya ke kantor pos. Mereka memberitahu Anda bahwa Anda tidak dapat mengirimkannya ke sini... Pergi ke fasilitas pengiriman pohon ek.' WHERE id = 'f892f5bd-3f09-427d-9d7b-1c149afa7488'; -- 送る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja.

Kanji itu sendiri berarti memegang dan versi kata kerjanya adalah memegang sesuatu, membawa sesuatu, memiliki sesuatu, atau menyimpan sesuatu.

Ini merupakan kata kerja transitif, artinya mengambil objek langsung. Anda memegang sesuatu, seperti sumpit, memiliki sesuatu, seperti listrik, atau menyimpan sesuatu, seperti buku teman Anda selama akhir pekan.', reading_mnemonic = 'Jika kamu mencoba memegang sesuatu di tanganmu cukup lama, benda itu akan berjamur (も). Lalu jamur itu akan menutupi tangan Anda, lalu lengan Anda, lalu seluruh tubuh Anda. Pada dasarnya, Anda tidak boleh memegang apa pun terlalu lama atau Anda akan menjadi orang yang berjamur.' WHERE id = 'ea500731-2875-415d-ac33-87e3a076e779'; -- 持つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Di atas atap adalah atap. Apa lagi yang ada di atas sana?', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda tidak mempelajari bacaan ini untuk 屋, jadi inilah mnemonik untuk membantu Anda:

Satu tempat di dunia memiliki lebih banyak atap dibandingkan tempat lain, dan itulah Oklahoma (おく). Mereka mendapatkan begitu banyak tornado sehingga mereka membutuhkan atap tambahan ketika beberapa tornado pertama terjadi.' WHERE id = 'd4cb26d2-e9c7-4438-be48-5f45a2ffc011'; -- 屋上 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari biru? Masih biru! Ini juga bisa berarti mentah, yang mungkin terdengar membingungkan, namun hal ini disebabkan oleh fakta bahwa dalam bahasa Jepang ada beberapa kesamaan antara biru dan hijau. Jadi meskipun dalam bahasa Inggris kita menganggap lampu lalu lintas "pergi" dan pisang mentah sebagai "hijau", dalam bahasa Jepang keduanya disebut "biru".', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian あお untuk membaca kata ini. Pikirkan benda-benda biru di tubuh Anda. Itu adalah memar. Sentuh mereka. Apa yang akan kamu katakan? Aduh! (あお).' WHERE id = '4ac7ed2c-7c5d-41d8-beba-949996056a48'; -- 青い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari berat? Ini juga berat.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda sedang mengangkat sesuatu yang berat. Aduh! Anda mengangkatnya di atas kepala Anda. Kamu luar biasa. Anda berteriak: "OH! LEBIH BANYAK!" (おも) mereka menambahkan lebih banyak. Anda berteriak lagi: "OH, LEBIH BANYAK!" dan lagi: "OH, LEBIH BANYAK!" Lanjutkan dan lakukan hal ini di mana pun Anda berada, berpura-puralah Anda sedang memegang satu atau dua atau tiga sofa di atas kepala Anda, sambil berkata, "OH LEBIH BANYAK!"' WHERE id = '701f1024-824c-4558-a012-a95606c96d7b'; -- 重い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal biru dan kanji biru sama persis.', reading_mnemonic = 'Bagaimana cara membaca kanji **Biru** (青)? Ingat saja bahwa **Setan/Sapi** sangat menyukai biru! Hubungan erat ini akan membantu Anda mengingat bunyi **せい**.' WHERE id = '5a266cd1-fd58-4cf0-bc14-aa168899c508'; -- 青 (kanji)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 下品 dianggap "kasar" dan "vulgar" - ini jelas merupakan kebalikannya. Ini elegan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '5d71d67d-eec4-44d5-a7a9-34a313bebd3b'; -- 上品 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda mempertajam penelitian Anda hanya melakukan studi atau investigasi. Atau dengan kata lain, Anda sedang melakukan riset!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'd193252c-883f-46c8-b977-876cd0e7e01f'; -- 研究 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa yang Anda bangun di di depan orang lain adalah citra publik Anda. Ini adalah perilaku publik Anda, cara Anda bertindak di sekitar orang yang tidak terlalu Anda kenal. Konsep ini ternyata sangat penting di Jepang, jadi Anda akan cukup sering mendengarnya meskipun konsep ini aneh di tempat lain. Anda harus memikirkan hal ini seperti Anda sedang membangun bangunan kepribadian di depan Anda. Ini menunjukkan siapa diri Anda di luar, namun melindungi apa yang ada di dalam.', reading_mnemonic = 'Pembacaannya cukup aneh. Ini sangat mirip dengan 建物 karena dibaca sebagai たて, yang mirip dengan kata 建てる meskipun て tidak ditampilkan di sini. Jadi, Anda harus ingat bahwa bacaannya seperti 建てる tetapi て dimasukkan ke dalam kanji.' WHERE id = '90575f91-5565-4bd7-938f-3d5f93bb426f'; -- 建前 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Beberapa pribadi kotoran Anda ada di tanah, jadi Anda menempelkan bendera ke dalamnya. Kemudian di tanah pribadi yang Anda klaim, Anda membangun atap. Di bawah atap Anda juga membangun beberapa toko dan toko.', reading_mnemonic = 'Ketika Anda sedang melihat **Atap** (屋), tiba-tiba muncul sesosok **Yoyo** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **や**.' WHERE id = '3087dcce-faf8-43b9-9cb3-7312cc09b718'; -- 屋 (kanji)
UPDATE items SET meaning_mnemonic = 'teh toko adalah kedai teh. Mmm, teh yang enak dan nikmat.', reading_mnemonic = 'Kata ini menggunakan bacaan yang Anda pelajari dengan kanji. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f'; -- 茶屋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'hati Anda menyimpan banyak perasaan. Hal-hal tersebut bisa sangat membebani dan terkadang terasa seperti tidak ada sama sekali, namun bukan berarti hal-hal tersebut tidak ada di hati Anda.', reading_mnemonic = 'Bacaan kata ini sama-sama bacaan kun''yomi. Anda mempelajarinya saat mempelajari kata 心 dan 持つ, jadi Anda seharusnya bisa membacanya sendiri.' WHERE id = '91f69392-b4da-4eb2-9b47-9cf3b96a0bb2'; -- 心持ち (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda melakukan keberangkatan dari rumah Anda menuju alam baka. Anda akan melihat yang tak terlihat, dan semoga mendapatkan penemuan yang hebat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Anda pasti tahu bagian はつ, yang disingkat menjadi はっ. 見 tidak seperti apa yang Anda pelajari dengan 見. 

Untuk mengingat bahwa ini adalah けん, bayangkan Anda pergi keluar untuk menemukan beberapa daratan baru yang aneh. Dengan negeri baru yang asing, datanglah orang-orang baru yang aneh. Yang ini memiliki seorang samurai bernama Ken けん di atasnya. Dia juga mencoba menemukan hal-hal baru!' WHERE id = '8c8aa4a0-9aeb-4cfe-bf2f-1e12d5dc6112'; -- 発見 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti cepat jadi versi kosakata kata kerjanya adalah cepat.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajarinya dengan kanji ini, jadi inilah mnemonik yang dapat membantu Anda: Seseorang yang mencoba untuk bergegas adalah seseorang yang merasa tidak nyaman (いそ).' WHERE id = '6183e46c-f780-4058-bfbd-2a908d130ebb'; -- 急ぐ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Apakah Anda mendengar suara itu? Hampir tidak terdengar (おと). Silakan ucapkan kata "audible" dengan pengucapan おと untuk membantu Anda mengingatnya.' WHERE id = '7e1b6c62-b878-48ba-8a0d-d831656e6ac2'; -- 音 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang memberi Anda waktu pengukuran adalah jam atau jam. Kebanyakan orang sekarang memilikinya di ponsel mereka, bukan di pergelangan tangan mereka.', reading_mnemonic = 'Pembacaan untuk ini cukup aneh. 計 semuanya bagus dan normal, tetapi 時 adalah と karena alasan tertentu. Mungkin berasal dari kosakata 時 (とき), begitulah tebakan saya. Tapi kalaupun ya, itu dipersingkat, membuatnya selangkah lebih rumit. Mungkin lebih baik membayangkan jam tangan Anda adalah walky talky (とけい) dan menjalankannya?' WHERE id = '71898150-a2d4-4f55-9735-32da8ceb7d15'; -- 時計 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki 発売, yang berarti "dijual", lalu Anda memiliki 中 yang merupakan tengah. Suatu barang yang sedang dijual adalah sekarang dijual, di toko sekarang atau dengan kata lain sekarang tersedia. Anda akan melihat ini untuk barang-barang yang baru saja dirilis atau ketika penjaga toko ingin memberi tahu Anda bahwa mereka sedang menjual sesuatu sekarang, akhirnya, atau apa pun.', reading_mnemonic = 'Pembacaannya berasal dari 発売 dan 中 (pembacaan kanji) yang disatukan.' WHERE id = 'd1277aaa-0fb8-4d90-b21b-4e6287b692f4'; -- 発売中 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda ingin mengatakan seberapa besar cross, Anda harus mengukur itu. Anda tidak dapat mengetahui ukuran suatu benda tanpa mengukurnya terlebih dahulu.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Pengukuran** (計) tiba-tiba berbicara dan meminta **Kakek/Keju**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **けい**.' WHERE id = '6c07217c-ef8f-425b-8d83-797a673bbfa0'; -- 計 (kanji)
UPDATE items SET meaning_mnemonic = 'Gaya Baratd Barat masih dikenal sebagai Barat. Kata yang dirujuk semua orang di Asia ketika mereka berbicara tentang negara-negara Barat di Eropa dan Amerika Utara. Di sinilah Anda akan mendengar orang mengatakan Anda berasal jika Anda tinggal di Kanada atau semacamnya.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '53373d45-090a-43d8-aabd-a791a6361a97'; -- 西洋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dengan skuter-nya, makhluk bertanduk dari surga akan membawa barang-barang yang ingin Anda kirim ke sana.', reading_mnemonic = 'Anda mengirim semangkuk **Soto** (そう) hangat lewat paket ekspres.' WHERE id = '3351cb4f-ef0e-4f15-b6a8-03ddafadd269'; -- 送 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini juga bisa berarti makan siang, terutama bila digunakan dengan awalan kehormatan お, seperti dalam お昼.', reading_mnemonic = 'Bacaan kata ini sama dengan kanji asalnya, jadi kalian harus bisa membacanya!' WHERE id = '4629d5db-baaa-497f-bfb4-f543702141a0'; -- 昼 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal produk dan kanji produk sama persis! Produktif!', reading_mnemonic = 'Ketika Anda sedang melihat **Produk** (品), tiba-tiba muncul sesosok **Hidung/Hijau** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **ひん**.' WHERE id = '938e39ed-5ecf-40d3-a5fa-8930fe34d891'; -- 品 (kanji)
UPDATE items SET meaning_mnemonic = 'energi yang Anda tahan di dalam tubuh Anda adalah perasaan Anda. Bentuknya bisa bermacam-macam. Perasaan baik, perasaan buruk, "perasaan aneh" itu.', reading_mnemonic = '気 adalah on''yomi dan Anda mempelajarinya dengan kanji. 持ち adalah kun''yomi, yang kamu pelajari dengan kata 持つ. Salah satu pembacaan pengecualian yang aneh, tapi ち di akhir 持ち adalah petunjuk bahwa ia menggunakan kun''yomi.' WHERE id = 'f2fd495e-66d9-47d5-bab8-ae3648536dcb'; -- 気持ち (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda akan melihatnya dilampirkan pada kata lain... seperti "menunggu" atau "tamu". Saat Anda melihat ini, Anda akan mengetahui bahwa itu adalah ruangan ___, sehingga kata ini berarti room (sama seperti kanji).', reading_mnemonic = 'Bacaannya adalah bacaan on''yomi. Jangan mengetik 〜 saat menulis jawabannya. Itu hanya untuk memberi tahu Anda bahwa biasanya ada sesuatu yang melekat pada kata ini.' WHERE id = '481fcaec-23cb-4a6a-88ff-badf903f8ce7'; -- 〜室 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika seseorang menanyakan apa kejadian atau berapa derajat mereka sebenarnya mencoba menanyakan berapa kali sesuatu terjadi. Terkadang mereka juga menanyakan berapa suhu.', reading_mnemonic = 'Bacaannya merupakan gabungan bacaan kun''yomi dan on''yomi. Meski begitu, kedua bacaan untuk kedua kanji tersebut adalah bacaan yang sudah Anda pelajari, jadi Anda harus bisa membaca ini.' WHERE id = '5ef8b2ac-9520-4b8b-8818-649234b510f9'; -- 何度 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 研究 berarti “penelitian?” ruangan tempat Anda melakukan penelitian adalah laboratorium!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7c5f057e-2637-4c04-a4b0-69d32c314564'; -- 研究室 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tiga kotak ditumpuk di atas satu sama lain. Ini adalah produk yang menunggu untuk dikirim.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'c7954769-6c83-4a71-926c-16e5174ea1df'; -- 品 (radical)
UPDATE items SET meaning_mnemonic = 'Jenis radikal ini terlihat seperti anak panah, tapi bukan anak panah biasa. Itu melengkung dan dipaksakan, bukan? Seolah-olah ia mencoba memberi tahu Anda bahwa ada sesuatu yang macet ke mana pun ia menunjuk.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '53ac50f3-3d6e-430e-97ca-0f292ee32218'; -- 介 (radical)
UPDATE items SET meaning_mnemonic = 'Bayangkan lentera gaya lama. Letaknya di atas beberapa kaki (Anda hanya dapat melihat dua dari sudut ini) dan berada dalam dudukan berbentuk kotak di bagian atas. Anda bisa membayangkan ini berjejer di jalanan sebelum ada listrik, bukan? Itu sebabnya kaum radikal ini adalah lentera.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7a5f74ec-2fa8-41a1-b148-46c33bae657b'; -- 开 (radical)
UPDATE items SET meaning_mnemonic = 'Ini tampak seperti tangan (手) yang radikal, namun lebih kecil. Itu karena itu hanya jari. Anda tidak selalu memiliki ruang untuk seluruh tangan untuk menulis kanji, tetapi selalu ada ruang untuk beberapa jari.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '53e6fc76-9e71-4fd5-8eaa-f2489b784ad5'; -- 扌 (radical)
UPDATE items SET meaning_mnemonic = 'Anda sudah mengetahui adanya unsur radikal dalam hal ini, itu seharusnya menjadi petunjuk. Hewan apa itu? Letaknya di dalam tanah, tertutup lumpur. Juga, ada jari-jari kakinya yang tergeletak di sana-sini, karena hewan ini akan memakan apa saja (cara yang baik untuk menyingkirkan mayat... kudengar). Lalu hewan apa yang berlumuran lumpur dan memakan jari kaki karena mau memakan apa saja? Itu adalah babi!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'e1e1b536-8c96-4450-b319-1ea1d685561a'; -- 豕 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Senjata". Perhatikan bentuk karakter "[Senjata]" dan asosiasikan bentuk goresannya dengan "senjata".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'b3a67baf-044a-461d-aad7-159e8cf778a0'; -- [Senjata] (radical)
UPDATE items SET meaning_mnemonic = 'Anda memiliki kehidupan di atas bulan (abaikan bahwa kehidupan tidak memiliki slide kecil di sisi kiri). Seperti apa kehidupan di bulan? Pertama-tama, mereka tidak memiliki udara, jadi mereka mungkin terlihat sangat biru karena sesak napas. Saat Anda bertemu mereka, ternyata Anda benar. Mereka adalah peradaban orang-orang biru. Bayangkan mereka semua tinggal di sana, berwarna biru dan Smurfy.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'c047405f-da3f-49e5-89dc-3063614a884e'; -- 青 (radical)
UPDATE items SET meaning_mnemonic = 'Di sawah Anda menemukan hati dan itu membuat Anda berpikir. Kamu pikir banyak pikiran yang seperti, "Hati siapa ini? Kenapa di sawah? Kenapa aku berpikir keras?"', reading_mnemonic = 'Untuk mengingat cara baca kanji **Pikirkan** (思), bayangkan Anda sedang membawa **おも** untuk ditaruh di atas pikirkan. Kejadian unik ini mengingatkan Anda pada bunyi **おも**!' WHERE id = '64d6561c-ea2f-448d-b69b-9325a7a27310'; -- 思 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji derajat dapat berarti derajat dalam hal sudut dan derajat dalam hal suhu. Kata ini adalah cara Anda membicarakan hal-hal ini. Cukup lampirkan ke sebuah angka dan Anda akan mendapatkan sendiri jumlah derajat sesuatu itu. Setelah angka 1, 2 dan 3 (dan dalam beberapa situasi lainnya) ini juga bisa berarti kali.', reading_mnemonic = 'Bacaannya sama dengan bacaan kanji yang Anda pelajari. Saat menulis jawaban untuk bacaan ini, hilangkan 〜 karena ini hanya untuk memberi tahu Anda bahwa ada kata lain yang harus didahulukan.' WHERE id = '6eb818a1-cf04-4d86-ab0e-4a17f44c57c8'; -- 〜度 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tempat yang terkenal dengan tua atap. Saya tidak tahu kenapa, tapi ini adalah kota Nagoya. Gabungkan saja kedua hal tersebut dan Anda akan sulit untuk melupakannya (selama Anda pernah mendengar tentang Nagoya sebelumnya - jika belum, bacalah tentangnya!).', reading_mnemonic = 'Ini adalah kata jukugo, yang biasanya berarti pembacaan on''yomi dari kanji (kecuali 名 dan 屋, yang merupakan kun''yomi di sini). Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Untuk な coba pikirkan 名前 (なまえ) yang menggunakan bacaan な. "Nama" (名前) kota ini adalah apa? Itu Nagoya. Hati-hati jika rendaku juga berubah こ menjadi ご.' WHERE id = '43fba0f6-2b6f-4c31-b178-2eb2e6e30835'; -- 名古屋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Siapakah wanita yang berpura-pura menjadi jet itu? Itu adik perempuanku. *Mendesah*', reading_mnemonic = 'Tahukah Anda bahwa **Saudari** (妹) ini sebenarnya dibuat dari tumpukan **Maimun/Mainan**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **まい**.' WHERE id = '703d794e-798c-43a9-b73b-e19968f7ef93'; -- 妹 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ngomong-ngomong, ini kakak perempuanmu. Bukan milik orang lain.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Anda belum mempelajari bacaan ini, jadi inilah mnemonik untuk membantu Anda mengingat:

Bayangkan kakak perempuan Anda (meskipun Anda tidak memilikinya), ulang tahunnya akan segera tiba dan hanya ada satu hal yang dia inginkan dari Anda. Sebuah kalung (あね). Dia menginginkan sebuah kalung selama bertahun-tahun dan Anda akhirnya akan memberikannya. Dia akan sangat bahagia.' WHERE id = '14f04faa-8676-4826-bf8f-c9da9b822a42'; -- 姉 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini sama dengan kanji, setidaknya dalam kaitannya dengan arti artikel atau barang, yang berarti Anda dapat menggunakan kata ini untuk mengartikan artikel atau barang.', reading_mnemonic = 'Jika kanji ini digunakan sebagai kosa kata berkarakter tunggal, biasanya dibaca sebagai しな. Anda akan lebih sering melihatnya dibaca sebagai ひん dalam kata kombinasi kanji. Meski begitu, ada ungkapan, 品がない, yang berarti "tidak dimurnikan" atau "kurang rasa", dan kanjinya dibaca ひん dalam kasus ini. Berikut ini mnemonik untuk membantu Anda mengingat bacaan しな:

Anggap saja seperti video game. Saat pertama kali Anda melihat barang baru, ada kemilau (しな) di dalamnya. Namun ketika Anda membawanya kembali ke tempat Anda, kilaunya hilang. Lalu ketika Anda kembali ke toko, wow! Semua barang yang belum Anda miliki memiliki kemilau itu! Harus membelinya!' WHERE id = 'f4b52089-42f2-4bad-b001-49ed128fbbad'; -- 品 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata keterangan dari kanji berpikir. Anda pasti berpikir, Anda melakukannya secara tidak sengaja. Jadi letakkan ini di depan hal-hal yang mengatakan bahwa Anda melakukannya tanpa disengaja.', reading_mnemonic = 'Bacaannya ini adalah bacaan kun''yomi yang sudah kamu pelajari, jadi kamu harus bisa membaca kata ini juga.' WHERE id = '44188a82-23b3-42ac-9cec-8a822998d9ff'; -- 思わず (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti membangun jadi versi kosakata kata kerjanya adalah to build.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajarinya dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: Pikirkan tentang apa yang terjadi ketika Anda membangun sesuatu. Apa yang sedang kamu lakukan? Anda berdiri tegak. Bagaimana Anda mengatakan "berdiri" dalam bahasa Jepang? たてる. Begitu pula dengan bacaan kata ini. Kalau dipikir-pikir, mereka mirip!' WHERE id = 'bf752cfc-22c1-432b-8743-6521aa525f44'; -- 建てる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti mencerminkan. Versi kosakata kata kerjanya berarti direfleksikan. Anda tidak melakukan refleksi secara langsung. Anda dapat mengingat hal ini dengan memikirkan betapa kasarnya (る) ketika seseorang memantulkan bayangan Anda menggunakan cermin agar semua orang di luar ruang ganti dapat melihatnya.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Bayanganmu terpantul di cermin. Anda tidak menyukainya, itu tidak terlihat seperti Anda. Refleksi penipu! Kamu mengambil palu dan 打つ (うつ) memukulnya sekuat tenaga, kaca beterbangan ke mana-mana. Kemudian beberapa dubstep mulai diputar dari cermin yang pecah: うつうつうつうつ.' WHERE id = '6a7c6a9a-db63-4066-aeba-56e643950f82'; -- 映る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Barang yang berada di bawah produk normal adalah barang tiruan yang murah dan kualitasnya buruk. Barang-barang ini sangat kasar dan vulgar dalam pembuatan dan desainnya. Begitu banyak vulgarity!', reading_mnemonic = 'Anda belum melihat bacaan ini untuk 下 (maaf kanji ini banyak sekali!) jadi inilah mnemonik untuk membantu Anda:

Barang-barang itu sangat kasar sehingga Anda bahkan tidak tahu barang apa yang seharusnya. Sejujurnya mereka semua terlihat seperti patung tokek yang menggumpal (げ). Katanya itu lampu tapi lebih mirip tokek yang melihat ke langit. Kursi itu? Pasti sekelompok tokek yang sedang mengadakan pesta biliar. Apakah Anda yakin tidak mendapatkan barang ini dari seniman tokek yang aneh?' WHERE id = '0779c47f-8a17-4cd7-b708-791ec38502b3'; -- 下品 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat 夏休み dan 冬休み. Jika itu belum cukup, Anda dapat melihat bahwa ini adalah semacam mata air istirahat. Itu akan menjadi liburan musim semi atau liburan musim semi.', reading_mnemonic = 'Pembacaan 春 sama dengan yang Anda pelajari dengan kanji. Bagian 休み sama dengan vocab kata 休み, semoga bisa anda baca! Jika Anda mengetahui bacaan tersebut, Anda dapat membaca ini juga.' WHERE id = '63c9f85b-6515-4f51-aea9-a0834e4a2043'; -- 春休み (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hal-hal yang cepat dan berjalan lebih cepat dibandingkan hal-hal lain adalah ekspresikan. Ini sering digunakan pada kereta api atau kereta bawah tanah, jadi berhati-hatilah jika Anda ingin pergi ke suatu tempat dengan tergesa-gesa. Berhati-hatilah juga jika kereta tidak berhenti di halte Anda, karena kereta 急行 tidak berhenti di setiap stasiun (yang membuatnya menjadi ekspres!).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'dbbe3c85-0f82-4638-bfde-51876ac81a7e'; -- 急行 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti tunggu jadi kata ini ada hubungannya dengan menunggu. Gunakan たせ sebagai petunjuk. Seseorang "melempar" bola ke dalam selokan, dan kemudian mereka harus menemukannya. Mereka membuatmu menunggu sampai mereka mendapatkan bolanya juga, padahal itu omong kosong yang murah. Merasa kesal tentang hal ini. Itu akan membantu Anda mengingat bahwa ini berarti membuat seseorang menunggu dan membuat seseorang menunggu.', reading_mnemonic = 'Anda mempelajari bacaan ini dari 待つ, selamat!' WHERE id = '9cb950d3-9c14-4e0a-9f12-c198c77029af'; -- 待たせる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal lima dan kanji lima adalah sama.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Lima** (五) tiba-tiba berbicara dan meminta **ご**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ご**.' WHERE id = '0ffe0e09-fa0f-4efc-9f46-28fd8fdfb28e'; -- 五 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal go dan kanji go sama persis!', reading_mnemonic = 'Ketika Anda sedang melihat **Pergi** (行), tiba-tiba muncul sesosok **Koko/Koki** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **こう**.' WHERE id = '39756746-9282-4aa3-a31c-56ca40b81a9f'; -- 行 (kanji)
UPDATE items SET meaning_mnemonic = 'Kosakata "一年" memiliki arti "Satu Tahun". Kombinasi kanji dalam kata ini melambangkan konsep satu tahun.', reading_mnemonic = 'Cara membaca kosakata "一年" adalah "いちねん".' WHERE id = '0f9a716f-5534-4400-8035-40732cb54508'; -- 一年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan kanji yang menyusun kata ini. Beruntungnya kamu!' WHERE id = '0788f330-eb19-4ec2-a457-546832b169a9'; -- 気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini sangat sederhana. Utara + Barat = Barat Laut.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7bca7244-ba8a-43ec-86eb-03b8c5b2c814'; -- 北西 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Listrik energi hanyalah cara yang bagus untuk mengatakan listrik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fc9db29f-a62a-4bdf-a2f8-9fb8c7318d94'; -- 電気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal api dan kanji api sama satu sama lain.', reading_mnemonic = 'Tahukah Anda bahwa **Api** (火) ini sebenarnya dibuat dari tumpukan **Kaki/Kaca**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **か**.' WHERE id = 'd3be5653-bb90-4956-9f27-10d910674c10'; -- 火 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda menggunakan imajinasi Anda, radikal ini sebenarnya terlihat seperti angka "5". Anda harus menghapus garis vertikal di kiri bawah, tetapi setelah Anda melakukannya, Anda memiliki cara mudah untuk mengingat bahwa radikal ini berarti lima.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'e716becd-3257-41ee-a479-3c2136c6369b'; -- 五 (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti pergi jadi bentuk kata kerjanya adalah to go.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian い. Untuk mengingat い kita menggunakan kata "elang". 

Anda ingin pergi ke suatu tempat (ke mana saja!) namun Anda tidak bisa. Seekor elang (い) menghalangi jalan Anda. Anda mencoba untuk maju dan ia membuka sayapnya dan menggigit Anda. Anda mencoba untuk kembali dan ia melompat ke arah Anda. Tidak ada tempat bagimu untuk pergi jika elang ini berdiri di sana.' WHERE id = '4986df2b-a8f4-445f-a2b8-2176fb3d1294'; -- 行く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda sedang mencari harta, tetapi bukan harta karun biasa... harta karun yang merupakan simpanan energi. Bukan emas, uang, atau semacamnya. Bayangkan diri Anda menemukannya, dan membuka peti harta karun. Semburan bola energi spirit yang belum pernah Anda lihat.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Antusiasme** (気) tiba-tiba berbicara dan meminta **Kipas/Kikir**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **き**.' WHERE id = '90d09cad-69f3-49d5-8e40-c5d12dafdcf8'; -- 気 (kanji)
UPDATE items SET meaning_mnemonic = 'Segala sesuatu yang terjadi pada Anda sebelumnyahanyalah puncak dari gunung es, dan hal-hal penting di depan Anda, di masa depan Anda. Jadi pastikan Anda mengutamakan hal itu first!

Arti asli kata ini adalah ujung suatu benda, misalnya pena atau jari. Dari makna tersebut diperluas menjadi berbagai macam makna, seperti depan, pertama, dan masa depan, tergantung konteks dan letaknya dalam kalimat. Ini juga bisa berarti "sebelumnya" dalam konteks formal (dan kami akan menerima arti itu juga, tapi kami tidak mengajarkannya di sini karena ini lebih maju).', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Anda tidak mempelajari cara membaca dengan kanji, jadi inilah mnemonik untuk membantu Anda:

Tepat di depan Anda adalah tip gergaji dan kunci(さき). Anda tidak tahu apa yang mereka lakukan di sana, tetapi gergaji dan kunci memiliki ujung yang sangat tajam, jadi berhati-hatilah agar Anda tidak melukai diri sendiri. Bayangkan diri Anda berjalan dengan hati-hati melewati gergaji dan tip-tip penting tersebut.

Anda dapat membedakan ini dari 先ず (まず) karena tidak ada hiragana di akhir.' WHERE id = 'a62d6cf8-46f0-4154-a883-334371c3d7e9'; -- 先 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sudah tampak seperti sepasang kaki. Bahkan ada kaki di kaki ini (tidak seperti sirip radikal yang Anda pelajari sebelumnya). Begitulah cara Anda mengetahui bahwa ini adalah kaki dan bukan sirip (atau yang lainnya).', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '08582f00-f56f-4ea3-8162-fd25ea55d5e9'; -- 儿 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari radikal sapi dengan radikal dasar di bawahnya. Jika Anda memiliki sapi di tanah yang kokoh, maka Anda benar-benar memiliki kehidupan yang baik, menurut saya. Terkadang radikal ini akan muncul tanpa bagian samping juga, meskipun kita akan memperlakukan keduanya sebagai "kehidupan".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a16eb59c-4b42-4b06-b77f-821f71c08dcf'; -- 生 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal kehidupan dan kanji kehidupan adalah sama, jadi mudah-mudahan Anda sekarang sudah mengetahui keduanya.', reading_mnemonic = 'Bagaimana cara membaca kanji **Hidup** (生)? Ingat saja bahwa **Setan/Sapi** sangat menyukai hidup! Hubungan erat ini akan membantu Anda mengingat bunyi **せい**.' WHERE id = 'a8cf2f66-04d3-4b58-a9c7-e6ed8078e3c0'; -- 生 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal putih dan kanji putih adalah sama.', reading_mnemonic = 'Bagaimana cara membaca kanji **Putih** (白)? Ingat saja bahwa **Hakim/Handuk** sangat menyukai putih! Hubungan erat ini akan membantu Anda mengingat bunyi **はく**.' WHERE id = 'bd22ddb5-fbd1-4075-819c-8d0acb663dae'; -- 白 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji barat dan kanji barat adalah sama. Bukankah itu bagus?', reading_mnemonic = 'Tahukah Anda bahwa **Barat** (西) ini sebenarnya dibuat dari tumpukan **Setan/Sapi**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **せい**.' WHERE id = 'f7fed555-4e1e-439a-a539-2af9f83afeb0'; -- 西 (kanji)
UPDATE items SET meaning_mnemonic = 'matahari mengeluarkan satu tetesan, dan kemudian tetesan lainnya. Tetesan air menari bersama di udara, menyatu, dan saat jatuh ke tanah, ibumu akan tumbuh!', reading_mnemonic = 'Ketika Anda sedang melihat **Ibu** (母), tiba-tiba muncul sesosok **はは** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **はは**.' WHERE id = '11d2dcad-4c58-4cd7-95c3-1899993a126d'; -- 母 (kanji)
UPDATE items SET meaning_mnemonic = 'Narwhal melakukan konstruksi dengan tangan kiri mereka (atau sirip, menurut saya). Itu karena semua narwhal kidal!', reading_mnemonic = 'Bagaimana cara membaca kanji **Kiri** (左)? Ingat saja bahwa **Sapi/Sate** sangat menyukai kiri! Hubungan erat ini akan membantu Anda mengingat bunyi **さ**.' WHERE id = '4b8bffdf-05dc-40c1-9caa-812e0bb66ff0'; -- 左 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki dua tongkat. Dua apa? Ya, Anda tidak bisa membedakannya karena terlalu kering. Seseorang menaruh dua benda pada tongkat ini hingga kering, tapi sepertinya mereka sudah terlalu lama membiarkannya. Apakah itu daging? Ikan? Mentimun? Anda tidak tahu, tapi itu dua hal yang sangat kering, itu sudah pasti.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7b6710e6-44eb-47c4-8fb7-d2d320e9b04f'; -- 干 (radical)
UPDATE items SET meaning_mnemonic = 'Ada potongan tepat di pangkal pohon ini. Mengapa seseorang menebang pohon? Untuk membuat buku darinya! Bayangkan hidup di masa lalu ketika Anda harus menebang pohon sendiri untuk menulis atau membaca buku.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '4daf8f6f-2d2b-45bb-b938-8660fbb9725f'; -- 本 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "kotak". Perhatikan bentuk karakter "囗" dan asosiasikan bentuk goresannya dengan "kotak".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5dbe2c70-a769-4df3-973d-9f1eca139800'; -- 囗 (radical)
UPDATE items SET meaning_mnemonic = 'Lubang persegi yang besar dan menganga melambangkan seseorang yang membuka mulut raksasanya untuk memberi tahu Anda sesuatu yang bodoh.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5e2320d9-0f2b-438a-b64a-cc64a47f9347'; -- 口 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini bentuknya seperti bendungan. Lihat tembok dan air mendorong dari atas? Jika radikal ini adalah sebuah bendungan, maka ia harus menciptakan banyak energi juga!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8c673ceb-e117-467b-9bce-8566d0593063'; -- 气 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat orang radikal di sini? Ada sesuatu yang keluar darinya... benda apa itu—YA TUHAN ITU API!!! Tolong tolong! Padamkan apinya!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '41111711-fcdf-47bb-91c8-67feb69f9d55'; -- 火 (radical)
UPDATE items SET meaning_mnemonic = 'Kombinasi radikal untuk kanji ini mungkin tidak terlihat jelas pada awalnya, namun jika Anda perhatikan dengan cermat Anda akan melihatnya. tutup berada di dalam kepala untuk kanji ini karena mengandung sesuatu. Bayangkan bagian atas kepala seseorang ditutup oleh penutup. Buka tutupnya dan intip ke dalamnya... penuh dengan koin yen, mata uang Jepang!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Lingkaran** (円), bayangkan Anda sedang membawa **Ember/Yen** untuk ditaruh di atas lingkaran. Kejadian unik ini mengingatkan Anda pada bunyi **えん**!' WHERE id = '807f194f-a005-4bec-9c8b-4f6396ca33d3'; -- 円 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal untuk book terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti buku.

Perhatikan bahwa arti kedua, ketiga, dan keempat dari kanji ini adalah asal, nyata, dan utama. Anda dapat mengetahuinya dengan memikirkan bagaimana buku pada dasarnya berasal dari kehidupan nyata.', reading_mnemonic = 'Ketika Anda sedang melihat **Buku** (本), tiba-tiba muncul sesosok **Pohon/Pondok** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **ほん**.' WHERE id = 'bf4e6392-d4b0-4ee7-9688-c44b491bfb9e'; -- 本 (kanji)
UPDATE items SET meaning_mnemonic = 'Setiap hari adalah setiap hari (atau hanya setiap hari).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 日 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Setiap hari Anda menonton program favorit Anda, My Nietzsche (まいにち). Ini adalah kartun harian tentang Nietzsche dan kehidupannya, yang Anda ikuti dengan setia. Oh betapa kamu mencintai Nietzsche.' WHERE id = 'cac5eba8-9bf7-4ff7-83df-c288c46ccfb2'; -- 毎日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki setiap dan tahun untuk digabungkan menjadi setiap tahun (yearly juga bisa digunakan).', reading_mnemonic = 'Pembacaan 毎 sesuai dengan yang Anda harapkan. Namun, bacaan untuk 年 adalah bacaan kun''yomi. Jadi, gunakan pengetahuan Anda tentang kosakata 年 untuk membantu diri Anda sendiri mengingat bacaan kata ini. Anda harus ingat bahwa bacaan untuk kata ini aneh agar bisa masuk ke dalam otak Anda. 

Meskipun demikian, pembacaan まいねん juga berfungsi. Saya tidak terlalu menyukai yang ini dibandingkan まいとし tetapi juga bisa diterima.' WHERE id = 'c3e2d6ba-d9c5-469d-8858-c8f1580ff90e'; -- 毎年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji rest memiliki sedikit hiragana yang melekat, tapi tidak ada yang menunjukkan bahwa itu hanyalah kata benda (itu!). Artinya sama dengan kanji, rest.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji dengan beberapa hiragana, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Jadi, apakah Anda ingin istirahat dari pekerjaan atau sekolah? Anda harus mengatakan "Ya!" (やす).' WHERE id = '25db1579-56d3-4593-99d7-3ac3b6d4608c'; -- 休み (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sebelumnya kehidupan... Jadi kita berbicara tentang seseorang yang memiliki kehidupan sebelumnya, atau mungkin pengalaman hidup sebelumnya? Bila Anda memiliki pengalaman hidup sebelumnya, Anda bisa mengajari orang lain tentang hal itu, sehingga membuat Anda memenuhi syarat untuk menjadi semacam guru.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f7146fe7-358c-4e73-b2f6-ee065821a38c'; -- 先生 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata ini sama dengan arti ''nama'' dalam kanji. Jika Anda bisa mengingatnya, Anda tidak akan kesulitan mengingat kata ini juga.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, kemungkinan besar menggunakan bacaan kun''yomi. Anda tidak mempelajari bacaan ini, jadi inilah mnemonik untuk membantu Anda mengingat: Coba pikirkan bagian pertama dari kata bahasa Inggris name. Apa itu? Itu na (な), seperti kata ini!' WHERE id = 'a880360a-e28f-4b27-b951-b292f620772d'; -- 名 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Setiap bulan adalah setiap bulan (seperti yang Anda ketahui dari semua kosakata yang berhubungan dengan bulan). Ini juga bisa berarti bulanan.', reading_mnemonic = 'Bacaan paling umum untuk kata ini adalah bacaan on''yomi untuk 毎 ditambah bacaan kun''yomi untuk 月. Itu menjadikannya まいつき. Tapi bisa dibaca まいげつ menggunakan kedua pembacaan on''yomi juga. Anda bisa menggunakan keduanya!' WHERE id = '736cc5f6-5848-49e6-8856-ba40569f5dcf'; -- 毎月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda memiliki istirahat hari Anda memiliki liburan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 日 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Setiap liburan, Anda makan bukan hanya satu, tapi dua mentimun. Wah, dua (きゅうじつ)? Tenang saja!' WHERE id = 'ec493294-08e4-441f-b9de-977b62251943'; -- 休日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika sebuah kata vocab berbentuk kanji tunggal tanpa okurigana (hiragana yang melekat pada kanji), biasanya kata tersebut memiliki arti yang sama dengan kanji asal kata tersebut. Jika Anda mengetahui arti kanjinya, Anda juga akan mengetahui arti vocabnya. Ini seratus!', reading_mnemonic = 'Untuk membaca kanji 百 (ratus), bayangkan ada seratus orang yang memiliki **Hidung** (ひゃく) yang sangat panjang!' WHERE id = '1086bb7a-c2eb-459d-9de0-59aa0d18e495'; -- 百 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada daun yang tumbuh dari matahari! Anda terbang ke luar angkasa untuk memeriksanya dan ketika Anda mendekat, Anda melihat bahwa itu bukan hanya satu daun, melainkan seratus! Masuk akal, Anda tidak akan bisa melihat satu daun pun di matahari dari tempat Anda berada di bumi.', reading_mnemonic = 'Untuk membaca kanji 百 (ratus), bayangkan ada seratus orang yang memiliki **Hidung** (ひゃく) yang sangat panjang!' WHERE id = '4959941b-c6c8-4ff3-bb66-0b754d4247fd'; -- 百 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda melihat beberapa jendela... Anda memiliki senjata. Menurutmu apa yang akan kamu lakukan dengan senjata ini? Tentu saja, Anda akan memotret jendelanya... setiap jendelanya. Setiap dan setiap orang.', reading_mnemonic = 'Bagaimana cara membaca kanji **Setiap** (毎)? Ingat saja bahwa **Maimun/Mainan** sangat menyukai setiap! Hubungan erat ini akan membantu Anda mengingat bunyi **まい**.' WHERE id = '6c84d6ef-a5fc-4a70-8439-cb51a1ff7bb4'; -- 毎 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda memiliki dua ratusan, Anda memiliki dua ratus.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f4d386c1-8167-433a-b83d-e19fafe7aa7e'; -- 二百 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji 休 berarti istirahat, jadi apa versi kata kerjanya? Itu adalah beristirahat atau mengambil cuti.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda perlu beristirahat, bukan? Jangan hanya menjawab dengan "ya", ini layak mendapat "YAASS" (やす)! YAAASSS ayo RESSST!!!' WHERE id = '5fe7340e-c604-4857-bdf7-2d3640e6c515'; -- 休む (vocabulary)
UPDATE items SET meaning_mnemonic = 'triceratops diletakkan di tempat kering. Tapi ukurannya sangat besar, dan letaknya miring, jadi hanya setengah saja yang kering.', reading_mnemonic = 'Ketika Anda sedang melihat **Setengah** (半), tiba-tiba muncul sesosok **Hantu/Handuk** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **はん**.' WHERE id = '66ab5dce-b3e5-4c33-a4d8-884f302a93d1'; -- 半 (kanji)
UPDATE items SET meaning_mnemonic = 'Slide kering pada siang. Matahari paling terang di siang hari, sehingga mengeringkan embun pagi dari perosotan, sehingga siang hari menjadi waktu yang tepat untuk meluncur.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Siang** (午), bayangkan Anda sedang membawa **ご** untuk ditaruh di atas siang. Kejadian unik ini mengingatkan Anda pada bunyi **ご**!' WHERE id = '234d47e4-5c34-48f6-8625-6fc6ffaad065'; -- 午 (kanji)
UPDATE items SET meaning_mnemonic = 'Tambahkan setetes matahari pada sesuatu dan itu akan mengubahnya menjadi putih. Matahari sangat terik, bahkan setetes pun bisa membakar apa pun yang putih. Menurut Anda mengapa banyak pantai berwarna putih? Bahkan tetes tabir surya yang Anda gunakan untuk menghentikan sinar matahari pun berwarna putih. Jadi ketika Anda memikirkan tetesan matahari, pikirkanlah putih.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '903d9e69-5654-41a7-939b-cc19ce20c934'; -- 白 (radical)
UPDATE items SET meaning_mnemonic = 'Ada dua gunung di depan Anda... dan mungkin masih banyak lagi di sekitar Anda juga. Anda terjebak, dan tidak tahu cara keluar. Anda dengan panik mencari keluar sebelum Anda mati kedinginan. Yang paling penting adalah menemukan jalan keluar dari pegunungan ini - hidup Anda bergantung padanya.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Keluar** (出) tiba-tiba berbicara dan meminta **しゅつ**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **しゅつ**.' WHERE id = 'f28422fc-dbdc-475a-8520-ab31153aa784'; -- 出 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda diketahui terkena penyakit malam jari kaki, yaitu ketika jari kaki Anda terbakar setelah menjadi sangat-sangat panas (bayangkan hal ini terjadi, aduh!). Satu-satunya cara untuk memperbaikinya adalah dengan mendinginkan kaki Anda, dan cara terbaik untuk melakukannya adalah dengan pergi keluar.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Luar** (外) tiba-tiba berbicara dan meminta **Gajah/Gagang**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **がい**.' WHERE id = '4d95af23-fb7d-4209-a396-dcff0be3f8c7'; -- 外 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda tahu balok baja besar yang digunakan untuk rangka bangunan besar? Ini seperti akhir dari salah satu dari itu, dan mempunyai bentuk yang sangat berbeda, sama seperti radikal ini. Balok-balok ini digunakan dalam konstruksi, itulah sebabnya kata radikal ini berarti konstruksi. Lucunya, Anda menggunakan balok-balok ini untuk menyusun bangunan seperti Anda akan menggunakan radikal ini untuk menyusun kanji!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5fd06fc6-f1ca-445a-8ff3-76da261c554e'; -- 工 (radical)
UPDATE items SET meaning_mnemonic = 'Bayangkan memutarbalikkan tubuh Anda sedemikian rupa sehingga kaki Anda berakhir di dalam mulut Anda. Anda telah membungkukkan tubuh Anda dengan cara yang salah untuk mencapai hal ini. Faktanya, jika Anda melihat diri Anda sendiri, Anda terlihat seperti persegi sekarang... Anda hanyalah orang dengan empat sisi.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Empat** (四), bayangkan Anda sedang membawa **Singa/Silet** untuk ditaruh di atas empat. Kejadian unik ini mengingatkan Anda pada bunyi **し**!' WHERE id = '1fac1a91-04c9-4f19-8eec-100f8ab93289'; -- 四 (kanji)
UPDATE items SET meaning_mnemonic = 'Lihat laci? Ada dua rak di dalamnya dengan pegangan nubbin kecil di masing-masing rak agar Anda dapat menariknya keluar. Bayangkan menggunakan laci ini - bentuknya sangat aneh.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '09d48174-1cf5-41f4-92bf-0d1bb732e35b'; -- 母 (radical)
UPDATE items SET meaning_mnemonic = 'Bayangkan saja seekor binatang dengan kelopak di kepalanya dan sirip di kakinya, berlari kesana kemari dengan penampilan yang paling gila (bayangkan!). Saat ia berlari ke arah Anda, ia memperlihatkan bagian atas kepala tutupnya. Di atasnya tertulis angka 666. Kenapa? Karena itu adalah keturunan iblis, dan angka enam adalah angka iblis.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Enam** (六), bayangkan Anda sedang membawa **Roti/Roda** untuk ditaruh di atas enam. Kejadian unik ini mengingatkan Anda pada bunyi **ろく**!' WHERE id = 'dff81d43-6045-41b0-8bcc-d9b6a1bdcd43'; -- 六 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini terlihat seperti sesuatu yang Anda taruh di ketel atau panci, bukan? Bahkan ada pegangan kecil untuk memastikan Anda tidak terbakar. Ini semacam penutup.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1c99f153-8c0c-4bd2-9280-6163e4dbd204'; -- 亠 (radical)
UPDATE items SET meaning_mnemonic = 'Anda memiliki pi yang keluar dari mulut. "3.14," katanya. Kita harus membawa rahasia lingkaran itu, menjauh dari sini. Kita harus pergi ke tempat ajaib di mana tak seorang pun akan menganiaya kita karena matematika kita... tempat di Barat!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '3b9a0280-235a-4749-adf4-b395ecf69e66'; -- 西 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya perubahan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'c9b019d0-4c02-4f13-98d9-d6ec31a2ac1e'; -- 化 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah jenis kepala yang mungkin digambar oleh seorang anak—dapatkah Anda membayangkannya dengan mata, hidung, mulut, dan telinga juga? Siapapun yang kepalanya ini, bentuknya persegi banget. Mungkin itu adalah kepala dari karakter kartun spons yang terkenal. Hmm.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9cb4ba37-1b23-4d87-ab87-e19f23af9b16'; -- 冂 (radical)
UPDATE items SET meaning_mnemonic = 'Bentuk radikal ini mirip dengan karakter katakana ト (to), yang bunyinya seperti kata toe. Jadi ketika Anda melihat ト, pikirkanlah.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '12682aed-baed-4482-b697-3b1dc5265707'; -- ト (radical)
UPDATE items SET meaning_mnemonic = 'Seimbangkan sendok pada jari Anda yang runcing dan sendok itu akan selalu mengarah ke utara. Sendok itu seperti jarum kompas dan jari-jari Anda memandu pengetahuan yang sudah dimiliki tubuh Anda dan menggunakannya untuk menunjuk ke utara. Itu sains, teman-teman!

Perhatikan bagaimana radikal jari sedikit berbeda di sini? Itu karena Anda menunjukkannya dengan sangat keras.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Utara** (北) tiba-tiba berbicara dan meminta **きた**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **きた**.' WHERE id = '28e478de-b40e-4707-8cc8-0a4abc9035e8'; -- 北 (kanji)
UPDATE items SET meaning_mnemonic = 'Apakah Anda melihat penjara dan drop radikal yang mengarang radikal ini? Penjara ini menahan jatuhnya karena ini malam. Udara malam bekerja lebih baik dalam menahan tetesan cairan seperti ini, itulah sebabnya semuanya tertutup embun di pagi hari.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7474a87f-8ddd-49d6-9d38-654db875dd39'; -- 夕 (radical)
UPDATE items SET meaning_mnemonic = 'Pemimpin (ｲ) yang radikal memiliki sesuatu yang ekstra di atas dirinya, menahannya, menahannya. Itu menyebabkan dia menunggu... itu menyebabkan dia berkeliaran.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '41f7383d-d00e-48b3-9dd0-3f90116af903'; -- 彳 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat salib dalam bentuk persegi semu? Itu adalah bingkai jendela besar yang dapat Anda lihat ke luar. Bentuknya tidak sempurna seperti sawah, lebih artistik. Itu sebabnya ini adalah jendela dan 田 bukan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '2f57ba2c-69a5-4772-9eb6-9cf7023c0ed3'; -- 毋 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya setengah.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'd197175b-208a-4ab2-ac44-9c080a01e985'; -- 半 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya utara.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '36453a5f-a188-41f9-90d7-52f49d712e61'; -- 北 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini adalah harta karena "X menandai titiknya", demikian kata mereka. Bukankah ini terlihat seperti tanda X pada peta harta karun bajak laut? Kamu ingin mencari harta karun itu sekarang, kan?!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6d5f57c8-bd3f-463e-921f-fd5a7127cf72'; -- メ (radical)
UPDATE items SET meaning_mnemonic = 'pemimpin berada di sebelah pohon. Apa yang dia lakukan? Dia bersandar padanya, beristirahating.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Istirahat** (休) tiba-tiba berbicara dan meminta **Kura-kura**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **きゅう**.' WHERE id = '96f0f1c7-d7a0-44c8-8ede-0970b1cd11a5'; -- 休 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki tiga ratusan. Apa hasilnya? Tiga ratus.', reading_mnemonic = 'Pembacaannya agak aneh, jadi berhati-hatilah. Anda seharusnya sudah mengetahui pembacaan on''yomi, namun ひゃく rendakus hingga びゃく. Pola ini akan berulang dengan 三 + banyak counter kanji yang bisa rendaku, jadi perhatikan pola ini saat Anda membaca bahasa Jepang.' WHERE id = '4c8b88e7-8136-4403-ba0d-c5dab1ef0404'; -- 三百 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa itu surga energi? Jika dipikir-pikir, itulah semua benda yang jatuh ke atas kita dari langit. Petir, hujan, salju, hujan es... Apa semua itu? Itu adalah cuaca.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e0f2d7d3-6b7a-4738-8f81-de538d74c9eb'; -- 天気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'sebelumnya bulan adalah bulan lalu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 月 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Mulai bulan lalu, centaurmu bangun (んげつ) setiap malam dan tidur di tempat tidurmu. Rupanya, dia mendapat mimpi buruk yang sangat buruk. Centaur kecil yang malang.' WHERE id = '27f66d42-54de-40d5-b409-8785c95ac04e'; -- 先月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'sekarang tahun adalah tahun berapa? Ini adalah tahun ini.', reading_mnemonic = 'Pada pembacaan pertama (yang lebih umum), こん dari 今 sebenarnya hanyalah こ. Terkadang ini dipersingkat, jadi berhati-hatilah. Juga, 年 adalah bacaan kun''yomi karena alasan tertentu. Benar-benar misteri mengapa hal ini terjadi. Mungkin alien kuno tahu, tapi saya tidak. Anda harus mengingat pengecualian ini dengan otak Anda dan mengandalkan SRS untuk memberikan pengetahuan ini kepada Anda.

Pembacaan kedua, yang kurang umum namun masih cukup umum, lebih masuk akal. Ini adalah こんねん dan hanya mengikuti pola jukugo.' WHERE id = '4efa1368-1caf-457c-99fc-c3e720065d83'; -- 今年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda pergi ke barat. Bahkan itu adalah Wild West. Tidak banyak orang di sini, sehingga mudah untuk menemukan niche (にし) untuk bisnis minyak ular Anda.' WHERE id = 'fee6608e-4579-491a-9cfc-34544475aeba'; -- 西 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bagian sapi dari kanji ini sedikit diubah, tapi saya rasa Anda bisa melihat di mana letaknya. gun terlihat baik-baik saja. Pikirkan kembali kenangan palsu yang Anda alami saat tinggal di pertanian. Anda punya senjata, dan Anda harus menggunakannya pada sapi (ruh roh). Sekali tahun di Tahun Baru, Anda harus keluar dan menembak salah satu sapi. Ini hanya syuting tahunan, jadi setidaknya ada jeda.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Tahun** (年), bayangkan Anda sedang membawa **Nenek/Nanas** untuk ditaruh di atas tahun. Kejadian unik ini mengingatkan Anda pada bunyi **ねん**!' WHERE id = '9d03603c-1196-482b-ad72-44ad34c2d50d'; -- 年 (kanji)
UPDATE items SET meaning_mnemonic = 'Arti kata ini cukup aneh, tidak ada hubungannya dengan arti kanji yang Anda pelajari. Kata ini berarti melaksanakan sesuatu. Mungkin Anda bisa menganggapnya seperti seseorang berkata "Kamu (う) pergi lakukan tugas itu!" untuk membuat diri Anda melaksanakan tugas tersebut. Apa pun yang Anda lakukan, ketahuilah bahwa ini adalah kata pengecualian yang aneh, jadi Anda mungkin harus bekerja ekstra untuk mengingatnya.', reading_mnemonic = 'Pembacaannya juga merupakan pengecualian yang aneh. Anda harus mengingat bagian おこな. Mungkin mnemonik ini bisa membantu: Anda harus melaksanakan suatu tugas tetapi Anda tidak terlalu bersemangat melakukannya. Kemudian Anda mengetahui tugas tersebut akan membawa Anda ke Kona, Hawaii. "Oh, Kona!?" (おこな), kamu berteriak. Dalam hal ini, Anda akan melakukannya dengan benar.' WHERE id = '1274870e-da4e-4b10-88d1-36bc5f16d20d'; -- 行う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Geser beberapa kotoran pada kaki Anda sehingga Anda dapat merasa seperti berasal dari masa lalu. Segala sesuatu dari masa lalu ada di dalam tanah. Orang mati, tulang dinosaurus, rahasia ibumu di dalam kotak dari kehidupan masa lalunya. Semua hal ini kembali kepada Anda saat Anda menggeser tanah ke seluruh kaki Anda.', reading_mnemonic = 'Bagaimana cara membaca kanji **Sebelum** (先)? Ingat saja bahwa **Senter/Semen** sangat menyukai sebelum! Hubungan erat ini akan membantu Anda mengingat bunyi **せん**.' WHERE id = 'a349c118-a873-4342-a1ed-ded325eadb69'; -- 先 (kanji)
UPDATE items SET meaning_mnemonic = 'Narwhal mulut berada di sisi kanan kepalanya. Bahkan, beberapa orang mengira mereka tidak punya mulut sama sekali karena tidak melihat dari kanan. Kesalahan pemula.

Lihat bagaimana posisi radikal "mulut" di sebelah kanan radikal "narwhal"? Itu akan membantu Anda mengingat bahwa ini artinya benar.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Kanan** (右) tiba-tiba berbicara dan meminta **Yuda**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ゆう**.' WHERE id = '99688031-c477-44ba-ac57-8d50d0c84ce1'; -- 右 (kanji)
UPDATE items SET meaning_mnemonic = 'Apa yang dimaksud dengan malam mulut? Bayangkan sebuah mulut yang berada di langit malam. Ia hanya ada di sana, berbicara, dan hanya keluar pada malam hari. Ia hanya muncul di satu wilayah di dunia (wilayah mana yang akan Anda pilih? Bayangkan diri Anda pergi ke tempat itu untuk melihat “mulut malam”), dan hanya muncul satu bulan dalam setahun (lebih lanjut tentang ini sebentar lagi). “Mulut malam” adalah yang paling terkenal di area _____ (ini adalah area yang Anda pilih). Dia sangat terkenal sehingga semua orang tahu namanya (“Mulut Sore.”).', reading_mnemonic = 'Ketika Anda sedang melihat **TIDAK** (名), tiba-tiba muncul sesosok **Meja/Merak** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **めい**.' WHERE id = '51b7b8a2-f982-4b04-8275-1660a6c39433'; -- 名 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Anda juga dapat menggunakan kata ini untuk membicarakan usia seseorang.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

tahun ini kamu berencana membuang (とし) semua barang lamamu sebagai resolusi Tahun Baru. Anda mengucapkannya "toshing", karena kekuatannya lebih besar.' WHERE id = 'bf08f040-526b-44cc-860c-5ba8666ed0cb'; -- 年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'toko anggota adalah seseorang yang menjadi "anggota" (alias dipekerjakan oleh) toko. Ini adalah staf toko.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'eedf6f4e-d83f-440a-b50e-a0ce8ec1693d'; -- 店員 (vocabulary)
UPDATE items SET meaning_mnemonic = 'bergerak benda... pikirkan tentang "benda" yang bergerak. Secara teknis bisa berupa banyak hal (alias apa saja pada dasarnya), namun dalam hal ini yang kita bicarakan adalah makhluk hidup yang bergerak. Kami tidak akan memasukkan manusia, karena manusia terlalu baik untuk disebut benda. Ini mengacu pada hewan.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '0b2488bf-2941-4b16-b3ed-eb3b9bf97058'; -- 動物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari buruk? Ini juga buruk.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Tahukah Anda bagaimana di alam semesta Mario semua versi buruk disebut "WARU" (わる)? Misalnya: "WARUIJI" dan "WARIO". Itu karena mereka jahat. Mereka berasal dari kanji ini. Jadi, jika Anda perlu mengingat bacaan ini, pikirkan kembali Wario dan Waruigi.' WHERE id = 'ab60e133-2a36-4b83-b1ae-caa96101a22b'; -- 悪い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sekarang Anda seharusnya sudah mengetahui bahwa 終わる berarti "mengakhiri" atau "menyelesaikan". Jadi apa versi kata benda dari kata itu? Ini akan menjadi akhir atau akhir.', reading_mnemonic = 'Bacaannya berasal dari 終わる. Selama kamu tahu kata itu, kamu bisa mempelajari bacaan kata ini juga!' WHERE id = 'cd2dcd65-c11e-4a72-82a0-b0f57d30eb82'; -- 終わり (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang istimewa dan terpisah dari yang lain adalah, ya, special.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '4b016019-8a63-4f5a-ad49-c91e209a8860'; -- 特別 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang dengan energi buruk adalah seseorang yang memiliki niat jahat, kedengkian, atau niat jahat. Semoga Anda tidak memiliki terlalu banyak 悪気.', reading_mnemonic = 'Pembacaannya sendiri memiliki banyak 悪気 dengan semua pengecualian yang dimilikinya. Bagian 悪 dibaca seperti 悪い. Kemudian, 気 adalah rendaku. Sungguh bacaan yang jahat. Coba pikirkan, "bacaan paling jahat apa yang bisa saya temukan?" ketika Anda melihat kata ini. Maka semoga Anda bisa membacanya.' WHERE id = '8b6e3edf-0a04-42d5-b259-4f5e35dabc82'; -- 悪気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 自動 adalah otomatis. Jadi apa itu mobil matic? Itu adalah mobil, atau sekadar mobil.', reading_mnemonic = 'Bacaannya berasal dari gabungan bacaan 自動 dan kanji 車.' WHERE id = 'ba78b94f-76bf-4e0c-a8ff-87a09cbeaae2'; -- 自動車 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari kanji mengajar. Jadi artinya mengajar.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda sudah mempelajari bacaan ini ketika mempelajari 教える, jadi Anda seharusnya bisa membaca kata ini juga.' WHERE id = '118e1e54-8a89-4d69-aa91-854b641ab884'; -- 教え (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu menuju (に) khusus. Hal itu terutama spesial, bukan begitu?', reading_mnemonic = 'Bacaannya sama dengan bacaan yang Anda pelajari untuk kanji ini.' WHERE id = '5e6c9354-f9c6-4b6d-a660-e997ecad8010'; -- 特に (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari beberapa kaki yang membawa matahari keluar dari penjara. Kaki itu milikmu. Namun, ketika polisi menghentikan Anda, apa alasan Anda? Buatlah satu dan ucapkan dengan lantang, dimulai dengan, "Alasan saya adalah..."', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1597cae0-00d6-43c6-8eb5-bcf359aec52f'; -- 免 (radical)
UPDATE items SET meaning_mnemonic = 'Gunakan skuter untuk melakukan perjalanan keliling dunia dan itu akan memakan waktu seminggu penuh. Tujuh hari penuh!', reading_mnemonic = 'Bagaimana cara membaca kanji **Minggu** (週)? Ingat saja bahwa **Susu/Sumpit** sangat menyukai minggu! Hubungan erat ini akan membantu Anda mengingat bunyi **しゅう**.' WHERE id = '957310e3-5b90-4355-96b4-5d96d1d9ddbe'; -- 週 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki pribadi busur yang terbuat dari serangga yang sangat kuat. Tubuh serangga sangat tahan lama, sehingga menghasilkan busur yang kuat. Kamu juga harus kuat untuk menggunakannya karena dibuat hanya untuk senjata yang kuat.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kuat** (強), bayangkan Anda sedang membawa **Kipas/Kikir** untuk ditaruh di atas kuat. Kejadian unik ini mengingatkan Anda pada bunyi **きょう**!' WHERE id = '36b4bc5d-c5d5-4c76-8800-a223ccfcf285'; -- 強 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata hitam radikal dan kanji hitam sama persis.', reading_mnemonic = 'Bagaimana cara membaca kanji **Hitam** (黒)? Ingat saja bahwa **Koko/Koki** sangat menyukai hitam! Hubungan erat ini akan membantu Anda mengingat bunyi **こく**.' WHERE id = '4b4703e7-2ddb-48ef-9add-d50191e413fb'; -- 黒 (kanji)
UPDATE items SET meaning_mnemonic = 'makaning aula adalah ruangan besar tempat Anda makan. Di ruangan besar manakah Anda makan? Bagaimana dengan kafetaria, ruang makan, atau restoran?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '86bf558b-cfeb-44af-b43a-7bbebcd283f6'; -- 食堂 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika tofu di lingkungan Anda yang ramah mengambil pistol dan mengarahkannya ke arah Anda, Anda mungkin ingin melakukan perjalanan. Tahu ini jelas ada yang salah. Jika ia mengambil pistol dan mengarahkannya ke arah Anda, mungkin sekarang saat yang tepat untuk pergi dan melakukan perjalanan yang telah Anda bicarakan.', reading_mnemonic = 'Bagaimana cara membaca kanji **Perjalanan** (旅)? Ingat saja bahwa **Roti/Roda** sangat menyukai perjalanan! Hubungan erat ini akan membantu Anda mengingat bunyi **りょ**.' WHERE id = '436deb91-e160-4d80-95ae-e03178a87100'; -- 旅 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada sendok yang menyendok dua tetes cairan. Lihat bagian gagang dan sendok sendoknya? Bayangkan menyendok air ke dalam mulut Anda. MM.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '53f3131c-8a74-4bcd-9f96-05c61c9afe2f'; -- 斗 (radical)
UPDATE items SET meaning_mnemonic = 'perusahaan anggota adalah karyawan dan staf.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ab66f352-f448-4bd4-bec6-2c4401308a32'; -- 社員 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mudah-mudahan Anda sudah melihat 旅行 pada saat ini. Ini adalah versi kata kerjanya. Alih-alih "berjalan", yang dimaksud adalah to travel atau melakukan perjalanan. Ini menyenangkan untuk dilakukan. Anda harus melakukannya!', reading_mnemonic = 'Bacaannya sama dengan 旅行, tapi kebetulan juga menggunakan bacaan yang Anda pelajari dengan kanji, jadi Anda seharusnya bisa membacanya.' WHERE id = 'b84b9b81-9781-4ed3-b022-d5bf9fd0b3ba'; -- 旅行する (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanopi radikal dengan es mengalir di bagian belakang. Kalau nongkrong di kanopi yang dingin seperti ini pasti sakit. Bayangkan Anda sedang sakit dan sendirian di dalam kanopi yang dingin. Brrrr, oh tidak... ACHOO!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '3f166059-62f8-4df9-8d8e-cffbec718837'; -- 疒 (radical)
UPDATE items SET meaning_mnemonic = 'Pasti ada banyak putih burung di luar sana, tapi ada satu yang sangat menonjol jika Anda bertanya kepada saya. Burung itu adalah angsa. Besar, putih, dan megah.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '276aeffc-d636-4a89-88b3-12a018185743'; -- 白鳥 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti meminjam jadi versi kosakata kata kerjanya adalah to pinjam.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Kamu belum mempelajarinya dengan kanji ini, jadi inilah mnemonik yang bisa membantumu: Bung, bolehkah aku meminjam mobilmu (か)? Silakan?' WHERE id = '00cc340a-6f0b-40e3-87d4-fb4fd2c61f59'; -- 借りる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda telah melihat bahwa 旅行 adalah "perjalanan". Jadi siapakah seseorang yang melakukan perjalanan? Yaitu turis atau traveler.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Akan membantu jika Anda sudah mengetahui bacaan 旅行.' WHERE id = '2e8fceaa-fc88-4d65-a736-73fc6cd7b0aa'; -- 旅行者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'desa raja adalah alasan dia menjadi raja. Tanpa desa, tidak ada alasan untuk mempunyai raja.', reading_mnemonic = 'Ketika Anda sedang melihat **Alasan** (理), tiba-tiba muncul sesosok **Riam/Ribu** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **り**.' WHERE id = '4f337b47-9a7f-4f29-80ce-8ee55c3376a0'; -- 理 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal ini sudah terlihat seperti sepasang sayap bukan? Apa yang ada di sayap? Biasanya banyak bulu.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '17370108-a9bc-4e6b-85ea-13313dce8a13'; -- 羽 (radical)
UPDATE items SET meaning_mnemonic = 'Jika seseorang sedang menuju ke arah Anda dengan senjata, letakkan panah di busur Anda dan kumpulkan suku Anda di belakang Anda karena itu akan menjadi nyata! Orang bodoh bersenjata ini sedang menuju ke arah Anda dan dia bahkan tidak tahu apa yang akan Anda dan suku Anda lakukan padanya. Jika dia mendekat, kemungkinan besar Anda akan menembakkan panah itu tepat ke arahnya.', reading_mnemonic = 'Bagaimana cara membaca kanji **Suku** (族)? Ingat saja bahwa **Soto/Sosis** sangat menyukai suku! Hubungan erat ini akan membantu Anda mengingat bunyi **ぞく**.' WHERE id = '9af70324-f30c-464d-b003-0c3832406374'; -- 族 (kanji)
UPDATE items SET meaning_mnemonic = 'utas yang mengikat Anda dengan klan Anda adalah kertas. Surat-suratmu, itu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kertas** (紙), bayangkan Anda sedang membawa **かみ** untuk ditaruh di atas kertas. Kejadian unik ini mengingatkan Anda pada bunyi **かみ**!' WHERE id = '5b5be093-c2ed-427b-9304-3a941cf29524'; -- 紙 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari peti mati dan anak-anak. Untuk menjauhkan seorang anak dari peti mati, mereka memerlukan guru yang baik untuk memastikan mereka tahu untuk tidak menempelkan garpu di stopkontak atau menari di tengah kemacetan. Itu sebabnya orang radikal ini adalah seorang guru.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9f88ea2e-8d45-4702-81ef-c3e1cd917131'; -- 孝 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari cara membacanya, jadi inilah mnemonik untuk membantu Anda dengan kata ini: Anda akan melakukan perjalanan tetapi Anda harus membawa kucing kecil (たび) Anda untuk menemani Anda. Kucing ini membuat Anda tetap tenang dan membiarkan Anda meninggalkan rumah, tetapi maskapai penerbangan tidak mengizinkan Anda membawanya dalam perjalanan ini. Apa yang harus dilakukan?' WHERE id = '9988eb32-ad85-4f5c-9d25-976757a14e18'; -- 旅 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana Anda mempelajari kata 文字 dan 通り? Ya, "jalan" yang terbuat dari "huruf" adalah secara harfiah sesuai dengan huruf. Mengedip.', reading_mnemonic = 'Ini adalah kombinasi kata 文字 dan 通り yang sudah Anda pelajari, jadi Anda harus bisa membaca yang ini. Pastikan Anda ingat bahwa とおり menjadi どおり karena rendaku.' WHERE id = '95748772-51bb-43c0-a9a5-a3ce17fcd284'; -- 文字通り (vocabulary)
UPDATE items SET meaning_mnemonic = 'uang (dan emas) yang Anda pinjam adalah hutang Anda. Pastikan untuk membayarnya kembali sebelum yakuza datang menjemput Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. しゃく disingkat menjadi しゃっ, jadi berhati-hatilah. Anggap saja itu seperti kekalahan kecil Anda dari yakuza, karena mereka tidak senang Anda tidak membayar kembali utang Anda. *memotong*' WHERE id = '4f6c382c-a190-497d-9f3c-cdbd7f13a149'; -- 借金 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda pergi dalam perjalanan, Anda melakukan perjalanan. Ini adalah perjalanan. Anda harus mencoba melakukan ini sesekali! Mungkin 旅行 yang menyenangkan ke Jepang?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'b7844cd3-9d3e-45ab-8878-cda7b425eb87'; -- 旅行 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Pembacaan yang dipelajari dengan kanji sama dengan pembacaan kosakata.' WHERE id = 'a9f8c478-67fb-4d53-939f-598548f40caf'; -- 夏 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seorang guru di musim dingin paling bahagia karena mereka bisa mengajar! Anak-anak tidak bisa keluar dan bermain karena terlalu dingin. Mereka semua harus masuk dan tetap hangat saat guru mengajar!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Ajarkan** (教), bayangkan Anda sedang membawa **Kipas/Kikir** untuk ditaruh di atas ajarkan. Kejadian unik ini mengingatkan Anda pada bunyi **きょう**!' WHERE id = '9ef4b3ce-5a9b-4f69-8910-dfbb343a65a0'; -- 教 (kanji)
UPDATE items SET meaning_mnemonic = 'Berjalan ke dalam diri sendiri dalam mimpi dan Anda pasti akan terbangun.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Bangun** (起), bayangkan Anda sedang membawa **お** untuk ditaruh di atas bangun. Kejadian unik ini mengingatkan Anda pada bunyi **お**!' WHERE id = '8c46c30e-d57d-476c-90d9-8f1cb10d2a40'; -- 起 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki beras sendok yang khusus digunakan untuk membayar biaya beras. Tiap sendok sesuatu dikenakan biaya tambahan, jadi saat kamu menggunakan bahan, ada biaya yang harus kamu bayar untuk bahan itu juga.', reading_mnemonic = 'Tahukah Anda bahwa **Biaya** (料) ini sebenarnya dibuat dari tumpukan **Roti**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **りょう**.' WHERE id = 'cfdfb0cb-f43c-4099-a978-07c07b913d11'; -- 料 (kanji)
UPDATE items SET meaning_mnemonic = 'sapi kuil ini adalah istimewa. Sapi ini pasti sangat penting sehingga seluruh kuil didedikasikan untuknya.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Spesial** (特), bayangkan Anda sedang membawa **Toko/Tomat** untuk ditaruh di atas spesial. Kejadian unik ini mengingatkan Anda pada bunyi **とく**!' WHERE id = 'ce3999fb-43fa-4bb0-a261-b85d5c6533ff'; -- 特 (kanji)
UPDATE items SET meaning_mnemonic = 'Bangunan ini memiliki atap dan akan mengajarkan Anda tentang asal-usul banyak hal. Ini adalah institusi!', reading_mnemonic = 'Bagaimana cara membaca kanji **Lembaga** (院)? Ingat saja bahwa **Indah/Intan** sangat menyukai lembaga! Hubungan erat ini akan membantu Anda mengingat bunyi **いん**.' WHERE id = 'cf7cafe5-5fea-4b93-b8c2-c66998a2a067'; -- 院 (kanji)
UPDATE items SET meaning_mnemonic = 'mata daun hanya tumbuh di musim dingin. Namun, setiap daun lainnya akan melakukan hal sebaliknya, yaitu tumbuh di musim panas.', reading_mnemonic = 'Tahukah Anda bahwa **Musim panas** (夏) ini sebenarnya dibuat dari tumpukan **なつ**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **なつ**.' WHERE id = '5761edf2-76f0-4d4e-a61c-ae1ba2815755'; -- 夏 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda harus maafkan saya, memiliki semua kekuatan ini memberikan banyak tekanan dan pengerahan pada tubuh saya. Kekuatanku berasal dari pengerahan otot, jadi mohon maaf jika aku mulai berkeringat.', reading_mnemonic = 'Bagaimana cara membaca kanji **Pengerahan tenaga** (勉)? Ingat saja bahwa **Bendi/Bensin** sangat menyukai pengerahan tenaga! Hubungan erat ini akan membantu Anda mengingat bunyi **べん**.' WHERE id = 'c3d32c5b-e2fe-4769-b7a0-c74276c08d3c'; -- 勉 (kanji)
UPDATE items SET meaning_mnemonic = 'Ketika sesuatu berat, Anda memerlukan banyak tenaga untuk memindahkannya. Itu tidak akan bergerak kecuali Anda menggunakan banyak tenaga. Benda itu berat dan kecuali Anda menggunakan semua kekuatan yang Anda punya, benda itu tidak akan bergerak.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Pindahkan** (動), bayangkan Anda sedang membawa **Domba/Topi** untuk ditaruh di atas pindahkan. Kejadian unik ini mengingatkan Anda pada bunyi **どう**!' WHERE id = 'e45c1e79-76e5-49f4-931e-e5cfddf00ea2'; -- 動 (kanji)
UPDATE items SET meaning_mnemonic = 'desa sebelumnya (yang merupakan desa sebelum menjadi desa) adalah ladang.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Bidang** (野) tiba-tiba berbicara dan meminta **Yoyo**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **や**.' WHERE id = '248de31e-896c-4634-8530-8548c9525be1'; -- 野 (kanji)
UPDATE items SET meaning_mnemonic = 'utas dari musim dingin terbagi menjadi dua ketika tahun berakhir berakhir. Separuh melambangkan tahun yang baru saja Anda jalani, dan separuh lainnya melambangkan permulaan tahun baru, memotong setengah musim dingin dan mengakhiritahun.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Akhir** (終) tiba-tiba berbicara dan meminta **Susu/Sumpit**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **しゅう**.' WHERE id = '69927f04-0a86-404d-bca7-3eb9fde99aa1'; -- 終 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika mobil Anda menabrak awan Anda akan berputar mengelilinginya alih-alih langsung melewatinya. Awan sangat sulit untuk dilihat, jadi meskipun Anda berusaha untuk tidak melihatnya, Anda tetap berputar dalam lingkaran rapat di atas dan mengelilingi awan.', reading_mnemonic = 'Bagaimana cara membaca kanji **Berputar** (転)? Ingat saja bahwa **てん** sangat menyukai berputar! Hubungan erat ini akan membantu Anda mengingat bunyi **てん**.' WHERE id = '917add9d-33b0-4843-96c2-b5327f4f21c3'; -- 転 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda menemukan beberapa putih bulu dan Anda ingin mempelajari lebih lanjut tentang dari mana bulu tersebut berasal dan terbuat dari apa.', reading_mnemonic = 'Ketika Anda sedang melihat **Pelajari** (習), tiba-tiba muncul sesosok **Susu/Sumpit** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **しゅう**.' WHERE id = 'fd190c3d-cb77-4874-bd42-625ee539b1e7'; -- 習 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki kuat kekuatan. Anda kuat dan kuat. Rasakan kekuatan Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 力 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Tidak ada yang kuat dan strong seperti gembok きょうと (きょうりょく). Itu adalah kunci legendaris yang diproduksi di きょうと kuno, dikabarkan sebagai kunci terkuat yang pernah ada. Menurut Anda, kekuatan magis apa yang ada di balik kekuatan kunci きょうと?' WHERE id = 'f18d3198-02e4-472c-87a8-6988f61ac94e'; -- 強力 (vocabulary)
UPDATE items SET meaning_mnemonic = 'ruang mengajar hanyalah sebuah ruang kelas.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e6547c0d-432c-4a6a-8d41-64bd02bac8d4'; -- 教室 (vocabulary)
UPDATE items SET meaning_mnemonic = 'minggu sebelumnya adalah minggu lalu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '36a7a780-1e95-49b5-9c4f-cdda9c2129c3'; -- 先週 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tangan kertas adalah surat karena huruf pada umumnya ditulis dengan tangan di atas kertas.

Jika Anda menginginkan gambar yang lebih gamblang, bayangkan menulis surat di tangan Anda, dan betapa sakitnya jika tangan Anda dipotong dan dikirimkan.', reading_mnemonic = 'Bacaannya kun''yomi ganda (bagian tubuh cenderung membuat kanji dalam kata berubah menjadi bacaan kun''yomi). Kedua kanji dalam kata ini telah Anda pelajari sejak awal, jadi Anda harus bisa membaca kata ini. Hati-hati dengan rendaku yang membuatnya がみ, bukan かみ.' WHERE id = '09e8b29a-7f20-4980-b870-b0f0c2ee4fc8'; -- 手紙 (vocabulary)
UPDATE items SET meaning_mnemonic = 'orang berkulit hitam hanyalah orang berkulit hitam, seperti 白人 yang berarti "orang berkulit putih", namun warnanya berbeda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Bayangkan orang berkulit hitam yang Anda kenal baik mengenakan jeans coke (こくじん). Yap, jeans seluruhnya terbuat dari botol coke. Itu sebenarnya suatu hal. Cari tahu jika Anda tidak percaya.' WHERE id = '2dbfa41f-f876-4f8d-bfbb-2068190046d4'; -- 黒人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'lembaga sakit adalah tempat orang sakit pergi. Itu adalah rumah sakit.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '608840be-6960-43b6-ac4f-aa7858f2b531'; -- 病院 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu itu putih dan hitam. Bentuknya hitam dan putih (Anda juga bisa mengucapkan putih dan hitam jika Anda mau).', reading_mnemonic = 'Bacaannya kun''yomi, tapi Anda seharusnya sudah melihat 白 dan 黒い secara terpisah sebagai kosa kata sekarang. Bacaannya sama di sini, jadi Anda bisa menerapkan ilmu itu dan membaca kata ini!' WHERE id = 'ab3f895c-c525-4700-b394-3e494013a276'; -- 白黒 (vocabulary)
UPDATE items SET meaning_mnemonic = 'biaya emas (atau uang, jika Anda mau) yang harus Anda bayarkan adalah biaya dan tagihan Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '61fe314f-cf5f-4c81-b179-f5105a51d698'; -- 料金 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti kembali ke rumah sehingga versi kosakata kata kerjanya adalah to return home, to return, atau to go home.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Anda dapat pulang ke rumah dengan gembira, mengetahui cara membaca kata ini! 

Kata ini memiliki kata kerja berpasangan, jadi sebaiknya ingat akhiran る. Bayangkan saja betapa kasarnya (る) ketika seseorang pulang ke rumah tanpa pamit. Saraf!' WHERE id = 'b50431fd-fca3-43d5-a70b-758b6771d6fd'; -- 帰る (vocabulary)
UPDATE items SET meaning_mnemonic = 'kenyataannya adalah hitam. Seperti, sangat hitam sehingga melebihi hitam palsu, itu adalah hitam nyata. Ini sangat hitam hingga gelap gulita.', reading_mnemonic = 'Bacaan 真 adalah bacaan vocab kun''yomi. Bayangkan apa yang gelap gulita. Itu ibumu yang malang (ま). Dia sangat gelap sehingga dia menyedot cahaya, seperti lubang hitam... tunggu, dia adalah lubang hitam, itu menjelaskan mengapa ibumu gelap gulita.' WHERE id = 'fefd7eb0-0f68-48d4-8c41-98da0cae6fd7'; -- 真っ黒 (vocabulary)
UPDATE items SET meaning_mnemonic = '気持ち (perasaan) adalah buruk. Jadi, bisa dibayangkan bagaimana perasaanmu yang tidak enak, itu adalah perasaan buruk. Faktanya, Anda merasa tidak enak.', reading_mnemonic = 'Bacaannya berasal dari kata 気持ち dan 悪い. Semoga Anda pernah melihat keduanya dan bisa menggabungkan keduanya untuk mengetahui bacaannya secara otomatis. Tidak ada perasaan buruk dengan kata ini, bukan?' WHERE id = '381c855e-0d8b-47f6-ac71-ca285b552fb1'; -- 気持ち悪い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda sudah melihat 勉強 (belajar) sekarang, bukan? Nah, ini adalah versi kata kerjanya. Ini adalah untuk dipelajari.', reading_mnemonic = 'Bacaannya sama dengan 勉強. Itu juga bacaan yang Anda pelajari dengan kanji ini.' WHERE id = '91822338-8f03-457e-9bd8-bc0dccad30d0'; -- 勉強する (vocabulary)
UPDATE items SET meaning_mnemonic = 'tangan yang meminjam adalah peminjam.', reading_mnemonic = 'Anda pasti ingin mengetahui kata 借りる dan 手 agar dapat membaca yang ini. Gabungkan mereka untuk mengetahui bacaannya.' WHERE id = '005c4063-11f5-463d-9031-b59176114736'; -- 借り手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari kanji bergerak. Jadi artinya gerakan.', reading_mnemonic = 'Ini adalah bacaan yang sama yang Anda pelajari dari kata 動く. Jika Anda mengetahui kata itu, Anda pasti tahu cara membaca kata ini!' WHERE id = '92e538d1-b3c8-4c0e-9ef5-5db63f23fa78'; -- 動き (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda bertemu cukup banyak anggota, Anda sendiri akan menjadi anggota!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '2628a235-5ab7-4f36-aaa5-bb5145fb429b'; -- 会員 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bagaimana cara mengatasi belajar masalah Anda? Dengan sedikit tambahan sekolah, study, dan learning.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '8fd13dc2-2123-4b95-96fb-e9d678ac6c2c'; -- 学問 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Produk yang Anda bayar biaya untuk makan nanti adalah bahan makanan Anda. Beli sekarang, makan nanti, enak!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '09e5444c-9bf6-48b0-aa8d-b64bed32d856'; -- 食料品 (vocabulary)
UPDATE items SET meaning_mnemonic = 'minggu berikutnya adalah minggu depan. Ini bukan minggu lalu atau minggu ini, ini minggu berikutnya!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '65d2c1fb-32d3-4c85-b558-9bb66f8e036e'; -- 来週 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika energi Anda adalah penyakit, Anda mungkin sakit.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '72ef1c94-317f-4cf8-97e1-28b53af102f8'; -- 病気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'salinan dari realitas sangat mirip dengan sihir. Namun, bagaimana Anda membuat salinan kenyataan? Anda mengambil foto.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'a2643b3b-dfb6-43c0-9d30-392c1de794b2'; -- 写真 (vocabulary)
UPDATE items SET meaning_mnemonic = 'mulut buruk Anda adalah mengatakan hal-hal buruk (seperti biasa!). Segala sesuatu yang keluar dari mulut burukmu ini adalah pelecehan verbal. Suatu hari seseorang akan memasukkanmu ke dalam mulutmu yang buruk itu.', reading_mnemonic = 'Bacaannya merupakan bacaan vocab kun''yomi untuk kedua kanji ini, mungkin karena kata ini hanyalah dua kata yang dirangkai menjadi satu (buruk+mulut). Gunakan pengetahuan Anda tentang kosakata 悪い dan 口 untuk mempelajari pembacaan kata ini.

Oke, aku berbohong. Anda juga dapat melakukan わるぐち jika Anda mau. Maaf telah mengatakan hal buruk seperti itu sebelumnya.' WHERE id = '862d5d54-76e4-4366-aee6-83c1111f7742'; -- 悪口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana Anda mengetahui bahwa 大学 berarti "perguruan tinggi?" institusi yang Anda tuju setelah kuliah adalah sekolah pascasarjana!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '76f33938-fafb-49a3-84e1-5ab78cfd18de'; -- 大学院 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 夏 berarti musim panas dan 休 berarti istirahat. Apa itu "istirahat musim panas"? Ini adalah liburan musim panas atau liburan musim panas.', reading_mnemonic = 'Bacaannya adalah bacaan kun''yomi karena kata ini pada hakikatnya adalah dua kata terpisah yang dirangkai menjadi satu kata. Anda harus mengetahui bacaan 夏 dari kanji dan bacaan 休み dari vocab.' WHERE id = '78d7cf35-93bb-4e4b-906a-33d9063221db'; -- 夏休み (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya lama sekali.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '54e9f16f-477c-402a-90e6-532b346636fd'; -- 昔 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama seperti karakter katakana "ma" (マ). Jadi mari kita buat semuanya tetap sederhana dan jadikan mama yang radikal.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5e8cde1e-d2bb-4e24-8746-dcf017d88552'; -- マ (radical)
UPDATE items SET meaning_mnemonic = 'Ada mata raksasa di atas beberapa sirip. Bayangkan mata raksasa ini berada di atas kerang atau remis. Ia mempunyai sirip-sirip kecil, yang berfungsi sebagai tempat berjalannya, menghindari setiap upaya Anda untuk menangkapnya. Itu sebabnya ini disebut radikal kerang.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '28e889ff-a473-4ebf-b2c1-5b4157c1ed13'; -- 貝 (radical)
UPDATE items SET meaning_mnemonic = 'Ini terlihat seperti S.S terbalik untuk Self. Tapi itu terbalik karena Anda tidak ingin mencampuradukkan diri Anda dengan orang lain di luar sana, jadi Anda membaliknya. Itu sebabnya artinya diri sendiri. (Itu kamu!)

Orang radikal ini akan tampak seperti diri Anda sendiri, dirinya sendiri, dll., jadi ingatlah itu!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'd3361fd9-0f76-41f9-9968-4c72a807390c'; -- 己 (radical)
UPDATE items SET meaning_mnemonic = 'Bukankah radikal ini terlihat seperti dinamit kuno yang didorong untuk mengatur sumbunya? Itu membuat dinamit ini!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '526001e4-5062-4e83-9877-83d82c979924'; -- 丙 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya sebelumnya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'c9a58de4-7da8-4920-b8ae-e296ceec9cbf'; -- 予 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah radikal untuk cloud. Lihat bagaimana awannya menggembung di bagian bawah tetapi memiliki dua garis di bagian atas? Itu karena ada pesawat yang terbang melewatinya. Jika manusia tidak menciptakan pesawat terbang, awan radikal ini mungkin terlihat berbeda. Benar-benar membuatmu berpikir, ya?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'fe3d0baa-db0b-4624-b83d-1423c9a64385'; -- 云 (radical)
UPDATE items SET meaning_mnemonic = 'Letakkan sedikit kotoran di sekitar kepala dan mulut Anda untuk mengetahui lingkar kepala Anda. Saat Anda menarik kepala keluar, Anda akan mendapatkan bentuk kepala yang sempurna, sehingga pengukuran keliling menjadi mudah. Oh, dan kotoran di mulutmu? Itu hanya untuk rasanya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1c8a9570-a327-4bec-8c03-b9355481dae5'; -- 周 (radical)
UPDATE items SET meaning_mnemonic = 'Jika Anda merebus sebuah desa, semuanya akan menjadi hitam. Sebagian besar karena Anda adalah seorang pembunuh gila, namun terlebih lagi karena ketika Anda merebus sebuah desa, seluruh jalan akan meleleh dan melapisi segala sesuatunya dengan tar hitam. Bayangkan! Sepertinya Pompeii. (Oof, terlalu cepat?)', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6f8a3975-c270-4ff1-b8f2-290a829d0b15'; -- 黒 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah atap dengan tambahan paku/tanduk di atasnya. Siapa yang terkenal memiliki atap berduri, helm berduri, perahu berduri?! Bangsa Viking! Itu sebabnya ini disebut radikal Viking.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '863dd362-4402-4777-84b1-2adffdaf8e0e'; -- [viking] (radical)
UPDATE items SET meaning_mnemonic = 'Lihat sayap keren di bawah? Lihat kepala dengan bulu rapi keluar dari atasnya? Ini adalah burung. Tweet tweet!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a7590e87-f71b-4a4f-a4f3-ba8aafcf0666'; -- 鳥 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Saat Anda memikirkan tentang burung, burung apa yang paling umum yang terpikirkan oleh Anda? Burung apa yang paling kamu benci atau paling suka kamu makan? Salah satu dari keduanya akan berhasil. Sekarang, bayangkan diri Anda mendekati burung itu. Anda melakukan sesuatu yang buruk. Anda merobek (とり) sayapnya dan mulai memakannya (berpura-puralah sayapnya sudah matang terlebih dahulu, jika itu membuat mual Anda berkurang).' WHERE id = 'ed3f195c-710e-4d81-9a62-a2467054dabb'; -- 鳥 (vocabulary)
UPDATE items SET meaning_mnemonic = 'studi institusi adalah akademi. Di sanalah semua orang-orang mewah belajar.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3f2a4052-deac-4271-9d80-6c4f9ae7755b'; -- 学院 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti mengajar sehingga versi vocab verbanya berarti to teaching. Kata ini juga digunakan dalam arti to tell dalam pengertian yang lebih umum.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Pikirkan tentang guru favorit Anda. Sekarang bayangkan mereka mengajari Anda hal berikut: "Hari ini saya akan mengajari Anda tentang laut (おし)." Itu besar. Sangat besar. Di dalamnya ada kraken, alien luar angkasa, dan kota yang hilang. 

Di sinilah Anda melanjutkan pelajaran di kepala Anda, menjadikannya pelajaran paling konyol tentang lautan yang pernah Anda dengar. Fokuslah pada bagian lautan, karena itulah bacaannya, selalu kembali ke sana.' WHERE id = 'b56dfc09-3bee-44e8-a8e9-5d8d446c2f20'; -- 教える (vocabulary)
UPDATE items SET meaning_mnemonic = 'orang yang sakit adalah orang sakit. Mereka juga sabar, setidaknya kita bisa berharap demikian, demi mereka.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Setiap orang sakit senang bermain di Nintendo mereka (にん). Anda menderita flu yang paling parah, tetapi Anda masih memiliki Nintendo, jadi semuanya baik-baik saja.' WHERE id = '5b0641d3-03ca-4c0c-8595-ebae47eab200'; -- 病人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anggota perusahaan (会社) adalah seseorang yang bekerja di sebuah perusahaan. Ini adalah karyawan perusahaan. Ada banyak hal seperti ini di Jepang. Kebanyakan dari mereka mabuk.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '9e02aec8-9340-4f2d-9c58-640f1c93ecc1'; -- 会社員 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seperti yang mungkin bisa Anda bayangkan, saat Anda menambahkan kanji sakit ke kata lain, Anda sedang mengatakan penyakit apa itu; Anda menyebutkan penyakit apa itu.', reading_mnemonic = 'Karena ini melekat pada kata lain, maka diperlakukan seperti jukugo dan mendapat perlakuan on''yomi. Ini adalah bacaan yang Anda pelajari dengan kanji.' WHERE id = '29abbfa5-6174-4dd2-9e65-3020e596c304'; -- 〜病 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sebatang sakit dari dynamite akan menjadi sakit selamanya. Sayangnya tidak ada obat yang efektif untuk batang dinamit, jadi begitu tertular penyakit, mereka akan sakit selamanya.', reading_mnemonic = 'Tahukah Anda bahwa **Sakit** (病) ini sebenarnya dibuat dari tumpukan **Burung/Buku**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **びょう**.' WHERE id = '75045e9f-2cae-486d-9474-a7265b072fb0'; -- 病 (kanji)
UPDATE items SET meaning_mnemonic = 'wanita yang buruk adalah wanita jahat. Anehnya, "ibu mertua" bukanlah salah satu arti dari kata ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'd4c7a2df-2ace-4b9d-bedf-cf1a28c243f6'; -- 悪女 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda berada dalam situasi di mana Anda harus memasuki sebuah institusi, itu disebut hospitalisasi. Mudah-mudahan Anda tidak berada di sana terlalu lama.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'caff2aa0-fdd9-4bbd-898d-41c5685dee04'; -- 入院 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Semoga Anda sudah mengetahui kata 通る sekarang. Itu adalah versi kata kerja dari kata ini, yang berarti “melewati”. Jadi, jika ini versi kata bendanya, apa yang Anda gunakan untuk melewati sesuatu? Untuk mengemudi atau berjalan bersama? Itu akan berupa jalan (atau jalan, road, dll). Ini adalah kata yang cukup umum di Jepang, dan bagus agar tidak tersesat.', reading_mnemonic = 'Bacaannya sama dengan kata 通る, jadi asal kalian tahu pasti bisa baca yang ini juga. Perhatikan suara お yang panjang dan aneh!' WHERE id = 'cac83056-9aca-4501-914d-9131aea9b116'; -- 通り (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana Anda mengetahui bahwa 大学院 berarti "sekolah pascasarjana" dan 大学生 berarti "mahasiswa?" Kita hancurkan semuanya dan Anda akan mendapatkan mahasiswa pascasarjana!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'd83113f3-557e-441f-ab30-db9b8a226da8'; -- 大学院生 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hal otomatisal (自動 + 的) tentu saja tidak "otomatis". Cara yang lebih baik untuk mengatakannya adalah dengan memotong -al dan menyebutnya automatic.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui cara membaca 自動 juga akan membantu.' WHERE id = '29dbc308-3598-45c9-ba78-49da368547f4'; -- 自動的 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dahulu kala, seorang pemimpin yang hebat berpikir untuk meminjam sesuatu yang berharga dari Anda. Pemimpin ini tidak mengembalikan barang yang dipinjamnya, dan sekarang dia akan membayarnya.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Pinjam** (借) tiba-tiba berbicara dan meminta **Sapi/Sampo**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **しゃく**.' WHERE id = 'c04bd75e-f6dc-4f5b-a919-e43c0a8e45a6'; -- 借 (kanji)
UPDATE items SET meaning_mnemonic = 'usaha Anda kuat. Anda mungkin berpikir ini berarti Anda sedang bekerja keras atau semacamnya, tapi itu berarti studi (seperti studi yang Anda lakukan untuk ujian atau semacamnya). Jadi untuk ini, bayangkan saja diri Anda mengerahkan upaya yang sangat kuat untuk mengerjakan pekerjaan rumah Anda. Ini adalah studi Anda / apa yang Anda pelajari.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '322c7a94-871f-4f87-92cc-1aba6d3061a9'; -- 勉強 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jangan bingung dengan sawah (田). Ini hanyalah beras mentah, seperti biji-bijian yang tumbuh dari tanah ketika beras masih mentah dan segar. Jika nasi sudah sangat matang, bagian atas batangnya akan terlihat seperti ini. Lihat daunnya yang panjang dengan sedikit jumbai nasi di atasnya? Itu sebabnya radikal ini disebut "beras".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'edad34d3-d548-42f2-8a16-a394e6c822bb'; -- 米 (radical)
UPDATE items SET meaning_mnemonic = 'Di Asia mereka menganggap hati setiap orang secara otomatis buruk dan jahat.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Buruk** (悪) tiba-tiba berbicara dan meminta **Aku/Aki**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **あく**.' WHERE id = 'ee2ed68a-ee9d-4afe-b903-517bcf35c340'; -- 悪 (kanji)
UPDATE items SET meaning_mnemonic = 'orang yang buruk orang adalah orang yang jahat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '88f8dcbf-a09e-41d4-b351-227b525249d5'; -- 悪人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti bangun sehingga versi kosakata kata kerjanya adalah to wake up atau to wake up.

Kata ini juga memiliki arti sekunder yaitu terjadi. Anggap saja seperti ini: ketika suatu tindakan "bangun", maka tindakan tersebut juga terjadi.', reading_mnemonic = 'Bacaannya sama dengan yang dipelajari dengan kanji, jadi besok kalau bangun semoga tidak perlu mempelajari kembali bacaan vocab ini.' WHERE id = '89b7a6c5-64ad-4f3e-8fc7-a5863a3530e0'; -- 起きる (vocabulary)
UPDATE items SET meaning_mnemonic = 'alasan hati Anda melakukan apa yang dilakukannya, semuanya bersifat psikologis. studi tentang itu adalah psikologi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '8c869abf-369c-4d27-98ae-97b25c6eb6d4'; -- 心理学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kerang dengan mulut adalah anggota dari keluarga invertebrata. Ya, kerang memang punya mulut, lihatlah!', reading_mnemonic = 'Tahukah Anda bahwa **Anggota** (員) ini sebenarnya dibuat dari tumpukan **Indah/Intan**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **いん**.' WHERE id = '98974473-5024-43b4-ab78-6627b76653c6'; -- 員 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal burung dan kanji burung adalah sama!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Burung** (鳥), bayangkan Anda sedang membawa **Cokelat/Corong** untuk ditaruh di atas burung. Kejadian unik ini mengingatkan Anda pada bunyi **ちょう**!' WHERE id = 'bcc6738d-d6b9-4585-948d-6591a871f6b9'; -- 鳥 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada alasan untuk biaya ini yang harus Anda bayar untuk masuk ke sini. Kami memasak masakan untuk Anda makan sambil menonton pertunjukan. Jika kami tidak memasak hidangan untuk Anda, kami mungkin tidak akan membebankan biaya ini kepada Anda!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '0abe5d43-e10e-45fe-80e7-fff741198e80'; -- 料理 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada skuter bersama mama Anda yang membawa tugas yang harus dia selesaikan. Anda melihatnya melewati, bergegas untuk menyelesaikan tugas itu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Lewati** (通), bayangkan Anda sedang membawa **Tusuk/Tuli** untuk ditaruh di atas lewati. Kejadian unik ini mengingatkan Anda pada bunyi **つう**!' WHERE id = 'bc93a2b8-1daa-48bd-9ae1-f78b955b7ebe'; -- 通 (kanji)
UPDATE items SET meaning_mnemonic = 'penalarandari hati Anda menentukan apa yang Anda lakukan. Mungkin saat kanji dibuat, orang mengira hatilah yang menentukan tindakan kita, bukan otak kita. Jadi, jika Anda memikirkannya seperti itu, alasan hati Anda adalah keadaan mental Anda. Saat ini hal itu dikenal sebagai psikologi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fb44c440-304d-4b88-825f-19c724d37c86'; -- 心理 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tugas dari meminjam sesuatu adalah ketika Anda meminjam sesuatu. Itu juga ketika Anda mendapatkan pinjaman.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'b18fa4a1-d4c6-40d0-bd22-04377bcc0d0a'; -- 借用 (vocabulary)
UPDATE items SET meaning_mnemonic = 'minggu ini minggu adalah minggu ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ec533f91-8fde-4690-bb90-24494030f6cf'; -- 今週 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang dapat bergerak dengan dirinya adalah sesuatu yang otomatis.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '99650853-a13c-4cbf-985c-a24900a6ab4c'; -- 自動 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda pergi untuk bergerak Anda sebenarnya melakukan tindakan. perilakusaat Anda pergi dan beraktivitaslah yang menentukan apa yang orang pikirkan tentang Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '021902cc-6a06-453b-b132-4d2bd6c1fea5'; -- 行動 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda pertama kali menemui gerbang mulut, Anda akan mendapat masalah. Menabrakkan mulutmu ke gerbang akan terasa sakit. Banyak. Masalah yang Anda hadapi sekarang adalah pergi ke rumah sakit dan menjahit mulut Anda kembali. Pertanyaannya adalah, bagaimana caramu pergi ke rumah sakit?', reading_mnemonic = 'Tahukah Anda bahwa **Pertanyaan** (問) ini sebenarnya dibuat dari tumpukan **Motor/Mobil**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **もん**.' WHERE id = 'fb26eede-689e-4023-bcb0-8356bcebbab2'; -- 問 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari kuat? Bahasa ini juga kuat.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Jadi kamu ingin menjadi kuat ya? Nah, kamu tinggal makan dua yogurt ini (つよ). Satu diisi dengan steroid kuda, yang lainnya penuh dengan steroid banteng. Mereka akan membuatmu begitu kuat.' WHERE id = 'ea673baf-394d-4015-b943-1a6ae6c2c9da'; -- 強い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat 料理 dan mungkin tahu artinya "memasak". Jadi, apa yang dimaksud dengan orang yang memasak? Yaitu seorang juru masak atau chef.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3f86981c-8006-48d9-8118-121e10d10fac'; -- 料理人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seorang Viking akan mengosongkan mulut dari semua kotoran di aula yang besar. Mereka semua berkumpul di semacam ruang publik dan membuang semua kotoran (secara harafiah dan kiasan) yang mereka punya.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kelas** (堂), bayangkan Anda sedang membawa **Domba/Topi** untuk ditaruh di atas kelas. Kejadian unik ini mengingatkan Anda pada bunyi **どう**!' WHERE id = '873bb149-ca22-4c23-acf4-fe8a3a849556'; -- 堂 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari hitam? Itu juga hitam. Catatan Khusus: Versi kata benda hitam juga ada dalam bahasa Jepang. Itu hanya 黒 dengan pengucapan yang sama, tetapi tanpa い yang menjadikannya kata sifat-tastic.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda:

Pikirkan hal-hal hitam. Salah satu benda hitam yang sangat umum adalah burung gagak (くろ). Kaitkan keduanya.' WHERE id = '5318b8e0-ed63-4c0f-bbad-30bd170c838a'; -- 黒い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda telah melihat 動く dengan penuh harapan, dan mengetahui artinya bergerak. Ini mirip dengan itu, tapi sekarang Anda memindahkan sesuatu yang lain. Anda mengetahui hal ini karena saat Anda memindahkan sesuatu benda yang Anda pindahkan tersebut mulai menyumpah (かす) Anda keluar karena ia sedang marah.', reading_mnemonic = 'Bacaan untuk ini bisa berasal dari 動く. Jika Anda mengetahui kata itu, Anda pasti tahu cara membaca kata ini!' WHERE id = 'cbbbe2cb-63fc-413c-b188-59420a42b7af'; -- 動かす (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika paus menghabiskan sepanjang hari menatap sirip di tanah, dia akan kehilangan kontak dengan realitas. Dia seharusnya fokus pada tugas kepausannya, tapi dia malah melihat sirip ikan yang dia jatuhkan, dan sekarang tidak bisa makan karena kotor. Paus konyol. Anda tidak bisa membiarkan hal ini membuat Anda kecewa. Ada hal lain yang harus kamu lakukan.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Penyataan** (真), bayangkan Anda sedang membawa **Shin-chan/Singa** untuk ditaruh di atas penyataan. Kejadian unik ini mengingatkan Anda pada bunyi **しん**!' WHERE id = '527bfdcb-65ed-4326-b100-b20052901594'; -- 真 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya adalah bacaan kun''yomi, namun untung bagi anda bacaan tersebut dipelajari dengan kanji, artinya anda harus bisa membaca vocab ini juga.' WHERE id = '5409148b-976a-492e-92a4-6d237ce22b5a'; -- 紙 (vocabulary)
UPDATE items SET meaning_mnemonic = 'alasan bumi menjadi seperti ini karena geografi darinya. Meskipun mungkin tampak aneh bahwa geografi membawa nalar ke bumi, jika Anda menganggap geografi sebagai sebuah studi, maka Anda juga dapat memikirkan bagaimana Anda mencoba untuk mendapatkan nalar melalui hal tersebut.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'a7e79eda-66bc-4dbb-bb41-0aabd985cfb0'; -- 地理 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apakah Anda ingat kata 転がる? Ini mirip, bukannya menggelinding, ini lebih pada saat sesuatu jatuh dan menyentuh tanah. Artinya jatuh atau jatuh. Bayangkan saja seseorang terjatuh dari kursi terlebih dahulu ke tanah dan mengeluarkan suara ぶ.', reading_mnemonic = 'Bacaannya berasal dari 転がる. Mudah-mudahan Anda cukup mengetahui yang satu itu untuk mengaitkannya dengan yang ini, artinya Anda bisa membaca keduanya.' WHERE id = 'fe807ca2-9abb-4114-9183-54599a2367d0'; -- 転ぶ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti selesai, jadi versi kata kerjanya adalah to finish Something atau to end Something.

Ini adalah kata kerja transitif, artinya Anda menyelesaikan sesuatu, misalnya seharian bekerja!

Anda perlu membedakannya dengan 終わる, yaitu ketika sesuatu berakhir dengan sendirinya. 終える adalah tentang saat kamu mengakhiri sesuatu. Ingatlah seperti ini: Orang Kanada selalu mengakhiri kalimatnya dengan "eh" え, bukan? Begitulah cara Anda mengetahui bahwa mereka mengakhiri kalimatnya. Dengarkan saja "eh", ya?', reading_mnemonic = 'Karena kata ini memiliki okurigana (hiragana yang melekat pada kanji), Anda tahu bahwa kemungkinan besar itu adalah pembacaan kun''yomi, yang tidak Anda pelajari dengan kanji. Berikut ini mnemonik untuk membantu Anda:

Anda akhirnya menyelesaikan proyek sekolah Anda. "Oh, A!" (おえ) Anda berkata pada diri sendiri, seolah-olah Anda bisa menilai proyek Anda sendiri.' WHERE id = 'f90e33d8-c504-4d20-9623-733f86114038'; -- 終える (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini terlihat seperti tamagotchi kecil atau (jika Anda bukan anak tahun 90an) bebek. Apa kesamaan yang dimiliki kedua makhluk ini? Mereka memiliki pengikut klan yang sangat gila. Dan orang-orang yang menikmatinya (permainan kecil-kecilan atau menonton bebek berkuak) membentuk klan yang berkumpul dan berbagi pengalaman. Anda termasuk dalam klan mana?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '068b6d2c-3ec1-4fad-a545-76e2f4eca3b0'; -- 氏 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Paus". Perhatikan bentuk karakter "[Paus]" dan asosiasikan bentuk goresannya dengan "paus".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '67be672c-65a4-4211-b252-1b9944ef2461'; -- [Paus] (radical)
UPDATE items SET meaning_mnemonic = 'Ada sesuatu yang menutupi tongkat itu. Itu adalah handuk!! Bayangkan mengambil handuk basah dan menggantungnya di pagar atau tongkat agar tidak pengap dan kotor. Ini akan terlihat seperti ini.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5cd2d4f0-576f-4f72-898b-17cadb621883'; -- 巾 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti helikopter di darat. Atau petarung TIE dari atas (ke samping). Apa pun pilihannya, tidak apa-apa karena Anda tahu di mana helikopter dan pesawat tempur TIE dibuat: Asia! Saat ini sebagian besar pesawat dibuat di Asia, tahu?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8c72ec7e-23af-4ab7-b8cc-50526a6edfc7'; -- 亜 (radical)
UPDATE items SET meaning_mnemonic = 'Bentuk radikal ini seperti huruf B yang melengkung. Apa kepanjangan dari B? Bangunan! Kata radikal ini digunakan dalam banyak kanji untuk menandai bahwa itu adalah sebuah bangunan, atau ada hubungannya dengan bangunan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7cd016f9-140c-4050-b262-95e6cf4d4330'; -- 阝 (radical)
UPDATE items SET meaning_mnemonic = 'Ada sesuatu yang kecil di beberapa kotoran. Anda mencondongkan tubuh ke dalam, menariknya keluar dengan hati-hati, dan menyadari bahwa itu adalah utas. Mengapa ada benang di kotoran kecil ini? Karena itu kotoran kucing. Dan kucing suka memakan benang saat Anda tidak melihat. Dan benang benang, tali hoodie, dan ekor tikus. Tapi kotoran ini hanya ada benang di dalamnya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'ff214bf5-f762-4c16-84fb-66b6c476269f'; -- 糸 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Tahu". Perhatikan bentuk karakter "[Tahu]" dan asosiasikan bentuk goresannya dengan "tahu".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '3203dc22-7767-46d0-b19c-2b68714d4160'; -- [Tahu] (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti bergerak sehingga versi kosakata kata kerjanya adalah to move.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajari cara membaca tersebut dengan kanji ini, jadi inilah mnemonik yang dapat membantu Anda: Seseorang menyuruh Anda untuk bergerak. Mereka berkata "kamu pergi (うご) ke sana. Bergerak! Bergerak!" Jika itu membantu, mintalah mereka mengucapkan "You go" seperti "Ugo".' WHERE id = 'a2068e37-69e9-4b57-8354-552ecb19970a'; -- 動く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jadi, Anda mengirimkan sesuatu yang berputar. Ini adalah sedikit transfer / transmission, melalui kabel. Pesan-pesan kecil yang berputar saat mereka melewati antrean untuk mencapai tujuan. Coba bayangkan ini terjadi dalam gerakan lambat, sampai ke ujung yang lain.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '24000326-7a95-4323-9b4b-91cf65944039'; -- 転送 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah sawah dengan tanah di sekitarnya. Ini adalah tempat yang tepat untuk mendirikan desa. Anda memiliki tempat untuk bertani dan tanah untuk ditinggali. Apa lagi yang Anda perlukan?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'cde9da29-32d2-4118-a46a-2ce7de38570b'; -- 里 (radical)
UPDATE items SET meaning_mnemonic = 'rumah suku Anda adalah keluarga Anda. Mereka tinggal serumah dengan Anda dan mereka adalah bagian dari "suku" Anda. Namun ini lebih dekat daripada keluarga (tergantung bagaimana Anda memandang keluarga). Ini adalah keluarga dekat Anda karena mereka adalah orang-orang yang tinggal bersama dan melahirkan Anda, dll.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '04a35114-63d8-498c-a082-2b1163b6060e'; -- 家族 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda meminjam sebuah rumah Anda menyewa rumah. Selain itu, ini adalah rumah yang disewakan.', reading_mnemonic = 'Ini merupakan kata jukugo yang biasanya berarti pembacaan on''yomi dari kanji, namun dalam hal ini kanji kedua dapat dibaca dengan on''yomi atau kun''yomi. Ini menggunakan kun''yomi 家 yang kurang umum, jadi inilah mnemonik untuk membantu Anda:

Jika Anda menyewa rumah, seseorang harus memberi Anda kuncinya dan mengizinkan Anda masuk dan sebagainya. Lagipula, Anda hanya menyewa. Jadi ketika mereka mengizinkanmu masuk, mereka akan berkata, "Ini gubuk untuk yah! (しゃくや) Selamat menikmati!"

Ngomong-ngomong, di bacaan sekunder しゃっか, しゃく menjadi しゃっ. Bacaan ini hanya digunakan dalam konteks seperti dokumen hukum, jadi しゃくや mungkin jauh lebih berguna bagi kebanyakan orang.' WHERE id = '915c6b47-cad1-4506-a119-c510bc1352d4'; -- 借家 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti belajar sehingga versi vocab verbanya berarti to learn atau to take learning sesuatu.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus belajar tentang Nara, kota rusa... banyak sekali rusa. Jika Anda tidak mengetahuinya, bagaimana dengan mempelajarinya?' WHERE id = '0f3d9bc1-1165-4a7c-99db-f188d5aad8ef'; -- 習う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa kanji di sini berarti berputar. Versi kata kerjanya serupa. Artinya berguling atau jatuh. Ketika sesuatu melakukan hal-hal ini, ia berputar, bukan?', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Bayangkan sesuatu menggelinding menuruni bukit. Di dalamnya terdapat inti uranium (ころ) yang sangat penting yang Anda butuhkan untuk terus berputar. Itu sebabnya mereka menggelindingkannya dari bukit demi bukit, karena mereka tidak punya apa-apa lagi untuk membuatnya tetap berputar seperti itu, mencegahnya meledak. Inti ini sangat penting!

Jika kamu kesulitan mengingat akhiran hiragana, bayangkan saja seorang gadis (がる) juga berguling menuruni bukit.' WHERE id = '4ff8bc1a-c163-455f-bcbb-b591c1cd992c'; -- 転がる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat 起きる yang artinya "bangun". Hal ini serupa, kecuali Anda sedang membangunkan orang lain, yang menjadikan arti dari kata ini membangunkan seseorang. Bagaimana Anda membedakan ini dan 起きる? Karena す di akhir. Anda membangunkan seseorang dengan kasar, mencekik lehernya. Mereka berbalik dan menuntut (す) Anda, membuat Anda berharap Anda tidak pernah membangunkan mereka.

Ini juga bisa berarti menyebabkan sesuatu. Saya kira jika Anda membangunkan seseorang dan mereka bukan orang yang suka bangun pagi, Anda dapat menyebabkan sesuatu... seperti masalah.', reading_mnemonic = 'Bacaannya sama dengan 起きる, jadi selama kamu tahu kata itu kamu pasti bisa membaca yang ini. Tentu saja, Anda juga bisa membayangkan mereka berteriak "OH!" ketika Anda membangunkannya juga, jika itu membantu.' WHERE id = 'afcdf8d2-ee94-4dca-9d08-9731e56c46ec'; -- 起こす (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 起きる berarti "bangun", tetapi apakah Anda mempelajari arti sekundernya, "terjadi"? Nah, kata ini berarti hanya terjadi. Bayangkan saja sebuah insiden terjadi yang melibatkan inti uranium (こる) dan ingat bahwa ini berarti terjadi. Lagi pula, insiden inti uranium tidak akan terjadi, bukan?', reading_mnemonic = 'Bacaannya sama dengan apa yang kamu pelajari dengan kanji dan sama dengan 起きる juga, artinya kamu harus bisa menyusun bacaannya sendiri.' WHERE id = 'd633b0dc-26c2-4ec9-8203-1e4a04e019ff'; -- 起こる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti berputar, dan versi kata kerjanya adalah saat Anda membuat sesuatu berputar. Anda menggulungnya. Itu sebabnya kata kerja ini adalah to roll Something.

Ini adalah kata kerja transitif. Itu berarti Anda menggulingkan sesuatu yang lain, seperti bola. Atau, jika Anda kumbang kotoran, buang air besar. 💩 Jangan bingung dengan 転がる, yang bersifat intransitif, seperti banyak kata kerja yang berakhiran がる.', reading_mnemonic = 'Anda mempelajari bacaan ini saat mempelajari 転がる, namun berikut ini ada mnemonik untuk berjaga-jaga:

Saat Anda mencoba memutar sesuatu, bagian luarnya mungkin bergerak, namun intinya (ころ) tetap diam. Bayangkan diri Anda membuat bumi berguling-guling di lantai. Bagian luar tempat tinggal manusia berputar-putar, namun inti bumi berada di tempat yang persis sama.' WHERE id = '7d7bb37d-160d-4e7d-8096-31a1f4ca8005'; -- 転がす (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Anda sudah mengetahui bahwa 通る artinya lulus, namun ini sedikit berbeda. Bukan kamu yang lewat, Sue (す) yang lewat. Jadi, kamu harus membiarkan Sue lewat. Dengan kata lain, verba ini bersifat transitif, artinya mempunyai objek. Itu sebabnya artinya membiarkan sesuatu lewat atau melakukan sesuatu.

Cara menerjemahkan kata kerja ini ke dalam bahasa Inggris banyak berubah tergantung pada kata benda yang dipasangkannya. Misalnya 火を通す secara harfiah berarti "membiarkan api melewatinya", dan berarti "memanaskan". 針に糸を通す secara harfiah berarti "memasukkan benang ke dalam jarum", jadi berarti "memasukkan benang ke dalam jarum".', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda mempelajari bacaan ini ketika Anda mempelajari 通る. Ganti る dengan す dan Anda akan siap!' WHERE id = '4effd724-ed9a-485e-beb4-19c817f0982b'; -- 通す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sebuah pisau tertancap di dahi Wolverine, dan dia dililitkan handuk untuk menghentikan pendarahan, tapi dia benar-benar harus kembali ke rumah.', reading_mnemonic = 'Ketika Anda sedang melihat **Pulang** (帰), tiba-tiba muncul sesosok **かえ** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **かえ**.' WHERE id = 'faaea376-668c-409a-ba35-e6294442da75'; -- 帰 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti berakhir sehingga versi kata kerjanya adalah to end atau to be over.

Ini adalah kata kerja intransitif, artinya terjadi dengan sendirinya. Sesuatu berakhir, tapi kamu tidak mengakhirinya.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Situasi ini harus diakhiri. Anda berhutang (おわ) banyak uang. Agar ini berakhir, Anda harus membayar kembali semua uang itu. Cobalah memikirkan cara untuk berhenti berhutang agar situasi stres ini bisa berakhir!' WHERE id = '3a4c8808-8c1c-47aa-9a57-2a7bfde67ece'; -- 終わる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kita telah melihat beberapa kali 電 mengacu pada kereta. Bagaimanapun, ini adalah masalah besar dan menggunakan banyak listrik. Jadi, kereta akhir untuk kata ini merujuk pada kereta terakhir.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fe5971e8-a9f4-4fa9-9389-bcd0b9c533b1'; -- 終電 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti sakit, jadi versi kata kerjanya adalah menjadi sakit. Ini juga dapat digunakan sebagai untuk mengatasi ketika Anda sedang terserang flu atau penyakit lainnya.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Hanya ada satu saat Anda membiarkan diri Anda sakit, dan saat itulah Yankees (や) sedang bermain. Anda tidak boleh melewatkan pertandingan apa pun sehingga Anda jatuh sakit setiap kali pertandingan tersebut dimainkan sehingga Anda dapat tinggal di rumah dan menonton. Cukup nyaman, bukan?' WHERE id = 'be17af5c-f540-4448-9d17-bb18a63d1f71'; -- 病む (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang istimewa dan dalam keadaan terburu-buru pastilah istimewa. Ini merujuk pada kereta ekspres terbatas di Jepang. Mereka melaju dengan cepat, berhenti di pemberhentian yang lebih sedikit (karena pemberhentian tersebut istimewa!) dan mereka bergegas. Carilah ini jika Anda ingin mencapai suatu tempat dalam sekejap.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Perhatikan saja bahwa とく menuju ke とっ.' WHERE id = 'b472520a-2b8d-4ac0-8dea-d20ea46e869c'; -- 特急 (vocabulary)
UPDATE items SET meaning_mnemonic = 'diri berputar mobil. Anda mungkin mengira ini adalah mobil biasa, namun sepeda mungkin sudah diperkenalkan sebelum mobil ada, artinya mobil yang dapat berputar sendiri adalah sepedanya, bukan mobilnya. Bayangkan saja diri Anda sedang mengendarai sepeda, dan Anda bahkan tidak perlu mengayuh. Mereka berputar sendiri, tapi sekarang Anda melaju terlalu cepat dan itu menakutkan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'cfcf6ee3-0504-49d2-b9bc-12a53d47dae9'; -- 自転車 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hiragana diakhiri dengan bunyi う, sehingga Anda tahu bahwa ini adalah kata kerja. Kanji sendiri berarti kembali, dan kata kerja ini bersifat transitif, artinya mengambil objek langsung. Anda mengirim seseorang kembali. Anda mengirim mereka pulang. Dan beritahu mereka untuk tidak pernah mendekatimu lagi. Jadi ini berarti mengirim seseorang kembali atau mengirim seseorang pulang.

Faktanya, sebagian besar kata kerja yang diakhiri dengan す bersifat transitif. Untuk membantu Anda mengingatnya, pikirkan suing (す) seseorang untuk memastikan mereka pulang!', reading_mnemonic = 'Pembacaan kata ini sama dengan yang Anda pelajari dengan kanji. Hore! Namun karena kata ini memiliki kata kerja berpasangan, mari pikirkan cara untuk mengingat bagian akhirnya:

Apa cara paling jitu untuk memulangkan seseorang? Mengancam akan menuntut (す) jika tidak melakukannya!' WHERE id = '4a7051c1-3335-40e5-a0d5-6b9096087c1f'; -- 帰す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji artinya melewati tetapi kita sudah mengetahui kata 通る yang artinya melewati. Kata ini memiliki arti melewati yang berbeda, seperti bagaimana Anda melewati aula sekolah Anda setiap hari. Namun kami tidak mengatakan untuk lulus sekolah, kami mengatakan untuk bersekolah, atau pergi ke sekolah.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan salah satu bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda:

Anda tinggal di tengah-tengah tiga distrik sekolah yang berbeda sehingga Anda perlu memutuskan sekolah mana dari tiga sekolah yang ingin Anda ikuti. Anda memutuskan tidak keberatan harus pergi ke yang terjauh dari ketiganya karena maskot mereka adalah Wile E. Coyote (かよ). Dia Looney Toon favoritmu karena dia selalu punya energi untuk bolak-balik setelah road runner itu.' WHERE id = 'd64b3106-ea20-4f86-992c-d841cef9c57a'; -- 通う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti melewati sehingga versi kosakata kata kerjanya memiliki arti seperti melewati, melewati, melakukan perjalanan bersama, dan to singgah.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Ada sesuatu di depan Anda yang harus Anda lalui tetapi Anda tidak bisa. Itu tembok. Untuk melewatinya, Anda memutuskan untuk menendangnya sekuat tenaga untuk menjatuhkannya. Sayangnya, ia jauh lebih kuat dari Anda, dan jari kaki Anda meledak saat bersentuhan. Anda berteriak: "JARI KAKI! OH!" (とお) dan kemudian berteriak-teriak.' WHERE id = '6b277049-30b8-4d0b-ad8a-a9ae4c8b1498'; -- 通る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji maka menggunakan bacaan kun''yomi. Beruntungnya Anda, Anda mempelajari bacaan ini dengan kanji.' WHERE id = '5ee5b8dc-efbe-4cc8-9f64-01068e39f55c'; -- 雨 (vocabulary)
UPDATE items SET meaning_mnemonic = 'mulut dari raja meluas ke sekelilingnya (seperti dalam kanji ini). Dimana mulutnya mencapai, itulah negara miliknya, memberi atau menerima beberapa tetes.', reading_mnemonic = 'Tahukah Anda bahwa **Negara** (国) ini sebenarnya dibuat dari tumpukan **Koko/Koki**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **こく**.' WHERE id = '447c6de5-6013-44bc-89a5-f1497697ef7b'; -- 国 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal untuk rain dan kanji untuk rain adalah hal yang sama.', reading_mnemonic = 'Ketika Anda sedang melihat **Hujan** (雨), tiba-tiba muncul sesosok **う** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **う**.' WHERE id = '08bfd207-41e7-4235-b573-f13caedf6184'; -- 雨 (kanji)
UPDATE items SET meaning_mnemonic = 'Kosakata "大雨" memiliki arti "Hujan Lebat". Kombinasi kanji dalam kata ini melambangkan konsep hujan lebat.', reading_mnemonic = 'Cara membaca kosakata "大雨" adalah "おおあめ".' WHERE id = '7477c4f4-3431-427e-83cf-16602095fb43'; -- 大雨 (vocabulary)
UPDATE items SET meaning_mnemonic = 'berikutnya tahun adalah tahun depan! Ini bukan tahun lalu atau tahun ini, ini tahun berikutnya!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '36e2650d-be95-4a78-868a-070ae1a70aca'; -- 来年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kata yang baik untuk diketahui untuk menanyakan waktu. Apa itu waktu? Beginilah cara Anda menanyakan jam berapa sekarang.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f5277c7a-ed0a-4487-8251-de435e61d2f9'; -- 何時 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "校長" memiliki arti "Kepala Sekolah". Kombinasi kanji dalam kata ini melambangkan konsep kepala sekolah.', reading_mnemonic = 'Cara membaca kosakata "校長" adalah "こうちょう".' WHERE id = 'aff37c31-52d0-407d-8bbb-775810849ed8'; -- 校長 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "北東" memiliki arti "Timur Laut". Kombinasi kanji dalam kata ini melambangkan konsep timur laut.', reading_mnemonic = 'Cara membaca kosakata "北東" adalah "ほくとう".' WHERE id = '09cf207f-9975-4c39-aead-4ce240c34b32'; -- 北東 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "後" memiliki arti "Setelah". Kombinasi kanji dalam kata ini melambangkan konsep setelah.', reading_mnemonic = 'Cara membaca kosakata "後" adalah "あと".' WHERE id = '282a9825-de46-4f74-ad9b-14db03ae2a47'; -- 後 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "東南" memiliki arti "Tenggara". Kombinasi kanji dalam kata ini melambangkan konsep tenggara.', reading_mnemonic = 'Cara membaca kosakata "東南" adalah "とうなん".' WHERE id = '58288523-7763-4b5a-b8b5-7a9b5ef6fa1c'; -- 東南 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "書k" memiliki arti "Menulis". Kombinasi kanji dalam kata ini melambangkan konsep menulis.', reading_mnemonic = 'Cara membaca kosakata "書k" adalah "かく".' WHERE id = '83dd45c2-34c2-4959-8a34-8d06a131668c'; -- 書k (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "外国語" memiliki arti "Bahasa Asing". Kombinasi kanji dalam kata ini melambangkan konsep bahasa asing.', reading_mnemonic = 'Cara membaca kosakata "外国語" adalah "がいこくご".' WHERE id = '36583ff4-9b54-44ca-8845-c88ed3c8be60'; -- 外国語 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada penutup di mulut dan kumis Anda, yang menutupi semua lubang bicara Anda. Ini karena kamu terus mengatakan betapa tinggi dan mahal kamu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Tinggi** (高), bayangkan Anda sedang membawa **Koko/Koki** untuk ditaruh di atas tinggi. Kejadian unik ini mengingatkan Anda pada bunyi **こう**!' WHERE id = '4a13551e-ed75-4521-b6fc-70150737bf38'; -- 高 (kanji)
UPDATE items SET meaning_mnemonic = 'di luar negara adalah negara yang berada di luar negara Anda sendiri. Yaitu negara asing, negara lain, atau luar negeri.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3b037f7d-d814-4651-9ee0-0262d7312210'; -- 外国 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki viking anak liar yang harus Anda jaga. Anehnya, dia tidak akan melakukan apa pun kecuali belajar. Anda tidak bisa membuatnya makan, menggunakan kamar mandi, atau apa pun. Dia hanya ingin belajar.', reading_mnemonic = 'Bagaimana cara membaca kanji **Belajar** (学)? Ingat saja bahwa **Gajah/Gagang** sangat menyukai belajar! Hubungan erat ini akan membantu Anda mengingat bunyi **がく**.' WHERE id = '5373175d-6452-4411-8378-d761055dc6b2'; -- 学 (kanji)
UPDATE items SET meaning_mnemonic = 'Ucapkan dengan lidah Anda. Jika ya, Anda akan dapat berbicara. Anda akan dapat berbicara.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Berbicara** (話) tiba-tiba berbicara dan meminta **Wajan**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **わ**.' WHERE id = '4fc51ea4-fb6b-4b8c-a0db-1a724e738696'; -- 話 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal samurai sangat mirip dengan radikal tanah. Perbedaannya terletak pada garis horizontal atas. Bagi samurai, atasannya lebih panjang karena dia memegang pedang. Kotoran tidak dapat menampung apa pun karena lengannya terlalu pendek. Jadi ketika Anda melihat hal radikal ini, pikirkan: lengan panjang sama dengan pedang panjang. Itu seorang samurai!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '590fdbc2-fa26-45ed-abe4-e9c955a2c09e'; -- 士 (radical)
UPDATE items SET meaning_mnemonic = 'お adalah sebuah kehormatan yang membuat kata ini sedikit lebih mewah. Ketika Anda berbicara tentang uang, Anda pasti mewah. Jadi, pada dasarnya Anda mengatakan "emas" dengan cara yang lebih baik. Apa yang dimaksud dengan emas pada masa itu? Itu adalah uang.', reading_mnemonic = 'Pembacaan 金 berbeda dengan yang Anda pelajari dengan kanji. Masuk akal karena ini adalah kanji tunggal dengan hiragana terlampir. Berikut ini mnemonik untuk membantu Anda: 

Anda telah menghemat banyak uang. Dengan itu Anda akan membeli sesuatu yang luar biasa. Lalu, tiba-tiba seseorang memukul lutut Anda dengan tongkat pemukul. Sekarang kamu harus menghabiskan seluruh uang kamu untuk membeli tongkat (かね). Kasian buat kamu :(' WHERE id = '81239f54-289c-41d1-bf6e-7dcbad950daf'; -- お金 (vocabulary)
UPDATE items SET meaning_mnemonic = 'waktu interval waktu hanyalah waktu. Seperti yang sering terjadi, jika dua kanji yang memiliki arti serupa digabungkan menjadi satu kata, cenderung menghasilkan kata yang memiliki arti serupa. Permisi kawan, apa itu 時間?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3c90e473-cdbf-4ebe-a552-f82cfd0adb70'; -- 時間 (vocabulary)
UPDATE items SET meaning_mnemonic = 'belajar sekolah jelas merupakan tempat orang belajar dan belajar. Dalam bahasa Inggris, itu hanyalah school.', reading_mnemonic = 'Kata jukugo ini terdiri dari bacaan on''yomi, hanya saja 学 (がく) disingkat dengan っ kecil menjadi がっこう.' WHERE id = 'eee857b4-f7ee-43ad-aa72-bf2b8b7ce4bb'; -- 学校 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tinggi sekolah adalah ketika anak-anak Anda mencapai tinggi yang seharusnya. Itulah sekolah menengah, saat kebanyakan orang berhenti bertambah tinggi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '61716628-7c01-4a88-8452-4d359770bf7a'; -- 高校 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti mendengar sehingga versi vocab verb-nya adalah mendengar.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda perlu mendengar sesuatu yang sangat penting, namun Anda tidak bisa. Untuk mendengar, kamu harus mengambil kunci (き) dan membuka kunci pintu yang menutupi telingamu. Silakan bayangkan diri Anda melakukan itu, dengan fokus pada kuncinya.' WHERE id = '7ad6231c-ac64-4242-8c1e-5f99cfe52f64'; -- 聞く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki sesuatu yang sebelum (atau di depan) siang. Apa sebelum tengah hari? Yaitu AM.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '1a4bcd41-925a-4b79-9497-07776fecac67'; -- 午前 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti melihat jadi kosakata di sini berarti melihat atau melihat.', reading_mnemonic = 'Pembacaan kata ini sama dengan pembacaan yang kamu pelajari dengan kanji (kun''yomi) jadi kamu harus bisa membaca ini.' WHERE id = 'dcfc48aa-6b2b-4ab9-95c8-6aa9ace5298e'; -- 見る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tentu saja, dahi ini agak persegi, tapi itu karena itu adalah dahi Monster Frankenstein. Juga, apakah Anda memperhatikan bahwa ini hanyalah bagian atas kepala (冂) yang radikal? Ini hanya bagian dahi saja!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'a6caa40e-668b-4943-9672-344286dc921d'; -- 冖 (radical)
UPDATE items SET meaning_mnemonic = 'Kosakata "読書" memiliki arti "Membaca Buku". Kombinasi kanji dalam kata ini melambangkan konsep membaca buku.', reading_mnemonic = 'Cara membaca kosakata "読書" adalah "どくしょ".' WHERE id = '04507f12-4b49-41ba-83c6-6c59b5f55e5f'; -- 読書 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa yang Anda ucapkan di antara lima mulut adalah bahasa. Selama ada lima orang berbeda yang mengucapkan kata-kata yang sama dengan kelima mulutnya, itu dianggap sebagai bahasanya sendiri.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Bahasa** (語) tiba-tiba berbicara dan meminta **ご**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ご**.' WHERE id = 'aa1e8557-96b6-411a-9bed-3375b003a563'; -- 語 (kanji)
UPDATE items SET meaning_mnemonic = 'Bukankah ini terlihat seperti tampilan bingkai mobil dari atas ke bawah? Ada batang-batang yang menjadi alas mobil dan benda-benda yang menggerakkan roda. Itu sebabnya radikal ini adalah radikal mobil.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '93965c62-101e-48ef-96d9-9ab977c16ab1'; -- 車 (radical)
UPDATE items SET meaning_mnemonic = 'berikutnya bulan adalah bulan depan! Ini bukan bulan ini atau bulan sebelumnya, ini bulan berikutnya!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 月 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Bulan depan adalah saat gandum hitam dimasukkan (らいげつ) ke dalam menu makananmu! Anda hanya akan makan roti gandum hitam dan hanya minum bir gandum sepanjang bulan depan. Pasti Anda tidak sabar lagi!' WHERE id = '6899f404-370e-4bf2-aaf9-c56245e3065b'; -- 来月 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa itu siang setelah? Yaitu PM atau sore.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '6bb0b1eb-883c-4697-83c5-1d2300219b0d'; -- 午後 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Partikel の membuat 人 menjadi milik 男. Pada dasarnya, ini secara harfiah berarti "manusia" atau "manusia". Ini adalah cara yang lebih sopan untuk mengatakan man yang biasa-biasa saja, jadi yang harus Anda ingat hanyalah itu.', reading_mnemonic = 'Kata ini sebenarnya adalah dua kata terpisah yang digabungkan dengan sebuah partikel. Jadi, karena Anda memperlakukannya seperti kata-kata yang terpisah, Anda membacanya masing-masing dengan pembacaan kun''yomi (keduanya merupakan kata-kata kanji tunggal). Meskipun demikian, di level 4 Anda belajar tentang pembacaan kosakata untuk kata-kata terpisah ini, jadi gunakan pengetahuan itu untuk mengingat bacaan kata ini juga.' WHERE id = '1a95145f-8f4d-4c84-8479-e2700292eb18'; -- 男の人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti makan jadi versi kata kerjanya adalah to eat.', reading_mnemonic = 'Anda harus mengingat bagian た jika ingin bisa membaca kata yang menggunakan bacaan kun''yomi ini. Bayangkan diri Anda makansedang taco (た). Bayangkan diri Anda memakannya, rasa daging sapi mentah di mulut Anda (suka atau tidak suka).' WHERE id = 'eec2120f-af25-4e16-ba9b-41180c7d567f'; -- 食べる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti belajar atau belajar. Ketika Anda melakukan hal-hal ini, apa yang akhirnya terjadi? Anda belajar. Itu sebabnya kata ini berarti belajar. 

Ada kata lain yang berarti "belajar" yang lebih umum digunakan, yaitu 習う. Anda akan mempelajarinya nanti. 学ぶ terdengar sedikit lebih serius dibandingkan 習う, jadi ingatlah hal itu saat Anda menggunakannya.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian まな untuk mempelajari pembacaan kata ini. Pikirkan tentang kelas yang Anda ambil. Ini adalah kelas tata krama, dan Anda berada di sana untuk belajar tata krama (まな). Bayangkan pembelajaran tentang tata krama ini dan bayangkan diri Anda mempraktikkannya.' WHERE id = 'cc1a0a29-75c7-4ad6-b3fd-cb77d6916c36'; -- 学ぶ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hiragana yang melekat pada kata ini tidak menunjukkan bahwa itu adalah kata kerja atau kata sifat, jadi kita dapat berasumsi bahwa itu adalah kata benda. Meskipun 後で (Anda mungkin atau mungkin belum pernah melihat kata ini) berarti "setelah", yang satu ini berarti semua arti lain yang Anda pelajari dengan kanji: di belakang, back, dan rear. Anggap saja ろ sebagai petunjuk. Ini seperti mengatakan Anda sedang berada di "jalan raya" (ろ) dan Anda mengemudi dengan sangat cepat sehingga Anda meninggalkan segalanya "di belakang".', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Teruslah berpikir Anda sedang mengemudi di jalan ini. Anda menabrak sesuatu, lalu melihat di belakang Anda, dan melihat Anda menabrak seekor sapi. Tahu kata sapi dalam bahasa Jepang? Namanya うし, yang juga merupakan bacaan untuk kata ini.' WHERE id = 'ba10b019-0cc6-4144-af3e-56d1ff794c2d'; -- 後ろ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Lihat iris di tengah bola mata? Ingatlah bahwa tidak ada benda bulat dalam kanji, jadi benda persegilah yang menggantikannya. Hal ini membuat mata persegi ini cukup realistis. Anda hanya perlu sedikit menyipitkan mata dengan mata asli Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0876e136-5e47-40b2-964e-fa2b14e514bb'; -- 目 (radical)
UPDATE items SET meaning_mnemonic = 'Sawah terdiri dari ladang-ladang dengan saluran irigasi di antara keduanya. Lihat empat sawah dengan air mengalir di antara dan di sekitarnya? Itu sebabnya radikal ini adalah padi.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'ce24780b-94cc-4900-9599-bc321bd3bfb8'; -- 田 (radical)
UPDATE items SET meaning_mnemonic = 'Bayangkan seorang pria melenturkan lengannya ke bawah untuk memamerkan lengannya yang dipompa steroid. Ini sangat besar. Ini penuh dengan kekuatan. RRRRWWWRRR!!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'ab7c29c7-683e-45a8-bc01-06589b9902bb'; -- 力 (radical)
UPDATE items SET meaning_mnemonic = 'Anda memiliki radikal kunci yang dimodifikasi di atas radikal tendangan. Anda menendang kunci sejauh yang Anda bisa, lalu mengukur jaraknya. Berapa lama perjalanannya? Berapa lama waktu yang Anda perlukan untuk menemukannya? Berapa lama Anda akan mendapat masalah karena menendang kunci ke dalam hutan?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '21a30a29-0348-41b9-b8b1-2d7e5269bbcb'; -- 長 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "permata". Perhatikan bentuk karakter "玉" dan asosiasikan bentuk goresannya dengan "permata".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '310832b8-2ccd-4f4c-8da1-cd99104b6b8b'; -- 玉 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini bukanlah sesuatu yang bisa dimiliki oleh siapa pun. Hanya seorang raja yang dapat memakai mahkota ini di kepalanya. Radikal ini adalah tanda raja. Bayangkan raja favorit Anda memakai ini di kepala mereka. Bentuknya cukup khas—saya rasa Anda bisa melakukannya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9710786c-5112-458d-a0b5-1d9cbb117768'; -- 王 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sudah terlihat seperti gerbang, bukan? Bayangkan saja sebuah gerbang besar dengan dua pilar, satu di kedua sisinya. Lalu, di atas ada pintu, yang bisa turun kapan saja.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '65a80b6d-0f40-4030-967d-6532c2d598dc'; -- 門 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sedikit lebih rumit daripada mata, meski serupa. Faktanya, jika Anda menjadi buta, telinga Anda menjadi salah satu indra penglihatan Anda yang baru, itulah sebabnya mengapa ini seperti mata lain yang agak dimodifikasi. Anda bahkan akan melihat garis-garis kecil menonjol dari mata. Itu karena telinga lebih menonjol dibandingkan mata (目), itulah sebabnya radikal ini disebut radikal telinga.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'ca802dcf-0d89-48a7-83c4-6f2ca9bf54e8'; -- 耳 (radical)
UPDATE items SET meaning_mnemonic = 'Pernahkah Anda menggunakan salah satu kompas matematika itu? Ini terlihat seperti salah satunya karena ini adalah radikal pengukuran. Kompas digunakan untuk mengukur sesuatu, seperti ini.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5a9122a4-1713-49d9-a6ba-5daaaf4621ce'; -- 寸 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.

Sadarilah bahwa kata yang digunakan sendiri mungkin terdengar agak kasar. Anda akan segera mempelajari opsi yang lebih netral.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Berikut ini mnemonik untuk membantu Anda mengingatnya: 

Ada manusia. Pikirkan pria paling jantan yang Anda bisa. Dia bekerja di bengkel mobil. Sebagai seorang anak, dia adalah seorang 子 (おとこ), bekerja di bengkel mobil sejak usia dini. Ini mengubahnya menjadi seorang pria dengan sangat cepat. 

Seperti mnemonik lain yang tidak tersusun sempurna, tujuan Anda di sini adalah berada cukup dekat untuk mengingat bacaan sebenarnya. Langkah, langkah, langkah, lompat!' WHERE id = 'fa45a1e3-1077-4d2b-8561-e1acee962a64'; -- 男 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Lebih mudah membayangkannya jika Anda menoleh ke samping. Sisi kiri radikal ini adalah sikat. Lihat semua bulunya?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9107ab44-1836-4397-af7f-1172c0ef6090'; -- 聿 (radical)
UPDATE items SET meaning_mnemonic = 'Kata radikal lihat dan kanji lihat sama persis!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Melihat** (見) tiba-tiba berbicara dan meminta **Kendi/Kencir**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **けん**.' WHERE id = '0c7e004b-b20c-4bb9-8540-a31c4acfffa8'; -- 見 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal untuk eat dan kanji untuk eat adalah sama! Beruntungnya kamu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Makan** (食), bayangkan Anda sedang membawa **Soto/Sosis** untuk ditaruh di atas makan. Kejadian unik ini mengingatkan Anda pada bunyi **しょく**!' WHERE id = '927fdee5-9dbe-4f63-8b27-b01c509fdf90'; -- 食 (kanji)
UPDATE items SET meaning_mnemonic = 'Mengapa Anda mencoba membawa sikat ke matahari? Ini hampir terlalu jelas, karena Anda ingin menulis sesuatu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Menulis** (書), bayangkan Anda sedang membawa **Sopir/Soto** untuk ditaruh di atas menulis. Kejadian unik ini mengingatkan Anda pada bunyi **しょ**!' WHERE id = '8cd8f92c-a91d-470c-8dba-4b8acb221588'; -- 書 (kanji)
UPDATE items SET meaning_mnemonic = 'Apa hari sama dengan terjemahan yang cukup jelas "hari apa." Namun, ini juga berarti berapa hari.', reading_mnemonic = 'Ini adalah kata jukugo, yang biasanya berarti bacaan on''yomi dari kanjinya, namun 何 sebenarnya menggunakan bacaan kun''yomi di sini! Dan karena 日 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat bacaan ini:

Berapa hari yang Anda perlukan untuk memanggang naan Nietzsche (なんにち)? Tidak mudah untuk membuat Nietzsche seluruhnya dari naan, jadi saya bertanya-tanya berapa hari yang dibutuhkan.' WHERE id = '8c753b5b-c5d0-4842-ab07-14e227de448b'; -- 何日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sawah kekuatan berasal dari manusia. Faktanya, satu orang. Dia berlari di atas roda besar di samping sawah dan menyediakan seluruh tenaga agar padi bisa tumbuh dan dipanen.', reading_mnemonic = 'Ketika Anda sedang melihat **Laki-laki** (男), tiba-tiba muncul sesosok **Dandan/Dapur** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **だん**.' WHERE id = 'b2c733cc-9c7a-4346-b304-368d07c2fc12'; -- 男 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda berkeliaran untuk buang air besar di musim dingin Anda tidak akan pernah tahu apa yang mungkin terjadi di belakang Anda. Setelah selesai, Anda dapat kembali untuk melihat sesuatu yang benar-benar gila yang Anda lewatkan karena terlalu lama buang air besar di udara dingin.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kembali** (後), bayangkan Anda sedang membawa **ご** untuk ditaruh di atas kembali. Kejadian unik ini mengingatkan Anda pada bunyi **ご**!' WHERE id = '0906d65f-4a7a-4724-9f30-89b20d7522aa'; -- 後 (kanji)
UPDATE items SET meaning_mnemonic = 'salib yang Anda pegang di atas kepala Anda untuk menjaga tanduk Anda kering terus menarik Anda selatan. Mungkin karena di bagian selatan Jepang lebih hangat, jadi lebih mudah untuk menjaga keadaan tetap kering.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Selatan** (南), bayangkan Anda sedang membawa **なん** untuk ditaruh di atas selatan. Kejadian unik ini mengingatkan Anda pada bunyi **なん**!' WHERE id = 'f33f4ebb-b421-4563-9cc3-676ca060e9ee'; -- 南 (kanji)
UPDATE items SET meaning_mnemonic = 'anak dari laki-laki bukanlah laki-laki, ia adalah anak laki-laki.', reading_mnemonic = 'Jika Anda mengetahui pembacaan kun''yomi dari kedua kanji ini, Anda seharusnya baik-baik saja. Anda memiliki dua kata kanji tunggal terpisah yang disatukan oleh の. Itu sebabnya bacaan kun''yomi - keduanya terpisah.' WHERE id = '69befb51-4ecc-4bec-99f6-5466190e88b2'; -- 男の子 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Ceritakan tentang negara Anda. Sekarang bayangkan semua orang di negara Anda mempunyai lutut yang dingin (くに). Itu karena aturan berpakaian nasional adalah celana pendek, sehingga lutut semua orang terasa dingin. Itu sebabnya lutut mereka dingin. Anda juga bisa membayangkan lutut keren dalam artian lutut trendi. Menurut Anda, apa yang membuat lutut terasa sejuk?' WHERE id = 'eaeef022-7760-40e0-a683-8d31dbc95022'; -- 国 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tengah negara... siapakah itu? Mari kita pikirkan tentang hal ini. Siapa yang menemukan kanji dan karena itu mungkin mengira itu adalah dunia tengah? Siapakah negara besar yang menguasai sebagian besar Asia? Itu tidak lain adalah China.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Pastikan Anda memperhatikan rendaku.' WHERE id = '55888580-6e9c-4e5c-8879-e8e5f0679f56'; -- 中国 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu 高校 berarti "sekolah menengah". Jadi, “kehidupan” yang dilakukan SMA adalah siswa SMA. Ini seperti 中学生 adalah siswa sekolah menengah dan 小学生 adalah siswa sekolah dasar!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Gunakan bacaan 高校 sebelumnya untuk mempelajari bacaan kata ini juga, jika itu membantu.' WHERE id = '2eff35d1-5584-4efc-80c9-25f9abba3612'; -- 高校生 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, biasanya Anda mengira kata tersebut menggunakan bacaan kun''yomi. Tapi bukan kata ini. Itu masih menggunakan bacaan on''yomi, yang Anda pelajari dengan kanji. Namun, jangan bingung membedakan yang ini dengan お金. Yang itu menggunakan kun''yomi yang lho karena ada hiragana yang terpasang.' WHERE id = '8b849db7-a48f-453a-9c8a-84ccb8bd59d6'; -- 金 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Siapa yang memiliki studi kehidupan? Hanya satu orang yang saya kenal, dan itu adalah siswa.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3e335d26-9ef4-4d47-8e9d-1fdfacf3fefe'; -- 学生 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata "雨水" memiliki arti "Air Hujan". Kombinasi kanji dalam kata ini melambangkan konsep air hujan.', reading_mnemonic = 'Cara membaca kosakata "雨水" adalah "あまみず".' WHERE id = '76528656-9740-4740-8996-cf461cc2c64b'; -- 雨水 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Pikirkan tentang selatan. Ada apa di bawah sana? Maksudnya Amy (みなみ) tinggal di bawah sana. Pikirkan tindakan kejam terakhir yang dia lakukan terhadap Anda dan bayangkan hal itu sambil berteriak "MAKNA AMYYYYY" ke langit.' WHERE id = 'a1cdea60-3b64-4ab7-a88d-04844391dcfd'; -- 南 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu satu kata 時, kan? Artinya waktu. Ini dua kali. Jadi, Anda punya satu waktu, dan Anda punya waktu lain. Mereka terpisah. Hal-hal tidak terjadi pada setiap waktu yang Anda miliki. Itu terjadi terkadang.', reading_mnemonic = 'Pembacaannya adalah vocab kata 時 sebanyak dua kali, yang kedua mendapat rendaku.' WHERE id = 'a3c913b3-121b-4a6e-a282-5f06943377ba'; -- 時々 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti menulis sehingga versi verbanya berarti to write.', reading_mnemonic = 'Pembacaan yang dipelajari dengan kanji adalah on''yomi, namun kata ini dibaca dengan kun''yomi, か. Jadi pastikan untuk mengingat bacaan kun''yomi untuk membaca kata ini di dalam mobil (か) ... atau untuk menulis, atau apa pun.' WHERE id = 'f69692ec-e2f3-40bf-9eea-f98bc4232694'; -- 書く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda melihat seorang pria berjalan ke timur, menuju matahari terbit di balik pohon itu, tapi terlalu terang. Dia tersandung dan kakinya terluka (ひがし) pada akar yang mencuat dari tanah. Kakinya robek parah, tapi dia mencoba mengambil satu langkah lagi dan, oh tidak, kakinya terluka lagi! Orang ini tidak mempunyai waktu yang mudah untuk pergi ke timur.' WHERE id = 'f52371dd-8c45-4491-9873-ef127a083313'; -- 東 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Kamu mengunjungi ibumu yang tinggal di dalam mobil. Ini menyedihkan, dan Anda merasa tidak enak. Hal pertama yang keluar dari mulutmu adalah: "Cool Room, Ma (くるま) karena kamu tidak tahu harus berkata apa lagi tentang situasi kehidupan ibumu. 

Pastikan untuk memotong huruf terakhir dari dua kata pertama... sesuatu seperti "coo'' roo'' ma!" Sedihnya, hanya ada satu ruangan di mobil ini yang disebut ibumu sebagai rumah.' WHERE id = '87c5daf6-cca0-4f39-b1a8-2c4be4f6b0a6'; -- 車 (vocabulary)
UPDATE items SET meaning_mnemonic = 'pemimpin kita mempunyai cincin bibir. Tunggu, pemimpin kita punya cincin bibir? APA??', reading_mnemonic = 'Tahukah Anda bahwa **Apa** (何) ini sebenarnya dibuat dari tumpukan **Kaki/Kaca**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **か**.' WHERE id = '12ded606-bc5d-46c9-b92d-4eb6843f9546'; -- 何 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari panjang? Katanya juga panjang.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda memiliki sesuatu yang sangat panjang. Ini adalah rambut gila yang tumbuh dari ujung hidung Anda. Anda tidak terlalu peduli apakah itu tetap ada atau hilang, tetapi Anda terlalu malas untuk memotongnya. Namun, orang tuamu terus berusaha mengomeli (なが) kamu agar memangkasnya. Bayangkan proses ini terjadi dan merasa kesal karenanya. Sungguh menjengkelkan.' WHERE id = '0aa15b30-44ec-480b-a6d9-0cbb894f463f'; -- 長い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari emas dalam seminggu adalah hari terhebat. Ini adalah hari yang membuat Anda merasa seperti emas karena ini adalah akhir hari kerja dan awal akhir pekan! Hari ini adalah Jumat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = 'ec34c03e-ceb8-42e7-b551-b032dea6e265'; -- 金曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'mobil radikal dan mobil kanji sama persis.', reading_mnemonic = 'Tahukah Anda bahwa **Mobil** (車) ini sebenarnya dibuat dari tumpukan **Sapi/Sampo**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **しゃ**.' WHERE id = '3c90500c-924a-4322-a39f-51def37853f2'; -- 車 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada beras yang tersebar di seluruh tanah. Hal ini akan menyebabkan Predator datang karena dia menyukai kome (nasi). Lalu setelah dia pergi, Predator berikutnya akan datang untuk makan.', reading_mnemonic = 'Tahukah Anda bahwa **Datang** (来) ini sebenarnya dibuat dari tumpukan **Rantai/Raja**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **らい**.' WHERE id = '8706109c-8a0b-4db4-8f4c-3f3efcf4b06c'; -- 来 (kanji)
UPDATE items SET meaning_mnemonic = 'Di sebelah pohon, sebuah penutup diletakkan di ayah Anda. "Halo nak," sapanya. "Ini adalah sekolah barumu."', reading_mnemonic = 'Ketika Anda sedang melihat **Sekolah** (校), tiba-tiba muncul sesosok **Koko/Koki** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **こう**.' WHERE id = '1a29e260-43de-41b9-8c86-e4ce31596eb2'; -- 校 (kanji)
UPDATE items SET meaning_mnemonic = 'Sebuah listrik pembicaraan. Apa sihir ini? Satu-satunya cara untuk berbicara melalui listrik adalah dengan telepon.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '65615f7b-8f30-4cc4-a122-03ea11bf015c'; -- 電話 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda mungkin berpikir bahwa listrik mobil adalah mobil listrik, namun kata ini dibuat sebelum zaman Prius. Ini mengacu pada kereta, yang menurut saya pernah menjadi listrik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'd75c2f4d-8292-485a-af1f-ccd2d2348d25'; -- 電車 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mudah-mudahan Anda sudah melihat 聞く. Hal ini serupa, namun alih-alih berarti "mendengar", yang dimaksud adalah dapat didengar (atau dapat didengar). Bayangkan saja こえ yang tergantung di sana sebagai suara yang dapat Anda dengar.', reading_mnemonic = 'Bacaannya berasal dari 聞く, jadi jika anda mengetahui bacaan dari kata tersebut anda bisa menerapkannya disini.' WHERE id = '8ead3756-cf27-47e4-92f4-4e0b77724f46'; -- 聞こえる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada sesuatu yang keluar dari mulut. Sesuatu dengan seribu selera kecil di dalamnya. Itu lidah Anda!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '851dcfc2-6c1a-4e15-ad54-394c463c6a1f'; -- 舌 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti radikal malam tetapi memiliki pukulan yang ekstra panjang. Hal ini karena malam hari merupakan waktu yang panjang di musim dingin. Hari mulai gelap.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'df5caa7a-ea91-4a1d-b4ae-7239baba7aa4'; -- 夂 (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti berbicara jadi versi kata kerjanya adalah to talk atau to speak.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Setiap kali Anda mencoba berbicara, 花 (はな) keluar begitu saja dari mulut Anda dan mencegah Anda. Bayangkan mulut Anda penuh dengan bunga. Cicipi, keluarkan, dan coba bicara lagi. Masalah yang sama.' WHERE id = '2436aca2-1fbb-4216-8c81-cd892692fef7'; -- 話す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya tinggi.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '93eb6b0f-0b6d-49fd-b07a-df8508d690be'; -- 高 (radical)
UPDATE items SET meaning_mnemonic = 'Ada banyak gelombang suara yang keluar dari mulut. Gelombang tersebut mewakili hal-hal yang Anda ucapkan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '2e53519c-8da3-4e56-a3b1-14193548a0a8'; -- 言 (radical)
UPDATE items SET meaning_mnemonic = 'Ada dua set paku di bawah topi itu. Ini sebenarnya sebuah jebakan, untuk mencegah siapa pun masuk dan mencuri emas Anda. Kenapa lagi kamu membuat jebakan? Semua orang suka melindungi emas mereka.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9b1808ad-20b2-4446-b7fb-378cbff3b759'; -- 金 (radical)
UPDATE items SET meaning_mnemonic = 'Anda berdiri di tengah sawah di tengah hujan dengan payung. Anda berdiri di sini karena tidak ada hal lain yang sangat tinggi di sekitar Anda. Anda ingin terkena listrik (alias petir) untuk menunjukkan keberadaannya.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Listrik** (電) tiba-tiba berbicara dan meminta **Dendeng/Denda**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **でん**.' WHERE id = '857587c2-57f5-47e5-9c9b-ed08cc79e862'; -- 電 (kanji)
UPDATE items SET meaning_mnemonic = 'Handuknya basah oleh tetesan cairan. Itu karena sedang hujan. Bawalah handuk dan pakaian lain ke dalam sebelum basah kuyup karena hujan ini!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0b8b0016-45ac-4bfb-8fc3-c22b077ba49a'; -- 雨 (radical)
UPDATE items SET meaning_mnemonic = 'Anda memakai topi dan pergi keluar untuk menendang sesuatu yang berwarna putih. Itu angsa putih besar dan kamu membunuhnya dengan tendanganmu. Itu karena Anda akan memasak dan memakannya itu. enak!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6d0fdf89-d956-493a-b03d-30a9ab37c44f'; -- 食 (radical)
UPDATE items SET meaning_mnemonic = 'Ada sesuatu yang menonjol dari diri Anda saat Anda sendirian. Itu kotoran! Anda tidak bisa buang air besar begitu saja di depan umum, itu ilegal dan menjijikkan di zaman sekarang ini. Jadi jika lain kali sesuatu mulai keluar dari diri Anda saat Anda sedang sendirian, pikirkan, "Ah ya, itu kotoran."', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '60ddb6d9-4c18-448f-8427-bea5aca52028'; -- 幺 (radical)
UPDATE items SET meaning_mnemonic = 'Ada gerbang yang dilewati matahari dengan interval yang teratur. Ada interval waktu dalam artian matahari melewatinya pada waktu yang sama setiap hari. Dan terdapat jeda ruang dalam artian harus melewati ruang antar tiang gerbang.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Jarak** (間) tiba-tiba berbicara dan meminta **Kancil/Kantor**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **かん**.' WHERE id = '8cb672b4-1718-43fb-8286-83d70cdf1fa9'; -- 間 (kanji)
UPDATE items SET meaning_mnemonic = 'matahari digunakan dalam kuil untuk memberitahukan waktu. Mereka tidak punya jam atau ponsel, mereka punya jam matahari dan gaya kuno yang bagus untuk "melihat ke atas dan melihat di mana matahari berada saat ini".

Ini juga bisa berarti jam, seperti dalam "jam lima" Ini digunakan untuk mengukur waktu dalam bahasa Jepang.', reading_mnemonic = 'Bagaimana cara membaca kanji **Waktu** (時)? Ingat saja bahwa **Juri/Jalan** sangat menyukai waktu! Hubungan erat ini akan membantu Anda mengingat bunyi **じ**.' WHERE id = '29b13f1f-62bd-4841-9127-44c8348fc87f'; -- 時 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Ini terkait dengan arti kanji 見 "melihat", tapi yang ini adalah tentang membuat orang lain melihat sesuatu. Dengan kata lain, artinya to show.', reading_mnemonic = 'Pembacaan kata ini sama dengan yang kamu pelajari dengan kanji, jadi kamu harus bisa membacanya.' WHERE id = '2a7925cd-fa8f-4134-af26-8fe3f5bfd3e0'; -- 見せる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti melihat, dan 見える adalah to be seen, atau to be in sight, meskipun sering kali lebih alami diterjemahkan ke dalam bahasa Inggris sebagai can see. Ini digunakan ketika Anda tidak secara aktif bermaksud untuk melihat sesuatu, itu terjadi begitu saja.

Kata kerja ini juga bisa berarti tampak, ketika berbicara tentang cara Anda memandang sesuatu yang dapat Anda lihat.', reading_mnemonic = 'Pembacaan kata ini sama dengan yang Anda pelajari dengan kanji (pembacaan kun''yomi). Jadi selama Anda mengetahuinya, Anda harus bisa membaca kata ini juga.' WHERE id = 'afaa674e-4032-4565-b736-140bd8768dbb'; -- 見える (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa studi besar itu? Jika saya harus memilih, saya mungkin akan mengatakan ini adalah college atau university.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Universitas Anda terkenal karena pewarnanya yang melongo (だいがく). Ini adalah olahraga yang membuat Anda terpesona dengan pewarna, dan universitas Anda adalah yang terbaik dalam hal itu! Universitas lain mungkin terkenal dengan tim sepak bola atau bola basketnya, tetapi universitas Anda adalah yang terbaik dalam hal melongo.' WHERE id = 'bfa2d6da-3fdc-4c7c-b4a7-97e56417274b'; -- 大学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda mendekatkan telinga ke gerbang, kemungkinan besar Anda akan mendengar apa yang terjadi di seberang sana. Orang lain di seberang sana tidak akan tahu bahwa Anda mendengarkan percakapan mereka karena Anda sangat licik dan pintar. Mereka tidak tahu Anda berada di balik gerbang dan mendengarkan setiap kata yang mereka ucapkan.', reading_mnemonic = 'Ketika Anda sedang melihat **Mendengarkan** (聞), tiba-tiba muncul sesosok **Bunga/Buku** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **ぶん**.' WHERE id = 'e6cf63c3-78a2-40c2-b12c-6334a14dea98'; -- 聞 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda tahu 日本 adalah "Jepang". Jadi, ketika Anda menambahkan bahasa di akhir, Anda memiliki Bahasa Jepang.', reading_mnemonic = 'Pembacaannya hanyalah kosakata 日本 (にほん) ditambah bacaan yang telah anda pelajari untuk 語. Gabungkan keduanya untuk mendapatkan bacaan untuk kata ini.' WHERE id = '26e22b79-2b2c-48ac-bfb8-f9fedce38775'; -- 日本語 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal emas dan kanji emas adalah sama!', reading_mnemonic = 'Tahukah Anda bahwa **Bukan itu** (金) ini sebenarnya dibuat dari tumpukan **Kincir/Kendi**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **きん**.' WHERE id = '1bddbc6e-83bc-49f7-b49e-d8ed5b35bb3e'; -- 金 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Pembacaan kata ini sama dengan pembacaan yang Anda pelajari dengan kanji. Apa? Ya, itulah yang terjadi.' WHERE id = '14cdbe4e-7501-4e4f-831a-88bc6a73d874'; -- 何 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Versi kanji dari 話 berarti berbicara. Kata ini juga berarti talk, namun juga memiliki arti lain. Ini bisa merujuk pada pidato atau story juga. Pada dasarnya segala sesuatu yang melibatkan sesi pembicaraan. Jadi, sebelum Anda pergi, saya harap Anda tinggal sebentar dan mendengarkan 話 saya.', reading_mnemonic = 'Siapa yang menceritakan kisah yang hebat? Hana, dia (はなし) menceritakan kisah yang hebat! Jika Anda mengenal seseorang bernama Hana atau Hanna, Anda dapat menggunakan orang tersebut untuk membantu Anda mengingat orang ini dengan lebih baik juga. 

Anda juga dapat menggunakan bacaan 話す untuk membantu Anda mengingat yang ini juga.' WHERE id = '25b4a3c6-c0c1-4a55-8d91-3c86c938edc7'; -- 話 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Di balik pohon itu, matahari sedang terbit di timur. Matahari selalu terbit di timur, jadi jika Anda menuju ke sana, melewati pohon, Anda juga akan menuju ke timur.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Timur** (東) tiba-tiba berbicara dan meminta **Topi/Toko**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **とう**.' WHERE id = 'a7df1150-cd43-49b3-9bec-502125724d38'; -- 東 (kanji)
UPDATE items SET meaning_mnemonic = 'makan sesuatu (alias "sesuatu yang kamu makan") adalah makanan. Makanlah itu. Makanlah makanan itu. Karena itu adalah "sesuatu", Anda tahu itu adalah kata benda. Menarik bagaimana kanji ini bisa mengubah kata kerja seperti ini menjadi kata benda bukan? Hati-hati karena pola ini akan muncul pada kata kerja lain juga!', reading_mnemonic = 'Kata ini menggunakan bacaan kun''yomi untuk kedua kanjinya, tapi kamu sudah mengetahui keduanya sekarang, jadi kamu harus bisa membacanya juga!' WHERE id = '6d9d8677-fb97-411e-9b1c-bef63c80737d'; -- 食べ物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Nama Anda ada di depan. Itu bukan nama belakang Anda, itu adalah nama biasa atau nama depan Anda.', reading_mnemonic = 'Kata ini menggunakan kedua bacaan kun''yomi (oh sial!). Meskipun demikian, Anda telah melihat pembacaan kun''yomi untuk kedua kanji yang membentuk kata ini. Kata 名 (な) dan kata 前 (まえ) keduanya adalah kun''yomi, jadi gunakan kata tersebut dan Voltron menjadi satu kata, なまえ.' WHERE id = '7a1f64c2-abb1-412c-8407-3af12b8dad1f'; -- 名前 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Apa yang depan dari Anda? Pikirkan tentang hal ini. Jadikan itu sesuatu yang konyol. Sekarang lihatlah tag yang ada di sana. Milik siapa benda ini? Oh, tunggu, itu (まえ) milikku ada di depanku. Katakan itu dengan lantang untuk ingatan yang lebih baik.' WHERE id = 'f4d8605e-91c9-442a-8a2d-a04315f4b282'; -- 前 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda harus mengatakan apa yang Anda jual karena orang tidak suka membaca. Jika mereka lewat dan tidak membaca, lebih baik Anda katakan apa yang Anda jual agar mereka tahu! Bacakan dengan lantang kepada mereka.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Membaca** (読) tiba-tiba berbicara dan meminta **Dokter/Domba**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **どく**.' WHERE id = '0ca8ea33-e149-4b09-ae88-161e7b50a612'; -- 読 (kanji)
UPDATE items SET meaning_mnemonic = 'Ibukota Timur di Jepang adalah Tokyo. Jika Anda melihat peta dan membandingkannya dengan 京都 (Kyoto, ibu kota lain dalam sejarah), Anda akan melihat bahwa itu adalah sebelah Timur Kyoto, menjadikannya Ibu Kota Timur, Tokyo.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'b6dbc807-a176-4253-907c-2aa80202167b'; -- 東京 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal panjang dan kanji panjang adalah sama! 

Kanji ini juga berarti pemimpin, karena semakin lama seseorang, semakin baik pula pemimpinnya. Atau mungkin... semakin lama mereka berada di suatu tempat? Terserahlah, panjang umur = kepemimpinan, tahu?', reading_mnemonic = 'Bagaimana cara membaca kanji **Panjang** (長)? Ingat saja bahwa **Cokelat/Corong** sangat menyukai panjang! Hubungan erat ini akan membantu Anda mengingat bunyi **ちょう**.' WHERE id = '800dd1c4-02c6-4647-b0b3-752de9917098'; -- 長 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri artinya datang jadi kalian pasti tahu kata ini artinya to come.', reading_mnemonic = 'Pembacaan kata ini cukup aneh. Ini berubah tergantung pada jenis bentuk kata kerja yang Anda gunakan (ini adalah kata kerja pengecualian yang mengganggu). Untuk mengingat bacaan kata ini, berikut mnemoniknya: 

"Saya ingin Anda datang ke sisi yang keren (くく), Luke," kata Darth Vader.
"Apa?" jawab Lukas.

Ganti saja baris ini dengan baris terkenal dari Star Wars. Katakan dengan lantang. Lakukan suara Vader. Ini akan membantu Anda mengingatnya.' WHERE id = '790b8be9-0318-4efe-972d-dd7fe3c06982'; -- 来る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada beberapa tanduk di tanah dan bulan pisau di depan Anda. Saat Anda mencoba bergerak, mereka selalu berputar bersama Anda, tetap berada di depan. Anda tidak dapat melarikan diri dari objek-objek ini, karena alasan tertentu.

Kanji ini juga berarti sebelum. Bagaimanapun, sesuatu yang ada di depan Anda ada di depan Anda.', reading_mnemonic = 'Tahukah Anda bahwa **Depan** (前) ini sebenarnya dibuat dari tumpukan **Semen/Senter**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **ぜん**.' WHERE id = '02799e7e-79a3-4e7a-a1c4-b3309cb0f970'; -- 前 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti membaca sehingga versi kosakata kata kerjanya adalah to read.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Bacalah yang lain, sekarang.' WHERE id = '467b293c-5ca9-4401-a338-2281610ae8f3'; -- 読む (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ambil semua kata yang Anda gunakan dalam tulisan, gabungkan semuanya dan Anda memiliki kamus!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'dfa348fd-55f2-4951-ab72-7ff0fdafe19a'; -- 辞書 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

jam jam berapa sekarang? Saatnya mengunci (とき) mobil musuhmu. Bayangkan diri Anda melihat arloji Anda, menunggu hingga waktu yang tepat untuk melakukan penguncian mobil seseorang secara tersinkronisasi. Siapa yang paling kamu benci? Mobil siapa yang ingin Anda kunci?' WHERE id = 'c5a30c7b-47e8-4902-b4b1-89930d6a7c4b'; -- 時 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari tinggi atau mahal? Sama saja: tinggi atau mahal. 

Aneh kalau kata ini berarti kedua hal ini, ya? Bayangkan saja uang yang ditumpuk menjadi sangat tinggi. Uang itu mahal karena perlu membeli sesuatu yang mahal.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Ada seorang pria tinggi yang mencoba menjual sesuatu yang sangat mahal kepada Anda. Dia benar-benar menjelaskan betapa hebatnya item ini dan bagaimana Anda harus membelinya. Orang ini adalah penjual sejati. Seorang pembicara sejati (たか).' WHERE id = 'c9199c16-e005-4f8b-87f0-c210e5b840c5'; -- 高い (vocabulary)
UPDATE items SET meaning_mnemonic = 'stasiun anggota kereta api adalah seseorang yang bekerja di stasiun kereta. Mereka adalah pegawai stasiun kereta. Jangan ragu untuk bertanya kepada mereka apakah Anda memerlukan bantuan untuk mengetahui arah mana yang harus Anda latih.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '85afc5b6-66c9-480f-afe0-067edd80e2e2'; -- 駅員 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada domba tepat di depan mata Anda, karena mereka menyukai apa yang pakai. Sudah menjadi rahasia umum bahwa domba adalah fashionista, dan mereka datang setiap hari untuk mengagumi gaya Anda. Domba-domba ini sangat bergaya sehingga mereka memakai ekornya ke satu sisi - dengan gaya terkini (lihat domba radikal - ekornya menyapu dengan gaya ke kiri!).', reading_mnemonic = 'Bagaimana cara membaca kanji **Pakai itu** (着)? Ingat saja bahwa **Ceri/Cili** sangat menyukai pakai itu! Hubungan erat ini akan membantu Anda mengingat bunyi **ちゃく**.' WHERE id = 'd05f740a-4d9f-47df-a59f-6bb57738d210'; -- 着 (kanji)
UPDATE items SET meaning_mnemonic = 'Ketika kekuatan Anda tidak berarti apa-apa, Anda tidak berdaya.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Anda juga dapat mengetahui bahwa 力 menggunakan pembacaan りょく karena ketika Anda mencoba mengambil batu kecil (りょく) Anda tidak dapat melakukannya, karena Anda tidak berdaya.' WHERE id = '65238981-75b4-4e4b-891e-63d3a629d5e6'; -- 無力 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 手 terkadang bisa merujuk pada seseorang? Dalam hal ini, kita mempunyai lagu orang (atau mungkin "orang yang menangani lagu"). Orang yang juga dikenal dengan lagu apa? Seorang penyanyi.', reading_mnemonic = 'Bacaannya adalah bacaan on''yomi. Anda sudah mempelajari keduanya (Anda mempelajari cara membaca on''yomi 手 dengan kata 投手), jadi Anda seharusnya bisa membaca ini seperti penyanyi bernyanyi dengan seikat kacang mete かしゅ di mulutnya. CEPAT DAN KERAS!' WHERE id = '648a17d6-a7c2-4cce-b08f-00d321e32da0'; -- 歌手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'ibu orang tua adalah ibu.', reading_mnemonic = 'Pembacaan untuk ini aneh. Itu adalah bacaan kosakata kun''yomi, mungkin karena terjemahan literalnya adalah "ibu orang tua" dan karena itu terdiri dari beberapa kata yang digabungkan menjadi satu konsep. Jadi, pastikan Anda mengetahui perbedaan pembacaan kata 母 dan 親. Jika ya, Anda seharusnya bisa membaca ini juga.' WHERE id = '24470cc5-587b-4524-bacd-52335a8bf46e'; -- 母親 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika istirahat tidak ada maka tidak ada hari libur. Jika tidak ada hari libur, berarti suatu tempat selalu buka, nonstop.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '34e3a369-55ce-4895-b0a8-c786966f452a'; -- 無休 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Arahkan leher skuter ke jalan! Skuter hanya dimaksudkan untuk berkendara di jalan dan jalur, dan jika Anda salah jalan, Anda mungkin akan patah leher sendiri!', reading_mnemonic = 'Ketika Anda sedang melihat **Jalan** (道), tiba-tiba muncul sesosok **Domba/Topi** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **どう**.' WHERE id = '35b3e5d3-3529-4ab3-8e7d-63363cbfa9f3'; -- 道 (kanji)
UPDATE items SET meaning_mnemonic = 'suara dari hatimu memberiku sebuah ide. Debaran jantung yang berdebar-debar secara metodis membuatku kesurupan yang memberiku ide-ide hebat. Itu suara yang sangat inspiratif, suara hati. Ini memberi saya ide. 

Alternatifnya, Anda bisa melihat kanji ini dan melihat kata "berdiri" yang radikal dan sesuatu yang (hampir) terlihat seperti kanji untuk "berpikir". Saat Anda berdiri dan berpikir, Anda memunculkan ide Anda sendiri!', reading_mnemonic = 'Ketika Anda sedang melihat **Ide** (意), tiba-tiba muncul sesosok **い** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **い**.' WHERE id = '50e8d3c1-8493-43d8-9818-5feb496eff04'; -- 意 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji tidak ada dan kanji tidak ada sama persis! Wah!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Tidak ada** (無) tiba-tiba berbicara dan meminta **Mulut/Muka**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **む**.' WHERE id = '44e904c6-78be-4597-908b-258583fb22ea'; -- 無 (kanji)
UPDATE items SET meaning_mnemonic = 'barang yang Anda pakai adalah pakaian Anda. Oh, dan pakaian Jepang juga diperhitungkan. Kita sedang membicarakan kimono. Dahulu kala, ini hanya bisa disebut pakaian karena memang itulah yang dikenakan semua orang, namun saat ini kita tahu bahwa kimono tersebut khusus untuk kimono stereotip yang Anda pikirkan saat memikirkan "Jepang".', reading_mnemonic = 'Pembacaannya agak aneh menggunakan bacaan kun''yomi. Untungnya, kami sudah mengajarimu hal ini, jadi kenakan kimonomu dan bersantailah di 温泉 sebentar.' WHERE id = 'fad60e90-395d-4543-8d27-16d8b2861822'; -- 着物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu di luar ide normal Anda tentang cara kerja akan terasa tidak terduga atau mengejutkan bagi Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '30af705c-7511-4684-876a-3e6be7fee734'; -- 意外 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan kanji.' WHERE id = 'd953d571-63cb-45db-b406-56bf5cc57045'; -- 銀 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika biaya tidak ada maka gratis dan tanpa biaya!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'dd4c0ad6-9bbf-4869-9222-ebb366994a66'; -- 無料 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kata ini juga mengacu pada nasi yang dimasak, karena Anda harus makan nasi setiap kali makan, jadi pada dasarnya ini identik dengan "makanan" itu sendiri.

Kata ini mempunyai kesan sedikit kasar sehingga sering digunakan dalam situasi informal.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari cara membacanya, jadi inilah mnemonik untuk membantu Anda dengan kata ini: Anda sedang makan makanan... MMmm, enak! Apa yang kamu makan? Ya, itu jaring Mesh (めし). Cicipi jaringnya. Rasanya tidak enak. Ini adalah makanan yang buruk. Rasakan di mulut Anda. Ini aneh dan berbelit-belit.' WHERE id = '3d2b2c10-2255-489e-869c-eaf68c7cf365'; -- 飯 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seekor kuda dan udang duduk bersebelahan. Mereka berdua berada di stasiun kereta, menunggu kereta datang dan membawa mereka pulang.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Stasiun** (駅), bayangkan Anda sedang membawa **Ember/Elang** untuk ditaruh di atas stasiun. Kejadian unik ini mengingatkan Anda pada bunyi **えき**!' WHERE id = 'da8281c8-9a17-4a75-abb3-51dd4c832548'; -- 駅 (kanji)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang membawa rotasi (pikirkan roda!) adalah sebagian besar jenis kendaraan. Jadi, ini seperti mengatakan Anda sedang "membuat kendaraan" di sini... tapi itu tidak masuk akal. Apa yang Anda lakukan terhadap kendaraan? Anda mengendarainya. Itu sebabnya kata ini berarti mengemudi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '9b374ece-9653-4e5c-af5f-e17ad2d78a58'; -- 運転する (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat mengendarai skuter, Anda membenturkan dahi Anda ke mobil di depan. Skuter Anda rusak, jadi Anda harus membawanya pulang. Anda memerlukan banyak keberuntungan untuk membawa skuter itu pulang dengan selamat.', reading_mnemonic = 'Tahukah Anda bahwa **Keberuntungan** (運) ini sebenarnya dibuat dari tumpukan **Unta/Ular**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **うん**.' WHERE id = 'c63e8920-cfa1-438a-afe1-dc483ca1c692'; -- 運 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada salib yang menonjol di bagian atas matahari dan salib lainnya yang menonjol di bagian bawah. bulan berada di sebelah kanan. Itu karena ini adalah pagi, yaitu saat matahari dan bulan berganti posisi. Salib tersebut memastikan matahari tetap tinggi di langit sepanjang hari.', reading_mnemonic = 'Ketika Anda sedang melihat **Pagi** (朝), tiba-tiba muncul sesosok **あさ** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **あさ**.' WHERE id = '7363769c-76c8-4a6c-9bf5-9446e9863e7d'; -- 朝 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada beberapa kerang di net yang bisa Anda beli. Anda tidak bisa begitu saja membeli kerang yang lepas. Anda hanya dapat membeli yang ada di jaring, dikantongi, dan siap untuk uang Anda.', reading_mnemonic = 'Anda membeli **Babi** (ばい) peliharaan yang lucu.' WHERE id = '206bb8b1-7845-472a-9141-7874d9d3fe70'; -- 買 (kanji)
UPDATE items SET meaning_mnemonic = '"Apakah kemeja bambu cocok untukku?" Anda bertanya... tapi tak seorang pun akan menjawab.', reading_mnemonic = 'Ketika Anda sedang melihat **Jawab** (答), tiba-tiba muncul sesosok **こた** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **こた**.' WHERE id = '901f758c-9c9b-45a9-ab14-f3f8debeda32'; -- 答 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda anti-makan makanan Anda akan tetap berada di depan Anda, tidak dimakan. Makanan dimaksudkan untuk dimakan! Berhentilah mencoba berpuasa dan makanlah.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Makan** (飯) tiba-tiba berbicara dan meminta **Hantu/Handuk**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **はん**.' WHERE id = '9f10178e-ad44-4fb9-91f3-afc3a465c3f2'; -- 飯 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda menggantikan sejumlah kerang sebagai jaminan sehingga teman Anda akan meminjamkan sejumlah uang kepada Anda. Biasanya dia akan meminta sesuatu yang lebih berharga, tapi Anda telah meyakinkan dia untuk mengganti kerang tersebut dengan apa yang biasanya dia ambil sebagai jaminan saat meminjamkan kepada orang lain.', reading_mnemonic = 'Tahukah Anda bahwa **Pinjamkan itu** (貸) ini sebenarnya dibuat dari tumpukan **Kaki/Kaca**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **か**.' WHERE id = 'ef0f7c9f-a157-449a-98e2-6f19e9405160'; -- 貸 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada berdiripohon  yang sedang Anda kapak ambil. Anda akan menebang pohon ini agar pohon baru tumbuh.', reading_mnemonic = 'Ketika Anda sedang melihat **Baru** (新), tiba-tiba muncul sesosok **Shin-chan/Singa** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **しん**.' WHERE id = 'ea1148d3-f9cf-47f9-872f-a2b43578ad7c'; -- 新 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika domba mengalami kesulitan saat mencoba memakan ikan dengan paku di sirip, maka domba tersebut mungkin tidak punya urusan untuk mencoba memakannya. Bukankah domba biasanya makan rumput dan sejenisnya? Apa yang dilakukan domba ini saat mencoba memakan ikan yang siripnya berduri? Bisnis konyol apa ini.', reading_mnemonic = 'Tahukah Anda bahwa **Bisnis** (業) ini sebenarnya dibuat dari tumpukan **Gajah**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **ぎょう**.' WHERE id = '8933b29b-c11e-4437-9272-989711ed315c'; -- 業 (kanji)
UPDATE items SET meaning_mnemonic = 'Makanmakan di atap ini adalah beruang, sehingga Anda tahu bahwa ini adalah gedung publik. Undang-undang menyatakan bahwa semua beruang diperbolehkan makan di atap gedung-gedung publik. Setidaknya di Jepang, saya tidak tahu di mana beruang seharusnya makan, di mana pun Anda berasal.', reading_mnemonic = 'Bagaimana cara membaca kanji **Gedung Umum** (館)? Ingat saja bahwa **Kancil/Kantor** sangat menyukai gedung umum! Hubungan erat ini akan membantu Anda mengingat bunyi **かん**.' WHERE id = '41fa46b3-40b5-4306-a2ac-2a7baebdd747'; -- 館 (kanji)
UPDATE items SET meaning_mnemonic = 'Saat matahari terbit di atas perbukitan, serigala yang ganas mengintai kalkun di pagi hari hari kerja. Serigala berburu kalkun untuk mencari nafkah, tetapi pada akhir pekan, dia suka bermain raket di gym setempat. Itu sebabnya kalkun diburu pada hari kerja.', reading_mnemonic = 'Ketika Anda sedang melihat **Hari kerja** (曜), tiba-tiba muncul sesosok **Yoga** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **よう**.' WHERE id = '34cdb410-a8c5-472f-ac5f-badd2600fabd'; -- 曜 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Bayangkan sebuah ikan. Sekarang bayangkan ikan itu bermain sepak bola sambil mengenakan pakaian biarawati. Ini adalah biarawati sepak bola (さかな).' WHERE id = '86fd0a89-d0d7-4e77-86b3-d55db41d5ceb'; -- 魚 (vocabulary)
UPDATE items SET meaning_mnemonic = 'emas ikan sebenarnya hanya berwarna emas, namun tetap disebut ikan mas.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'd91f1587-1a60-4548-9965-57c75a2b4331'; -- 金魚 (vocabulary)
UPDATE items SET meaning_mnemonic = 'ocean fish hanyalah ocean fish. Mereka juga merupakan jenis ikan yang paling enak.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.

Beberapa orang juga menggunakan pembacaan kun''yomi, tetapi ini kurang umum, dan umumnya dianggap bahasa sehari-hari.' WHERE id = 'c9507151-60c5-4727-92f0-a8527ee5689d'; -- 海魚 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Mudah-mudahan ini berarti Anda tidak perlu bangun terlalu pagi untuk mempelajari kanji sekarang.' WHERE id = 'c0157a8e-c3c9-4fef-85ab-032dee84d1e1'; -- 朝 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti membeli jadi bentuk kata kerjanya adalah to buy.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Jika Anda ingat pembacaan kanji Anda, Anda akan baik-baik saja.' WHERE id = '4c5c4174-2796-4356-b09a-58d4be585f39'; -- 買う (vocabulary)
UPDATE items SET meaning_mnemonic = 'jalan yang Anda jalani adalah trotoar... setidaknya saya berharap di situlah Anda berjalan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7878f9f9-1791-485e-b86b-dd6e7c7c6af8'; -- 歩道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Pembacaannya juga sama dengan kanji yang Anda pelajari, sehingga mudah dipelajari!' WHERE id = 'c700de8e-0dc8-4c83-aa28-a7a8d7c363c1'; -- 楽 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti membuka dan versi kosakata kata kerjanya adalah membuka sesuatu.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda pergi untuk membuka pintu. Ketika Anda melakukannya, teriakan keras keluar: "AAAHHH!" (あ). Bayangkan karakter あ raksasa terbang keluar dari pintu yang Anda buka juga.' WHERE id = '2552342f-37be-441a-a90e-668e48500c3b'; -- 開ける (vocabulary)
UPDATE items SET meaning_mnemonic = 'bisnis dari industri adalah... yah... industri.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e7a19b5d-5c5a-4daf-b23a-e914661001d1'; -- 工業 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Pikirkan tentang sebuah lagu... tapi bukan sembarang lagu... pikirkan tentang lagu yang diucapkan (うた), dan buatlah lagu itu sekarang juga dan nyanyikan dengan lantang. Seperti apa suara lagu aslinya? Mengapa Anda sangat menyukai ucapan sehingga Anda membuat lagu tentangnya?' WHERE id = '4c59262b-3efa-40f0-8814-d1bed297cefc'; -- 歌 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Bayangkan saja orang tuamu berkata oh yah (おや) berulang kali kepadamu. Apa yang kamu lakukan di sekolah hari ini? Aku memukuli anak ini. "Oh ya?"' WHERE id = '9beb60b5-e175-4d06-9993-a7b8ae2e78c4'; -- 親 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 飲む adalah minuman, jadi ini ada hubungannya dengan minuming. Selain itu, 会 berarti bertemu, jadi ketika Anda bertemu untuk minum, Anda berkumpul dengan orang lain untuk minum. Ini adalah pesta minum!', reading_mnemonic = 'Bacaannya berasal dari kosakata 飲む dan bacaan kanji biasa untuk 会. Semoga Anda sekarang sudah mengetahui keduanya sehingga bisa menerapkannya dalam bacaan kata ini juga!' WHERE id = '7ec1c297-4df5-4c7e-8caf-32fba45d1084'; -- 飲み会 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tahun baru adalah tahun baru. Semoga Anda pernah/memiliki/sedang mengalami hal yang baik, tergantung kapan Anda membaca ini.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '0d32e8b8-8e63-4730-9a9b-dc7d277b72ba'; -- 新年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'khusus kualitas Anda adalah karakteristik atau sifat Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '5be30d12-b34d-4c65-80e2-89346314b4e2'; -- 特質 (vocabulary)
UPDATE items SET meaning_mnemonic = 'ide yang lihat di kepala Anda adalah opini Anda. Seperti yang pernah dikatakan pria itu... "Itu seperti, 意見 milikmu, kawan."', reading_mnemonic = 'Pembacaannya semua on''yomi, artinya 意 baik-baik saja. On''yomi (けん) 見 adalah bacaan yang tidak Anda pelajari dengan kanji karena kurang berguna, tetapi Anda harus mengetahuinya di sini. Anda pernah melihatnya dengan 発見 beberapa level yang lalu, jadi itu akan membantu. Namun, berikut ini mnemonik untuk membantu Anda mengingat:

Dalam hal ini, coba pikirkan bagaimana Ken sang samurai mempunyai opini dalam segala hal. Ken adalah orang yang sok tahu segalanya, dan sebaiknya Anda menyetujui pendapatnya. Bagaimanapun juga, dia seorang samurai!' WHERE id = 'daf04002-788d-41ff-ab91-c0b3f42cbe07'; -- 意見 (vocabulary)
UPDATE items SET meaning_mnemonic = 'rasa dari sebuah ide, apakah itu? Bayangkan diri Anda menjilat sebuah ide untuk mencari tahu seperti apa rasanya. Menurut Anda apa yang akan Anda cicipi? Mungkin arti dari ide tersebut.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7b778269-1b0c-47b9-955d-de21f441eea6'; -- 意味 (vocabulary)
UPDATE items SET meaning_mnemonic = 'pagi matahari bukan hanya matahari pagi, tapi juga matahari terbit (karena saat itulah matahari terbit, bukan?).', reading_mnemonic = 'Kata ini menggunakan pembacaan kun''yomi untuk kedua kanji, yang berguna karena Anda sudah mempelajari keduanya sekarang dengan kata 朝 (あさ) dan 日 (ひ). Gabungkan semuanya dan apa yang Anda dapatkan? あさひ!' WHERE id = '2c9dd4ff-b049-4642-b96c-8c1808b6d9df'; -- 朝日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'biaya untuk memasukike gedung publik adalah biaya masuk. Harus membayarnya jika Anda ingin masuk ke dalam.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '70a05f50-1b16-456a-9a6e-3f4fa016fa32'; -- 入館料 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mudah-mudahan kamu pernah melihat 映画 di level 13. gedung publik untuk film (映画) adalah bioskop.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '0b725f55-29d9-4232-a3ca-63339e2162c0'; -- 映画館 (vocabulary)
UPDATE items SET meaning_mnemonic = 'perak warna hanyalah perak (warna).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '0fd3ea6d-1c65-4e0c-a8b0-a5a63ef73ab2'; -- 銀色 (vocabulary)
