UPDATE items SET meaning_mnemonic = 'topik yang sedang kita bicarakanadalah topik yang sedang kita bicarakan. Itu adalah subjek percakapan kita.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '278e5ff6-e3ba-451e-a25d-ce1cc6da5775'; -- 話題 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Artinya sama dengan kanji. Saat Anda berdiri dan minum, Anda berdiri dan minum. Atau memang, minum sambil berdiri.', reading_mnemonic = 'Bacaannya diambil dari kata 立つ dan 飲む yang disatukan.' WHERE id = '8e62b6b8-8174-46d7-8c7d-cb466065d2b1'; -- 立ち飲み (vocabulary)
UPDATE items SET meaning_mnemonic = 'tsunami menghantam Tiongkok kuno dan membentuk negara Tiongkok yang sekarang kita kenal sebagai... Tiongkok!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Cina** (漢), bayangkan Anda sedang membawa **Kancil/Kantor** untuk ditaruh di atas cina. Kejadian unik ini mengingatkan Anda pada bunyi **かん**!' WHERE id = 'b42f7713-8e9f-4404-947e-da6a8b8b15ea'; -- 漢 (kanji)
UPDATE items SET meaning_mnemonic = 'siang makanan adalah makanan yang Anda makan pada siang hari. Makanan apa itu? Ini makan siang yang lezat dan lezat.', reading_mnemonic = 'Bacaannya berasal dari kata 昼 dan ご飯. Jika Anda tahu cara membaca kata-kata itu, Anda juga bisa membaca kata ini.' WHERE id = 'fcf7291c-f131-4085-8b1e-c995d68fdc45'; -- 昼ご飯 (vocabulary)
UPDATE items SET meaning_mnemonic = 'hari kerja hari adalah hari dalam seminggu, seperti dalam "Senin" atau "Selasa". Anda akan mempelajarinya di level 18, namun pertama-tama Anda harus mempelajari 曜日 agar Anda siap.', reading_mnemonic = 'Kata ini menggunakan bacaan on''yomi untuk 曜 dan bacaan kun''yomi untuk 日. Anda sudah mempelajari keduanya, tapi hati-hati karena ひ dari 日 berubah menjadi び di sini.' WHERE id = '537d486f-6d70-4838-9766-de3165c4102f'; -- 曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda ingin mengatakan sesuatu di upacara untuk pekerja konstruksi Anda harus berusaha dengan sangat keras. Konstruksinya keras, jadi jika Anda ingin didengar, Anda harus mencoba untuk lebih keras daripada mengebor, menghancurkan, menggali, dan membagikan penghargaan.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Coba** (試), bayangkan Anda sedang membawa **Singa/Silet** untuk ditaruh di atas coba. Kejadian unik ini mengingatkan Anda pada bunyi **し**!' WHERE id = 'a26ace0c-d99d-4484-89e9-d8088364d42e'; -- 試 (kanji)
UPDATE items SET meaning_mnemonic = 'Seseorang yang tidak memiliki "tidak ada" untuk nama-nya sedang mencoba untuk tetap anonymous atau hanya unknown.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '8017ff65-7b70-4d0f-9c56-32a4ffa1fed3'; -- 無名 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat kata 楽しい, yang artinya "menyenangkan". Ini jelas terlihat sangat mirip, meskipun yang ini berarti menanti-nantikan. Mengapa? Karena ada み di akhir yang berbunyi "siapa yang akan bersenang-senang? Ini saya! Itu sebabnya saya menantikannya!"', reading_mnemonic = 'Bacaannya seperti 楽しい, jadi pastikan Anda mengetahuinya dan Anda juga bisa membaca yang ini.' WHERE id = '1bf96550-ff5a-484b-922d-9c0322a9ec2e'; -- 楽しみ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari pohon dalam seminggu adalah Kamis. Hari pohon datang setelah hari air (yaitu hari Rabu, untuk Hari Air-Rabu!). Pohon membutuhkan air untuk tumbuh, itulah sebabnya pohon muncul tepat setelah air.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = '86d22caa-cd5c-4364-8d59-914b5394baf8'; -- 木曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Silakan mencoba dan makan. Bagaimana percobaan kecil itu? contoh kecil itu? rasa kecil itu?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '5d64171f-493f-4f9b-9c13-68ac88e2f2c0'; -- 試食 (vocabulary)
