UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Membacanya sama dengan yang Anda pelajari dengan kanji.' WHERE id = '8eebdac1-d2d0-49cb-9d1b-e10eb719c51f'; -- 質 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kualitas masalah bernilai pertanyaan. Namun masalah kualitas rendah... jangan ajukan pertanyaan. Lagipula, ada pertanyaan-pertanyaan bodoh.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f7155bac-c45d-42a6-a50c-6257822b7f57'; -- 質問 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kualitas suatu produk terletak pada kualitas material-nya. Jika bahannya tidak bagus maka produknya juga tidak bagus.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '74da44fc-b05f-4346-9624-a1d84581695e'; -- 品質 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika pinjaman telah dipotong, berarti item tersebut telah dipesan.', reading_mnemonic = 'Ini adalah pembacaan 貸す dan 切る yang digabungkan. Ketahuilah kedua bacaan itu dan Anda juga mengetahui yang ini. Terkadang Anda akan melihat kata ini sebagai 貸切り atau 貸切 juga.' WHERE id = '60594531-65ba-4412-93eb-decf7315c968'; -- 貸し切り (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda memiliki sebuah ide, itu berarti Anda penting. Anda memiliki signifikansi. Mereka yang tidak punya ide hanyalah lelucon besar dan tidak bisa berbuat apa-apa.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'f0d873bd-f654-49af-86da-510ec87dc5fb'; -- 有意 (vocabulary)
UPDATE items SET meaning_mnemonic = 'HurufCina... Anda akhirnya mempelajari kata untuk mereka, hal yang telah Anda pelajari selama ini sejak lama! Ini adalah kanji, sahabat baru Anda (berasal dari Tiongkok, itulah sebabnya hurufnya berbahasa Mandarin).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '45f0c2e0-59a0-4662-b706-ed56b87cad9f'; -- 漢字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Setiap pagi adalah setiap pagi!', reading_mnemonic = 'Bacaannya merupakan gabungan on''yomi dan kun''yomi. Meskipun demikian, kedua bacaan untuk kedua kanji tersebut adalah bacaan yang Anda pelajari dengan kanji tersebut sehingga Anda harus bisa membaca ini.' WHERE id = 'a99a47a3-3e69-488f-8996-210ed163848e'; -- 毎朝 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari kanji berkumpul, jadi artinya berkumpul.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda sudah mempelajari bacaan ini jadi Anda harus bisa membacanya!' WHERE id = 'd2e578b6-a899-48c6-9ad8-24de966a694f'; -- 集まり (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 運動 berarti "olahraga?" Saat Anda bertemu dengan sekelompok orang untuk berolahraga, ini disebut Hari Olahraga! Ini adalah hari di sekolah-sekolah di Jepang di mana semua orang melakukan aktivitas fisik bersama! Menyenangkan dan juga sangat melelahkan!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '8b6527bf-5460-4984-805a-48e4425b7535'; -- 運動会 (vocabulary)
UPDATE items SET meaning_mnemonic = 'sesuatu yang Anda minum adalah minuman.', reading_mnemonic = 'Keduanya adalah bacaan kun''yomi. Anda sudah mempelajarinya, jadi Anda sudah tahu cara membaca kata ini!' WHERE id = '5a43e1e6-cd52-455d-85e0-6af46b1db363'; -- 飲み物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Air pakaian adalah baju renang, baju renang, atau pakaian renang.', reading_mnemonic = 'Bacaan yang satu ini seluruhnya adalah bacaan kosakata kun''yomi, namun Anda harus mengetahuinya sekarang. 着 menggunakan bacaan yang Anda pelajari dengan kata kosakata 着る, tetapi kata ini menggunakan rendaku yang mengganggu, jadi ingatlah bahwa き menjadi ぎ di sini.' WHERE id = 'a28cd40a-2dcd-4b9a-a96d-e46f8f3c9400'; -- 水着 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Meminjamkan adalah 貸す. Ini adalah versi kata benda. Itu adalah sesuatu yang telah disewa, sebuah rental.', reading_mnemonic = 'Bacaannya sama dengan 貸す.' WHERE id = 'de8247b6-04cb-4be4-8bc3-ad2fbe4b3e09'; -- 貸し (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 運転 ada hubungannya dengan mengemudi, bukan? Dan tahukah Anda bahwa 手 sering kali berkaitan dengan seseorang yang melakukan sesuatu dengan kata-kata seperti ini. Jadi, orang yang mengemudikan mobil itu apa? driver.', reading_mnemonic = 'Pembacaannya semua on''yomi, karena ini jukugo. Anda seharusnya sudah mengetahui pembacaan on''yomi 手 sekarang hanya dengan melihat pola kata yang mirip dengan ini.' WHERE id = '355dc7b8-dfa5-4679-86a3-cfbee5b9dc29'; -- 運転手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang idenyanya dibumikandi dalam kejahatan adalah jahat, jahat brengsek!', reading_mnemonic = 'Bacaan ini merupakan gabungan dari bacaan on''yomi untuk 意 dan 地, serta bacaan kun''yomi untuk 悪. Anda sudah mempelajari semuanya, jadi ini pasti kue!' WHERE id = '3ac6439d-d92f-4c27-a866-e6a2d60a1775'; -- 意地悪 (vocabulary)
UPDATE items SET meaning_mnemonic = 'yang sebenarnya kualitas dari sesuatu adalah esensi, atau sifat sebenarnya. Entah itu baik atau buruk, itu lain cerita.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '531a9bca-6dcf-4edc-a63d-fc70af69451a'; -- 本質 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya anti.

Kalau-kalau Anda tidak mengingatnya, inilah arti mnemonik kanjinya: bangku ada di tebing. Jika seseorang memiliki bangku jauh di dalam tebing, kemungkinan besar mereka adalah masyarakat yang cukup anti, bersembunyi seperti itu.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '71df06c3-f0a4-46c0-9cc3-c5293a586479'; -- 反 (radical)
UPDATE items SET meaning_mnemonic = 'yang baru mendengar adalah seperti apa bunyinya. Ini adalah hal-hal baru yang Anda dengar di telinga Anda... setidaknya itulah yang terjadi di masa lalu. Sekarang hal-hal baru yang sampai ke telinga Anda sampai kepada Anda melalui media lain. Dalam hal ini, surat kabar.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fc415fa8-70d2-4137-9a95-b36eb5f43f42'; -- 新聞 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Persediaan teh habis tidak ada??? Itu tidak masuk akal! Bagi orang Amerika, saya membayangkan kata ini adalah "無コーヒー" sebagai gantinya. Mengerti?? Jika Anda seorang pecandu kafein, kata ini sangat masuk akal.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '84cc504b-e05e-4779-b374-fedec3b18524'; -- 無茶 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari Minggu dalam seminggu adalah Minggu. Tidak ada yang lebih mudah dari itu bagi Anda. Beruntung!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = '2d276e24-3b4e-4dd2-8c0c-4bc374749726'; -- 日曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda tidak punya apa-apa untuk diucapkan, Anda duduk dalam hening.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda tidak mempelajari bacaan ini untuk 言, jadi inilah mnemonik untuk membantu Anda:

Tidak ada yang bisa menembus silence seperti gong (ごん). Setelah gonging selesai, Anda benar-benar menyadari betapa sunyinya dunia di sekitar Anda.' WHERE id = '1216d478-f8ec-47d6-9976-4ef4cbbc39d1'; -- 無言 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti lagu jadi versi kosakata kata kerjanya adalah menyanyi, karena Anda tidak "menyanyi", Anda "menyanyi".', reading_mnemonic = 'Hebatnya, bacaan ini menggunakan bacaan yang sama dengan bacaan kosakata 歌. Lempar saja う ke bagian akhir dan Anda sendiri yang membacanya. Jadi, bernyanyilah sepuasnya dan pelajari kata ini dengan mudah. "IIIiiiIIIiiiIII AKAN SELALUYYYs Loovvve YoOooOOooooOOOO ♬!"' WHERE id = 'da1ef08e-2d0a-405a-ba7b-85f8a6caecbf'; -- 歌う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari kebakaran dalam seminggu adalah hari setelah hari terburuk dalam seminggu (Senin). Kamu membakar segalanya karena kamu sangat kesal dengan hari kemarin, sehingga menjadikan hari ini Selasa.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = '7c4f0978-0843-4ad4-bb6c-c97b91b947d2'; -- 火曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sebuah gedung publik tempat tertulisn segala sesuatu diagram dibuat sedemikian rupa sehingga Anda dapat menemukan hal-hal tertulis tersebut? Kedengarannya seperti perpustakaan bagi saya!', reading_mnemonic = 'Bagian 書館 seharusnya dapat Anda baca, tetapi bagian 図-lah yang menyusahkan dengan pembacaan alternatif dari yang Anda pelajari. Bayangkan diri Anda berada di perpustakaan. Anda membaca setiap buku tentang jari kaki manusia (と). Anda mempunyai setumpuk besar buku di atasnya, lalu Anda menjatuhkannya... ironisnya di jari kaki Anda. Anda memutuskan untuk menunjukkan kepada Khan (teman Anda) jari kaki Anda yang patah.' WHERE id = '95e44842-9883-4d18-a5e4-75f436d86c56'; -- 図書館 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda memiliki sayap, terbang menuju matahari akan mudah. Jika Anda mencoba mencapainya dengan tubuh manusia tak bersayap, hal itu tidak akan mudah.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '78825fc7-930a-4d0e-8bc0-de73d69225bc'; -- 易 (radical)
UPDATE items SET meaning_mnemonic = 'Ada beberapa tanduk di tanah yang Anda inginkan untuk diri Anda sendiri. Anda mengambilnya dan menempelkannya ke leher Anda. Bayangkan tanduk ini mencuat di leher Anda. Tidak ada yang bisa menggorok leher Anda sekarang karena leher Anda terlindungi.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '92401ce3-8e61-4965-8125-0df48bb89b45'; -- 首 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya suara.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '525ed076-9b58-44e5-bf90-7724be757837'; -- 音 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Paku". Perhatikan bentuk karakter "[Paku]" dan asosiasikan bentuk goresannya dengan "paku".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '58fb8b39-add1-4932-bd23-21df7b429307'; -- [Paku] (radical)
UPDATE items SET meaning_mnemonic = 'Jika matahari terbit dan Anda menginjak tanah, Anda akan mencapai akar. Akar mencoba muncul saat matahari cerah. Namun jika Anda menendang terlalu keras, akarnya akan membuat Anda tersandung, jadi berhati-hatilah!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '00e4c5c0-fe1d-4da5-9eff-2ffca2476eba'; -- 艮 (radical)
UPDATE items SET meaning_mnemonic = 'Jangan bingung antara radikal ini dengan radikal burung 鳥. Kelihatannya mirip, dengan sayap di bawah dan bentuk di atas, namun tidak ada bulu yang mencuat di atas kepalanya serta memiliki leher yang panjang dan tebal. Jadi meskipun ia bergerak cepat seperti memiliki sayap, ia bukanlah burung, melainkan kuda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '42fb8b31-1af3-4813-95c8-f301f276b00a'; -- 馬 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Beruang". Perhatikan bentuk karakter "[Beruang]" dan asosiasikan bentuk goresannya dengan "beruang".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '27b3db4c-725f-4b5d-89aa-a0cd19804293'; -- [Beruang] (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terdiri dari kerang dengan daun di atasnya. Apa itu? geoduck yang misterius. Ini adalah makhluk mirip kerang yang sangat berbeda. Jika Anda tidak tahu apa itu geoduck, carilah. Ini cukup aneh. Ia mempunyai tonjolan panjang berbentuk daun yang keluar dari badan cangkangnya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'add2c0f2-3ff1-4c1f-8f22-c10340296768'; -- 頁 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah jaring, yang tersebar di atas air. Bayangkan semua ikan yang bisa Anda tangkap di jaring ini!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0a73a5bd-d9eb-43e9-b831-e4f0da5ba54a'; -- 罒 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Cumi-cumi". Perhatikan bentuk karakter "[Cumi]" dan asosiasikan bentuk goresannya dengan "cumi-cumi".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'b206c040-2051-490a-81b2-0757993e22b0'; -- [Cumi] (radical)
UPDATE items SET meaning_mnemonic = 'Ketika sesuatu publik terbuka maka itu adalah terbuka untuk umum. Anda dapat melihat hal-hal yang 公開. Anda juga dapat menggunakan ini saat Anda merilis sesuatu ke publik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '86167b09-aba3-4e31-81a6-271be2d832cc'; -- 公開 (vocabulary)
UPDATE items SET meaning_mnemonic = 'ikan toko adalah toko ikan, tempat Anda membeli ikan. Khususnya di Jepang, sangat penting.', reading_mnemonic = 'Pembacaan kun''yomi digunakan untuk 魚 (jadi さかな) dan pembacaan kun''yomi digunakan untuk 屋 (や). Anda harus menggunakan bacaan 魚 dari kosakata beberapa level yang lalu untuk mengingat bacaan yang satu ini.' WHERE id = 'f2b05d2a-466f-4095-923e-be3b51cb6fe8'; -- 魚屋 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari baru? Ini baru.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Keluargamu membelikanmu Atari baru! Kamu sangat bersemangat! Tapi tunggu... apa ini? Ini bukan Atari. Ini adalah Atara... sistem video game tiruan :(' WHERE id = '5c22f6ca-ad27-4e4d-96ad-e3e7e87dafa2'; -- 新しい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sekarang pagi hanyalah cara lain untuk mengucapkan pagi ini. Ini adalah pagi yang paling dekat dengan saat ini!', reading_mnemonic = 'Bacaan ini merupakan pengecualian. Mari gunakan mnemonik ini untuk mengingatnya:

Pagi ini Anda ingin quesadilla (けさ) untuk sarapan. Anda tidak bisa menunggu sampai besok pagi, Anda MEMBUTUHKANnya pagi ini! Bayangkan makan quesadilla yang lezat pagi ini. Hmm!' WHERE id = 'ef85402c-abb4-466d-af54-e2b66c17baba'; -- 今朝 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Untuk penerimaan sekolah (入学) Anda mengikuti ujian (試験). Ujian apa yang harus Anda ambil untuk masuk ke sekolah? Bagaimana dengan ujian masuk? Yang Jepang cukup sulit. Kata lain untuk mereka adalah “ujian neraka”.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Ini juga akan membantu jika Anda mengetahui dua kata terpisah yang membentuk kata yang lebih panjang ini.' WHERE id = '3cae6aab-6142-470b-bf5a-491b4d3b06bc'; -- 入学試験 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti mencoba atau mencoba. Versi kosakata kata kerjanya adalah mencoba sesuatu atau mencoba sesuatu. Mengapa Anda tidak mencoba arti dari kata kerja ini, selagi Anda melakukannya?', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajarinya dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: Oke. Inilah kesepakatannya. Kami memiliki hewan liar ini. Saya ingin Anda mencoba menjinakkan (ため) itu. Sekarang, bayangkan mencoba menjinakkan hewan liar ini. Ya ampun!' WHERE id = 'd03c4453-9cce-40e8-80f3-c127f82ac8b1'; -- 試す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini mengambil arti keberuntungan dari kanji. Anggap saja seperti ini: Jika Anda "membawa", Anda akan menciptakan keberuntungan Anda sendiri. Sekarang tidak ada yang akan macam-macam denganmu, kanji gangstah. Anda membawa senjata dan mendapatkan banyak keberuntungan karenanya.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji! Bagaimana... haruskah saya katakan... penuh dengan keberuntungan?' WHERE id = '0b9dfb3d-2656-4a8b-a355-95857788b072'; -- 運 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kemungkinan besar, orang tua Anda sangat dekat dengan Anda. Mereka adalah kerabat terdekat Anda. Merekalah yang intim dan ramah dengan urusan Anda. Mereka ingin tahu segalanya!', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Mereka yang paling intim dengan Anda bergaul dengan Anda bahkan ketika Anda sedang melakukan hal-hal kotor, seperti duduk di atas kasur (した). Kotor, keluargamu.' WHERE id = '096b0f44-a141-4989-bb6a-4d55695ce6ea'; -- 親しい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata sifat dari kanji baru, jadi artinya new juga.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Orang tuamu meletakkan hadiah yang baru dibungkus di bawah pohon Natal. Anda tentu tidak ingin menunggu untuk melihat hal baru apa yang mereka berikan kepada Anda sehingga Anda membukanya dan menemukan mereka memberi Anda steak mentah (あら). Mendapatkan steak baru memang keren, tetapi steak mentah cukup menjijikkan. Darahnya menetes ke mana-mana.' WHERE id = 'cbdeb3bb-132a-4106-a67b-ba8dc7373c89'; -- 新た (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu 晩ご飯 itu "makan malam"? Ya, kata itu benar 12 jam yang lalu. Ini adalah pagi hari dan pagi makanan Anda adalah sarapan.', reading_mnemonic = 'Bacaannya adalah yang Anda pelajari dengan kanji. Ini juga seperti vocabnya: 朝 seperti versi vocabnya, あさ dan ご飯 seperti kata yang Anda pelajari, ごはん.' WHERE id = '5f84d8f7-d003-4eb7-bbd3-560864765a79'; -- 朝ご飯 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari air dalam seminggu adalah tempat air mengalir. Bayangkan seluruh minggu Anda sebagai sebuah bukit besar, dengan hari Rabu (hari punuk) berada di tengah-tengahnya. Punuk ini adalah sebuah bukit. Apa yang berasal dari bukit? Air! Itu sebabnya Hari Air jatuh pada Rabu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = '43f62f24-f58e-4998-8b4f-14d48f0a2e7c'; -- 水曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Pada akar dari emas, terdapat perak. Emas pada dasarnya hanyalah perak yang naik levelnya. Itu sebabnya emas menempati urutan pertama, dan perak menempati urutan kedua. Jika Anda menggaruk emas dengan baik, Anda akan menemukan bahwa pada akarnya, ada perak yang tersembunyi di bawahnya.', reading_mnemonic = 'Tahukah Anda bahwa **Perak** (銀) ini sebenarnya dibuat dari tumpukan **Gasing/Gigi**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **ぎん**.' WHERE id = 'a21cc683-fea2-4efe-b5f8-8ffaf2802b7b'; -- 銀 (kanji)
UPDATE items SET meaning_mnemonic = 'Tanda ご membuat kata ini lebih sopan dan mewah. Ketika berbicara tentang makanan, menyenangkan untuk melakukan hal-hal itu. Kata ini memiliki arti yang sama dengan kanji (makanan) yang menjadikannya makanan, namun juga mengacu pada nasi yang dimasak. Jadi, "Ayo makan ご飯mu" bisa berarti "ayo makan nasimu" dan "ayo makan makananmu". Sebenarnya, karena sebagian besar makanan Jepang disajikan dengan nasi, Anda bisa melihat bagaimana tumpang tindihnya terjadi.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Sekarang bagaimana kalau kamu "memberiku" semangkuk nasi lagi?' WHERE id = 'cb688c12-b70b-4a43-85dc-c42c3b75621c'; -- ご飯 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada bola mata di atas beberapa kaki. Ketika mata Anda tertuju pada suatu tempat (dalam hal ini pada kaki), mata Anda melihat hal-hal tersebut. Itu sebabnya cara radikal ini lihat.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6cb70e07-7631-41f2-814c-6db231f546d0'; -- 見 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari "bulan" dalam seminggu adalah senin. Mengapa? Karena "Bulan" sebenarnya hanyalah "Senin", bukan?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = '65e5bc50-59df-4d79-a8d7-61b00c2dc2c6'; -- 月曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini sulit, karena ada kata lain di level ini (着る) yang artinya "memakai" yang sangat mirip. Namun kata ini berarti tiba. Anda seharusnya sudah melihat makna itu dengan kanji 着 juga, jadi saya harap ini membantu. Namun, untuk membedakan antara ini dan 着る, perbesar く. Anda ingin menjadi kerenl (く) sehingga Anda terlambat datang ke pesta.', reading_mnemonic = 'Ini menggunakan pembacaan kun''yomi yang berbeda dari yang baru saja Anda pelajari (maaf). Untuk membantu Anda, pikirkan hal ini:

Anda ingin tiba tepat waktu tetapi Anda datang terlambat. Seberapa terlambat kamu? Tepatnya terlambat dua (つ) jam dua menit.' WHERE id = 'a531f364-0557-4217-b9dc-f55167a4f554'; -- 着く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti mencoba sehingga versi kosakata kata kerjanya adalah to try to do Something atau to try Something.

Kata kerja ini bersifat transitif, artinya mengambil objek langsung. Di sini, objek langsungnya adalah apa pun yang Anda coba lakukan.', reading_mnemonic = 'Tahukah Anda bagaimana ketika Anda mencoba melakukan sesuatu, Anda mengerahkan seluruh hati Anda ke dalamnya? Nah, pikirkan itu dalam bahasa Jepang. Anda memasukkan seluruh 心 (こころ) ke dalamnya.' WHERE id = 'ea357904-909e-4d6f-ac72-20231957a932'; -- 試みる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada seseorang di penjara. Mengapa orang ini dipenjara? Karena mereka kekurangan hal-hal yang dibutuhkan manusia untuk berada di dekat manusia lain. Jika Anda kekurangan sesuatu (kebaikan, pengendalian diri, dll.), Anda mungkin melakukan sesuatu yang membuat orang lain memenjarakan Anda. Berusahalah untuk memperbaiki kekuranganmu agar hal ini tidak menimpamu.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '24b92233-3a6c-4990-895c-9758ec1da1ee'; -- 欠 (radical)
UPDATE items SET meaning_mnemonic = 'Ini menyenangkan. Air perak adalah merkuri, yang sangat masuk akal. Merkuri berbentuk cair seperti air, tetapi seluruhnya berwarna perak seperti perak. Jadi air perak bukanlah air mineral baru yang bisa Anda dapatkan seharga $4 di toko, melainkan merkuri! Atau quicksilver, jika Anda mau.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '525208c8-6c04-4d61-9868-8abce7b72c74'; -- 水銀 (vocabulary)
UPDATE items SET meaning_mnemonic = 'teman yang seperti salah satu orang tua Anda adalah seseorang yang akan menjaga Anda. Faktanya, mereka sudah seperti keluarga! Itu sebabnya kata ini berarti sahabat atau sahabat dekat. Bayangkan saja seseorang yang mengawasi Anda seperti halnya orang tua. Ini adalah cara untuk menggambarkannya.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '001fe173-bf64-44b2-b0e1-5301202637e6'; -- 親友 (vocabulary)
UPDATE items SET meaning_mnemonic = 'stasiun depan adalah depan stasiun. Omong-omong, kata ini bagus untuk memberi tahu orang-orang di mana Anda ingin bertemu.', reading_mnemonic = 'Ini seperti dua kata terpisah yang disatukan menjadi satu, jadi bisa dibayangkan itulah bacaan kun''yomi. Anda telah mempelajari cara membaca 駅 yang benar dalam kanji, dan Anda seharusnya sudah mengetahui kosakata 前 sekarang. Gabungkan keduanya dan Anda akan mendapatkan di depan stasiun.' WHERE id = '6187031c-6840-479f-9cd5-9868f7d52e02'; -- 駅前 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya pengganti.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9ef0aa3b-ae90-483d-aee3-d236ea567ee1'; -- 代 (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini menggunakan 長 dengan cara yang sama seperti 社長, yang artinya seperti "bos" atau "manajer". Jadi, 長 ini adalah bos dari stasiun, kan? Apa yang kamu sebut orang seperti itu? Anda menyebut mereka stationmaster (kecuali jika Anda ingin dilempar ke kereta).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3a2a8f68-62a9-434e-a132-9204ac16c7bc'; -- 駅長 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda bisa makan sepuasnya, namun Anda masih kekurangan sesuatu untuk minum. Anda tidak bisa hidup hanya dengan makan, Anda juga harus minum!', reading_mnemonic = 'Tahukah Anda bahwa **Minum** (飲) ini sebenarnya dibuat dari tumpukan **Noda**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **の**.' WHERE id = 'c7ad89de-5bd3-4cda-973d-2fe9b9bbd084'; -- 飲 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti menjawab jadi versi verbanya berarti menjawab.', reading_mnemonic = 'Bacaannya adalah bacaan kun''yomi seperti yang Anda harapkan dengan semua hiragana, tapi untungnya itu adalah bacaan yang Anda pelajari dengan kanji jadi Anda seharusnya bisa membaca ini.' WHERE id = 'dc3ef421-18f2-40b2-a668-a7e35743d07f'; -- 答える (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti minum sehingga versi vocab verbanya adalah to drink.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Pergilah minum atas nama Allicrab yang agung!' WHERE id = '23eba982-99dc-4d34-854b-b0beef6cd7c0'; -- 飲む (vocabulary)
UPDATE items SET meaning_mnemonic = 'konstruksi lokasi adalah pabrik. Pabrik adalah tempat di mana Anda atau mesin melakukan banyak konstruksi!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '1acf32de-b889-464e-9416-1b2fc2a12ea3'; -- 工場 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda melihat sebuah pohon yang ingin Anda berdiri di bawahnya untuk beristirahat saat mendaki, orang tua yang baik akan berdiri di bawah pohon bersama Anda. Ini adalah orang tua yang baik dan perhatian yang dapat melihat bahwa Anda lelah dan ingin bersantai dengan berdiri di bawah naungan pohon ini.', reading_mnemonic = 'Ketika Anda sedang melihat **Induk** (親), tiba-tiba muncul sesosok **Shin-chan/Singa** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **しん**.' WHERE id = '3956736e-d1d0-4b6f-9dce-3e0f4caeb275'; -- 親 (kanji)
UPDATE items SET meaning_mnemonic = 'ayah orang tua Anda adalah ayah Anda.', reading_mnemonic = 'Pembacaan di sini cukup aneh. Itu semua kun''yomi. Dugaan saya ini diterjemahkan secara harfiah menjadi "ayah orang tua" (dua kata yang berbeda, oleh karena itu menggunakan bacaan yang lain). Namun, Anda harus mengetahui bacaan dari dua kata terpisah ini. Yaitu 父 (ちち) dan 親 (おや).' WHERE id = '92f095fc-ae6f-463a-b621-afe6d54e1c6a'; -- 父親 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda menggunakan matahari, Anda dapat menemukan yang benar geoduck. Itulah topik kuliah hari ini.', reading_mnemonic = 'Bagaimana cara membaca kanji **Topik** (題)? Ingat saja bahwa **Dadu/Dahi** sangat menyukai topik! Hubungan erat ini akan membantu Anda mengingat bunyi **だい**.' WHERE id = '8858f6c5-587c-426d-b948-a106c31748ef'; -- 題 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda mengejar kalkun ke atas pohon untuk mengumpulkan itu. Setidaknya, Anda akan mengumpulkancukup banyak kalkun di satu pohon ini.', reading_mnemonic = 'Bagaimana cara membaca kanji **Kumpulkan** (集)? Ingat saja bahwa **Susu/Sumpit** sangat menyukai kumpulkan! Hubungan erat ini akan membantu Anda mengingat bunyi **しゅう**.' WHERE id = '9e16675c-c30f-408b-87c7-90ffd2ce7aee'; -- 集 (kanji)
UPDATE items SET meaning_mnemonic = 'Seekor kuda dan cumi-cumi sedang menjalani tes.', reading_mnemonic = 'Bagaimana cara membaca kanji **Tes** (験)? Ingat saja bahwa **Kendi/Kencir** sangat menyukai tes! Hubungan erat ini akan membantu Anda mengingat bunyi **けん**.' WHERE id = 'c686146c-ca8b-45ee-ba89-8ccf3cbb8ec8'; -- 験 (kanji)
UPDATE items SET meaning_mnemonic = 'Kotoran memudahkan mudah mengidentifikasi lokasi Anda. Jika Anda mengetahuinya, Anda bisa berpindah dari tempat ke tempat lain.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Lokasi** (場), bayangkan Anda sedang membawa **Joni/Jenderal** untuk ditaruh di atas lokasi. Kejadian unik ini mengingatkan Anda pada bunyi **じょう**!' WHERE id = 'c786e4af-48e8-4569-acee-32a37cbc5e8a'; -- 場 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda sekarang buka untuk keberangkatan. Anda naik perahu dan meninggalkan tempat ini. Anda akan pergi ke tempat lain untuk memulai pengembangan di mana Anda akan menciptakan dunia baru.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f14007cf-e12a-434f-a393-48c45922b3d9'; -- 開発 (vocabulary)
UPDATE items SET meaning_mnemonic = 'gerbang dengan lentera terbuka untuk Anda. Itu nyaman, karena di luar cukup gelap dan Anda mungkin tidak akan melihat gerbang yang terbuka tanpa bantuan lentera.', reading_mnemonic = 'Bagaimana cara membaca kanji **Buka** (開)? Ingat saja bahwa **Kail/Kain** sangat menyukai buka! Hubungan erat ini akan membantu Anda mengingat bunyi **かい**.' WHERE id = '1d863db0-dce1-4675-99b7-fe2ff8a83bd4'; -- 開 (kanji)
UPDATE items SET meaning_mnemonic = 'lokasi tempat Anda masuk adalah tempat Anda membuat pintu masuk. Ini ada hubungannya dengan hal-hal seperti "biaya masuk" dan "tidak diizinkan masuk", dll.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '18233e59-a6a0-4b8f-9e55-5255ff080eb1'; -- 入場 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda mengumpulkan dan fokus pada tengah. Benar-benar memperbesarnya. Ketika Anda melakukan ini, Anda berkonsentrasi pada titik ini, sehingga membuat arti dari kata berkonsentrasi atau to focus.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '601d8a66-46a7-4c58-bb94-72b0a2cd82af'; -- 集中する (vocabulary)
UPDATE items SET meaning_mnemonic = 'Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti meminjamkan jadi versi kosakata kata kerjanya adalah to lending.', reading_mnemonic = 'Izinkan saya untuk meminjamkan beberapa saran kepada Anda. Pembacaan yang Anda pelajari dari kanji dapat digunakan di sini.' WHERE id = '2077fb59-fb65-4551-a929-df269d8efa71'; -- 貸す (vocabulary)
UPDATE items SET meaning_mnemonic = 'putih es pohon adalah pohon ajaib. Saat Anda memakan bunga esnya, Anda akan mendapatkan kenyamanan, kemudahan, dan kesenangan yang luar biasa.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kenyamanan** (楽), bayangkan Anda sedang membawa **Rak/Rakyat** untuk ditaruh di atas kenyamanan. Kejadian unik ini mengingatkan Anda pada bunyi **らく**!' WHERE id = 'b4f9321a-5247-4750-b429-bbfb0588679a'; -- 楽 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda kekurangan cincin bibir (atau dua dalam hal ini), itu akan memudahkan Anda menyanyikan lagu.', reading_mnemonic = 'Bagaimana cara membaca kanji **Bernyanyi** (歌)? Ingat saja bahwa **Kaki/Kaca** sangat menyukai bernyanyi! Hubungan erat ini akan membantu Anda mengingat bunyi **か**.' WHERE id = '3b8e0019-bc3d-4e1f-a369-f7aa0b3cd865'; -- 歌 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti membawa jadi versi kata kerjanya adalah to carry.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Bayangkan Anda mempunyai untuk membawa seekor elang (はこ). Bayangkan membawanya di tangan Anda. Ia mencoba mencakar dan mematuk dirinya sendiri untuk bebas, namun Anda tidak melepaskannya. Tugas Anda adalah membawa elang ini ke mana pun.' WHERE id = '558dd424-f34d-434e-94d3-62349baa5ea7'; -- 運ぶ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda harus menggunakan dua kapak untuk membuka kerang ini. Tampaknya ini berlebihan, tetapi ini perlu. Kerang khusus ini memiliki kualitas yang sangat tinggi sehingga tidak mudah dibuka.', reading_mnemonic = 'Tahukah Anda bahwa **Kualitas** (質) ini sebenarnya dibuat dari tumpukan **Silet/Singa**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **しつ**.' WHERE id = 'f988c828-230b-4aa1-b963-ed48fe194f50'; -- 質 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Biasanya ini mengacu pada stasiun kereta api tertentu, tetapi bisa juga stasiun apa saja.', reading_mnemonic = 'Kanji di sini menggunakan えき sebagai on''yomi dan kun''yomi, jadi jangan khawatir. Anda dapat pergi ke stasiun ini atau stasiun itu, dan kedua stasiun tersebut akan menggunakan bacaan yang sama sesuai kanji asalnya.' WHERE id = 'ef3a6afb-f68b-4147-a9fb-ca043056789f'; -- 駅 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda dapat menebak ini adalah versi kata benda dari kanji tersebut karena hiragana yang menonjol di dalamnya bukanlah bunyi yang berhubungan dengan う atau bunyi yang berhubungan dengan い. Jadi, apa versi kata benda dari jawaban? Itu juga jawaban.', reading_mnemonic = 'Bacaannya kun''yomi, tapi ini juga bacaan yang kamu pelajari dengan kanji jadi kamu harus bisa membaca ini dan kemudian memberikan 答え dengan benar.' WHERE id = '41741139-6c48-4208-9cc3-7138d78cfe2c'; -- 答え (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda mengumpulkan emas Anda mengumpulkan uang (atau melakukan pengumpulan uang). Tentu saja, pada masa lalu, emas disamakan dengan uang, itulah sebabnya kata ini berfungsi sebagaimana mestinya. Semoga Anda tidak harus berurusan dengan terlalu banyak 集金 dalam kehidupan sehari-hari Anda. Kami akan berusaha menjaga WaniKani tetap bagus dan harga terjangkau untuk Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'cfcab7b8-7d5e-4f5e-880a-ec27cf65cd6b'; -- 集金 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. 

Namun, jangan bingung membedakannya dengan kata 〜道. Yang ini tidak ada 〜 di awal, artinya tidak melekat pada kata lain. Kata ini hanyalah jalan lama. Itu punya arti tersendiri!', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda sedang berjalan di jalan. Di jalan, kamu bertemu dengan temanmu, Mitch (みち). Bayangkan menyapa, lalu melanjutkan perjalanan. Yang aneh adalah Anda berdua berjalan di jalan beraspal dengan banyak mobil di atasnya. Kelihatannya berbahaya, tapi kamu dan Mitch, kamu tahu apa yang kamu lakukan. 

Jika Anda tidak mengenal siapa pun yang bernama Mitch, pikirkan tentang Mitch terkenal atau Mitch yang Anda buat.' WHERE id = '74d4091b-2242-4c8b-b1a9-d3240823e8e0'; -- 道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat orang tuamu memotong kamu, kamu akan mengira mereka jahat... padahal sebenarnya tidak. Mereka mengeluarkan semua darah buruk darimu. Mereka benar-benar baik. 

Coba bayangkan betapa gilanya jika orang tuamu memotongmu... lalu pikirkan semacam perubahan agar mereka bersikap baik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ac60cf3f-1560-49ed-8984-d289426ef045'; -- 親切 (vocabulary)
UPDATE items SET meaning_mnemonic = 'masalah topik adalah masalah atau pertanyaan yang harus Anda jawab. Kalau dipikir-pikir, topik sebagai masalah cenderung berhubungan dengan sekolah. Jadi, ketika harus menjawab suatu soal di sekolah, itulah 問題.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '005c015f-8b28-4f66-9fda-831bc4277914'; -- 問題 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mudah-mudahan Anda sudah melihat 買う sekarang dan mengetahui artinya "membeli". Jadi, 買い akan serupa dengan itu. Tambahkan itu ke sesuatu dan Anda akan mendapatkan semacam kata "membeli sesuatu". Apa yang dimaksud dengan "membeli sesuatu"? Ini menggambarkan belanja.', reading_mnemonic = 'Pembacaannya adalah kun''yomi, yang biasanya terjadi jika ada hiragana di tengahnya. Anda mempelajari pembacaan 買い ketika Anda mempelajari kanji, serta kata 買う, dan Anda mempelajari pembacaan 物 dalam kata 物!' WHERE id = 'eb98c9c8-0efc-4e60-b796-aef91ef612b6'; -- 買い物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'gunung jalan adalah jalan gunung! Atau jalur gunung, atau jalur gunung.', reading_mnemonic = 'Kedua kanji pada kata ini menggunakan kun''yomi, yang Anda pelajari saat mempelajari kosakatanya. Bila menggunakan bacaan ini, terdengar biasa saja, dan lumrah dalam percakapan. Namun, dapat juga dibaca dengan menggunakan on''yomi, sehingga memiliki kesan yang lebih formal. Itu ciri khas on''yomi, yang cenderung menambah formalitas pada sebuah kata!' WHERE id = 'fe330237-3678-4b47-818a-fec705121ae8'; -- 山道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda menuangkan ide Anda ke dalam sesuatu, Anda banyak memikirkannya. Anda sangat memperhatikan perhatian dan menggunakan hati-hati. Anda akan melihat ini di banyak tanda peringatan yang menandai hal-hal berbahaya di Jepang, jadi pastikan untuk memperhatikannya!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '0c67eea9-f282-4110-ae13-e290f03084be'; -- 注意 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Salah satu arti dari 本 adalah main (yang kami gunakan di sini). utama gedung publik adalah gedung utama.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'db3e24fa-42e5-4f78-b5da-5087d2aad024'; -- 本館 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda mengumpulkan ke tengah diri Anda, Anda mengumpulkan ke arah otak Anda. Semua energi diarahkan ke sana, berkumpul di tengah, memberi Anda kemampuan concentration yang ekstrim. Sekarang Anda benar-benar ahli dalam fokus.

Bayangkan saja sebuah cahaya di tengah otak Anda, begitu terkonsentrasi sehingga Anda mampu berkonsentrasi, menembakkan laser kecil dari dahi Anda ke benda yang sedang Anda konsentrasikan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '31a2ac27-1d64-47cc-89a1-0ba06f50ab36'; -- 集中 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda membawa gerakanAnda (atau membawa sesuatu bersama gerakan Anda, seperti beban, misalnya), Anda sedang melakukan olahraga. Omong-omong, mungkin akhir-akhir ini Anda terlalu banyak mempelajari kanji. Saatnya bangun dan melakukan squat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '449c0601-2bf3-4494-858d-5ce7e3ac1360'; -- 運動 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saya yakin Anda ingat 集める yang artinya "mengumpulkan". Hal ini mirip dengan itu, hanya saja Anda tidak melakukan tindakan pengumpulan, melainkan terjadi begitu saja. Daripada "mengumpulkan", yang dimaksud adalah berkumpul. Anda dapat mengingat hal ini karena kawanan Maru (kucing) akan berkumpul di satu tempat jika mereka merasakan adanya kotak di sana.', reading_mnemonic = 'Cara membacanya sama dengan 集める jadi jika Anda mengetahui kata tersebut, Anda juga akan mengetahui cara membaca kata tersebut.' WHERE id = 'fa8ba0d1-f059-4dee-a658-0bff58fa0641'; -- 集まる (vocabulary)
UPDATE items SET meaning_mnemonic = 'baru produk adalah sesuatu yang baru atau item baru. Saya suka melihat-lihat toko untuk mencari barang baru karena menarik!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Namun perhatikan bahwa ひん berubah menjadi ぴん. Ini karena Anda membeli beberapa pin baru?' WHERE id = 'db5b294f-f7ce-4940-b76c-c17e616047f8'; -- 新品 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda seharusnya sudah mengetahui 開ける sekarang. Kata ini mirip dengan itu, hanya saja ada hubungannya dengan saat segala sesuatunya terbuka. Tapi itu sama saja. Artinya juga membuka.', reading_mnemonic = 'Apakah Anda ingat bacaan 開ける yang Anda pelajari di level 10? Benar sekali, ini あける! Jadi jika Anda mengetahui arti kata tersebut (saya harap Anda mengetahuinya!), maka Anda dapat menerapkan pengetahuan tersebut di sini.

Sekadar catatan singkat — 開く juga dapat dibaca sebagai ひらく, namun kita akan fokus pada pembacaan あく di sini. Karena ひらく memiliki arti yang sedikit berbeda, kami tidak akan menerimanya sebagai bacaan untuk kata ini, jadi pastikan untuk memasukkan あく!' WHERE id = '928e29c1-d6f0-41db-b1c9-e0c5fc72877e'; -- 開く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda tidak tahu apa pun (Jon Snow), Anda tidak tahu apa pun. Ini adalah ketidaktahuan, yaitu ignorant.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '5242b0e5-1994-4b5c-b5ba-65dfad6ce3ac'; -- 無知 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari bumi dalam seminggu adalah hari di mana Anda berada dekat dengan bumi. Entah Anda mendapati Anda minum terlalu banyak pada hari Jumat, sehingga pada pagi hari ini Anda terbaring di tanah. Atau mungkin Anda hanya ingin tidur setelah begadang di hari Jumat. Apa pun yang terjadi, hari ini Anda berbaring dekat dengan bumi adalah Sabtu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = '6b06acb0-efe1-4a9e-a132-89e1314fcd47'; -- 土曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'aksi di sekitar sini tidak ada. Sama sekali tidak ada yang terjadi. Jika tidak terjadi apa-apa, itu berarti aman dan sehat untuk Anda.', reading_mnemonic = 'Satu hal yang tidak aman dan sehat adalah pembacaan 無 pada kata ini. Alih-alih む, melainkan ぶ. Mengapa? Karena Anda mengira itu aman dan sehat, tetapi Anda tertipu. Ada hantu di mana-mana, semuanya melompat keluar dan berteriak Boo! (ぶ) padamu. Rasakan kejutannya. Anda pikir itu aman dan sehat!' WHERE id = 'fc5e4a10-64eb-4850-b447-653f477f4d7c'; -- 無事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah hari dalam seminggu. Anda mengetahui hal ini karena ada 曜日 di dalamnya. Tapi hari apa dalam seminggu ini? Hari emas dalam seminggu adalah hari terhebat. Ini adalah hari yang membuat Anda merasa seperti emas karena ini adalah akhir hari kerja dan awal akhir pekan! Hari ini adalah Jumat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Mengetahui kata 曜日 juga akan membantu.' WHERE id = 'd8994d0e-a248-440c-8a10-1169a80d1a92'; -- 金曜日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tubuh Anda melewati ujian dan setiap kali melewatinya, ia memperoleh lebih banyak pengalaman. Apa yang dialami tubuh Anda? Tes apa yang telah dilalui tubuh Anda?', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'bf0353e1-27b4-4dd3-9a13-304befd08fc2'; -- 体験 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda mempunyai ide untuk suatu tugas, Anda berada dalam persiapan untuk benar-benar melakukannya. Karena itu masih sekedar ide, Anda masih bersiap-siap.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '0b5e22a1-093b-4476-9ef0-15abc9acd4cc'; -- 用意 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda ingin membuat sebuah bisnis sukses, Anda harus bersiap untuk melakukan banyak pekerjaan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 作 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Anda menyukai pekerjaan yang terlibat dalam menggergaji gyoza (さぎょう). Ada sesuatu tentang mengambil sepotong gyoza dan menggergajinya yang sangat Anda sukai.' WHERE id = '3809193a-8258-400b-a684-8e0484c5d8a2'; -- 作業 (vocabulary)
UPDATE items SET meaning_mnemonic = 'utara laut jalan adalah jalan yang Anda ambil untuk sampai ke laut utara. Sebenarnya itu adalah wilayah Jepang. Daerah itu dikenal sebagai Hokkaido. Ini adalah tempat yang sangat bagus, pastikan untuk mengunjunginya jika Anda bisa untuk menikmati makanan laut segar di sekitar.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri. ほく memang dipersingkat, jadi berhati-hatilah!' WHERE id = '5ac174a5-5e19-43e0-910b-5c69364daae4'; -- 北海道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda mencoba sebuah tes, Anda sedang mengikuti ujian. Ada banyak hal seperti ini di Jepang, jadi pastikan Anda mengetahui kata ini jika Anda ingin menyesuaikan diri dengan semua rengekan dan keluhan yang dilakukan siswa, terutama menjelang tahun terakhir sekolah menengah atas.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '8c1f02c0-8c07-4945-8be6-62d6ebce12b3'; -- 試験 (vocabulary)
UPDATE items SET meaning_mnemonic = 'air jalan membawa persediaan air Anda. Di masa lalu, saluran ini disebut aqueducts.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '96c4aca9-4b8a-43d8-bdf8-ae97b6968abb'; -- 水道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda tidak melakukan apa pun dengan alasan, maka apa yang Anda coba lakukan adalah tidak masuk akal dan mungkin benar-benar tidak mungkin. Jika Anda masih mencobanya, Anda mungkin berlebihan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Selama Anda mengetahui bacaan kanji ini, Anda seharusnya bisa membaca kata ini dengan baik.' WHERE id = '606ea189-549b-49d3-b4d9-80ecc91f0ed5'; -- 無理 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Cina". Perhatikan bentuk karakter "[Cina]" dan asosiasikan bentuk goresannya dengan "cina".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1e28af7c-8fff-4a55-9b55-5d3eaf7898ce'; -- [Cina] (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari kanji tidak ada, jadi ketika Anda tidak punya apa-apa, Anda tanpa.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Saat kamu tanpa kamu juga tidak punya apa-apa untuk dimakan, jadi kamu malah mengertakkan gigi (なし).' WHERE id = '0d496769-16ff-4936-894b-8d6684d02cad'; -- 無し (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang Anda pakai, dan pakai lagi, adalah sesuatu yang terus-menerus Anda kenakan. Anda sering melakukannya, itu dapat diandalkan. Selain itu, jika Anda memakai sesuatu sebanyak ini, pakaian tersebut juga akan cepat rusak.', reading_mnemonic = 'Kata ini menggunakan pembacaan on''yomi dari kanji yang Anda pelajari sebanyak dua kali. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '098b4065-3d37-4902-9a34-2325c17153c7'; -- 着々 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya benar.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0e6a63b8-27f0-4d74-9ab9-2b7a15fdc0a8'; -- 正 (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini diakhiri dengan bunyi う sehingga Anda dapat menebaknya sebagai kata kerja. Kanji tidak berarti tidak ada, dan Anda tidak akan mendapatkan apa-apa jika Anda ingin menyingkirkan sesuatu, menghilangkan sesuatu atau kehilangan sesuatu.

Kata kerja ini bersifat transitif, yaitu tindakan yang terjadi pada sesuatu. Jadi mungkin Anda sedang terbebas dari hutang, atau diskriminasi, atau stres... Apa pun itu, ada objek langsung dengan kata kerja ini!', reading_mnemonic = 'Kata ini menggunakan kun''yomi, yang telah Anda pelajari saat mempelajari kata 無し.' WHERE id = '72db3fcb-98b2-412b-abc9-919d17f66ad4'; -- 無くす (vocabulary)
UPDATE items SET meaning_mnemonic = 'Lihat seberapa tinggi batangnya dengan tanaman kecil yang lebat di bagian atasnya? Ini terlihat seperti bambu, jika Anda menggunakan imajinasi Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '34a686ed-b54b-49f8-8207-8cbf5937adfc'; -- 竹 (radical)
UPDATE items SET meaning_mnemonic = 'Di penjara di sawah mereka sedang merebus sesuatu. Menurutmu apa itu? Ikan! Apa yang lebih baik dengan nasi? Apa yang mudah ditemukan sehingga menjadikannya makanan penjara yang murah? Ikan, tentu saja!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '45bebcec-c42e-4524-9d31-c3f38138ab61'; -- 魚 (radical)
UPDATE items SET meaning_mnemonic = 'Ada banyak kandang yang mendidih. Tapi Anda melihat ke dalam kandang dan di sana... tidak ada apa-apa. Anda merebus apa pun yang ada di sana hingga habis!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7059d9ce-ff87-4c15-a29a-25e8536edc2d'; -- 無 (radical)
UPDATE items SET meaning_mnemonic = 'Anda menemukan topi di tanah dengan mulut sebagai desain di bagian depan. Anda berpikir itu terlihat aneh, namun ketika Anda memakainya, Anda merasa cocok dengan cukup baik. Bayangkan diri Anda merasa tidak begitu yakin dengan topi ini pada awalnya. Tapi begitu Anda memakainya, Anda merasa terkejut.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '922e3d1a-c835-4ec4-a312-d272fe972e5a'; -- 合 (radical)
UPDATE items SET meaning_mnemonic = 'Ini tampak seperti puncak dari burung yang radikal, tetapi tidak sepenuhnya. Ini semacam atasan radikal yang tampak bodoh. Burung apa yang bodoh, begitu bodohnya sehingga ia memandang ke langit untuk menenggelamkan dirinya dengan mulut terbuka? kalkun.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1849a3bd-1300-4582-9c74-a5b315fd029d'; -- 隹 (radical)
UPDATE items SET meaning_mnemonic = 'ごはん adalah makanan atau santapan (mungkin nanti Anda akan mempelajari kanjinya, tetapi biasanya tidak digunakan, jadi Anda mempelajarinya dengan cara ini sekarang). Apa makanan pagi Anda? Itulah sarapan (jangan bingung dengan sarapan kedua, hobbit).', reading_mnemonic = 'Pembacaan 朝 sama dengan yang Anda pelajari dengan kanji, artinya Anda harus bisa membaca semuanya di sini.' WHERE id = 'af732d29-b023-41e6-98df-4f1d84f133be'; -- 朝ごはん (vocabulary)
UPDATE items SET meaning_mnemonic = 'Pakaian yang pakai di bawah pakaian Anda yang lain. Itu adalah pakaian dalam Anda. Anda memang memakai pakaian dalam, kan?', reading_mnemonic = 'Bacaan yang satu ini seluruhnya adalah bacaan kosakata kun''yomi, namun Anda harus mengetahuinya sekarang. 着 menggunakan bacaan yang Anda pelajari dengan 着る, tetapi kata ini menggunakan rendaku yang mengganggu, jadi ingatlah bahwa き menjadi ぎ di sini.' WHERE id = '550e277a-4055-45c9-912b-801ebc295c87'; -- 下着 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bagian いい berarti "baik". Jadi, ketika apa yang bawa Anda bagus, Anda beruntung. Anggap saja keberuntungan adalah benda fisik yang Anda bawa di tangan. Sekarang bayangkan diri Anda membawanya. Sekarang pikirkan dalam hati “yang saya bawa bagus, untung!”', reading_mnemonic = 'Pembacaan kanji pada vocab ini sama dengan yang kamu pelajari dengan kanji, artinya kamu harus bisa membacanya.' WHERE id = '72163200-1623-48fe-8dba-2fd1eff3691f'; -- 運がいい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari kesenangan? Ya, bisa dibilang itu "menyenangkan", tapi sayangnya bukan itu tujuan kita di sini. Dalam hal ini, kata ini sedikit lebih polos. Artinya menyenangkan.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Berapa banyak kesenangan yang Anda alami? Anda baru saja bersenang-senang (たの)!' WHERE id = '351f20d0-ab0e-4499-a546-79b175c89b6d'; -- 楽しい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah salah satu kata yang memiliki kanji yang pada dasarnya memberi tahu Anda artinya. Anda membuka sebuah bisnis... alias membuka bisnis.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7ee50923-af3a-4b65-bf23-45fc0f6f4a95'; -- 開業 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tidak akan meletakkan ide Anda dalam format diagram ~seperti jika tidak disengaja. Melakukan hal itu membutuhkan banyak usaha. Jadi Anda hanya dapat membuat diagram seperti hal-hal dengan sengaja!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda belum mempelajari bacaan ini untuk 図, jadi inilah mnemonik untuk membantu Anda:

Anda sengajamematikan jari kaki Anda (と) sepanjang waktu! Jika jari kakimu sengaja kamu terluka, kamu boleh keluar kelas dan bekerja! Ini adalah cedera yang sangat sederhana, tetapi Anda tidak dapat melakukan hal lain saat cedera itu terjadi, jadi Anda selalu melakukannya dengan sengaja untuk keluar dari situasi tersebut.' WHERE id = '9c0f248a-cf9f-4a0a-b0fa-83062bda03b4'; -- 意図的 (vocabulary)
UPDATE items SET meaning_mnemonic = 'gedung publik untuk melakukan perjalanan adalah tempat Anda menginap ketika Anda melakukan perjalanan. Dulu, itu hanyalah sebuah penginapan atau semacamnya. Sekarang, ini menetapkan bahwa penginapan tersebut adalah penginapan Jepang atau hotel Jepang. Banyak orang bahkan hanya menyebutnya dengan nama Jepangnya: ryokan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e2157a75-d8f4-4511-b626-1cfac32607f2'; -- 旅館 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Siapakah bagian orang tua bagi Anda? bos Anda! Mereka membuatnya agar Anda bisa menjaga diri sendiri dengan membayar Anda, bukan? Mereka akan mematahkan kaki seseorang yang melintasimu. Namun obat-obatan tersebut tidak akan membantu Anda kembali tidur setelah mengalami mimpi buruk. Jadi mereka hanya sebagian seperti orang tua.', reading_mnemonic = 'Kata ini terdiri dari bacaan kun''yomi untuk 親 dan bacaan on''yomi untuk 分. Anda telah mempelajari keduanya sehingga Anda seharusnya sudah bisa membacanya!' WHERE id = '7d5a9c65-e022-4c05-8c7a-f6538a1f9b98'; -- 親分 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda mungkin pernah melihat kata 楽しい, yang artinya "menyenangkan". Sekarang Anda akan mengetahui versi kata kerjanya (diakhiri dengan bunyi う, kan?). Itu akan menjadi untuk dinikmati. Omong-omong, saya harap Anda menikmati WaniKani sejauh ini!', reading_mnemonic = 'Bacaannya sama dengan kata 楽しい, jadi pastikan Anda mengetahui kata tersebut dan Anda akan dapat menerapkannya di sini.' WHERE id = 'f1ce1566-4265-4889-a4cd-30d09f85a64c'; -- 楽しむ (vocabulary)
UPDATE items SET meaning_mnemonic = 'ikan radikal dan ikan kanji sama persis!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Ikan** (魚), bayangkan Anda sedang membawa **Gigi/Giyono** untuk ditaruh di atas ikan. Kejadian unik ini mengingatkan Anda pada bunyi **ぎょ**!' WHERE id = '19e7d17e-44ce-4cf2-a7f1-b348ce0b10d6'; -- 魚 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kata yang ditempelkan di akhir berbagai kata lainnya. Bayangkan "jalan" sebagai cara atau metode sesuatu. Misalnya, どう dalam Judo adalah "cara" yang lembut. Ada banyak kata yang diakhiri dengan 道, dan Anda akan melihatnya nanti. Untuk saat ini, ketahuilah bahwa ini berarti metode atau cara.', reading_mnemonic = 'Kata ini ditambahkan di akhir banyak kata berbeda, artinya kata ini diperlakukan seperti kebanyakan jukugo (dan menggunakan bacaan on''yomi). Anda tahu bacaan on''yomi, jadi Anda harus bisa membaca kata ini. Namun, pastikan untuk menghilangkan 〜 saat menulis dalam bacaan ujian. Itu hanya untuk menunjukkan bahwa itu ditambahkan ke sesuatu dan bukan bagian dari jawaban yang benar.' WHERE id = 'a8467005-e7e7-4564-b08a-9d27541c7502'; -- 〜道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mengambil jalan terdekat akan membawa Anda ke tujuan lebih cepat (karena jaraknya lebih dekat!). Ini adalah shortcut alias jalan pintas.', reading_mnemonic = 'Pembacaannya agak aneh dalam hal ini. Ini menggunakan pembacaan kun''yomi untuk kedua kanji, meskipun sepertinya semuanya harus dibaca on''yomi. Ini seperti Anda mengambil jalan pintas dengan pembacaan kanji Anda dan melakukan pembacaan asli bahasa Jepang (kun''yomi) daripada pembacaan bahasa Cina yang lebih intelektual (on''yomi). Untungnya, Anda mungkin sudah melihat kedua kanji ini sebagai kosakata. Anda memiliki ちか untuk 近 (kependekan dari 近い) dan Anda memiliki 道 (みち), sama seperti kata "jalan" yang Anda pelajari sebelumnya. Gabungkan ini bersama-sama dan Anda akan mendapatkan bacaan untuk kata ini. Mungkin seperti ini karena Anda menggabungkan beberapa konsep menjadi satu kata, setidaknya dalam hal "pendek + cara".' WHERE id = '679ee3c6-2fd4-4417-93e7-196cfbd720e3'; -- 近道 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti mengumpulkan dan kata kerja ini bersifat transitif, artinya tindakan yang dilakukan terhadap sesuatu atau seseorang. Jadi kata kerja ini memiliki arti seperti mengumpulkan sesuatu dan mengumpulkan sesuatu.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Ketika Anda hanya memiliki satu hal, hanya ada satu hal. Tidak ada yang dikumpulkan. Tapi ketika kamu punya dua... "ah dua!" (あつ). Sekarang Anda mulai mengumpulkan sesuatu.' WHERE id = '066ae0d8-5a17-4998-9b20-df45119c904c'; -- 集める (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa suara dari kesenangan? suara apa yang membuat Anda nyaman? Bagi kebanyakan orang, itu adalah musik yang bagus. Pastikan saja kamu tidak memakai Bieber... itu akan seperti 不音楽 atau semacamnya... nak, nak.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Anda belum mempelajari bacaan ini untuk 楽, jadi inilah mnemonik untuk membantu Anda:

Jika Anda memainkan musik terlalu keras, orang-orang akan datang dan melongo (がく) ke arah Anda. Tetapi jika Anda mencoba mematikannya dan berkata, "OH APA SAYA TIDAK SUKA MUSIK!" mereka akan semakin melongo melihatmu. Pelajari etiket musik yang benar dan orang-orang tidak akan terlalu memandangmu, oke?' WHERE id = '66e41b9d-20e2-4a8e-ae85-512b87c7d8b1'; -- 音楽 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata kerja lain untuk kanji ini! Gila! Aku tahu, aku minta maaf. Yang sebelumnya adalah: 着る (memakai), 着く (tiba), dan sekarang 着ける (memakai / memakai). Setidaknya mirip dengan 着る, kan? Dalam hal ini, kata tersebut seperti 付ける, yang artinya "melampirkan". Ini digunakan untuk benda-benda yang Anda "pasang" ke tubuh Anda untuk dipakai, seperti aksesoris, atau masker wajah. Itu sebabnya ini untuk dipakai atau untuk dipakai. Suaranya sama, kanjinya berbeda, idenya mirip.', reading_mnemonic = 'Bacaannya sama dengan bacaan 着く, namun mungkin akan lebih mudah jika dianggap bacaannya sama dengan 付ける, yang memiliki arti serupa. Kenakan pakaian, tempelkan pada pakaian, dll!' WHERE id = '6c2dd6e6-a299-4327-9018-dfc90fd54c65'; -- 着ける (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti memakai jadi kata ini berarti memakai atau memakai. Anda harus membedakannya dari 着く yang berarti (tiba). Bayangkan saja bagaimana る adalah pria rude yang mencoba membuat Anda mengenakan pakaian yang tidak Anda sukai.', reading_mnemonic = 'Apa yang ingin pakai Anda hari ini? Bagaimana dengan gaun yang seluruhnya terbuat dari kunci (き)? Rasakan logam di kulit Anda dan beban di bahu Anda. Ini bukan hal yang nyaman untuk dikenakan. Mungkin lain kali Anda hanya perlu memakai satu kunci di leher Anda.' WHERE id = '13c818a7-b355-4fb7-93ab-980bf2d1ef60'; -- 着る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal dan kanji untuk arah adalah sama! Sabas!

Namun ada juga arti lain. Ini juga bisa berarti cara. Anggap saja seperti ini: Ketika Anda bergerak ke satu arah dalam hidup Anda, Anda mengembangkan cara Anda sendiri. "Cara [namamu di sini]."', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Arah** (方) tiba-tiba berbicara dan meminta **Hotel/Hormon**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ほう**.' WHERE id = '426aac96-2336-43ac-be37-ad9375cb1d81'; -- 方 (kanji)
UPDATE items SET meaning_mnemonic = 'hati radikal dan hati kanji adalah sama. Bergembiralah dan biarkan hatimu bebas!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Jantung** (心), bayangkan Anda sedang membawa **Shin-chan/Singa** untuk ditaruh di atas jantung. Kejadian unik ini mengingatkan Anda pada bunyi **しん**!' WHERE id = 'f409f927-b633-442a-aa45-9156292dcbad'; -- 心 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki fins di pribadi. Namun, Anda ingin dunia melihatnya, jadi Anda menjadikannya publik.', reading_mnemonic = 'Tahukah Anda bahwa **Publik** (公) ini sebenarnya dibuat dari tumpukan **Koko/Koki**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **こう**.' WHERE id = 'fa07190b-fc75-4b59-bfb5-88c72ff21de5'; -- 公 (kanji)
UPDATE items SET meaning_mnemonic = 'publik tugas akan menjadi urusan pemerintah. Anda harus menganggap masyarakat ini sebagai pemerintah untuk mengetahui arti kata ini dengan mudah.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '81ce5883-9433-4f03-b8ee-1ecc23cf4896'; -- 公用 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kanan tangan Anda adalah tangan kanan Anda! Kata ini juga dapat digunakan untuk mengartikan lengan kanan, dan sisi kanan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Namun kata ini menggunakan bacaan kun''yomi. Hal ini mungkin karena 手, karena bagian tubuh sering menggunakan kun''yomi. Anda mempelajari kedua bacaan dengan kata-katanya masing-masing, jadi Anda seharusnya bisa membaca ini.' WHERE id = '1730b1c0-a124-461a-9813-a4cf438c1cbe'; -- 右手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat kamu mempelajari kanji yang menyusun kata ini, yang kamu pelajari hanyalah pembacaan kun''yomi, jadi sebaiknya kamu mulai saja.' WHERE id = '2355f74a-b30b-4aec-93f6-f7a9366d7eb4'; -- 田 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka harus menggunakan bacaan kun''yomi, tapi bisa juga bacaan itu atau on''yomi, tergantung konteksnya. Anda belum mempelajari bacaan kun''yomi untuk 方, jadi ada mnemonik yang dapat membantu Anda:

Anda harus menuju arah tertentu. Bagaimana Anda sampai ke sana? Dengan melompat ke ketapel (かた) dan menembak diri sendiri ke cara yang benar. Perlu mendapatkan arah tertentu dengan cepat? Pertimbangkan ketapel lain kali.' WHERE id = 'ad862c24-bb74-46d9-97de-942593bcf0ef'; -- 方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sesuatu berada di tengah suatu tindakan namun berhenti, ini berarti tindakan tersebut dimasukkan ke dalam suspension. Bayangkan Anda membeku saat Anda berlari. Ini seperti itu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fa5b9f86-650f-4848-bf1b-4b9e8752a798'; -- 中止 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda menggabungkan kedua kanji ini, Anda akan dapat melihat bagaimana kata dua mesin terbentuk.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '291288cb-78e5-425b-9618-a760fe7bd911'; -- 二台 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang dengan studi tentang industri adalah seseorang yang menciptakan sesuatu. Itu adalah studi tentang engineering.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'd31a673d-d7ec-4399-be7c-e1a11aa71dbe'; -- 工学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'pengganti tugas adalah substitusi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3f51613f-8ce5-4706-ae94-1d7081762299'; -- 代用 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dari sebelum, berarti sebelumnya atau sebelum sekarang.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '5ec07948-81ca-422c-ae27-76bfdc19ada1'; -- 以前 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Yang ini menggunakan bacaan on''yomi, yang sudah Anda pelajari dari kanji!' WHERE id = '8655f189-53d4-4c53-969d-171f6bf77254'; -- 用 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dibandingkan dengan ini, di bawah. Itu cara lain untuk mengatakan bahwa apa yang Anda miliki kurang dari itu.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '8927ce76-ed0e-4bfb-a05b-d6e0cfdc1b16'; -- 以下 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda belajar menulis itu disebut sastra. Anda akan mempelajari banyak hal yang ditulis orang lain sebelum Anda!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 文 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Semua karya besar sastra adalah tentang roti (ぶん). Itulah benang halus yang ada di seluruh literatur: roti.' WHERE id = 'b6450baa-441c-426c-8b2b-57853ff0bbbc'; -- 文学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dari sesudah, berarti setelah ini atau mulai sekarang.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f93a2ba7-bed1-4be3-bc6f-f932caa658e9'; -- 以後 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Semua yang kami lakukan adalah untuk melayani Anda, lho.

Kata kerja ini agak kuno dan karena itu memiliki kesan formal. Kata ini digunakan untuk berbicara antara lain tentang melayani kaisar, raja, dan dewa.', reading_mnemonic = 'Untuk melayani Anda dengan baik, kami menyediakan dua mobil (つか). Jika salah satu mobil rusak, kami masih bisa melayani Anda dengan mobil lainnya.' WHERE id = '75dba553-2d8d-420c-a8d5-03306994dd9c'; -- 仕える (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sebuah kata kosakata terdiri dari satu kanji dan hanya itu, hampir selalu maknanya diambil dari kanji induknya. Jadi, kosakata ini juga berarti power.', reading_mnemonic = 'Jika sebuah kata vocab berbentuk kanji tunggal tanpa okurigana (hiragana yang melekat pada kanji), biasanya menggunakan bacaan kun''yomi. Anda tidak mempelajari pembacaan kun''yomi dengan kanji, jadi untuk kosakata ini, kita akan menggunakan mnemonik.

Orang paling berkuasa di dunia. Seluruh power miliknya berasal dari pipinya (ちから). Bayangkan dia meledakkan pipinya seperti balon raksasa, lalu melepaskan kekuatannya ke arah Anda. Thwap thwap thwap thwap.' WHERE id = 'd7bcd275-0788-4950-af8c-3db303f45de8'; -- 力 (vocabulary)
UPDATE items SET meaning_mnemonic = 'master radikal dan master kanji memiliki arti yang sama!

Kanji ini juga berarti utama karena master adalah orang utama dalam dojo atau rumah tangga atau bisnis.', reading_mnemonic = 'Ketika Anda sedang melihat **Guru** (主), tiba-tiba muncul sesosok **Susu/Sumpit** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **しゅ**.' WHERE id = 'df6ba003-2b4c-4bb8-a56b-0b257bc14d98'; -- 主 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini memiliki satu kanji dengan hiragana yang dilampirkan, diakhiri dengan い. Ini berarti Anda tahu itu adalah kata sifat. Apa bentuk kata sifat dari sedikit? Jumlahnya juga sedikit.', reading_mnemonic = 'Pembacaannya cukup sulit, karena ini adalah pembacaan kun''yomi (Anda dapat mengetahui itu kun''yomi karena semua hiragana terlampir). Anda harus mengingat bagian すく untuk mengingat bacaan kata ini. Pikirkan seperti ini: 

Anda memiliki beberapa sesuatu. Ini sesuatu yang menyebalkan (すく). Bayangkan memasukkan ketiganya ke dalam mulut Anda sekaligus. Bagaimana rasanya? Bisakah Anda mencicipi rasa dari masing-masingnya?' WHERE id = 'd05b5c11-3541-48cf-bae9-64d9ec3fa085'; -- 少ない (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat bahwa 代わる berarti "menggantikan" atau "menggantikan". Ini adalah versi kata benda that (tidak ada bunyi う di akhir). Jadi, apa versi kata benda dari kata kerja tersebut? Itu akan menjadi pengganti atau pengganti.', reading_mnemonic = 'Anda harus bisa memahami bacaan dari pembelajaran 代わる di level sebelumnya.' WHERE id = 'f1d58a4e-3992-4efc-8daa-263e75ec3f5a'; -- 代わり (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda memiliki tujuh pedang, tidak banyak yang dapat Anda lakukan dengan pedang tersebut. Hal utama? Mungkin menggunakannya untuk memotong sesuatu.', reading_mnemonic = 'Tahukah Anda bahwa **Potong** (切) ini sebenarnya dibuat dari tumpukan **Setan/Senter**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **せつ**.' WHERE id = '07ac5eeb-f625-4af3-817c-b3b4e954715f'; -- 切 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal berhenti sama dengan kanji berhenti.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Berhenti** (止), bayangkan Anda sedang membawa **Singa/Silet** untuk ditaruh di atas berhenti. Kejadian unik ini mengingatkan Anda pada bunyi **し**!' WHERE id = '6ed84f05-23b5-4611-80e7-3b4becb50e7b'; -- 止 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal mata dan kanji mata sama satu sama lain, jadi sekarang Anda sudah mengetahui keduanya.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Mata** (目) tiba-tiba berbicara dan meminta **Meja/Merak**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **め**.' WHERE id = '7dc6c977-26cc-4055-b60f-d4e881a9eb7e'; -- 目 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan yang kamu pelajari untuk kanji, artinya kamu harusnya sudah mengetahuinya!' WHERE id = '6e05c9f9-2f0d-48f1-afdd-78e87c97eefa'; -- 目 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Selama Anda mengetahui dua kanji yang membentuk kata ini, Anda pasti bisa memahami arti kata tersebut juga.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '809b44cb-53a1-4ed5-a7e6-39c8a7046e74'; -- 一台 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Selama Anda mengetahui kedua arti kanji masing-masing, Anda seharusnya bisa menggabungkan yang satu ini untuk mendapatkan lima mesin.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f13c56fd-b1ad-4637-829e-13664ee09672'; -- 五台 (vocabulary)
UPDATE items SET meaning_mnemonic = 'dua generasi adalah generasi kedua.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ad058e9e-ef5e-432a-a39d-8fdfbcc4fa52'; -- 二世 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji berarti tangan, dan kata tersebut juga berarti tangan! Ini juga dapat digunakan untuk merujuk ke seluruh lengan Anda.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Karena ini bagian tubuh, pembacaan kun''yomi biasanya diprioritaskan. Artinya, Anda sudah mempelajari bacaan kun''yomi saat mempelajari kanji.' WHERE id = '4aef0f92-1adf-4b68-9a7d-147187046908'; -- 手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki periode dari waktu dan itu disebut periode atau era! Sederhana!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '638b041b-47a7-4917-9f7f-ec91d67d5ea2'; -- 時代 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah cara menulis (seperti 見方 adalah cara melihat). Namun, cara yang lebih baik untuk mengatakan hal ini adalah dengan menyebutnya penmanship. Bagaimana 書き方mu? Milik saya sangat buruk.', reading_mnemonic = 'Ini menggunakan bacaan kun''yomi dari vocab kata 書く dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = '9ca1db73-b481-4d7c-a119-05da1fc34997'; -- 書き方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu kanji adalah pengganti, dan Anda tahu ini adalah kata kerja. Ada yang serupa lainnya, tapi yang ini berarti mengganti sesuatu. Untuk mengingat bahwa kata khusus ini berarti "mengganti sesuatu" fokuslah pada え. Anda memiliki sebutir telur di tangan yang menurut Anda tidak ada gunanya (warnanya hitam dan berjamur). Jadi, Anda menggantinya dengan telur lain (atau menggantinya dengan telur lain, atau menukarnya dengan telur lain, dan seterusnya).

Kata kerja ini bersifat transitif, artinya mempunyai objek langsung. Anda mengganti sesuatu, seperti telur itu!', reading_mnemonic = 'Pembacaan untuk yang ini sama dengan 代わる yang Anda pelajari di level sebelumnya. Selama Anda mengetahuinya, Anda harus bisa mempelajari bacaan yang satu ini juga.' WHERE id = 'be46de7a-f612-450d-84b5-f252dcf5249a'; -- 代える (vocabulary)
UPDATE items SET meaning_mnemonic = 'tengah dari dunia adalah masyarakat. Itu yang menyatukan segalanya, bagi kita manusia. Anda juga bisa menyebutnya dunia.', reading_mnemonic = 'Bacaannya adalah bacaan kun''yomi. Mengapa? Karena kata ini sebenarnya adalah dua kata terpisah yang dihubungkan menjadi satu kata yang lebih besar. Anda mengetahui bacaan kun''yomi dari latihan kosakata di level sebelumnya.' WHERE id = '11f5213f-e213-46a0-920f-2e5d9f9d3a40'; -- 世の中 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti pengganti, jadi kita bisa memahami arti kata ini melalui: To replace / to replace for.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajarinya dengan kanji ini, jadi inilah mnemonik untuk membantu Anda mengingat bagian か. 

Anda memiliki untuk mengganti mobil Anda (か). Ini semakin tua, dan sepertinya akan meledak kapan saja, secara harfiah.' WHERE id = '3b197695-d71d-4cfd-b4ef-fd8eab5493e0'; -- 代わる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama. Kata ini sedikit lebih luas daripada cow, dan juga dapat digunakan untuk banteng dan ox.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Berikut ini mnemonik untuk membantu Anda mengingatnya: 

Anda sedang memimpin sapi berkeliling lapangan. Untuk membuat mereka bergerak, teriakkanlah "USH, USH, USH!" (うし) karena kamu mempunyai gangguan bicara dan ingin mengatakan "MUSH MUSH MUSH." Silakan katakan ini dengan lantang, sambil berteriak jika Anda bisa.' WHERE id = 'b721dfeb-9212-434a-98d6-2feaa809a8a2'; -- 牛 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dengan cincin bibir, segalanya mungkin. Memiliki cincin bibir memberi Anda kekuatan untuk menaklukkan rintangan apa pun, mencapai tujuan apa pun. Selama itu adalah cincin bibir yang lumayan, itu saja. Kalau kurang bagus, tidak mungkin bisa lumayan.', reading_mnemonic = 'Ketika Anda sedang melihat **Kemungkinan** (可), tiba-tiba muncul sesosok **Kaki/Kaca** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **か**.' WHERE id = '73625a8a-ec89-4ce3-b6b2-2093638116bc'; -- 可 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda telah mengetahui bahwa 口 berarti "mulut" dan di sini diikuti oleh partikel に, yang menunjukkan dengan tepat suatu lokasi. Kata kerja する berarti "melakukan" jadi Anda melakukan sesuatu pada mulut Anda! Logikanya, ungkapan ini digunakan untuk menggambarkan banyak tindakan yang Anda lakukan dengan mulut Anda. Kata ini sering digunakan dalam arti to mention atau to say, namun dengan tambahan nuansa deskriptif bahwa Anda telah mengatakan sesuatu secara tidak sengaja atau tidak terduga, mungkin sesuatu yang seharusnya tidak Anda katakan! 🙊

Bisa juga berarti hal lain yang dilakukan dengan mulut, seperti makan dan minum!', reading_mnemonic = 'Dalam ungkapan ini, 口 adalah kosakata yang berdiri sendiri, sehingga menggunakan bacaan yang sama yang Anda pelajari saat mempelajari kosakata tersebut.' WHERE id = 'c6ce93d6-419d-48a7-b4d7-a5ad8e28828f'; -- 口にする (vocabulary)
UPDATE items SET meaning_mnemonic = 'tiga generasi adalah generasi ketiga. Tergantung pada konteksnya, terkadang Anda dapat menggunakan kata ini untuk mengatakan bahwa Anda adalah generasi ketiga Jepang. Namun biasanya, Anda ingin menentukan apakah Anda generasi ketiga Jepang atau berkewarganegaraan lain.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'b04b2634-2971-4666-9f39-9393010e5244'; -- 三世 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dua batang kayu menopang tutupnya. Dengan melakukan hal ini, mereka membuat berdiri.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'c59efbef-e607-4c07-82c1-1a29cd7ced99'; -- 立 (radical)
UPDATE items SET meaning_mnemonic = 'Apa asal dari energi Anda? Ini adalah kesehatan Anda. Kata ini juga berarti energi, dan jika digunakan sebagai kata sifat, artinya sehat atau energik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'a9758f22-c611-44d8-b65b-ac39327eab3c'; -- 元気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Bayangkan hati raksasa duduk di perahu dayung. Itu juga minum coklat. Fokus pada ketiga bagian tersebut dan kaitkan menjadi satu cerita/ingatan. Setelah Anda selesai melakukannya, nyanyikan lagu "cocoa row" (こころ)! Saya tidak tahu lagu apa itu, tapi saya ingin Anda membuat lagunya dan menyanyikannya dengan lantang. Jika ya, saya yakin Anda tidak akan mudah melupakan bacaan kata ini.' WHERE id = '23aabb75-a835-487e-b452-5df8c00d7210'; -- 心 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Yang ini agak sulit untuk dibayangkan, tapi aku percaya padamu. Duri di tengah adalah pergelangan tangan/lengan. Lalu, ada empat jari biasa yang keluar dan satu ibu jari besar (slide radikal di atas). Jadi Anda memiliki empat jari, satu ibu jari, dan satu pergelangan tangan. Inilah yang membuat tangan Anda tampak gila.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1378a28d-d40d-460b-a787-4c1b368b9314'; -- 手 (radical)
UPDATE items SET meaning_mnemonic = 'Raja ini mempunyai setetes air yang mengambang di atas kepalanya. Itu karena dia bukan hanya seorang raja, dia adalah penguasa air. Ahli elemen. Penguasa Segala Sesuatu!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'e40b5a77-856c-43c4-90f9-9d116b621542'; -- 主 (radical)
UPDATE items SET meaning_mnemonic = 'Ada sesuatu yang ketagihan masuk ke dalam mulut. Namun, bukannya pengait, ini adalah cincin bibir. Mereka biasa menggunakan kail dan paku ikan di masa lalu. (Senang kita tidak hidup di masa itu lagi!)', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'fa18252d-ef0d-421d-91bb-b6283a10bd4b'; -- 可 (radical)
UPDATE items SET meaning_mnemonic = 'Ketika Anda memiliki sesuatu yang tidak benar, Anda tidak memiliki keadilan. Faktanya, Anda memiliki ketidakadilan. Bayangkan saja diri Anda berada dalam situasi yang tidak adil, dan pikirkan betapa tidak benarnya situasi tersebut. Ini mungkin tidak jujur dan tidak sah juga.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'a9920e62-c377-4300-8bf6-39797038d097'; -- 不正 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata radikal dan kanji untuk sapi sama persis! Itu membuatnya mudah untuk diingat, selama Anda mengenal radikal Anda dengan cukup baik.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Sapi** (牛), bayangkan Anda sedang membawa **Gajah** untuk ditaruh di atas sapi. Kejadian unik ini mengingatkan Anda pada bunyi **ぎゅう**!' WHERE id = 'e66cacc3-8efa-42b4-b5a2-bbc5903fd1be'; -- 牛 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal tidak dan kanji tidak adalah hal yang sama! Itu membuatnya mudah... Tidak!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Tidak** (不) tiba-tiba berbicara dan meminta **Feri/Foto**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ふ**.' WHERE id = '287a6803-0a67-4838-b231-8e43e5d255fb'; -- 不 (kanji)
UPDATE items SET meaning_mnemonic = 'pemimpin samurai tidak menjadi pemimpin hanya dengan duduk diam dan tidak mengambil tindakan. Dia mencapai tempatnya sekarang dengan melakukan.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Melakukan** (仕) tiba-tiba berbicara dan meminta **Singa/Silet**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **し**.' WHERE id = '97e7872e-69a7-4710-9c41-64c0458cac43'; -- 仕 (kanji)
UPDATE items SET meaning_mnemonic = 'berdiri radikal dan berdiri kanji adalah hal yang sama, jadi sekarang Anda sudah mengetahui keduanya.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Berdiri** (立), bayangkan Anda sedang membawa **Rusa/Raja** untuk ditaruh di atas berdiri. Kejadian unik ini mengingatkan Anda pada bunyi **りつ**!' WHERE id = '612b440d-aefe-4a90-89d3-9556dc1e1862'; -- 立 (kanji)
UPDATE items SET meaning_mnemonic = 'pemimpin untuk upacara tidak dapat datang sehingga Anda memerlukan pengganti untuk menggantikan mereka secepatnya!

Kanji ini juga memiliki arti lain. Pemimpinnya tidak bisa datang ke upacara tersebut karena lupa periode waktunya. Jika mereka merasa usia mereka salah, mereka tidak akan datang karena mereka malah mencoba memimpin beberapa monyet dalam upacara.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Pengganti** (代), bayangkan Anda sedang membawa **Dadu/Dahi** untuk ditaruh di atas pengganti. Kejadian unik ini mengingatkan Anda pada bunyi **だい**!' WHERE id = '76d77c98-0e5e-43c6-baf5-64cb3355cf58'; -- 代 (kanji)
UPDATE items SET meaning_mnemonic = 'Bayangkan seseorang mengulurkan tangannya setinggi bahu. Apa pun di atas itu berarti “terampil”. Segala sesuatu di bawah itu sama dengan "tidak terampil. Jadi, dalam kasus kata ini, "di bawah tangan" berarti "tidak terampil".', reading_mnemonic = 'Jika Anda buruk dalam sesuatu dan Anda mengeluh tentang hal itu, maka Anda hanyalah seorang pembenci (へた). Jangan menjadi pembenci.' WHERE id = '8f985df2-785c-4d26-856f-9c0ce8e9c362'; -- 下手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mulut tempat Anda keluar hanyalah sebuah pintu (saya harap), namun cara yang lebih mudah untuk menggambarkan kata atau konsep ini adalah dengan menyebutnya sebagai exit.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. 出口 merupakan pengecualian terhadap aturan ini, dan menggunakan pembacaan kun''yomi. Tidak ada alasan khusus mengapa hal ini terjadi, tetapi seringkali kata "bagian tubuh" (seperti mulut) mengubah kata menjadi menggunakan bacaan kun''yomi daripada yang on''yomi. Anda sudah mengetahui bacaan kun''yomi untuk 口 (くち) dari mempelajari kosakatanya, namun untuk mengingat bacaan untuk 出 Anda dapat memikirkan hal berikut:

Jika aku keluar dari mulut ini, aku akan berakhir di lautan (kamu ditelan ikan paus) dan aku pasti akan mati (で).

Perlu diingat juga bahwa karena rendaku, くち menjadi ぐち.' WHERE id = 'c58f9d31-5e27-41db-91e6-bd8e70380f73'; -- 出口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan beberapa hiragana yang dilampirkan, diakhiri dengan bunyi う. Artinya, kata tersebut merupakan kata kerja. Kanji itu sendiri artinya "benar", lalu apa bentuk kata kerjanya? Ini akan menjadi untuk mengoreksi.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Setelah kamu mengoreksi sesuatu untuk seseorang, kamu berteriak ta da (ただ) dengan sangat bersemangat. Silakan bayangkan diri Anda melakukan ini beberapa kali untuk membantu Anda mengingat.' WHERE id = 'df1e3f93-7f47-4e5d-a657-ef3090d2bc58'; -- 正す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dibandingkan dengan ini, di luar yang Anda inginkan. Anda akan memiliki selain itu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '38acce9f-36c1-4dcf-8c11-072ca784feb1'; -- 以外 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika memungkinkan untuk memisahkan sesuatu, maka sesuatu itu dapat dibagi. Bayangkan saja memisahkan sesuatu menjadi beberapa bagian. Itu mungkin. Jadi kalau bisa, itu habis dibagi. Sekarang pikirkan sesuatu yang bukan apa-apa (yaitu "tidak ada permen batangan"). Itu tidak mungkin dipisahkan menjadi beberapa bagian. Itu tidak dapat dibagi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '9e2fe102-763f-4dd4-b8f1-59d5acdd413f'; -- 可分 (vocabulary)
UPDATE items SET meaning_mnemonic = 'orang dari industri membuat banyak hal dengan tangan, jadi semua yang mereka buat adalah buatan, dan juga berarti buatan manusia.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Ingatlah hal ini dengan memikirkan bagaimana jeans (じん) adalah buatan. Anda belum pernah melihat jeans tumbuh di pohon, bukan? Tidak, jeans 100% buatan manusia.' WHERE id = 'c327cb8d-fe09-4a5c-9b89-d670d46ce553'; -- 人工 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kosakata yang terdiri dari satu kanji ini memiliki arti yang sama dengan kanji tunggal tersebut. Artinya adalah anjing.', reading_mnemonic = 'Karena ini adalah kata yang terdiri dari satu kanji dan tidak ada yang lain, Anda dapat berasumsi bahwa kata ini akan menggunakan bacaan kun''yomi. Pembacaan yang Anda pelajari untuk kanji ini kebetulan merupakan pembacaan kun''yomi juga. Jadi jika Anda tahu kanjinya, Anda tahu bacaannya.' WHERE id = '047fd314-c5a2-4ca6-9065-1df50b36a58a'; -- 犬 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda mempunyai anak sapi. Menurutmu anak sapi itu apa? Mungkin anak sapi atau bayi sapi.', reading_mnemonic = 'Karena kamu seharusnya mengetahui pembacaan kata 子 dan 牛 dari level sebelumnya, kamu juga harus bisa membaca kata ini meskipun menggunakan pembacaan kun''yomi untuk kanjinya.' WHERE id = '5391c288-647d-4686-af3b-5dd3de50ae67'; -- 子牛 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada garis di tanah sehingga Anda berhenti dan sebuah tanda raksasa muncul bertuliskan BENAR! Anda mematuhi peraturan lalu lintas dan melakukan hal yang benar.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Benar** (正) tiba-tiba berbicara dan meminta **Setan/Sapi**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **せい**.' WHERE id = 'eb24585c-7a09-42de-8633-59a57a02bab6'; -- 正 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda memiliki pribadi mulut yang merupakan mesin. Namun Anda harus merahasiakan mulut mesin Anda karena hal itu akan menakuti semua orang non-mesin di sekitar Anda.', reading_mnemonic = 'Bagaimana cara membaca kanji **Mesin** (台)? Ingat saja bahwa **Dadu/Dahi** sangat menyukai mesin! Hubungan erat ini akan membantu Anda mengingat bunyi **だい**.' WHERE id = '542d3210-7fbb-4f22-98e5-2880c92b401f'; -- 台 (kanji)
UPDATE items SET meaning_mnemonic = 'kiri tangan Anda adalah tangan kiri Anda! Kata ini juga dapat digunakan untuk mengartikan lengan kiri, dan sisi kiri.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Namun kata ini menggunakan bacaan kun''yomi. Hal ini mungkin karena 手, karena bagian tubuh sering menggunakan kun''yomi. Anda mempelajari kedua bacaan dengan kata-katanya masing-masing, jadi Anda seharusnya bisa membaca ini.' WHERE id = 'e0f76efd-5cb9-4719-b0f2-42d5777d6724'; -- 左手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kecil wanita adalah gadis atau wanita muda. Kata ini umumnya digunakan untuk menggambarkan seseorang yang berusia antara lima dan delapan belas tahun.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '9ca7fa68-e4eb-4f02-b35e-2fa20bd0206a'; -- 少女 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Timur Arah adalah Ke Timur atau Timur.

Kata ini memiliki kesan kuno.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'e5122b2b-df69-44f6-9a01-0efc9e34b417'; -- 東方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bayangkan seseorang mengulurkan tangannya. Ini rata-rata. Hal-hal yang dinilai di bawah kendali adalah hal-hal yang tidak Anda kuasai. Hal-hal yang dinilai di atas adalah hal-hal yang kuasai.', reading_mnemonic = 'Kedua kanji ini menggunakan bacaan on''yomi, meskipun 手 menggunakan bacaan on''yomi yang tidak Anda pelajari dengan kanji tersebut. Ini adalah bacaan yang langka, jadi tidak disertakan (dan kami hanya harus menangani pengecualian seperti ini seiring berjalannya waktu). Untuk mengingat bacaan kata ini, berikut mnemoniknya:

Apa yang kamu kuasai? Kamu benar-benar pandai mengajak Jourm (じょう) ke kebun binatang (ず). Tidak ada orang lain yang bisa membawa Jourm ke kebun binatang, dia marah dan melemparkan mereka ke kandang hewan. Tapi kamu? Jourm mempercayai Anda.' WHERE id = '2cb97827-0486-4265-a852-ccec1c46c8f5'; -- 上手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda mengetahui kedua kanji tersebut secara terpisah, Anda harus bisa menggabungkan keduanya sehingga membentuk arti dari kanji tersebut.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '6dbd3c77-8d1f-4d87-9851-6446cf3ff071'; -- 十台 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang berumur sedikit tahun adalah seseorang yang masih muda. Tapi, dulu orang Jepang dan Cina cenderung menyukai laki-laki, jadi yang satu ini artinya cowok, biasanya cowok. Maaf gadis-gadis! Gunakan kekesalan Anda pada kanji ini untuk mengingatnya dengan lebih baik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e95d8bb4-a9b7-4271-b2a6-0115d26b67f9'; -- 少年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal asal dan kanji asal adalah sama!', reading_mnemonic = 'Bagaimana cara membaca kanji **Asal** (元)? Ingat saja bahwa **Gendang/Genta** sangat menyukai asal! Hubungan erat ini akan membantu Anda mengingat bunyi **げん**.' WHERE id = '3b03bb02-17a8-400d-bdd3-b7e27df00075'; -- 元 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Kata ini menggunakan salah satu bacaan kanji yang Anda pelajari: ぶん. Anda dapat mengingat hal ini dengan memikirkan bagaimana setiap kali Anda sedang mengerjakan tulisan Anda, Anda merasa lapar dan ingin makan **Bunga/Buku**.' WHERE id = '1f6e24ad-ebe2-4c75-a659-5f0c0f4a1a67'; -- 文 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah segitiga kecil yang hampir tertutup seluruhnya. Saat Anda ingin sendirian, Anda bersembunyi di tempat di mana Anda bisa berada dalam pribadi. Itu sebabnya ini disebut radikal swasta. Anda menutup diri dari dunia luar, hanya dengan sedikit lubang intip.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '4d0f9a32-40f6-4753-8270-6269025b6fe4'; -- ム (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti pria yang lari ke kanan. Dia sedang menuju ke arah yang sangat berbeda. Ke arah mana lagi?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'efa2cc8d-a592-4ce1-8b40-e35cc02c43ed'; -- 方 (radical)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti memotong, dan bentuk kata kerjanya adalah to cut.', reading_mnemonic = 'Ketika Anda berpikir untuk memotong sesuatu, apa yang Anda pikirkan tentang memotong? Salah satunya adalah menebang pohon, yang juga dikenal sebagai 木, atau き. Anda きる dan き.' WHERE id = '9d8f66c6-133d-4aa8-9586-001bfbc492c9'; -- 切る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Jika digunakan sebagai prefiks, kata ini memiliki arti terkait dengan ex- atau mantan.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda mencoba melacak asal usul seseorang sehingga Anda dapat mempelajari lebih lanjut tentang orang tersebut. Anda akhirnya sampai di sana - itu adalah sebuah kastil. Masalahnya adalah tempat itu dikelilingi oleh parit besar (もと) dan kamu tidak bisa melewatinya karena jembatan angkatnya sudah terpasang. Rasakan frustrasinya ini. Pikirkan tentang tujuan Anda dan seberapa dekat Anda untuk mencapainya jika bukan karena parit yang buruk ini.' WHERE id = 'eebb8345-8b06-44ed-85f2-1dc822e4cfbe'; -- 元 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hal utama yang Anda bicarakan dalam bahasa Anda menjadi subjek kalimat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '838faea9-7545-4b76-8896-fceaa4c5b42b'; -- 主語 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki dua kaki yang membentuk radikal ini. Di antara dua kaki adalah tempat asalmu, tidak peduli bagaimana kamu melihatnya. Kedua kaki ini adalah asal Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1c6f4519-94ba-4430-9fa4-d8219ed0c71c'; -- 元 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal tangan dan kanji tangan identik dalam tampilan dan makna! Itu seharusnya membuat segalanya menjadi mudah!', reading_mnemonic = 'Bagaimana cara membaca kanji **Tangan** (手)? Ingat saja bahwa **Teko/Tenda** sangat menyukai tangan! Hubungan erat ini akan membantu Anda mengingat bunyi **て**.' WHERE id = 'fe1c12e2-592c-4085-8db1-16e923d27772'; -- 手 (kanji)
UPDATE items SET meaning_mnemonic = 'cara yang Anda lihat adalah cara melihat sesuatu. Ini seperti ketika seseorang mempunyai opini bodoh dan Anda seperti "oh, oke, jadi itu salah satu cara untuk melihatnya..."', reading_mnemonic = 'Ini menggunakan pembacaan kun''yomi dari vocab kata 見る dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = '8d1fef41-3af1-49c5-994a-33c98e5554fa'; -- 見方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal sawah dan kanji sawah adalah sama, membuat yang satu ini sangat mudah diingat, setidaknya dari segi makna.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Peternakan** (田), bayangkan Anda sedang membawa **Tali/Tahu** untuk ditaruh di atas peternakan. Kejadian unik ini mengingatkan Anda pada bunyi **た**!' WHERE id = '84f71e6f-71f0-4637-af05-0d2f448e088b'; -- 田 (kanji)
UPDATE items SET meaning_mnemonic = 'Kosa kata ini memiliki sedikit tambahan yang aneh (べ). Anda bisa mengabaikannya, itu tidak berarti apa pun secara khusus. Arti kosakata ini dan kanji asalnya sama: malam', reading_mnemonic = 'Ketika hiragana dilampirkan pada sebuah kanji, Anda biasanya dapat berasumsi bahwa kanji tersebut akan dibaca menggunakan pembacaan kun''yomi, dan itulah yang terjadi dengan kata ini juga. Dengan mempelajari kanji kata ini, Anda juga mempelajari cara membaca kata tersebut.' WHERE id = '7ee772b1-383d-4b2f-a9f2-904be213eac5'; -- 夕べ (vocabulary)
UPDATE items SET meaning_mnemonic = '主 berarti main sehingga ketika Anda menambahkan に itu menjadi kata keterangan mainly.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda terutama menghabiskan waktu Anda berbicara dengan master Anda, Moe. Tapi Anda biasanya memanggilnya seperti, "Oh Moe Yang Agung!" (おも). Itu karena dia lebih tinggi darimu. Bayangkan diri Anda berkata "OH MOE YANG HEBAT!" saat Anda masuk ke kamarnya, membungkuk rendah.' WHERE id = 'cd887337-06d0-42fe-93f2-8b5ddc013034'; -- 主に (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki kecil slide. Hal yang menarik tentang perosotan kecil adalah bahwa perosotan tersebut hanya dapat memuat beberapa orang dalam satu waktu.', reading_mnemonic = 'Tahukah Anda bahwa **Sedikit** (少) ini sebenarnya dibuat dari tumpukan **Sopir/Soto**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **しょう**.' WHERE id = '43918d15-2ac3-4a22-ba0d-1d6ac7801352'; -- 少 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji malam dan kanji malam adalah sama. Jika Anda tahu radikalnya Anda pasti tahu arti kanjinya.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Sakit** (夕), bayangkan Anda sedang membawa **Yuda** untuk ditaruh di atas sakit. Kejadian unik ini mengingatkan Anda pada bunyi **ゆう**!' WHERE id = '784c84f4-6c23-4835-bcf4-44f6136c66e9'; -- 夕 (kanji)
UPDATE items SET meaning_mnemonic = 'Jumlah orang yang mempunyai mulut (yang harus Anda beri makan) adalah populasi yang harus Anda beri makan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Di Tofugu, kami mengukur populasi yang mengenakan jeans (じん). Masing-masing dari kita hanya memiliki satu celana jeans, jadi jika Anda mengetahui jumlah jeans, Anda juga mengetahui populasinya.' WHERE id = '14b06b15-1e68-4cd2-b6ec-9fe0795dfb38'; -- 人口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dunia dan kanji dunia adalah sama, namun ada arti lain yang sangat penting yang perlu Anda ketahui: generasi. 

Anggap saja seperti ini: dunia ini terdiri dari banyak generasi manusia, tumbuhan, dan hewan yang hidup bersama-sama.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Dunia** (世), bayangkan Anda sedang membawa **Setan/Sapi** untuk ditaruh di atas dunia. Kejadian unik ini mengingatkan Anda pada bunyi **せい**!' WHERE id = '57039dbc-7af0-4505-be71-08d09465e212'; -- 世 (kanji)
UPDATE items SET meaning_mnemonic = 'singa menjatuhkan setetes air liur ke orang dari di atas. Orang tersebut berada di tempat yang jauh lebih buruk dibandingkan di mana mereka sebelumnya, karena mereka baru saja jatuh ke dalam lubang ini.', reading_mnemonic = 'Ketika Anda sedang melihat **Dari** (以), tiba-tiba muncul sesosok **い** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **い**.' WHERE id = '0dedcc46-3e44-403e-91d4-a75ed65d4a64'; -- 以 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda pasti tahu 人気 yang artinya "populer". Dan Anda juga tahu bahwa 不 berarti "tidak". Lalu apa yang Anda dapatkan jika menggabungkan keduanya? Sesuatu yang tidak populer atau tidak populer.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '1055c12b-223c-47c0-b98a-fea7b377b758'; -- 不人気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Penghitung ini digunakan dengan beberapa jenis mesin, biasanya yang berukuran cukup besar (jadi tidak ada yang terlalu kecil). Mobil adalah contoh yang bagus untuk hal ini. Namun dapat juga digunakan untuk benda-benda seperti komputer, yang dulunya berukuran ruangan, namun kini menjadi bagus dan kecil. Terima kasih teknologi!', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji. Pastikan untuk menghilangkan 〜 dalam jawaban Anda karena ini hanya pengganti angka.' WHERE id = 'fe242365-0857-4753-85d1-7ee0ab378393'; -- 〜台 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti berhenti dan versi kosakata kata kerjanya adalah menghentikan sesuatu.

Kata khusus ini adalah ketika Anda menghentikan sesuatu (yaitu melakukan tindakan menghentikannya).', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda memerlukan untuk menghentikan sesuatu agar tidak bergerak. Mungkin mobil... atau pintu... atau seseorang... apa pun yang Anda inginkan. Untuk menghentikan hal ini, kamu membuang jari kakimu (と), sehingga menyebabkan jari kakimu hancur. Bayangkan itu berdarah dan bengkak. Betapa sakitnya! Anda berusaha sekuat tenaga untuk menghentikan hal besar ini, sungguh suatu kesalahan!' WHERE id = '021346c8-94de-4a4f-839e-d941a551bd4e'; -- 止める (vocabulary)
UPDATE items SET meaning_mnemonic = 'mulut yang Anda masukkan adalah pintu masuk.', reading_mnemonic = 'Kata ini sebenarnya adalah dua kata terpisah yang digabungkan menjadi satu, jadi mari kita lihat dalam dua bagian:

Kanji 入 memiliki り yang melekat padanya sebagai okurigana (hiragana yang muncul setelah kanji), jadi bisa dipastikan 入り akan menggunakan pembacaan kun''yomi untuk kanjinya. Anda belum mempelajari bacaan ini, jadi inilah mnemonik untuk membantu Anda:

pintu masuk yang Anda lalui sungguh menakutkan (いり). Ada sarang laba-laba dan ukiran sosok menyeramkan di dalamnya, dan itu memberi Anda perasaan yang sangat menakutkan.

Karena 入り menggunakan kun''yomi, Anda dapat menebak bahwa 口 akan mengikutinya. Anda mempelajari bacaan ini dengan kosakata, tetapi く di くち berubah menjadi ぐ karena sesuatu yang disebut rendaku. Anggap saja ini sebagai pintu masuk yang menakutkan ke dalam toko Gucci (ぐち).' WHERE id = 'f71a1465-b502-4e67-8fd9-cea3d347433d'; -- 入り口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tidak ada lingkaran dalam kanji, ingat? Jadi bayangkan sudut-sudut ini benar-benar berbentuk lingkaran. Lingkaran kecil dalam lingkaran besar, dengan garis melewatinya. Ya, itulah dunia. Dunia terlihat seperti ini, dengan benua di dunia dan sebuah garis adalah garis khatulistiwa. Bisakah kamu melihatnya?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '4e45c6ae-cbba-4d18-9d48-2fa2532ffc74'; -- 世 (radical)
UPDATE items SET meaning_mnemonic = 'melakukan cara pada dasarnya adalah "cara melakukan" sesuatu. Sederhananya, ini adalah metode. "Apa caramu melakukan ini?" Tidak tidak tidak. “Apa METODEmu.” Ini dia.', reading_mnemonic = 'Kata ini menggunakan bacaan on''yomi untuk kanji pertama 仕, dan bacaan kun''yomi untuk kanji kedua 方, jadi berhati-hatilah! Anda sudah mempelajari kedua bacaan ini, jadi Anda harus bisa membaca ini!' WHERE id = 'a172593d-4371-4597-9c38-b7a18d42d85d'; -- 仕方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal kecil ini adalah tetesan air atau cairan lainnya. Perhatikan bagaimana itu hanya satu tetes? Terkadang radikal atau kanji memiliki lebih dari satu huruf, jadi penting bagi Anda untuk mengetahui cara membedakannya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7a124b58-3465-4b16-9d7c-9ce2d81b5c46'; -- 丶 (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Berikut ini mnemonik untuk membantu Anda mengingatnya: 

Karena Anda memiliki generasi-generasi yang membentuk world ini, pikirkanlah generasi rapper. Apa yang selalu mereka katakan (tentu saja saya tidak tahu apa-apa tentang rap)? Mereka berkata "Yo yo yo!" (よ).' WHERE id = '7f934a69-935a-45e5-9d8c-10333d720118'; -- 世 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anak anjing adalah anak anjing!', reading_mnemonic = 'Meskipun ini kata jukugo, namun tidak menggunakan bacaan on''yomi. Baik kanji 子 dan 犬 sering kali menyukai pembacaan kun''yomi, dan kata ini tidak terkecuali. Bacaan 犬 adalah bacaan yang sudah anda ketahui, dan bacaan untuk 子 sebagai こ adalah bacaan yang sangat umum (mungkin anda sudah mempelajari bacaan tersebut?). Jika tidak, pikirkan saja untuk meninju wajah anak anjing dan memberinya KO (Itu KO).' WHERE id = '7a57f3cd-55a2-444e-a4c9-55a6287b327f'; -- 子犬 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda melihat radikal ini dalam sebuah kanji, Anda pasti ingin memikirkan kebalikan dari radikal apa pun yang ada. Kelihatannya sangat mirip "di bawah", tapi coba tebak? Ini bukan yang di bawah radikal. Hanya saja tidak.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9dcc7e8e-fadc-474d-8fba-0fd5b557d21d'; -- 不 (radical)
UPDATE items SET meaning_mnemonic = 'Tutup mata Anda dan bayangkan Anda menjadi anak-anak lagi. Sekarang buka dan... lihat! Itu adalah slide! Bayangkan Anda meluncur ke bawah slide ini berulang kali, bersenang-senang. Imajinasi + emosi menghasilkan hafalan yang baik!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9de45f4d-39b5-4b91-9d16-84f4d4620c23'; -- 丿 (radical)
UPDATE items SET meaning_mnemonic = 'Bentuknya seperti bangku dengan penutup, namun sebenarnya ini adalah meja tulis. Apakah kamu melihatnya? Ini tempat yang bagus dan tenang untuk menulis. Anda bahkan dapat melihat pena mencuat di tengah. Tidakkah Anda ingin menulis di sini?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '97d9b601-356a-44d2-bb19-212d3030602e'; -- 文 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti orang dengan gaun panjang atau kereta api yang berjalan di belakangnya. Itu karena calon pengantin akan menghadiri upacara pernikahan mereka! Biasanya Anda harus mengenakan gaun panjang atau jubah jika berada di sebuah upacara. Jadi ketika Anda melihat hal radikal ini, pikirkan semua upacara berbeda yang mungkin harus Anda hadiri dalam hidup Anda dan apa yang perlu Anda kenakan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'fe2e6a28-9f37-480f-a2ef-25135ff5a3c3'; -- 弋 (radical)
UPDATE items SET meaning_mnemonic = 'Perhatikan baik-baik yang ini. Bentuknya seperti hati (namun, bukan hati pada Hari Valentine pada umumnya). Pikirkan hati yang nyata. Pada dasarnya, terdapat benjolan (jantung) di tengahnya, dan tiga garis yang membentuk arteri yang masuk dan keluar dari jantung untuk membuat Anda tetap hidup. Radikal ini sering muncul, jadi tidak akan terlalu sulit untuk mempelajarinya seiring berjalannya waktu. Ingat, benjolan (jantung) ditambah pembuluh darah sama dengan jantung… seperti, jantung asli, bukan palsu, cantik.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'da98c2a3-db4f-4217-8fb1-570bfce7105e'; -- 心 (radical)
UPDATE items SET meaning_mnemonic = 'Ada salib dan pistol, dengan pistol menembus salib. Anda menggunakan salib untuk menstabilkan senjata Anda, karena Anda harus menembak sapi untuk makan malam. Anda membawa salib Anda karena Anda perlu memberkati sapi itu setelah Anda membunuhnya (dan itu juga merupakan tempat yang baik untuk senjata Anda). Sapi yang malang.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '26564c95-7e33-4658-87d6-1d0216972ea1'; -- 牛 (radical)
UPDATE items SET meaning_mnemonic = 'Ini terlihat seperti kalender dengan ruang untuk Anda tuliskan dalam tugas Anda untuk hari itu. Lihat bagian kosong itu? Pastikan Anda menuliskan tugas harian Anda, agar tidak lupa melakukan sesuatu yang penting!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5982d2d2-b74d-4059-ae6f-c5cd5765cef6'; -- 用 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal berbentuk L ini adalah radikal singa, karena "L berarti Singa". Ini juga terlihat seperti mulut singa yang terbuka sangat-sangat lebar. Bayangkan seekor singa membuka mulutnya untuk menguap. Sepertinya ini radikal!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0b702446-a297-447f-a803-0cd18a4f486a'; -- L (radical)
UPDATE items SET meaning_mnemonic = 'Ingat orang besar yang membantu Anda mengingat orang radikal besar? Sekarang lelaki besar itu mempunyai sesuatu di bahunya... apa itu? Anda melihat dan melihat bahwa dia memiliki seekor anjing di atas sana, bertengger seolah-olah itu adalah burung beo atau kucing atau semacamnya. Anjing tidak seharusnya berada di pundak orang seperti itu, tapi untuk dia? Itu berhasil!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'ed00bbcd-79b2-4970-94b3-cc640db13ede'; -- 犬 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal dan makna kanji ini sama. Keduanya adalah kekuatan.', reading_mnemonic = 'Ketika Anda sedang melihat **Kekuatan** (力), tiba-tiba muncul sesosok **Roti/Roda** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **りょく**.' WHERE id = 'e0f1e139-fa80-4e51-96d8-60a9f9e6deb1'; -- 力 (kanji)
UPDATE items SET meaning_mnemonic = 'listrik kekuatan sesuatu adalah tenaga listrik-nya.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 力 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Seluruh tenaga listrik di dunia disimpan di balik gembok ini (りょく). Teruskan. Bukalah. Apa yang mungkin salah?' WHERE id = 'fcd22869-0520-4652-a5b8-92cfa213e9ea'; -- 電力 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini mempunyai arti yang mirip dengan 主人 (kepala rumah tangga). Anda juga dapat mengingatnya sesuai makna yang Anda pelajari dengan kanji 主, yaitu master.', reading_mnemonic = 'Pembacaannya tentu saja berbeda dengan yang Anda pelajari dengan kanji. Pikirkan ini:

Orang yang menjadi kepala rumah tangga Anda sangat ketat. Setiap kali kamu melakukan sesuatu yang salah atau buruk, dia akan mencabut talinya (ぬし), tapi dia akan menyebutnya "noosey" karena lucu, karena kamu masih kecil.' WHERE id = 'b2fa04eb-2ccf-4dc9-87df-ac93916dd589'; -- 主 (vocabulary)
UPDATE items SET meaning_mnemonic = 'cara berbicara adalah cara berbicara Anda (atau bisa juga gaya berbicara Anda). Beginilah cara seseorang berbicara. Beberapa orang punya gaya bicara yang menarik.', reading_mnemonic = 'Ini menggunakan pembacaan kun''yomi dari vocab kata 話す dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = 'a80277d7-f014-4843-ac6a-c84f9a971f45'; -- 話し方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal konstruksi dan kanji konstruksi adalah sama!

Kanji ini juga berarti industri, yaitu konstruksi jika dipikir-pikir. Itu semua adalah bagian dari industri konstruksi.', reading_mnemonic = 'Ketika Anda sedang melihat **Konstruksi** (工), tiba-tiba muncul sesosok **Koko/Koki** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **こう**.' WHERE id = 'a5cfd66d-fe67-46e6-ad66-0985b005eb1d'; -- 工 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal untuk tugas terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti tugas.', reading_mnemonic = 'Ketika Anda sedang melihat **Tugas** (用), tiba-tiba muncul sesosok **Yoga** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **よう**.' WHERE id = '055ac98c-0e93-4444-87f6-f8b4bc9fa77b'; -- 用 (kanji)
UPDATE items SET meaning_mnemonic = 'Dibandingkan dengan yang lain, ini di atas. Itu cara lain untuk mengatakan bahwa apa yang Anda miliki adalah lebih dari sesuatu yang lain. Itu saja. ;)', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '257c3a39-5432-4dbf-9b42-7541ae601873'; -- 以上 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal mulut dan kanji mulut sama persis!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Mulut** (口), bayangkan Anda sedang membawa **Koko/Koki** untuk ditaruh di atas mulut. Kejadian unik ini mengingatkan Anda pada bunyi **こう**!' WHERE id = 'a9d7ef1e-70fc-430f-9cdf-36b5bc38d960'; -- 口 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal untuk menulis terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti tulisan.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Menulis** (文) tiba-tiba berbicara dan meminta **Bunga/Buku**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ぶん**.' WHERE id = 'fdb76ab7-02d9-4791-9280-71b45e40ae94'; -- 文 (kanji)
UPDATE items SET meaning_mnemonic = 'Diakhiri dengan い memberitahu Anda bahwa kata ini adalah kata sifat い. Jadi karena Anda tahu bahwa kanji 正 berarti "benar", apa versi kata sifat dari kata tersebut? Ya, itu juga benar.', reading_mnemonic = 'Kata ini menggunakan bacaan yang tidak Anda pelajari dari kanji. Anda harus mengingat bagian ただ untuk membaca kata ini, jadi pikirkan seperti ini:

Setelah kamu mendapatkan jawaban benar tiba-tiba ada badut yang melompat keluar sambil berteriak "TA DA!!!" Bayangkan hal itu juga membuat Anda takut.' WHERE id = 'd61f1cbd-c8ed-4247-97fe-744051d510c0'; -- 正しい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada jari kaki raksasa dan tongkat di tanah di depan Anda. Anda mengendarai mobil Anda ke arah mereka, tetapi Anda tidak melihatnya sampai lampu Anda menyinari mereka. Hal-hal ini menyebabkan Anda melakukan apa? Kemungkinan besar menghentikan mobil Anda segera.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5083654b-e17f-4c61-a5df-5f1131393d99'; -- 止 (radical)
UPDATE items SET meaning_mnemonic = 'Kata radikal ini secara teknis berarti orang (seperti 人), namun kita akan mengubah maknanya sedikit. Ini seperti orang radikal, tapi lebih tinggi dan lebih kurus, berdiri di atas prajurit infanteri lainnya. Itu sebabnya dia adalah pemimpin, bukan orang tua biasa.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'ae029774-b184-41ec-b673-8c9dffabd852'; -- ｲ (radical)
UPDATE items SET meaning_mnemonic = 'Bagian kanji dari kata ini seperti mengatakan "the doing way" ... alias cara kamu melakukan sesuatu. Jadi, ketika Anda tidak punya cara untuk melakukan sesuatu, tidak ada yang bisa Anda lakukan. Maka lahirlah ungkapan populer dalam bahasa Jepang: 仕方がない, yang berarti tidak dapat ditolong, tidak ada gunanya, atau tidak ada jalan lain. Ini adalah ungkapan yang sangat bagus untuk mengetahui apakah Anda berada di Jepang.', reading_mnemonic = 'Anda sudah mengetahui cara membaca ini setelah mempelajari 仕方, jadi sebaiknya Anda segera melakukannya!' WHERE id = '81a96bdc-be03-478f-8ec5-6ee9accaa5ae'; -- 仕方がない (vocabulary)
UPDATE items SET meaning_mnemonic = 'berhenti yang hanya beristirahat (alias tidak permanen) bukanlah perhentian langsung. Anda berencana untuk melanjutkan lagi. Itu sebabnya ini disebut jeda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '4290cfdb-35ca-44f5-b1c1-47f98b0d600c'; -- 休止 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji anjing radikal dan anjing sama persis!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Anjing** (犬) tiba-tiba berbicara dan meminta **いぬ**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **いぬ**.' WHERE id = '0ab21533-8d9d-474c-9269-c80ecc0cfdb3'; -- 犬 (kanji)
UPDATE items SET meaning_mnemonic = 'Menambahkan "generasi ketiga" pada nama seseorang berarti mereka adalah generasi ketiga dari orang-orang dengan nama tersebut. Dalam hal ini, nama orang tersebut adalah ナポレオン (Napoleon), jadi ini berarti Napoleon The Third, juga ditulis sebagai Napoleon III.', reading_mnemonic = 'Kanji di sini diucapkan persis sama dengan kata yang berdiri sendiri 三世. Artinya, itu adalah kata jukugo yang menggunakan on''yomi untuk kedua kanjinya.' WHERE id = '7ea5a5bd-1fca-4aa8-a598-f287796f830f'; -- ナポレオン三世 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Pikirkan kembali masa lalu. Dulu ketika keputusan dibuat dengan pedang. besar potongan akan menjadi penting. Bayangkan saja sepasang samurai bersiap-siap, lalu menyerbu, lalu membuat satu tebasan besar. Itu adalah hal terpenting yang akan mereka lakukan dalam hidup mereka (jika mereka masih hidup!).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Sangatlah penting untuk menjaga ikatan Anda tetap dalam set (たいせつ). Jika Anda tidak mengaturnya dengan rapi dalam beberapa set, polisi dasi mungkin akan datang mengetuk pintu Anda dan membawa Anda bersama mereka!' WHERE id = 'ba65942b-d55f-4398-94b7-b57ce8811391'; -- 大切 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri artinya "berdiri", lalu apa versi kata kerjanya? Itu adalah berdiri.', reading_mnemonic = 'Anda harus mengingat bagian た dari kata ini untuk mempelajari cara membacanya. Pikirkan seperti ini: 

Anda harus berdiri untuk melambaikan tangan kepada seseorang. Saat kamu berdiri, kamu juga mengucapkan ta ta (た)!' WHERE id = '61ca5759-bfc5-4c0e-88cb-e69cdcf9891a'; -- 立つ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mudah-mudahan Anda sudah mengetahui bahwa 力 berarti "kekuatan". Anda mungkin juga pernah mendengar kata いっぱい, karena kata tersebut sering digunakan dalam percakapan. Ini memiliki beberapa arti (Anda akan mempelajarinya lebih lanjut nanti) tetapi yang penting di sini adalah "penuh" atau "banyak". Gabungkan kedua kata ini dan Anda akan memiliki kekuatan penuh, dengan segenap kekuatan, dan sekeras yang bisa. Ingat yang ini dengan segenap kekuatanmu!

Sekadar catatan tambahan: いっぱい juga bisa ditulis dalam kanji, yang akan Anda pelajari nanti! Namun, dalam kata sederhana seperti ini biasanya ditulis dalam kana.', reading_mnemonic = '力 menggunakan bacaan yang sama seperti yang Anda pelajari dengan kosakata. Itu karena pada dasarnya ini adalah dua kata terpisah yang disatukan.' WHERE id = 'f24ac386-ef4f-4a03-ac8b-2eb7a1c262ef'; -- 力いっぱい (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini memiliki kanji untuk satu dan periode. Anda hanya mempunyai satu periode untuk hidup, jadi ini adalah satu-satunya seumur hidup yang Anda dapatkan. Kecuali jika Anda dilahirkan kembali, tapi itu mungkin terjadi di zaman berikutnya, bukan di zaman ini. Jadi satu seumur hidup untukmu!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'a8e46ef1-886a-4536-b007-232680859d7e'; -- 一代 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti "berdiri" dan ini berarti mendirikan sesuatu. Ini juga bisa berarti untuk membuat sesuatu, baik dalam arti fisik, seperti membuat suara, maupun dalam arti mental, seperti membuat rencana. 

Jangan bingung membedakannya dengan 立つ. 立てる berarti Anda sedang mempertahankan sesuatu. Seperti dalam, "Saya berdiri sebagai figur aksi" atau "Saya akan mengibarkan bendera". Anda melakukan tindakan untuk hal lain.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian た. Untuk melakukan itu, bayangkan diri Anda sedang berdiri di atas papan besar. Di atasnya, tertulis dengan kata-kata besar:
"ta ta (た)!"' WHERE id = '2b2fcd77-056b-4a29-bba8-5934da191c11'; -- 立てる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 入り口 berarti masuk dan 出口 berarti keluar? Ini hanyalah bagian 口 dengan petunjuk arahnya. Artinya bisa menjadi pintu masuk atau keluar. Jadi jika ada Timur di sana, kata ini bisa berarti Pintu keluar Timur dan Pintu masuk Timur. Ini adalah kata yang bagus untuk diketahui jika Anda ingin mengetahui sisi stasiun kereta mana yang harus Anda tinggalkan untuk pergi ke suatu tempat atau bertemu seseorang!', reading_mnemonic = 'Kata ini menggunakan bacaan kun''yomi, kemungkinan karena 口 yang merupakan bagian tubuh (bagian tubuh sering melakukan hal tersebut dalam kata dan kanji). Mudah-mudahan Anda telah melihat kedua bacaan kun''yomi dari level sebelumnya yang berarti Anda dapat membaca kata ini juga. Hati-hati dengan rendaku yang mengubah くち menjadi ぐち.' WHERE id = 'ceb89c19-ef90-49ed-9621-e07d3349d183'; -- 東口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Masukkan sesuatu dengan seluruh kekuatan Anda dan Anda akan melihat ke bawah untuk melihat bahwa yang Anda lakukan adalah memasukkandata. Anda sedang memasukkannya sekarang! Ke situs ini! Jawaban yang Anda masukkan ke dalam WaniKani dengan seluruh kekuatan Anda dapat diucapkan dengan kata ini. Wow. Lingkaran penuh sudah, dan Anda baru berada di level 2. Lihat, lanjutkan!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 力 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Di tempat Anda bekerja, memasukkanmemasukkan sesuatu akan memberi Anda kunci baru (にゅうりょく). Pekerjaan Anda tidak hanya sekedar memasukkaning sesuatu ke dalam komputer, Anda juga dibayar secara eksklusif di kunci baru. Mungkin pertimbangkan perubahan karier!' WHERE id = '76bd3e6d-c3c3-4b78-8c02-f41c269fcc1d'; -- 入力 (vocabulary)
UPDATE items SET meaning_mnemonic = 'master orang bukan hanya seorang master. Anda harus mengingat kembali saat mereka membuat kanji ini. Siapa masternya? Itu adalah kepala rumah tangga. Kepala rumah tangga ini mungkin menyuruh pelayannya apa yang harus dilakukan dan dia suka memerintah dan sebagainya. Dia adalah orang yang ahli. 

Selain itu, kata ini juga sering berarti suami. Sebab, menurut saya, kepala rumah tangga pada masa itu adalah suami. Orang-orang kuno yang seksis itu!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Di Jepang, tradisi mengatakan kepala rumah tangga harus turun dari saluran hanya dengan mengenakan jeans (しゅじん). Kapan pun Anda perlu berbicara dengan kepala rumah tangga, mereka akan turun dari saluran hanya dengan mengenakan celana jins. Pemandangan yang luar biasa!' WHERE id = 'c3b7afb6-5602-4014-946d-80fab9ec1535'; -- 主人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Untuk mengingat arti kata ini, coba pikirkan bagaimana di masa lalu, sebelum perforasi ditemukan, orang harus memotong prangko mereka dengan tangan. Butuh waktu lama, terutama jika Anda memiliki banyak teman yang bisa Anda kirimi surat. Bersyukurlah bahwa perforasi diciptakan untuk menghemat waktu Anda saat memotongnya.', reading_mnemonic = 'Anda mungkin mengira bacaan ini terdiri dari bacaan on''yomi, tetapi bagian tubuh manusia (tangan) melakukan hal-hal lucu pada kata-kata. Dalam hal ini, pembacaan kun''yomi dari kedua kanji tersebut. Anda harus mengetahui bacaan kun''yomi untuk 切 dan 手 dari level sebelumnya, artinya Anda harus dapat mengingat bacaan kata ini dengan cukup mudah. Hati-hati dengan っ yang kecil.' WHERE id = '66c8800c-20f2-458f-8d58-4953b682350f'; -- 切手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika tidak mungkin memisahkan sesuatu menjadi bagian, maka hal tersebut tidak dapat dibagi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '15fab8f7-3fa7-4d2b-bd10-99eb31a5979d'; -- 不可分 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja.

Ini adalah kata kerja intransitif. Artinya tidak mengambil objek secara langsung. Kanji berarti memotong jadi secara umum ini berarti ada sesuatu yang dipotong. Sesuatu rusak atau patah. Tidak ada objek langsung di sini. Itu sebabnya kata kerja ini berarti dipotong atau menjentikkan. Arti lain dari kata kerja ini adalah kedaluwarsa atau kehabisan. Ini bisa berupa berbagai hal seperti paspor Anda, atau batas waktu suatu tugas.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Berikut penyegaran untuk membantu Anda mengingat bagian き dari kata ini: 

Ada yang snapping. Ternyata ada sesuatu di lenganmu. Lenganmu adalah 木 (き) yang tumbuh dari dirimu suatu hari nanti. "Apa yang ki ini lakukan di sini?" kamu bertanya. Lalu tiba-tiba pecah menjadi dua! "OW OW OW! Ki-ku! Sudah dipotong!!"' WHERE id = '98f31d19-7a9f-428d-8514-f0347d1a3772'; -- 切れる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti tugas atau penggunaan. Anda dapat menganggap kata kerja ini sebagai cara yang lebih formal untuk mengatakan to use, dan itu adalah to use.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajari bacaan tersebut dengan kanji ini, jadi inilah mnemonik untuk membantu Anda mempelajari bagian もち dari もちいる: 

Apa yang akan Anda manfaatkan untuk menyelesaikan pekerjaan? Anda memiliki mochi (もち) di tangan Anda, jadi Anda akan menggunakannya. Sekarang pikirkanlah tugas khayalan yang akan Anda selesaikan dengan mochi, buatlah tugas itu sekonyol mungkin.' WHERE id = '60528dc7-429c-4966-ae26-82376bf6edee'; -- 用いる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja.

Ini adalah kata kerja intransitif. Artinya tidak mengambil objek secara langsung. Sesuatu terhenti. Tidak ada objek langsung di sini. Itu sebabnya kata kerja ini berarti berhenti.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda datang ke rambu berhenti dan memutuskan untuk berhenti karena rambu tersebut mempunyai gambar jari kaki (と) di atasnya. Jari kaki ini terlihat sangat mirip dengan jari kaki yang dimiliki ibumu (ま)... dan ibumu selalu mengajarimu untuk berhenti dan melihat ke dua arah sebelum menyilangkan jari kakinya.' WHERE id = '220e17cd-1c0b-4cc6-ab2f-a19f6ed24af9'; -- 止まる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini berupa kanji tunggal dengan hiragana di dalamnya, meskipun tidak ada petunjuk spesifik mengenai jenis kata tersebut. Artinya, biasanya Anda dapat menebaknya apakah itu kata benda, kata keterangan, atau kata sifat na (dalam hal ini kata benda/kata keterangan). Arti kata ini hampir sama dengan kanji, namun membuatnya cukup mudah. Arti kanji untuk 少 adalah sedikit, dan arti bentuk kosakatanya adalah sedikit atau beberapa.', reading_mnemonic = 'Tahukah Anda bahwa kata ini menciptakan kata dalam bahasa Inggris yang mungkin sudah Anda ketahui? Pernahkah Anda mendengar seseorang berkata "hanya skosh"? Itulah 少し! Semoga Anda mengetahui kata dalam bahasa Inggris ini dan karena itu mengetahui kata dalam bahasa Jepang ini juga.' WHERE id = 'aee5d7f5-f9cc-42da-a970-e1bed90c9685'; -- 少し (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa ini ada hubungannya dengan membacadan Anda tahu bahwa 方 berarti cara atau metode. Jadi, ketika Anda memikirkan "cara membaca", Anda dapat memikirkan beberapa kata lain yang lebih baik, seperti membaca (alias membaca sebuah kata) atau pengucapan. Kapan pun Anda ingin mengetahui bunyi sesuatu, inilah yang akan Anda minta.', reading_mnemonic = 'Ini menggunakan bacaan kun''yomi dari vocab kata 読む dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = '91ab7580-beac-4333-9119-f4e58429ee99'; -- 読み方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Mulut Selatan sebenarnya bukan mulut yang Anda temukan di kutub selatan atau apa pun, itu adalah pintu masuk atau keluar. Ini seperti 入り口 yang berarti pintu masuk (口 melambangkan pintu). Anda akan sering melihat kata ini di tempat-tempat seperti stasiun kereta atau bandara. Artinya Pintu keluar selatan dan Pintu masuk selatan.', reading_mnemonic = 'Pembacaan kanji ini sama-sama kun''yomi. Mungkin karena dua kata disatukan (Selatan + Keluar) dan bukan satu kata. Selain itu, bagian tubuh juga cenderung mengubah kata menjadi bacaan kun''yomi. Jadi, Anda pernah melihat kosakata yang memberi Anda pembacaan kun''yomi dari 南 dan 口, bukan? Sekarang Anda hanya perlu menggabungkan kedua bacaan vocab tersebut menjadi satu untuk bisa membaca kata tersebut. Hati-hati dengan rendaku yang mengubah くち menjadi ぐち.' WHERE id = 'e46f1cc1-ae15-459d-944c-2090f063b2a3'; -- 南口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sebuah kosakata terdiri dari satu kanji tanpa okurigana (hiragana yang melekat pada kanji), secara umum maknanya akan sama dengan kanji asalnya. Dari situ kamu tahu arti kata ini adalah mulut.', reading_mnemonic = 'Ketika kosakata terdiri dari satu kanji tanpa okurigana (hiragana melekat pada kanji) umumnya akan menggunakan bacaan kun''yomi, yang tidak Anda pelajari dari mempelajari kanji. Untuk mengingat kata ini, Anda harus menggunakan mnemonik. Dengan mulut Anda, buatlah suara "kuchi kuchi kou" (くち). Silakan, buatlah. Fokus pada mulut Anda dan coba bayangkan setiap bentuk yang dihasilkan sambil memperbesarnya. Anda sedang berbicara dengan bayi, itulah sebabnya Anda mengeluarkan suara-suara konyol ini. Selain itu, alih-alih "coo" di akhir, Anda malah mengucapkan "kou", karena itulah pembacaan kanji (こう).

くちくちこう！くちくちこう！ Sebenarnya terdengar seperti sesuatu dari Arrested Development.' WHERE id = '6eb9541f-cfdb-457e-8a08-40bc9d4032e8'; -- 口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaan kata ini sama dengan bacaan kun''yomi yang kamu pelajari untuk kanjinya, artinya kamu harus mengetahui keduanya!' WHERE id = '2685a800-3d32-4359-9146-5b25f73f06b0'; -- 冬 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kanopi yang Anda gunakan di pribadi sangat lebar.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Lebar** (広), bayangkan Anda sedang membawa **ひろ** untuk ditaruh di atas lebar. Kejadian unik ini mengingatkan Anda pada bunyi **ひろ**!' WHERE id = '8876edc5-41bb-4478-9fd9-9ab384f7deb2'; -- 広 (kanji)
UPDATE items SET meaning_mnemonic = 'Siapakah seseorang yang hanya mulut dengan kaki? Itu adalah kakakmu yang sok tahu, yang tidak akan diam tentang apa pun.', reading_mnemonic = 'Tahukah Anda bahwa **Saudari** (兄) ini sebenarnya dibuat dari tumpukan **Kipas/Kikir**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **きょう**.' WHERE id = '72d9015a-283b-4ede-a2f4-afd65001dc7f'; -- 兄 (kanji)
UPDATE items SET meaning_mnemonic = 'Kita punya radikal musim dingin dan radikal dua (walaupun agak miring). Apa artinya dua kali radikal musim dingin, jika radikal hanyalah bagian dari kanji? Dua kali sudah cukup untuk membuat seluruh kanji, yang juga merupakan musim dingin.', reading_mnemonic = 'Bagaimana cara membaca kanji **Musim dingin** (冬)? Ingat saja bahwa **ふゆ** sangat menyukai musim dingin! Hubungan erat ini akan membantu Anda mengingat bunyi **ふゆ**.' WHERE id = '65c6851b-7081-47a0-8059-ee9618433ee9'; -- 冬 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji bertemu dan kanji bertemu adalah sama!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Bertemu** (会), bayangkan Anda sedang membawa **Kail/Kain** untuk ditaruh di atas bertemu. Kejadian unik ini mengingatkan Anda pada bunyi **かい**!' WHERE id = '4bf9164a-ae65-41fb-95bc-0f16d486acbc'; -- 会 (kanji)
UPDATE items SET meaning_mnemonic = 'diri radikal dan diri sama dalam penampilan dan makna.', reading_mnemonic = 'Bagaimana cara membaca kanji **Diri sendiri** (自)? Ingat saja bahwa **Juri/Jalan** sangat menyukai diri sendiri! Hubungan erat ini akan membantu Anda mengingat bunyi **じ**.' WHERE id = 'dc496f9c-c6b3-4a1e-ba63-d85f90766283'; -- 自 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika yakuza memberi Anda sendok, kematian akan datang untuk Anda. Itu adalah sendok kematian, pertanda kedatangan yakuza yang menyebabkan kematianmu.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kematian** (死), bayangkan Anda sedang membawa **Singa/Silet** untuk ditaruh di atas kematian. Kejadian unik ini mengingatkan Anda pada bunyi **し**!' WHERE id = 'b12d5793-c36b-4cf6-9a4f-bffb6a15f557'; -- 死 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan kanji yang Anda pelajari, artinya Anda tahu bacaannya!' WHERE id = '94ab5021-cb31-4615-8501-79221179f936'; -- 死 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hanya narwhal dan moon yang Anda miliki. Bayangkan masing-masing satu di bawah lengan Anda.', reading_mnemonic = 'Ketika Anda sedang melihat **Memiliki** (有), tiba-tiba muncul sesosok **Yuda** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **ゆう**.' WHERE id = '69e2c7c0-fadb-4b39-a3e5-5ee09cf529da'; -- 有 (kanji)
UPDATE items SET meaning_mnemonic = 'Di mulut Anda menaruh pedang dan pisau. Sekarang setelah Anda memilikinya di sana, Anda harus membuat terpisah satu sama lain.', reading_mnemonic = 'Tahukah Anda bahwa **Pisahkan** (別) ini sebenarnya dibuat dari tumpukan **Bebek/Besi**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **べつ**.' WHERE id = '2df7e287-2802-4a56-af0a-202b5a3673ff'; -- 別 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata radikal untuk kaki dan kanji untuk kaki sama persis.

Meski begitu, ada juga arti lain yang harus Anda ingat, yaitu cukup. Jika dipikir-pikir, satu kaki seharusnya cukup untuk berjalan jika Anda melompat.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kaki** (足), bayangkan Anda sedang membawa **Soto/Sosis** untuk ditaruh di atas kaki. Kejadian unik ini mengingatkan Anda pada bunyi **そく**!' WHERE id = 'c64c78b7-349a-480b-8d25-334b58b9a9cf'; -- 足 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari lebar? Kata ini juga memiliki luas.', reading_mnemonic = 'Pembacaan kata ini sama dengan pembacaan yang kamu pelajari di bagian kanji: ひろ, jadikan ini ひろい.' WHERE id = 'efebba90-440b-4eb6-9bc2-c64dbd27ea91'; -- 広い (vocabulary)
UPDATE items SET meaning_mnemonic = 'masa lalu tahun hanyalah tahun lalu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'c9f9aa7b-b281-434a-a61f-e97d6e4907f8'; -- 去年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki yang sama hari, yang keluar pada hari yang sama.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 日 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Pada hari yang sama, Anda pernah makan dua donat utuh. Wah, dua (どうじつ) di hari yang sama? Bagaimana rasanya?' WHERE id = 'bb0115d2-fa71-4861-a6ea-2f15e828ab06'; -- 同日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari berpikir. Apa itu "berpikir"? Itu adalah pemikiran.', reading_mnemonic = 'Anda mempelajari bacaan ini dengan 考える, potong saja る!' WHERE id = '3cad3622-3750-4983-977f-27442b6d6b5e'; -- 考え (vocabulary)
UPDATE items SET meaning_mnemonic = 'berpikir cara sebenarnya adalah cara seseorang berpikir. Itu sebabnya kata ini berarti cara berpikir.', reading_mnemonic = 'Ini menggunakan bacaan kun''yomi dari vocab kata 考える dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = '68631048-f426-4e6f-894d-34a349e82d8c'; -- 考え方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda dapat berdiri menggunakan diri Anda. Tidak ada yang membantu Anda. Tidak ada yang menahanmu. Inilah kemandirian Anda!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ac83ab1f-416c-4db5-bb29-d1710df75c5c'; -- 自立 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka menggunakan bacaan kun''yomi. Ini adalah bacaan yang Anda pelajari dengan kanji, jadi nikmatilah.' WHERE id = '7ab0218f-5bc2-46e6-8f85-ce0de46c16ae'; -- 色 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari kanji dekat. Jadi itu juga berarti dekat, atau di neighbourhood dari sesuatu.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda sudah mempelajari bacaan ini ketika mempelajari 近い, jadi Anda seharusnya bisa membaca kata ini juga.' WHERE id = '2590b80a-5e45-4acf-893f-ce6d2b902f5e'; -- 近く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda tidak santai, apa yang Anda rasakan? Kegelisahan adalah apa yang Anda rasakan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '0c9c46d2-422c-4b60-a67c-db852344f735'; -- 不安 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji untuk kematian dan tubuh digabungkan menjadi mayat. Semoga Anda tidak terlalu sering menggunakan atau melihat vocab ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '54234c04-d9c7-4c0a-a225-1380a4a4f56e'; -- 死体 (vocabulary)
UPDATE items SET meaning_mnemonic = 'yang terpisah orang adalah seseorang yang berbeda dari dirinya sebelumnya. Aku melihatmu setahun yang lalu dan kamu adalah orang lain. Sekarang Anda menjadi orang yang berbeda, dalam arti yang baik! Anda adalah pria yang telah berubah.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '2d6d56ff-986c-4a1e-85ad-cead618ef076'; -- 別人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda memisahkan memisahkan Anda menempatkan segala sesuatunya di areanya masing-masing. Anda menandainya secara terpisah dan satu per satu.', reading_mnemonic = 'Bacaannya cuma bacaan べつ lho, dua kali.' WHERE id = 'ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa'; -- 別々 (vocabulary)
UPDATE items SET meaning_mnemonic = 'cara mengatakan sesuatu adalah cara mengucapkan Anda. Ini bisa jadi aksen Anda atau cara Anda berbicara.', reading_mnemonic = 'Ini menggunakan bacaan kun''yomi dari vocab kata 言う dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = '71a300c7-ed70-4050-b69d-f14a7c796638'; -- 言い方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda memiliki cepat mulut, Anda mungkin adalah pembicara yang cepat, bukan mulut motor?', reading_mnemonic = 'Ingat bagaimana bagian tubuh sering mengubah kata jukugo menjadi bacaan kun''yomi? Itu juga yang terjadi di sini. Kedua bacaannya adalah kun''yomi, jadi yang ini はやくち.' WHERE id = 'c843c0e1-f697-45be-9a90-67c127002649'; -- 早口 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata keterangan dari kanji awal. Ini adalah kalimat kecil yang bisa digunakan untuk mengawali kalimat yang mengatakan Anda melakukan sesuatu awal atau dengan cepat.', reading_mnemonic = 'Karena anda sudah mengetahui cara membaca vocab kata 早い, seharusnya anda juga bisa membaca kata ini.' WHERE id = '2f89818d-c3f8-4681-91c1-7630d30f187f'; -- 早く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan kanji yang Anda pelajari, artinya Anda tahu bacaannya!' WHERE id = '39832552-1b81-4155-8aea-0c5ae3a308b7'; -- 別 (vocabulary)
UPDATE items SET meaning_mnemonic = 'jalan keluar dimana seseorang dimulai adalah asal seseorang, kampung halaman seseorang, atau tempat lahir seseorang.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri. Hati-hati dengan つ dari 出, yang menjadi っ.' WHERE id = 'a1510bc1-9149-488d-97eb-4bda5b6f306a'; -- 出身 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda membuat tulisan, apa yang Anda lakukan? Sederhananya, Anda sedang menulis. Jika Anda ingin lebih tertarik lagi, bisa dibilang ini adalah composition.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 文 dan 作 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Anda tidak bisa berhenti menulis komposisi tentang sacks ''n'' buns (さくぶん). Anda terobsesi dengan mereka. Anda telah menulis esai demi esai tentang sacks ''n'' buns. Berhentilah menulis tentang karung ''n'' roti!' WHERE id = '0ec47f2a-ece0-4930-b9de-3c3eb36a862f'; -- 作文 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Flek/tetesan kecil di matamu itulah yang membuatmu unik. Itulah yang menjadikan Anda diri Anda. Itu kamu, kamu tahu?', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '003b7ca6-13f9-4bd2-9982-be9b78e8730b'; -- 自 (radical)
UPDATE items SET meaning_mnemonic = 'Anda memiliki tubuh kekuatan Anda. Ini hanyalah cara lain untuk mengatakan kekuatan fisik. Awas, jika kamu menggunakan terlalu banyak kekuatan fisik, kamu bisa kehabisan stamina dan daya tahan fisik sepenuhnya! Mereka terikat bersama, jadi pastikan untuk mengatur kecepatan Anda sendiri.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 力 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

kekuatan fisik dan stamina Anda diikat menjadi satu dengan kunci pengikat (たいりょく). Itu adalah kunci yang terbuat dari ikatan yang mengikat kekuatan dan stamina Anda, membuatnya lebih mudah untuk mengatur kecepatan Anda.' WHERE id = 'a68839af-8c41-4538-bb27-7a5e4ff66017'; -- 体力 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tempat Saya berdiri adalah area pribadi saya sendiri. Pikirkan tentang "lingkaran ruang pribadi". Di sinilah Anda berdiri ditambah jarak satu lengan. Area ini sangat pribadi bagi Anda. Siapa yang tahu apa yang Anda lakukan di area pribadi Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fa5983c4-4a9b-4a0b-8010-0c2737aba61e'; -- 私立 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika Anda memiliki nama (yang dikenal orang) atau Anda memiliki terkenal, Anda mungkin adalah seseorang yang terkenal.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '81578233-8e09-4373-a434-7b12f7e5bdfe'; -- 有名 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari awal? Ini juga awal.', reading_mnemonic = 'Bacaan kata ini adalah bacaan kun''yomi, yang tidak anda pelajari saat mempelajari kanji. Anda harus mengingat bagian はや untuk dapat membaca kata ini. Untuk melakukan itu, inilah mnemoniknya: 

Anda cepat! Anda lebih awal! Pukulanmu jatuh ke leher lawan dengan sangat cepat! Saat kamu memotongnya, kamu berteriak "はや!"' WHERE id = '4b36b063-116b-4e80-aeec-9f4dde0072ca'; -- 早い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Anda hanya mempelajari satu bacaan untuk kanji yang menyusun kata ini, dan itu sama dengan bacaan untuk kata ini (tentu saja). Artinya, Anda seharusnya sudah mengetahui bacaannya.' WHERE id = 'e6b494fb-ff53-4d12-8c8e-c3de096a17a4'; -- 字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda memiliki tubuh Anda. Itu bagus - terlihat bagus! Apa yang benar-benar mengacaukan tubuh Anda? Itu akan menjadi perampok mobil (からだ). Saya sedang berbicara tentang seorang pria yang merupakan seorang perampok yang mengendarai mobil. Jika dia menabrak tubuh Anda, tamatlah Anda, jadi waspadalah terhadap perampok mobil. 

Tentu saja, mnemonik ini hanya dimaksudkan agar Anda lebih dekat dengan bacaannya. Mudah-mudahan cukup dekat untuk membawa Anda ke bacaan sebenarnya, からだ.' WHERE id = 'bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946'; -- 体 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika hati Anda rileks, bagaimana perasaan Anda? Bagaimana jika hal ini terjadi setelah sesuatu yang mengejutkan terjadi? Anda akan merasakan lega atau ketenangan pikiran.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'cf16c4a0-d77d-450d-967b-491cff3fc078'; -- 安心 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa yang Anda sebut sapi daging? Anda menyebutnya daging sapi (makan malamnya apa?).', reading_mnemonic = 'Kedua bacaan untuk kedua kanji tersebut adalah bacaan yang kamu pelajari dengan kanji tersebut jadi kamu harus bisa membaca ini.' WHERE id = 'e1514a84-9b8b-48d7-925f-9d9c9468961d'; -- 牛肉 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Secara teknis kanji ini adalah hati dan seseorang, tapi pikirkan seperti ini. Dari mana datangnya segala sesuatu dalam diri seseorang? Jantung! Ia menjaga segala sesuatunya tetap berjalan dengan memompa darah, memberikan landasan bagi pikiran dan tubuh yang baik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'fa570062-9250-4e52-bd17-a4e0315dd45f'; -- 心身 (vocabulary)
UPDATE items SET meaning_mnemonic = 'yang waktu yang sama? Oke, katakanlah menurut kami arti kata ini pada waktu yang sama. Ups, saya baru saja mengatakannya, maaf.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '3029f190-3702-468c-878c-bec340270ff8'; -- 同時 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tubuh seseorang. Ini mengacu pada kata tubuh yang sangat umum. Seperti dalam, "tubuh manusia" atau sesuatu seperti itu. Ini juga bisa merujuk pada kesehatan juga.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'b1c3e423-f288-4320-bae8-02dcc75a10fd'; -- 身体 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Di dalam peti mati ada seseorang yang mengemis. Tapi itu tidak akan berhasil. Anda tidak akan mendengarkan. Jadi, pria di dalam peti mati itu mulai berpikir: Apa yang bisa saya lakukan dengan lebih baik dalam hidup saya? Mengapa saya berada dalam situasi ini? Bagaimana saya bisa keluar? Pikirkan, sial, pikirkan!!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Pikirkan** (考) tiba-tiba berbicara dan meminta **Koko/Koki**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **こう**.' WHERE id = '971e847f-cb01-45cf-b0a1-16b67338d6e5'; -- 考 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada berapa malam hari? Ada banyak.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Banyak** (多), bayangkan Anda sedang membawa **Tali/Tahu** untuk ditaruh di atas banyak. Kejadian unik ini mengingatkan Anda pada bunyi **た**!' WHERE id = '0f457b18-22e5-4fde-a772-cb6efe5b2f7a'; -- 多 (kanji)
UPDATE items SET meaning_mnemonic = 'perusahaan pemimpin adalah presiden perusahaan, manajer, atau direktur. Pastikan untuk menyapa 社長 Anda dengan ucapan selamat pagi yang hangat saat dia tersandung!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'cb3da577-8ee5-40e7-b016-58dee46253d0'; -- 社長 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah atap. Anda tahu itu atap dan bukan dahi karena ada cerobong kecil yang mencuat dari atasnya. Dan dahi pastinya tidak mempunyai cerobong asap.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9b111d27-48ef-4287-b61a-9dddbb0e7516'; -- 宀 (radical)
UPDATE items SET meaning_mnemonic = 'Jika kamu punya satu tulisan surat apa yang kamu punya? Ini petunjuknya, ada satu kanji di kata ini yang terdiri dari satu huruf tulisan (alias garis lurus).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 文 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Garis lurus adalah untuk monster (もん). Hanya monster yang bisa menggambar garis lurus sempurna. Kamu bukan monster, jadi tidak ada garis lurus untukmu!' WHERE id = '9d426aef-e6e4-41e9-af92-0b4c73e79b5b'; -- 一文字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah versi kata benda dari kanji meet. Jadi artinya pertemuan.', reading_mnemonic = 'Bacaannya sama dengan kanji yang Anda pelajari, artinya Anda tahu bacaannya!' WHERE id = '0223917c-3053-4d36-a0a9-6602c54ca12a'; -- 会 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tempat tidur yang Anda dapatkan di penjara adalah satu-satunya dengan warna yang akan Anda lihat saat berada di sana. Bayangkan sebuah sel yang gelap dan lembap. Mungkin toilet juga. Sekarang bayangkan tempat tidur yang cerah dan berwarna-warni menempel di dinding. Inilah satu-satunya kebahagiaan yang Anda miliki.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6a017a44-e9b4-40f5-a8aa-31f4740f4da5'; -- 色 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari lama? Kata ini juga lama, kuno, atau ketinggalan zaman.

Kata ini digunakan untuk hal-hal seperti pakaian, makanan, dan persahabatan, tetapi tidak untuk orang! Jadi 古い友人 (teman lama) adalah seseorang yang sudah lama berteman dengan Anda, bukan teman lama.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji dengan beberapa hiragana yang dilampirkan, maka akan menggunakan bacaan kun''yomi. Anda mempelajari on''yomi saat mempelajari bagian kanji, jadi mari gunakan mnemonik untuk membantu Anda membaca kata ini: 

Jika Anda tua, Anda juga penuh (ふる) kenangan. Dan Anda mungkin penuh dengan rahasia lama. Dan kamu kenyang dengan makanan orang tua.' WHERE id = '4b84fc36-fe60-4d28-84c0-291ae0528a95'; -- 古い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki banyak bagian. Lihatlah semuanya. Anda harus memilih salah satu bagian. Anda tidak dapat memutuskan mana yang Anda inginkan. Yang ini? Mungkin. Bagaimana dengan yang ini? Hmm, mungkin yang itu juga.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '995d671a-15a9-4f66-8ca4-446712df9135'; -- 多分 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kombinasi kanjinya kurang masuk akal, tapi tidak apa-apa. Ambil sesuatu yang menengah lama dan Anda memiliki sesuatu yang bekas atau bekas. Belum 100% tua..masih di tengah-tengah, artinya kamu bisa memberikannya kepada orang lain untuk digunakan seperti adik-adikmu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '83e0e067-23de-41d0-ac0f-df089a7dd5ad'; -- 中古 (vocabulary)
UPDATE items SET meaning_mnemonic = 'atap anak berdiri di atas atap, memegang satu huruf, satu karakter, satu simbol untuk dilihat dunia.', reading_mnemonic = 'Bagaimana cara membaca kanji **Surat** (字)? Ingat saja bahwa **Juri/Jalan** sangat menyukai surat! Hubungan erat ini akan membantu Anda mengingat bunyi **じ**.' WHERE id = 'f2cf511f-12ec-48e0-b828-17cfe918df7d'; -- 字 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Meskipun ini hanya satu kanji, ia menggunakan bacaan on''yomi. Ini adalah bacaan yang kamu pelajari dengan kanji, dasar bebek yang beruntung.' WHERE id = '7d493466-dd95-4ba5-9307-a71930f77343'; -- 地 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanjinya adalah seseorang, tetapi kata yang dimaksud adalah body. Saya kira seseorang adalah tubuh seseorang, jadi setidaknya mereka mirip.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, kemungkinan besar menggunakan bacaan kun''yomi. Anda tidak mempelajari bacaan ini, jadi inilah mnemonik untuk membantu Anda mengingat: Siapakah orang itu? Siapakah tubuh itu? Wah, tentu saja **Minyak/Mimi** (み).' WHERE id = 'cc680f63-748b-4726-a57a-f0b4ce6bb6f3'; -- 身 (vocabulary)
UPDATE items SET meaning_mnemonic = '"Jika menyangkut seseorang seperti diri saya... alias saya..." Ketika Anda mengatakan ini, Anda sebenarnya mengatakan "secara pribadi" atau "untuk saya."', reading_mnemonic = 'Pembacaannya agak aneh di sini. 私 adalah わたし dan sisanya adalah bacaan kanji on''yomi. Jadi, ini campuran keduanya, saya khawatir. “Kalau soal diriku, aku suka mencampuradukkan on''yomi dan kun''yomi karena aku membenci diriku sendiri.”' WHERE id = '43f31045-9b91-4600-bed3-2b61af36d107'; -- 私自身 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jangan bingung dengan 会社 yang merupakan perusahaan, ini adalah society. Ketika perusahaan bertemu bersama, itu seperti sekelompok orang, yang berada dalam kelompok, yang berkumpul untuk hidup di satu dunia. Itulah masyarakat.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '5d633797-ca8c-4ae7-b77d-1c2bf975fd3c'; -- 社会 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini adalah skuter. Lihat stang dan lampu kecilnya? Dan ada platform di bagian bawah tempat Anda dapat berdiri atau duduk (jika itu salah satu platform bermotor yang bagus).', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '110deca9-1ec1-4543-bdbd-248f1d551712'; -- ⻌ (radical)
UPDATE items SET meaning_mnemonic = 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal lama terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti lama.

Catatan: Kata "lama" ini tidak mengacu pada orang. Anggap saja sebagai "hal lama".', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Tua** (古) tiba-tiba berbicara dan meminta **Kopi/Koki**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **こ**.' WHERE id = 'be7b7c13-8c99-45ed-ac0a-632e895a9a01'; -- 古 (kanji)
UPDATE items SET meaning_mnemonic = 'penutup tahun adalah tahun-tahun yang belum terlalu lama berlalu. Itu adalah tahun-tahun terakhir.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '11f8396c-2f3d-434b-b6ac-b7f6d26b9860'; -- 近年 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat 私立 yang berarti "swasta", dan Anda pernah melihat 大学 yang berarti "perguruan tinggi" atau "universitas". Jadi, gabungkan keduanya dan Anda memiliki perguruan tinggi swasta / universitas swasta.', reading_mnemonic = 'Jika Anda mengetahui bacaan dari kata 私立 dan 大学 Anda pasti bisa membaca ini. Itu juga semua bacaan jukugo on''yomi, jadi Anda bisa membacanya seperti itu.' WHERE id = '8c896604-435f-43ba-8b6e-2e52842cba07'; -- 私立大学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang berada di skuter memiliki kapak, dan mereka mendekati dengan Anda dengan sangat cepat! Oh tidak, mereka dekat sekarang, kamu harus keluar dari sini!', reading_mnemonic = 'Ketika Anda sedang melihat **Menutup** (近), tiba-tiba muncul sesosok **Kincir/Kendi** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **きん**.' WHERE id = '8e3d0b44-43f1-4ff8-b6ee-6d1e4195164a'; -- 近 (kanji)
UPDATE items SET meaning_mnemonic = 'menulis surat lebih sederhana dari kedengarannya. Itu sebenarnya hanya sebuah surat, kan? Faktanya, Anda sedang membaca 文字!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Pembacaan 文 merupakan pengecualian di sini, jadi inilah mnemonik untuk membantu Anda mengingatnya:

Anda mengetahui semua huruf alfabet hanya karena Moe (も). Jika bukan karena temanmu Moe yang mengajarimu semua huruf, kamu mungkin tidak akan bisa membaca hari ini. Terima kasih Moe!' WHERE id = 'c70b0764-350b-4522-a615-efb481403211'; -- 文字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini terlihat seperti karakter katakana untuk ne. Bukan untuk ahli nujum! Itu menjadikannya roh, yang dibangkitkan dari kubur. OooooOOooooOoo!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '4aae2400-4f20-4cde-83df-ec20c82174d7'; -- ネ (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Pengemis". Perhatikan bentuk karakter "[Pengemis]" dan asosiasikan bentuk goresannya dengan "pengemis".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '662563bb-481b-4563-84a4-4a7846817e53'; -- [Pengemis] (radical)
UPDATE items SET meaning_mnemonic = 'Mulutmu berbentuk salib—mulut itu cukup religius. Siapa yang paling banyak berbicara tentang agama? Tua kebanyakan. Juga, pikirkan tentang ajaran agama itu sendiri - juga cukup tua, berdasarkan usia. Tidak peduli bagaimana Anda melihatnya, segala sesuatu tentang radikal ini sudah “kuno”.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'b7e87ddd-c228-491b-9736-61a6bf599f71'; -- 古 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat kumis di sekitar mulut? Saya berharap saya bisa menumbuhkan kumis manis seperti ini.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'bf18f5dc-3e51-42ab-96c2-cae2da254cb0'; -- 冋 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat mulut dan gigi buaya ini yang menghadap ke kanan? Anda tidak ingin tangan Anda tersangkut di sana, itu sudah pasti.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6f54c654-910d-4f3d-95e3-be0537bdc1c7'; -- 也 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini tampak seperti sendok! Nah, sendok yang banyak dibengkokkan oleh orang yang sedang marah atau paranormal. Ambil sendok dan coba tekuk menjadi bentuk ini. Kemudian peganglah agar Anda tidak pernah lupa bahwa ini adalah sendok radikal!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '02baaf22-acf6-4946-a897-4b8e657f1452'; -- 匕 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat slidenya masuk ke tanah? Di situlah mereka membuang tubuhmu saat kamu mati. Ini sebenarnya adalah peti mati!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8d96cc02-008d-4795-bad2-4d4f84d39025'; -- 耂 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah pohon dengan slide yang memotong bagian atasnya. Dengan apa Anda memotong bagian atas pohon dan tanaman? biji-bijian. Bayangkan mengambil sabit dan mengiris butiran beras atau gandum. Tanaman yang Anda tinggalkan akan terlihat radikal seperti ini. Itu tandanya kamu mendapat semacam butiran darinya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '6bdf0f7d-eae0-49a1-a101-e615911b6e62'; -- 禾 (radical)
UPDATE items SET meaning_mnemonic = 'Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri memiliki arti terpisah, jadi bisa ditebak maksudnya adalah memisahkan atau dibagi.', reading_mnemonic = 'Ingat kata 分ける? Kata itu juga berarti "memisahkan". Bacaannya serupa, meski tidak sama, tapi setidaknya kita bisa menggunakannya sebagai titik awal. Kita beralih dari わける ke わかれる. Ini seperti kita telah "memisahkan" け dan る dan menggabungkannya di tengah. け, membuat かれ, yang membawa Anda ke わかれる.' WHERE id = '6a3dae58-c6b3-4a92-9227-c20dd69509b0'; -- 別れる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda mengucapkan kata-kata dalam bahasa, Anda sedang mengucapkan bahasa. Tidak yakin bahasa apa itu, tapi karena Anda mengatakannya, itu pasti nyata.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '317abc16-85d4-475e-9a09-230552eb9ff8'; -- 言語 (vocabulary)
UPDATE items SET meaning_mnemonic = 'pengemis mengarahkan dahinya ke arah Anda, kakinya terjebak di tanah. Skema jahat apa yang kamu rencanakan dengan pengemis malang yang kamu jebak ini? Ternyata, Anda berencana untuk menyalin dia agar memiliki versi Anda sendiri.', reading_mnemonic = 'Tahukah Anda bahwa **Terjemahan** (写) ini sebenarnya dibuat dari tumpukan **Sapi/Sampo**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **しゃ**.' WHERE id = 'f88dfc1a-284f-4117-8d5d-8bff7bb46e15'; -- 写 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada kumis di tanah. Setelah diperiksa lebih dekat, Anda melihat bahwa kumis di tanah persis sama dengan milik Anda!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Sama** (同) tiba-tiba berbicara dan meminta **Domba/Topi**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **どう**.' WHERE id = '5c4c770c-f9e7-49be-8bcf-d718aff12ec9'; -- 同 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal daging dan daging memiliki tampilan dan makna yang sama.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Daging** (肉), bayangkan Anda sedang membawa **にく** untuk ditaruh di atas daging. Kejadian unik ini mengingatkan Anda pada bunyi **にく**!' WHERE id = '1b3eb9f0-3351-457f-9304-80123823e6e6'; -- 肉 (kanji)
UPDATE items SET meaning_mnemonic = 'pemimpin memiliki buku yang membahas tentang tubuh manusia. Mengetahui tentang tubuh adalah suatu kehormatan. Sesuatu yang hanya dimiliki oleh para pemimpin—ini membantu mereka mengendalikan seluruh rakyatnya, seperti Anda.', reading_mnemonic = 'Ketika Anda sedang melihat **Tubuh** (体), tiba-tiba muncul sesosok **Tali/Tari** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **たい**.' WHERE id = 'bd3e3324-b7ba-49f1-bc11-4d725d37b0ed'; -- 体 (kanji)
UPDATE items SET meaning_mnemonic = 'Radikal diri sedikit dimodifikasi, dengan hal-hal yang menonjol, tapi itu karena ia terjatuh.

Tentu saja,diri Andalah yang terpuruk dalam slide… setidaknya itulah yang Anda rasakan. Siapa kamu? Apa yang kamu? Yang Anda tahu hanyalah Anda adalah seseorang, tetapi Anda tidak tahu siapa orang itu.', reading_mnemonic = 'Bagaimana cara membaca kanji **Seseorang** (身)? Ingat saja bahwa **Shin-chan/Singa** sangat menyukai seseorang! Hubungan erat ini akan membantu Anda mengingat bunyi **しん**.' WHERE id = 'bd9d5a8b-6687-498d-a06b-d61b59a290c6'; -- 身 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda mungkin mengira air warna ada hubungannya dengan cat air, namun ternyata tidak. Tidak, ini ada hubungannya dengan warna air, yang ironisnya adalah sky blue dalam bahasa Inggris. Biru muda juga bisa digunakan.', reading_mnemonic = 'Bacaan kata ini terdiri atas bacaan kun''yomi 水 dan bacaan kun''yomi 色. Untuk 水 Anda akan mengetahui bacaan ini melalui studi kosakata Anda. Untuk 色 kebetulan itu adalah bacaan yang Anda pelajari dengan kanji.' WHERE id = '1bc4a883-7b30-4dd8-9686-dbd2aefc1371'; -- 水色 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki besar tulisan huruf. Menurut Anda apa ini? ITU HARUS HURUF BESAR, kan? Ups, maaf, caps lock aktif sebentar, itu.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Namun, 大 menggunakan bacaan kun''yomi dan 文 merupakan pengecualian di sini, jadi inilah mnemonik untuk membantu Anda mengingatnya:

Setiap kali kamu melihat huruf besar, kamu berteriak "おお, Moe!" (おおも). Temanmu, Moe, mengajarimu huruf-huruf itu sejak awal, jadi ketika kamu mengalami kebuntuan, kamu berteriak padanya untuk datang membantumu. Dan dia selalu melakukannya. Pria yang baik.' WHERE id = '2ffbe878-636e-432c-a267-9712bcf184b8'; -- 大文字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji warna yang diulang dua kali (karakter 々 hanya mengulangi kanji sebelumnya). Ketika Anda memiliki warna dan warna dan warna, Anda memiliki banyak variasi. Itu sebabnya kata ini berarti berbagai.', reading_mnemonic = 'Pembacaan kanji ini hanyalah pembacaan kun''yomi sebanyak dua kali. Karena Anda sudah mempelajari bacaan kun''yomi, Anda seharusnya bisa membaca kata ini juga. Tidak ada yang rumit tentang hal itu.' WHERE id = '3d00ada4-519f-4421-bcaa-b4aa4e3cbcf4'; -- 色々 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tanah dari bumi adalah bagian bumi yang terdiri dari tanah.', reading_mnemonic = 'Pembacaannya adalah pembacaan on''yomi, tetapi 土 diubah menjadi と karena alasan tertentu. Ingatlah bahwa tanah tempat Anda berdiri terbuat dari jari kaki... jutaan jumlahnya. sial.' WHERE id = '193df329-4267-4464-8e76-dafb11f86ff4'; -- 土地 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Di bawah tanah adalah bawah tanah.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '4dd00d20-beab-4976-930e-99641ed3f640'; -- 地下 (vocabulary)
UPDATE items SET meaning_mnemonic = 'の ada untuk menunjukkan bahwa itu adalah perbedaan dari sesuatu. Contohnya seperti mengatakan "yang terpisah ______" atau "yang berbeda _____" atau "lainnya ______". 別 dengan sendirinya berarti terpisah, berbeda, atau lainnya.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari. Pindah ke 別の漢字, mmk?' WHERE id = '54f8ef68-fca5-4d36-8a62-7eff216da5d9'; -- 別の (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bagaimana 私 bisa berarti pribadi dan bagaimana 大 merupakan bagian pertama dari 大学? Gabungkan semuanya dan Anda akan mendapatkan versi singkat dari perguruan tinggi swasta atau universitas swasta.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Anda kuliah di perguruan tinggi swasta tertentu hanya untuk belajar pewarna (だい). Anda sangat menyukai pewarna sehingga Anda memutuskan untuk kuliah di universitas swasta yang sangat mahal dan berspesialisasi dalam pewarna. Bagus untukmu!' WHERE id = '965a077b-c27e-49a0-8499-08c110015d6d'; -- 私大 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda berada di tengah dari tanah, kemungkinan besar Anda berada di bawah tanah. Apakah Anda seorang penganiaya? Itu cukup keren.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'd716860b-fb39-47cc-a0aa-f6456a294cc4'; -- 地中 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda sering berpikir tentang mempelajarihal-hal lama, itu disebut arkeologi. Semua arkeologi melibatkan pemikiran tentang hal-hal lama, setidaknya sedikit.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '5ab43d6a-477e-468c-88ff-d4104450be8c'; -- 考古学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'pribadi biji-bijian Anda dimaksudkan untuk tetap pribadi! Anda tidak boleh membaginya dengan seluruh kota, itu hanya untuk Anda.

Kanji ini juga berarti Saya. Mengapa? Karena apa yang lebih pribadi darimu? Maksudku, aku! Pada dasarnya, beberapa hal hanyalah urusan Anda (saya) dan hal-hal itu harus bersifat pribadi.', reading_mnemonic = 'Tahukah Anda bahwa **saya** (私) ini sebenarnya dibuat dari tumpukan **Singa/Silet**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **し**.' WHERE id = '009766e6-79e6-48b5-b07f-ffad16df62b0'; -- 私 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini diawali dengan お agar lebih sopan. Lalu ada kanji 兄 yang sudah anda ketahui. Terakhir, ada さん yang merupakan suatu kehormatan untuk meninggikan orang dan bersikap sopan. Ini pada dasarnya adalah cara formal untuk mengucapkan kakak (versus 兄 biasa). Ini juga bisa digunakan untuk merujuk pada pria yang tidak Anda kenal yang memiliki penampilan awet muda.', reading_mnemonic = 'Pembacaan untuk yang satu ini cukup rumit, dan saya menganggapnya sebagai pengecualian. Untuk mengingatnya, Anda harus mempelajari bagian 兄, dan yang lainnya akan sesuai dengan tempatnya. Berikut ini mnemonik untuk membantu Anda:

kakak (baik hati)mu mendorongmu hingga jatuh ke tanah. Kamu berdiri dan melihat lututmu (にい), yang berlumuran darah. "Kenapa kamu melakukan itu pada lututku!?" kamu bertanya. "Kamu seharusnya menjadi kakak yang baik, itu sebabnya aku memanggilmu お兄さん!"' WHERE id = '6a8ec0b2-29e2-4b19-b9f7-a9ccc38f54a7'; -- お兄さん (vocabulary)
UPDATE items SET meaning_mnemonic = 'kunci pemimpin adalah kunci yang membuat semua kunci lainnya. Ini seperti satu cincin untuk mengatur semuanya, satu cincin untuk mengikat mereka... kecuali dengan kunci.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Membuat** (作) tiba-tiba berbicara dan meminta **Saku/Saksi**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **さく**.' WHERE id = 'ad8a055b-957d-43a1-ba74-6791c405ccb5'; -- 作 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda datang ke pesta dengan mengenakan sesuatu yang sangat, sangat tua, semua orang akan tahu bahwa Anda berasal dari zaman kuno (seolah-olah kerutan Anda belum menunjukkannya, bukan?).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'ffc99a15-facc-4c1b-ae37-6a5a99886144'; -- 古来 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika Anda keluar ke suatu tempat untuk pergi ke perusahaan Anda, itu adalah pergi ke kantor, tiba di kantor, dan mulai bekerja.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri. Berhati-hatilah terhadap しゅつ, yang diubah menjadi しゅっ, seperti yang banyak dilakukan dalam situasi ini.' WHERE id = 'fa893367-17ae-4940-b7f8-fd600a688f92'; -- 出社 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji katakan dan kanji katakan adalah sama!', reading_mnemonic = 'Bagaimana cara membaca kanji **Mengatakan** (言)? Ingat saja bahwa **Gendang/Genta** sangat menyukai mengatakan! Hubungan erat ini akan membantu Anda mengingat bunyi **げん**.' WHERE id = '5689130e-e5df-4dc4-8171-a4f85944d03e'; -- 言 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Beruntungnya bagi Anda, kata ini menggunakan bacaan on''yomi yang Anda pelajari meskipun hanya berupa satu kanji saja. Jadi, kamu harusnya sudah mengetahuinya!' WHERE id = 'e2a56be5-70e1-4a74-a5db-586352f0ca2a'; -- 肉 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda membuat sebuah tugas, Anda mencari efek dan/atau action tertentu. Tugas apa yang dapat Anda lakukan saat ini untuk mendapatkan efek mempelajari lebih banyak kanji?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 作 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Apa efek gergaji pada yoghurt (さよう)? Apa yang akan dilakukan action gergaji pada yoghurt? Tampaknya sia-sia, tetapi Anda akan tetap mencobanya. Untuk sains.' WHERE id = '02aa7bed-ddcb-4adf-8c45-ad1872b7c0ce'; -- 作用 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kotoran buaya hidup di bumi, bukan di air. Mereka bisa berenang menembus bumi itu sendiri! Itu cukup menakutkan.

Anda juga bisa menganggap kata ini sebagai tanah, karena bumi terbuat dari bahan tersebut.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Bumi** (地), bayangkan Anda sedang membawa **Cili/Ceri** untuk ditaruh di atas bumi. Kejadian unik ini mengingatkan Anda pada bunyi **ち**!' WHERE id = 'e1cb826f-3d14-45b1-a3ed-b16dadf4d973'; -- 地 (kanji)
UPDATE items SET meaning_mnemonic = 'Tanamkan semangat di tanah sebelum Anda memulai perusahaan Anda dan itu akan berhasil. Hal itulah yang dilakukan oleh perusahaan-perusahaan besar Jepang di masa lalu. Itu sebabnya perusahaan seperti Mitsubishi telah ada selama ratusan tahun. Mereka menanamkan semangat untuk membantu perusahaan mereka tumbuh, dan perusahaan itu pun berkembang!', reading_mnemonic = 'Bagaimana cara membaca kanji **Perusahaan** (社)? Ingat saja bahwa **Sapi/Sampo** sangat menyukai perusahaan! Hubungan erat ini akan membantu Anda mengingat bunyi **しゃ**.' WHERE id = 'ccf3fa1d-701b-469a-b812-f45c21b4c9e0'; -- 社 (kanji)
UPDATE items SET meaning_mnemonic = 'publik perusahaan adalah perusahaan yang dikelola pemerintah atau perusahaan milik pemerintah. Dengan kata lain, ini adalah perusahaan yang dijalankan oleh pemerintah pusat atau daerah untuk kepentingan masyarakat.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '86db5546-e91f-4601-960e-3fba522bc18d'; -- 公社 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti bertemu jadi bentuk kata kerjanya adalah to meet atau to face.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian あ tetapi mari sertakan う juga untuk bagian ini. Siapa yang paling ingin Anda temui dibandingkan orang lain? Pikirkan tentang hal ini. Lalu, bayangkan bertemu mereka. Hal pertama yang mereka lakukan adalah meraih lengan Anda dan mencubitnya. Anda berteriak "OW!" (あう) dan mereka tertawa lalu lari.' WHERE id = '7aaab382-385b-4859-a8e7-f4eb67b20436'; -- 会う (vocabulary)
UPDATE items SET meaning_mnemonic = 'asal perusahaan adalah asal segala sesuatu di perusahaan Anda. Ini adalah basis utama Anda. Ini adalah kantor pusat Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '4a8f03f0-aa0d-4485-b2c2-e21581d7f499'; -- 本社 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Jika Anda beruntung, Anda sudah mengetahui bacaan kata yang (sangat) umum ini. Itu adalah kata untuk "Saya", mungkin salah satu hal pertama yang Anda pelajari dalam bahasa Jepang. Bacaannya adalah わたし. Jika Anda belum mengetahuinya, coba pikirkan: "Apa, し?" mengacu pada pembacaan kanji yaitu し.' WHERE id = 'b56a8c95-175d-4f22-9fd4-57f8fc56d9b0'; -- 私 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dengan atap di atas kepalanya, seorang wanita dapat bersantai. Dia tidak perlu khawatir tentang hujan atau salju atau mencari tempat yang aman untuk tidur. Atapnya juga super murah, sehingga dia bisa bersantai dengan keuangannya.', reading_mnemonic = 'Bagaimana cara membaca kanji **Tenang** (安)? Ingat saja bahwa **Angsa/Anak** sangat menyukai tenang! Hubungan erat ini akan membantu Anda mengingat bunyi **あん**.' WHERE id = 'd935e776-2ce1-41cd-b0e3-77f4e0b9693b'; -- 安 (kanji)
UPDATE items SET meaning_mnemonic = 'Tempat perusahaan bertemu Anda adalah perusahaan Anda. Sony adalah sebuah perusahaan. Nintendo adalah sebuah perusahaan. Dll.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '4d31c5a0-1471-4c88-ac56-7777086fa1ec'; -- 会社 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah cara untuk membuat sesuatu. Inilah cara membuat sesuatu. Anda akan melihat ini untuk petunjuk dalam membangun sesuatu.', reading_mnemonic = 'Ini menggunakan bacaan kun''yomi dari vocab kata 作る dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = '67bad6a7-6e4c-4fb0-b040-4396baa260fc'; -- 作り方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'cara Anda mengatakan sesuatu dapat diterjemahkan sebagai aksen Anda... tapi ini jauh lebih besar. Ini adalah keseluruhan "cara" berbicara. Ini adalah dialek. 

Anda bahkan dapat menganggap 方 sebagai "arah" di mana Anda pergi ke berbagai arah di suatu negara dan menemukan dialek yang berbeda, jika cara berpikir seperti itu membantu.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '852c7c14-8884-4b77-8c65-e27d6d23c724'; -- 方言 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti kematian, jadi versi kata kerjanya adalah to die.', reading_mnemonic = 'Bacaannya sama dengan yang Anda pelajari dengan kanji.' WHERE id = 'c219a0bb-4a75-4340-8425-ce8b8dc4fbd8'; -- 死ぬ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda memasuki sebuah perusahaan, Anda sebenarnya bergabung dengan sebuah perusahaan. Selamat datang, rekrutan baru. Bersiaplah untuk dikaburkan!', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '80a9abd0-face-4ef8-a29a-f6fae5896e07'; -- 入社 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bahwa 文字 berarti "huruf". Jadi, apa itu "huruf kecil"? Itu akan menjadi huruf kecil.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Namun, 小 menggunakan bacaan kun''yomi dan 文 merupakan pengecualian di sini, jadi inilah mnemonik untuk membantu Anda mengingatnya:

Anda mempelajari huruf kecil dari 子 Moe (こも). Benar sekali, setelah Moe mengajarimu semua huruf, putranya 子 Moe mengajarimu huruf kecil. Kerja tim seperti itu.' WHERE id = '38924381-e7e5-4fa8-baf3-b4ff53b871a1'; -- 小文字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sesuatu tangan buatan, maka itu adalah buatan tangan!', reading_mnemonic = 'Bacaan kanji ini adalah bacaan kun''yomi. Anggap saja kata ini sebagai dua kata terpisah yang disatukan (手 dan 作る). Kata る di 作る diubah menjadi り karena merupakan kata sifat, dan つ di つくり diubah menjadi づ karena cara kata-katanya digabungkan satu sama lain. Anda harus mengetahui sebagian besar bacaan yang ada dalam kata ini, meskipun mungkin perlu sedikit pemikiran untuk memilah perubahan kecil dalam bacaan tersebut.' WHERE id = '5e7688f3-ae65-4d67-95e1-c63e2b87de3e'; -- 手作り (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti memiliki sehingga versi kata kerjanya berarti to has. Arti alternatifnya adalah ada meskipun ini hanya mengacu pada benda mati yang tidak hidup, bukan benda bergerak dan hidup. Jadi sebenarnya, ini mirip dengan "memiliki" juga.

Kanji tidak terlalu sering digunakan untuk kata ini, jadi saat Anda menulis gunakan saja kana. Namun terkadang Anda akan melihat kanji yang digunakan, jadi penting untuk bisa mengenalinya!', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Memiliki sesuatu sangatlah menyenangkan. Tapi sekarang, satu-satunya yang kamu miliki hanyalah jeritan. Bayangkan ini. Anda berada di ruangan yang benar-benar kosong tanpa harta benda. Anda membuka sebuah kotak kecil dan melihat ke dalam. Berisi teriakan yang meneriakkan: "AAAAHHHH" (あ).' WHERE id = '789174f6-9c76-4bc3-9600-7f612e664752'; -- 有る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kelompok radikal malam ada di bawah tanah. Siapa yang melakukan hal-hal di bawah tanah pada malam hari? Yakuza. Bayangkan anggota Yakuza menyelinap di kereta bawah tanah, atau di selokan. Mereka pasti sedang merencanakan sesuatu yang tidak baik di bawah sana.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0d9e36e7-a722-4f03-b487-dd54155e2fb1'; -- 歹 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanopi. Lihat kainnya menjuntai ke bawah dan ujung kecil di tengahnya menahannya? Anda bisa duduk di bawah sini dan menikmati hari musim panas yang cerah tanpa terkena sinar matahari!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '109bcb35-315f-47ea-b361-1e2488524eaa'; -- 广 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah pisau. Lihat bagaimana ia memiliki dua sisi yang tajam? Dan ada pegangan kecil di bagian bawah untuk... yah pegangannya. Hati-hati jangan sampai melukai diri sendiri!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8e475e89-af31-4d84-a596-8d4fb2c37829'; -- 刂 (radical)
UPDATE items SET meaning_mnemonic = 'Apakah Anda melihat pria itu melakukan tendangan naga terbang ke kanan? Dengan apa dia mencapai target? Jelas sekali itu adalah kaki miliknya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'f3054be3-2053-4ef7-a4c1-bcebe0aaefd0'; -- 足 (radical)
UPDATE items SET meaning_mnemonic = 'Di dalam kepala Anda, Anda hanya bisa memikirkan orang, orang, dan lebih banyak orang. Ini buruk, karena sebenarnya yang kamu inginkan hanyalah daging mereka, karena kamu adalah sejenis kanibal yang sakit... dasar monster. Ketika Anda memikirkan "orang" di kepala Anda, Anda sebenarnya hanya memikirkan tentang lebih banyak daging yang bisa Anda makan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '85b3c535-4c7c-4fd2-9806-2e4e1db204db'; -- 肉 (radical)
UPDATE items SET meaning_mnemonic = 'Di bawah topi ada dua orang yang bertemu secara pribadi. Lihatlah mereka meringkuk di sana. Mereka pasti punya alasan ingin bertemu di tempat privat seperti itu, tapi itu bukan hak Anda untuk menilai. Mungkin lain kali Anda harus bertemu dengan seseorang, Anda juga akan bersembunyi di bawah topi bersama mereka.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'fc7064fc-7638-45e4-835b-bf3ff46c1491'; -- 会 (radical)
UPDATE items SET meaning_mnemonic = 'Ini adalah kunci yang bentuknya sangat aneh, namun tetap saja ini adalah kunci.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '14f0d720-ede2-4b19-ba2e-3a83c19fc566'; -- 乍 (radical)
UPDATE items SET meaning_mnemonic = 'Anda tahu kata 足りる dari Level 4. Kata apa ini? justru sebaliknya (bentuk negatif pada kata kerja adalah ない). Jadi, apa kebalikan dari 足りる (Mencukupkan)? Kebalikannya adalah tidak cukup atau tidak cukup.', reading_mnemonic = 'Pembacaannya sama dengan 足りる (たりる) yang seharusnya Anda lihat di Level 4.' WHERE id = '7992b16c-53f1-4be1-9a37-7e4c3526cd92'; -- 足りない (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika sesuatu dekat dekat (karakter 々 mengulangi kanji sebelumnya) hal itu akan terjadi dalam waktu dekat, atau segera. 

Hal ini agak kabur, dan terserah kepada orang yang berbicara untuk memutuskan seberapa cepat segera itu. Tergantung pada orang dan situasinya, secara teknis dapat digunakan untuk apa pun hingga beberapa tahun!', reading_mnemonic = 'Bacaannya adalah bacaan kun''yomi sebanyak dua kali; itulah yang kamu pelajari dengan vocab kata 近い dari level sebelumnya. 近 kedua akan dikonversi menjadi ぢか, jadi perhatikan itu.' WHERE id = 'aea7f0c9-0731-4902-995d-3cedb9ceed32'; -- 近々 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari banyak? Ini juga banyak (atau bisa dibilang banyak). Ngomong-ngomong, ada banyak sekali kanji yang harus dipelajari ya?', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Pikirkan sesuatu yang banyak. Tidak masalah apa pun asalkan Anda membayangkan jumlahnya yang konyol. Banyak dari mereka. Begitu banyak sehingga mereka mulai menyerbu dan menghancurkan Anda. Hal terakhir yang Anda teriakkan adalah "おお!!!" saat kamu hancur.' WHERE id = '5705e2fb-70a5-4e67-a508-1ede7d386b22'; -- 多い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya hampir persis sama. Itu berarti mereka juga berbagi makna. kaki adalah kaki, tahu?', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Jika Anda ingat dalam mnemonik radikal/kanji, Anda menendang seseorang dengan kaki Anda. Tapi apa yang terjadi setelah Anda menendangnya? Ternyata itu terbuat dari api, dan kamu baru saja membakar kakimu hingga menjadi abu (あし). Bayangkan ini terjadi.' WHERE id = '61f4657f-8085-4a26-ab6b-ff96081dfbaf'; -- 足 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki sesuatu yang tidak cukup. Ketika ada sesuatu yang tidak mencukupi, Anda mengalami kekurangan. Perlu diingat bahwa ini adalah kekurangan fisik, bukan kekurangan kemampuan mental atau semacamnya. Untuk mengingat hal ini, coba pikirkan bagaimana 足 juga berarti "kaki". Apa itu kaki? Sesuatu yang bersifat fisik. Itu sebabnya ini adalah kekurangan fisik.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'da335c6e-ab2a-4bd8-9fe4-aaec4105a3bc'; -- 不足 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji sendiri berarti salinan, tapi apa itu salinan? Pada dasarnya ini adalah sebuah foto, itulah sebabnya kata ini berarti difoto, atau berada di dalam sebuah foto. Anda tahu yang ini "untuk difoto" karena diakhiri dengan る. Seseorang mengira Anda "rude" sehingga mereka memotret Anda.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian うつ. Anda bersikap kasar, bukan? Itu sebabnya kamu difoto. Mengapa kamu kasar? Anda melakukan beatboxing, terus-menerus mengucapkan うつうつうつ berulang kali. Ucapkan juga dengan lantang.' WHERE id = '6d2b7ac0-e461-4fc0-bd1a-d635e5e87542'; -- 写る (vocabulary)
UPDATE items SET meaning_mnemonic = 'musim dingin istirahat! Tunggu, tidak ada yang menyebutnya begitu. Ini adalah liburan musim dingin atau liburan musim dingin.', reading_mnemonic = 'Bacaannya sama-sama bacaan kun''yomi. Mudah-mudahan Anda sudah mempelajarinya saat mengerjakan kosakata di level sebelumnya sehingga yang perlu Anda lakukan sekarang hanyalah menggabungkan dua kata yang terpisah menjadi satu kata yang lebih besar. Tolong jangan mengambil liburan musim dingin sampai Anda memahami kata ini.' WHERE id = 'cc18bddc-e14c-41ce-9808-fdd30144fe19'; -- 冬休み (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika matahari telah melewati salib inilah waktunya untuk pergi ke gereja... yang mana ini sangat pagi. Dan jika Anda ingin datang ke gereja lebih awal, Anda harus cepat, jika tidak, Anda akan terlambat.', reading_mnemonic = 'Anda harus bangun pagi-pagi sekali untuk makan semangkuk **Soto** (sou) hangat.' WHERE id = '69c8b732-e0ca-4c50-beed-271ae9beaf8b'; -- 早 (kanji)
UPDATE items SET meaning_mnemonic = 'Saat Anda mengadakan besar pertemuan, ada banyak orang yang berkumpul. Mengapa Anda mengumpulkan banyak orang? Mungkin untuk konvensi atau semacam turnamen atau event.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Tahukah Anda bahwa Jepang mempunyai seluruh konvensi tentang kayak dasi (たいかい)? Mereka rutin mengadakan turnamen di mana mereka bermain kayak hanya dengan menggunakan dasi! Kedengarannya cukup melelahkan...' WHERE id = '2c360e40-ee86-43fc-b825-f940909e9825'; -- 大会 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari murah? Ini juga murah. Saatnya pergi ke toko 100円 dan membeli beberapa barang 安い, oke?', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

"Apakah kamu ingin item ini dengan harga murah?" 

"Eh, ya (やす) tolong!"' WHERE id = '2c20b5b7-e762-4667-b1da-aa361eb0ffa4'; -- 安い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika seseorang mencoba menggali pribadi kotoran pada Anda, katakan tidak, terima kasih, hal itu sudah masa lalu. Beberapa hal harus tetap menjadi masa lalu. Tidak semua orang perlu mengetahui segalanya tentang kehidupan dan masa lalu Anda.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Masa lalu** (去), bayangkan Anda sedang membawa **きょ** untuk ditaruh di atas masa lalu. Kejadian unik ini mengingatkan Anda pada bunyi **きょ**!' WHERE id = '205feb54-24cb-4604-8d4d-5e752f320441'; -- 去 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari dekat? Itu dekat atau dekat.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian ちか untuk dapat membaca kata ini. Bayangkan seseorang yang dekat dengan Anda... Terlalu dekat. Mereka begitu dekat dengan Anda sehingga mereka menyentuhkan pipinya (ちか) ke pipi Anda. Rasakan pipimu, ini semakin canggung.' WHERE id = 'b4ad9a87-d159-4612-886f-8f77f07af1d4'; -- 近い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda bertemu dan berbicara dengan orang lain, Anda sedang melakukan percakapan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '28a1b7f9-25f3-4175-853c-1e7f39c0a297'; -- 会話 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Oke, jadi yang ini aneh sekali, maaf. Masing-masing dari kita hanya mendapatkan satu tubuh seumur hidup, bukan? Apa apa-apaan ini! Bagaimana jika saya menginginkan lebih dari satu tubuh. Mari kita semua marah tentang hal ini bersama-sama.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri. Berhati-hatilah karena いち disingkat menjadi いっ di sini!' WHERE id = '12c37eb5-cf5e-489b-9f33-10cf06b3fe8e'; -- 一体 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti membuat. Bentuk kata kerjanya adalah to make.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian つく. Untuk melakukan itu mari pikirkan tentang sesuatu yang akan Anda buat. Bayangkan sesuatu yang sangat mengagumkan. Anda menyelesaikannya dan melihat karya agung Anda. Sungguh menakjubkan. Anda langsung menyadari bahwa itu terlalu keren (つく) untuk dilihat oleh masyarakat umum. Anda melanjutkan untuk menghancurkannya. Itu terlalu keren.' WHERE id = '5312bdac-8898-451f-bac3-553433582dcf'; -- 作る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. 

Kanji itu sendiri berarti lebar, dan versi kata kerjanya adalah apa yang terjadi ketika Anda mencoba membuat sesuatu lebih luas. Bagaimana cara membuat sesuatu lebih luas? Benar sekali, Anda harus menyebarkan sesuatu, membuka sesuatu atau membuka sesuatu. Semua tindakan itu akan membuat segalanya menjadi lebih luas!

Ini adalah kata kerja transitif. Artinya dibutuhkan objek langsung. Anda menyebarkan sesuatu. Seperti koran, atau kain di atas meja.', reading_mnemonic = 'Karena kata ini memiliki okurigana (hiragana yang melekat pada kanji), Anda tahu bahwa kemungkinan besar itu adalah bacaan kun''yomi. Anda mempelajari bacaan ini dengan kanji, namun berikut ini mnemonik pengingat untuk membantu Anda:

Anda akan menyebarkan sesuatu. Apa yang akan kamu sebarkan? Bagaimana dengan lengan Anda, sehingga Anda bisa terbang ke angkasa seperti pahlawan super (ひろ)! Kebanyakan pahlawan bisa terbang ketika mereka merentangkan tangannya lebar-lebar!' WHERE id = '25395bac-b32f-4415-8f6f-28afbcbd874d'; -- 広げる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki diri bagian Anda. Bagian dari diri Anda adalah Anda. Ini adalah diri sendiri. Ini adalah saya sendiri. Tunggu, siapa bagian diriku ini? Anda tidak yakin... tunggu, tidak, itu saya sendiri. Apakah itu? Jadilah sedikit psikotik sejenak saat Anda mencoba mengingat kosakata ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7ca73d80-942b-4913-af7b-9211d6fe9348'; -- 自分 (vocabulary)
UPDATE items SET meaning_mnemonic = 'besar buatan! Apa penghasilan besar Anda? Lebih besar dari apa pun. Ini adalah epic Anda (seperti dalam epik yang Anda tulis). Bisa juga berupa sebuah epik, epic saga, dan mahakarya.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Tahukah kamu kalau ada sebuah epik tentang karung dasi (たいさく)? Ini adalah mahakarya tentang karung ajaib yang menghasilkan dasi demi dasi demi dasi. Mirip seperti Panci Bubur Ajaib, namun dilengkapi karung dan dasi.' WHERE id = '47f54492-5576-4249-92be-2840b138363c'; -- 大作 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat 地下, yang berarti "di bawah tanah". Ya, ini adalah tanah dan di atas digabungkan menjadi satu, jadi saya yakin Anda bisa menebak bahwa ini artinya di atas tanah. Namun biasanya benda di atas tanah tidak mengapung (kecuali jika Anda berada di luar angkasa), sehingga benda tersebut benar-benar di atas tanah.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'caa109d7-57f0-444f-b173-30cfea742a26'; -- 地上 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti mengatakan, jadi versi kata kerjanya adalah to say.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Untuk mengingat bacaan い kita menggunakan kata "elang". 

Anda mencoba mengatakan sesuatu, tetapi setiap kali Anda mencoba mengatakan sesuatu, seekor elang (い) menukik ke bawah dan mematuk wajah Anda lalu terbang menjauh. Bayangkan saja diri Anda mengucapkan sedikit kata, lalu seekor elang jatuh menimpa wajah Anda. Lalu, kamu menunggu dalam diam. Tidak ada yang terjadi. Anda mencoba mengatakan sesuatu lagi, dan elang itu menyerang Anda lagi.' WHERE id = 'bf802987-d5cd-483e-8f82-9af73de396fb'; -- 言う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saya tahu, ini kapak yang tampak aneh. Tapi coba pikirkan seperti ini: huruf "T" ada di tebing. Apa itu "T"? Tentu saja harus Pak T yang super hebat. Bayangkan Tuan T yang memegang kapak yang menakutkan, berlari mengejar Anda sambil berteriak, "Kasihan sekali orang bodoh itu!" sambil mencoba menebasmu. Itu menghasilkan kapak yang cukup menakutkan.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '86b3f9a3-1e99-4745-8aa4-a3881a8a8bb3'; -- 斤 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal warna dan warna memiliki tampilan dan makna yang sama.', reading_mnemonic = 'Tahukah Anda bahwa **Warna** (色) ini sebenarnya dibuat dari tumpukan **いろ**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **いろ**.' WHERE id = '466fbeaa-f861-45dc-9ce9-c68e534212ec'; -- 色 (kanji)
UPDATE items SET meaning_mnemonic = 'Karena kata ini diakhiri dengan bunyi う, Anda dapat mengetahui kemungkinan itu adalah kata kerja. Bagian kanji berarti dekat. Versi kata kerjanya adalah mendekati, mendekati atau mendekati. Pada dasarnya, gagasan umumnya adalah Anda semakin dekat dengan sesuatu. Anda menjadi lebih dekat. Anda mendekat.', reading_mnemonic = 'Ada hiragana yang melekat pada kanji ini, yang artinya mungkin bacaan kun''yomi (dan memang demikian). Anda pernah melihat kun''yomi membaca melalui kata 近い. Jadi, asal kamu tahu kata itu, kamu pasti bisa membacanya juga.' WHERE id = 'fa9aa47f-a751-4eed-8a1f-e4dfb31c555e'; -- 近づく (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ngomong-ngomong, ini menyiratkan bahwa itu adalah kakak laki-lakimu. Bukan milik orang lain.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Anda belum mempelajari bacaan ini, jadi inilah mnemonik untuk membantu Anda:

kakakmu berbeda dari milik orang lain. Dia memiliki kekuatan yang aneh... beberapa orang akan mengatakan kekuatan kekuatan. Tahukah kamu siapa namanya? Itu Ani (あに), kependekan dari Anikin... tunggu sebentar, apakah itu terdengar familier?' WHERE id = '7e0227c6-891e-4e33-af87-cf37a362c437'; -- 兄 (vocabulary)
UPDATE items SET meaning_mnemonic = 'nama yang ditulis dengan huruf adalah nama belakang. Dulu, nama belakang Anda adalah nama yang penting (bagaimanapun juga itu adalah nama keluarga Anda, dan keluarga adalah raja pada masa itu). Ini adalah nama yang akan kamu tulis dalam kanji... alias dalam huruf. Jadi itulah mengapa kombinasi kanji ini berarti "nama keluarga".', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. 

Perhatikan bahwa bagian 名 adalah bacaan alternatif, jadi sesuaikan pemikiran Anda sehingga Anda bisa sampai ke みょう. Bayangkan saja seseorang berkata "lebih" dengan aksen yang lucu. Mereka mengatakan "myou" bukannya "lebih". Bayangkan mereka mengatakan bahwa mereka memiliki orang-orang seperti Anda di keluarga mereka daripada keluarga Anda. Nama keluarga mereka lebih tersebar di antara orang-orang saya daripada nama keluarga Anda.' WHERE id = '0fd64212-b1f8-4426-b8b2-4cf00a40dca9'; -- 名字 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti berpikir, sehingga versi kata kerjanya adalah to think about atau to mempertimbangkan. 

Perhatikan bahwa ini bukan "berpikir" yang seperti "Saya pikir dia adalah seorang power ranger." Tidak, ini lebih seperti tindakan berpikir sebenarnya. Itu sebabnya kata ini adalah "berpikir tentang" atau "mempertimbangkan" dan bukan "berpikir" yang biasa yaitu 思う.', reading_mnemonic = 'Jika Anda ingin berpikir, cara terbaik melakukannya adalah dengan melakukan conga (かんが). Bayangkan diri Anda melakukan conga dan berpikir jauh. Anda sangat terinspirasi! Pikiran mengalir sebebas gerakan tarian Anda yang manis dan lambat.' WHERE id = 'aa53743f-e222-4728-8cca-f184ed98148d'; -- 考える (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini kanjinya sama dengan hiragana yang ditempelkan, dan juga berarti sama.

Ini agak aneh di antara kata sifat bahasa Jepang, karena Anda tidak memerlukan な atau い untuk melampirkannya ke kata benda. Jadi biasanya dianggap sebagai kata sifat な yang "khusus". Lihatlah kalimat konteks untuk melihatnya beraksi!', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Ketika Anda memikirkan kata "sama", pikirkanlah pemilik sama (おな). Anda sedang melihat sebuah restoran yang memiliki tanda bertuliskan, "Pemilik baru!" Namun, ketika Anda masuk, Anda melihat itu adalah pemilik buruk yang sama yang Anda ingat sebelumnya. Benar-benar pembohong.' WHERE id = 'f3299fee-acb8-4723-913e-c7d7b17f8465'; -- 同じ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri artinya menyalin jadi kalian pasti tahu kalau ini artinya menyalin. Anda tahu kata ini berarti "menyalin" karena diakhiri dengan す. Anda menyalin dokumen yang Anda perlukan untuk menuntut (す) seseorang yang telah menipu Anda.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian うつ. Untuk mengingatnya, anggaplah diri Anda sebagai seorang beatboxer. Anda mengucapkan うつうつうつ berulang kali. Masalahnya, beatboxer lain akan menyalin semua yang Anda lakukan. Itu sebabnya Anda menuntutnya.' WHERE id = 'df567719-f097-4384-b5ed-335766fec971'; -- 写す (vocabulary)
UPDATE items SET meaning_mnemonic = 'mendekati hari adalah hari yang akan segera segera. Ini adalah hari yang akan datang dalam beberapa hari atau dalam hari-hari mendatang.

Dengan kata lain, Anda tidak akan menggunakan kata ini untuk sesuatu yang akan terjadi dalam beberapa menit, atau beberapa bulan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 日 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Sebentar lagi, tempat tinggalmu akan memiliki dua raja. Wah, ada dua (きんじつ)? Ya, negara Anda adalah negara pertama yang memiliki dua raja.' WHERE id = '7b9f0885-106e-4425-9c6a-04db132df29c'; -- 近日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Intinya Anda memiliki kanji 早 dua kali, karena 々 hanyalah kanji pengulang. Ketika Anda memiliki sesuatu lebih awal dua kali, hal itu jelas memiliki semacam urgensi. Anda harus mengambil tindakan segera setelah Anda menyelesaikan apa pun yang Anda lakukan di sana.', reading_mnemonic = 'Pembacaannya hanyalah pembacaan on''yomi (yang dipelajari dengan kanji) dua kali berturut-turut.' WHERE id = 'c0485a5f-8070-45b4-a032-33f3a00212be'; -- 早々 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat 足りる? Itu berarti "menjadi cukup". Bagaimana Anda bisa membuat sesuatu menjadi cukup? Anda terus menambahkan sesuatu ke tumpukan sampai Anda mencapai titik di mana jumlahnya cukup! Itu sebabnya kata kerja ini adalah menambahkan sesuatu, karena Anda terus menambahkan sesuatu sampai Anda 足りる.

Kata kerja ini bersifat transitif, seperti kebanyakan kata kerja yang berakhiran す, itulah sebabnya Anda menambahkan sesuatu. Itu tidak bertambah dengan sendirinya. Mungkin Anda menambahkan terlalu banyak sehingga seseorang mencoba menuntut (す) Anda atas tumpukan tupai jahat yang Anda simpan di luar.', reading_mnemonic = 'Bacaannya sama dengan 足りる, jadi jika Anda mengetahuinya, Anda bisa menambahkannya ke dalamnya.' WHERE id = 'b4ee7a19-cd26-4647-811c-a32ab65d1285'; -- 足す (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kehidupan yang keluar dari bumi terdiri dari berbagai jenis material. Terkadang kain, terkadang adonan, tetapi semuanya harus dibuat dari sesuatu.', reading_mnemonic = 'Kata ini menggunakan bacaan kun''yomi baru untuk 生 dan bacaan on''yomi baru untuk 地. Anda belum mempelajari salah satu bacaan ini, maaf! Berikut beberapa mnemonik untuk membantu Anda:

Jika kamu menginginkan bahan terbaik untuk membuat pakaian atau pai, kuncinya (き)adalah bertanya kepada Yesus (じ)! Dia tahu segalanya, termasuk di mana menemukan bahan untuk benda aneh apa pun yang Anda buat. Ingat saja: Siapa kuncinya? Yesus!' WHERE id = '4ca81e1b-35e3-4dd0-a682-0182dd927933'; -- 生地 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika yang bisa Anda lihat hanyalah besar tubuh dari sesuatu, maka Anda hanya akan mendapatkan gambaran umum tentang benda itu. Anda bisa mengatakan bahwa itu umumnya dengan cara tertentu, tapi itu tentang semuanya. Anda akan mendapatkan inti, tapi tidak lebih.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Secara umum, mewarnai dasi Anda adalah ide yang buruk (だいたい). Polisi berdasi bukanlah penggemar beratnya, dan Anda tidak ingin ditangkap!' WHERE id = 'e5869fca-50d9-4494-b10b-752becd8fe9c'; -- 大体 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apa yang dimaksud dengan "industri dari buatan"? Tentu saja, itu terjadi ketika Anda rajin membuat sesuatu. Itu hanya bisa berupa handicraft atau craft! Hal ini juga bisa berarti manuver, dalam artian melakukan sesuatu di belakang layar.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 作 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

kerajinan tangan favoritmu adalah membuat こういち karung (こうさく). Itu adalah karung yang bentuknya persis seperti こういち, dan Anda sangat pandai membuatnya. Sebentar lagi, kantor Tofugu akan dihias seluruhnya dengan karung こういち Anda.' WHERE id = 'e412bb0f-4ca9-404d-941f-86c40ac97493'; -- 工作 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat 広い? Ya beginilah, kecuali kata kerjanya. Saat sesuatu melakukan tindakan melebar, itu berarti menyebar, memperluas, atau meregangkan.

Anda sudah mempelajari 広げる, yang digunakan saat ANDA menyebarkan sesuatu. 広がる, sebaliknya, berarti sesuatu menyebar dengan sendirinya. Perlu disebutkan bahwa banyak kata kerja intransitif yang diakhiri dengan がる, dan ini tidak terkecuali. Bayangkan saja bagaimana dengan seorang gadis (がる) yang kamu tahu bisa melakukan segalanya sendirian. Dia tidak pernah membutuhkan bantuan dari orang lain.', reading_mnemonic = 'Bacaannya juga sama dengan 広い, asalkan Anda tahu bahwa Anda juga mengetahui bacaan ini.' WHERE id = 'fb572519-bc47-4d4e-9289-10635ff5af0b'; -- 広がる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika seseorang bertanya apakah Anda ingin lutut terpisah (に), Anda akan menjawab tidak terlalu. Maksud saya, Anda belum pernah memikirkannya, tapi apakah Anda benar-benar membutuhkan lebih banyak lutut? Tidak juga...

Dalam arti pertama ini, 別に sering digunakan sendiri, atau dengan kata kerja atau kata sifat negatif, seperti dalam 別に長くない (tidak terlalu panjang).

Namun, ketika 別に digunakan dengan kata kerja positif, sering kali maknanya adalah secara terpisah, atau di samping. Lagi pula, ketika Anda harus melakukan sesuatu secara terpisah, Anda harus melakukannya sebagai tambahan terhadap hal lain. Suka mempelajari makna ini selain yang pertama. Sungguh sebuah tugas!', reading_mnemonic = 'Bacaannya hanyalah bacaan yang Anda pelajari dengan kanji. Bagus sekali!' WHERE id = 'e5a741d8-7f1f-4acc-afc2-9d26a6065461'; -- 別に (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda keluar rumah Anda dan bertemu seseorang. Anda tidak bermaksud untuk bertemu mereka, tetapi hal itu tetap terjadi. Itu sebabnya kata ini berarti bertemu secara kebetulan.', reading_mnemonic = 'Pembacaannya adalah kata 出る dan kata 会う, yang keduanya mudah-mudahan sudah Anda lihat. Bagian 出 mungkin membingungkan, tetapi Anda biasanya dapat berasumsi bahwa jika salah satu bagian dari kata tersebut adalah kun''yomi / bacaan vocab, bagian lainnya juga demikian, itulah sebabnya 出 menggunakan bacaan vocab.

Oh ngomong-ngomong, kata ini juga bisa ditulis seperti ini: 出合う. Ini tidak umum, tetapi Anda mungkin menemukannya sesekali, jadi ada baiknya Anda mengetahuinya!' WHERE id = '466e7394-14ed-4417-9b40-5081b575f0c1'; -- 出会う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti kaki atau cukup, dan kita akan menggunakan arti "cukup" untuk kata ini! Kata ini berarti menjadi cukup.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak mempelajari bacaan tersebut dengan kanji ini, jadi inilah mnemonik untuk membantu Anda mengingat bagian た. Kapanpun kita perlu mengingat た kita menggunakan kata "taco". 

Apa yang kamu punya cukup? Apa yang cukup? Ternyata itu taco (た). Bunkermu penuh dengan mereka dan akan cukup untuk bertahan di musim dingin.' WHERE id = 'b8c04a52-effd-41cc-9b28-a517b84c8377'; -- 足りる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat kata radikal untuk setetes (cairan)? Ini adalah dua tetes, bukan satu. Saat Anda melihat dua tetes, Anda harus berpikir, "tahap air selanjutnya". Apa tahap selanjutnya? Wah, itu es.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '60b6d463-b6d3-4dc0-83ab-eaa75b4c6999'; -- 冫 (radical)
UPDATE items SET meaning_mnemonic = 'Saat Anda melihat sawah dan jalan di tempat yang sama, Anda akan mendapatkan kota yang utuh!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Kota** (町), bayangkan Anda sedang membawa **Cokelat/Corong** untuk ditaruh di atas kota. Kejadian unik ini mengingatkan Anda pada bunyi **ちょう**!' WHERE id = 'ad4d64e6-2a2f-4b55-9e15-24af7813ea05'; -- 町 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata run dan kanji run sama persis!', reading_mnemonic = 'Anda berlari kencang demi mengejar penjual **Soto** (そう) yang lewat!' WHERE id = '82d9838e-e69f-42bc-89f0-f350cb69cd80'; -- 走 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda menggali sembilan lubang untuk penelitian Anda. Anda harus selalu melakukan penelitian dengan sembilan variabel sehingga Anda dapat membandingkannya sehingga ada angka yang tidak merata.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Penelitian** (究), bayangkan Anda sedang membawa **Kura-kura** untuk ditaruh di atas penelitian. Kejadian unik ini mengingatkan Anda pada bunyi **きゅう**!' WHERE id = '01c8dd0a-0b59-4686-be52-3931ed685a0a'; -- 究 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada seseorang dengan busur dan tongkat, memakai tanduk, menuruni slide. Tipe orang seperti apa yang kamu bayangkan? Menurutku, seseorang adalah anak laki-laki yang belum dewasa. Itu akan menjadi adikmu.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Adik laki-laki** (弟) tiba-tiba berbicara dan meminta **Dadu/Dahi**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **だい**.' WHERE id = 'ff696f0b-b6f6-4685-8004-601d91c8f0aa'; -- 弟 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada gambar daun dari dekat di sawah di dalam kotak. Tunggu, ini bukan sebuah kotak, semua ini hanya sebuah gambar.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Menggambar** (画) tiba-tiba berbicara dan meminta **Gajah/Gagang**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **が**.' WHERE id = '8c042927-b9b3-479c-b23c-9e7f3e863f74'; -- 画 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda berhenti pada slide kecil. Apa yang kamu lakukan sebelum berhenti di sini? Anda sedang berjalaning.', reading_mnemonic = 'Ketika Anda sedang melihat **Berjalan** (歩), tiba-tiba muncul sesosok **Hotel/Hormon** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **ほ**.' WHERE id = '6eb5c8a5-d257-4288-9252-00ded7d1ccad'; -- 歩 (kanji)
UPDATE items SET meaning_mnemonic = 'Ambil bulan cap pada bangku di depan Anda dan gunakan pada semua pakaian Anda. Sekarang bahkan jika Anda menjual atau kehilangan sepotong pakaian, Anda akan dapat menemukannya lagi dengan memeriksa stempel bulan khusus Anda.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Pakaian** (服) tiba-tiba berbicara dan meminta **Fosil/Foto**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **ふく**.' WHERE id = '6220bf2d-345c-4972-a039-428012fb6391'; -- 服 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya sama dengan kanji yang Anda pelajari, artinya Anda tahu bacaannya!' WHERE id = '9b376ace-a649-48a8-a45e-99f3be315581'; -- 赤 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Kamu melihat adik laki-lakimu. Dia orang yang licik. Dia tersenyum padamu. Mengapa? Karena dia menyalakan petasan di kakimu. Itu meledak, membuat jari kaki Anda terbang. Anda berteriak, "OH. Jari kaki? Jari kaki!" (おとうと) saat Anda menyadari apa yang terjadi.' WHERE id = 'b9964ad4-1029-4922-a8ac-652fedf32c90'; -- 弟 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki kakak laki-laki dan adik laki-laki. Wow! Keduanya ada di sini. Ini adalah saudara!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '62384156-5fd7-4f0e-93b4-5d451bb07ede'; -- 兄弟 (vocabulary)
UPDATE items SET meaning_mnemonic = 'diagram dari bumi. Apa lagi selain peta?', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '81cb09f9-88df-4e04-8c44-7c531d843765'; -- 地図 (vocabulary)
UPDATE items SET meaning_mnemonic = 'studi tentang kedokteran adalah ilmu kedokteran. Ini juga bisa disebut medicine, tapi pastikan untuk menganggapnya sebagai "obat" yang ada hubungannya dengan "ilmu kedokteran".', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '271daf40-fc05-45d5-999a-f12f6629ba5a'; -- 医学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang bekerja di bidang kedokteran adalah dokter.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc'; -- 医者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda mencerahkan penelitian Anda, rasanya seperti Anda menyorotinya. Untuk melakukan itu, Anda harus melakukan investigasi. 

Kata ini terutama digunakan dalam situasi akademis dan ilmiah.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e16b73a7-5455-40d3-8900-4e91b53bd151'; -- 究明 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang belajar untuk mencari nafkah. Itu adalah sarjana.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '16058998-d743-432a-a5e1-16d74c7abeff'; -- 学者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Yang membacaing seseorang adalah seseorang yang sedang membaca. Mereka adalah pembaca (sebuah buku, blog, artikel, dll).', reading_mnemonic = 'Pembacaan 読 adalah pembacaan on''yomi, yang tidak Anda pelajari dengan kanji. Bacaan ini adalah どく, dan Anda dapat mengingatnya dengan memikirkan bagaimana Anda adalah pembaca, dan sebagai pembaca Anda memilih tempat untuk membaca. Bagi Anda, tempat terbaik untuk membaca adalah dermaga yang tenang (どく). Duduklah di dermaga dan bersantai. Jadilah pembaca.' WHERE id = 'e614c7e5-3dc2-421a-b33d-633ea9a749d7'; -- 読者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'tindakan dari makaning adalah saat Anda sedang makan.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '704418c4-de8f-4e53-ad99-2d61b39b6b5c'; -- 食事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu bagian kanji berarti mulai. Tanda に di akhir merujuk pada arah. Jadi, anggaplah ini seperti "arah permulaan" yang merupakan awal mula segala sesuatunya. Itu sebabnya kata/frasa ini berarti "pada mulanya."', reading_mnemonic = 'Bacaannya adalah kun''yomi (lihat semua hiragana itu!) tapi itulah bacaan yang kamu pelajari dengan kata 始める, jadi jangan takut, kamu mengerti!' WHERE id = 'a7aa654c-47a3-487a-b43d-2e3e6cc880ca'; -- 始めに (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Bacaannya adalah bacaan yang dipelajari dengan kanji dan menggunakan on''yomi meskipun hanya satu kata. Sangat aneh, tapi nyaman bagi Anda selama Anda mengingat kata bacaan pengecualian ini.' WHERE id = 'f58f9e6d-fda2-4c2f-b1ac-291fc9310363'; -- 服 (vocabulary)
UPDATE items SET meaning_mnemonic = 'terkenal hal suatu daerah adalah produk terkenal mereka, namun kedengarannya lebih baik dalam bahasa Inggris jika Anda mengatakan itu adalah makanan khas lokal. Saat Anda bepergian keliling Jepang, pastikan untuk mencari 名物! Itu selalu menyenangkan.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '810b38d7-aa06-4906-8d50-7f65c2fc747d'; -- 名物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seorang pemimpin mengenakan penutup dan berdiri di luar pada musim dingin. Ditambah lagi saat itu sedang hujan dan dia berlumuran tetesan air. Terlebih lagi, ini adalah malam.', reading_mnemonic = 'Ketika Anda sedang melihat **Malam** (夜), tiba-tiba muncul sesosok **Yoyo** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **や**.' WHERE id = 'f0f62569-831a-4828-82ad-6e5a3422ca56'; -- 夜 (kanji)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin sebuah kata sifat. Apa bentuk kata sifat dari merah? Wah, warnanya merah!', reading_mnemonic = 'Bacaannya sama dengan kanji yang Anda pelajari, artinya Anda tahu bacaannya!' WHERE id = '4a33754a-f4f2-4041-849c-75a99ef2fbbe'; -- 赤い (vocabulary)
UPDATE items SET meaning_mnemonic = 'orang dari tempat tinggal adalah seseorang yang tinggal di tempat tinggal tersebut. Mereka adalah penduduk.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 人 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Yang dipedulikan penduduk di daerah saya hanyalah permata dan Nintendo (じゅうにん). Rumah mereka penuh dengan perhiasan dan barang-barang Nintendo. Bagaimana dengan penduduk di kotamu? Saya yakin mereka semua menyukai perhiasan dan Nintendo juga.' WHERE id = '3c5a5de9-8ce3-41a7-a57a-39024fd73b13'; -- 住人 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika mata Anda berada pada target Anda mengetahui tujuan Anda. Anda juga memperhatikan tujuan (bagaimanapun juga, itulah targetnya!).', reading_mnemonic = 'Pembacaannya adalah pembacaan 目 yang tidak normal. Anda telah melihat bacaan ini dengan 目標 dan 目次, jadi semoga saja saat ini tidak terlalu sulit. Bayangkan saja memberi tahu seseorang 目的 Anda, hanya untuk membuat mereka tertawa di depan Anda dan mulai mengejek もく Anda karenanya. Sekarang Anda tidak begitu yakin apakah tujuan Anda akan berhasil.' WHERE id = '26d875ac-49b6-413d-b028-e0ed408a8926'; -- 目的 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika mobil memiliki langit di dalamnya (dan bukan, katakanlah, sekelompok orang), Anda bebas memberi tumpangan. Jika Anda melihat tanda ini menyala di taksi, jangan ragu untuk menghentikannya, itu akan membawa Anda ke suatu tempat. Ini adalah taksi terbuka.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'fb2d5cc6-418e-4693-80b2-e1da345bac2f'; -- 空車 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Orang yang menggunakansurga untuk keuntungannya adalah seseorang dari surga, seperti malaikat.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'ace9af80-a2be-4128-b9cf-41581fdf56f3'; -- 天使 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Api adalah benda yang membuat lebih banyak api. Pada dasarnya api adalah api.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '498fae4a-ce0b-49ce-b608-391c32a37159'; -- 火事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Setiap hal yang Anda lihat adalah menakjubkan. Anda sudah melihatnya, jadi tentu saja luar biasa. Matamu begitu indah sehingga membuat segalanya mencerminkan dirimu. Dan kamu cantik.', reading_mnemonic = 'Bacaan kata ini sama-sama bacaan kun''yomi. Anda sudah mempelajarinya, jadi Anda seharusnya bisa membacanya sendiri. Ingatlah bahwa ada rendaku di こと dan itu menjadi ごと.' WHERE id = 'ad63dff0-0171-4162-a3bb-376817fb03a0'; -- 見事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'kehidupan benda adalah makhluk hidup, makhluk, atau organism.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '025651b5-e70c-45b5-ae99-5033fada3e35'; -- 生物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ingat bagaimana 生物 berarti "makhluk hidup?" Nah, ketika Anda mempelajari makhluk hidup, Anda sedang mempelajari biologi.', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = 'facbc165-cc56-4322-911a-0e66405c3697'; -- 生物学 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti menuangkan jadi versi kosakata kata kerjanya adalah to pour.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda akan menuangkan saus (そそ).' WHERE id = 'd5bd929f-f589-4be3-930b-7e43b9d2f317'; -- 注ぐ (vocabulary)
UPDATE items SET meaning_mnemonic = 'yang cerah hari bukanlah hari ini (karena hari ini sangat buruk), melainkan besok, karena Anda selalu dapat menantikan hari esok sebagai hari yang lebih baik dan lebih cerah.', reading_mnemonic = 'Bacaannya tidak masuk akal sama sekali. Anda harus mempelajarinya secara langsung, dan tidak bisa mengandalkan kanji pembuatnya. Mengapa besok akan menjadi hari yang cerah dan menakjubkan? Karena Anda membuat ash taco untuk makan malam, dan itu favorit Anda. Bayangkan membayangkan hari esok, penuh dengan abu taco dan kelezatannya. Mungkin Anda bisa menggunakan kulit taco Dorito itu?

Catatan tentang dua bacaan lainnya あす dan みょうにち: あす digunakan dalam berita dan laporan cuaca, dan みょうにち hanya digunakan dalam bisnis, jadi sebaiknya Anda hanya menggunakan あした untuk sekarang. Namun ada baiknya mengetahui bahwa dua bacaan lainnya ada!' WHERE id = '163c2b0b-f2fc-43c9-bc84-497c099611e1'; -- 明日 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain itu, di atas thing terdapat arti matter dan action juga. Seperti kanji, kata ini berkaitan dengan tindakan... hal-hal yang Anda lakukan, misalnya, bukan hal-hal fisik.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Sulit untuk memulai mnemonik dengan kata "benda" atau "tindakan", jadi mari kita lanjutkan mnemonik kanji di mana Anda memberi tanda silang di mulut serigala.  Mengapa kamu melakukannya? Kamu tahu bahwa serigala yang penuh semangat akan memakan mantelmu (こと).' WHERE id = '64047cd7-7507-4f55-b3da-575ddaf2e726'; -- 事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Ini adalah bacaan yang Anda pelajari saat mempelajari kanji, jadi Anda siap melakukannya. Namun, jangan lupa untuk berhenti dan mencium bunga mawar di perjalanan.' WHERE id = '21cf4a39-8aab-4c80-a8cf-4e04f73d2b46'; -- 花 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata radikal untuk merah dan kanji untuk merah adalah hal yang sama!', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Merah** (赤) tiba-tiba berbicara dan meminta **あか**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **あか**.' WHERE id = '89a2bbf9-1a3a-4934-951a-364053cf745e'; -- 赤 (kanji)
UPDATE items SET meaning_mnemonic = 'Kendaraan yang berjalan-pergies adalah berjalan dan memindahkan Anda ke tempat lain. Anda sedang bepergian!

Kami biasanya menggunakan kata ini untuk menggambarkan kendaraan yang bergerak atau berjalan seperti mobil dan kereta api. Perhatikan kalimat konteks tersebut untuk memastikan Anda menggunakannya dengan benar. ;)', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '35511cfb-c21c-42c5-a39d-07a00cc3990b'; -- 走行 (vocabulary)
UPDATE items SET meaning_mnemonic = 'pemimpin dari master mendapatkan tempat tinggal terbesar. Dia tinggal di sebuah rumah besar di puncak gunung, dikelilingi oleh semua tuan lainnya di tempat tinggal mereka yang lebih kecil.', reading_mnemonic = 'Bagaimana cara membaca kanji **Tempat tinggal** (住)? Ingat saja bahwa **じゅう** sangat menyukai tempat tinggal! Hubungan erat ini akan membantu Anda mengingat bunyi **じゅう**.' WHERE id = '42b6568f-aa17-4f17-bfb4-2b3a48433d7c'; -- 住 (kanji)
UPDATE items SET meaning_mnemonic = 'rasa dari arah ini adalah salah satu yang ingin saya ikuti dan ikuti, bersama Anda. Anda memiliki selera yang bagus dan Anda menuju ke arah yang baik. Maukah kamu menjadi sekutu saya? Saya akan menjadi pendukung Anda.', reading_mnemonic = 'Kata ini menggunakan bacaan on''yomi untuk 味 dan bacaan kun''yomi untuk 方. Untungnya, Anda sudah mempelajari keduanya sehingga Anda seharusnya bisa membaca kata ini!' WHERE id = '6c88ceda-18b5-4497-b23c-0824e2e79753'; -- 味方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ketika jualing dipotong, itu berarti sesuatu terjual habis. Anda akan sering melihat kata ini di toko-toko (atau, mudah-mudahan tidak...) di Jepang. Berhati-hatilah jika Anda mampu!', reading_mnemonic = 'Kata ini menggunakan bacaan kun''yomi untuk kedua kanjinya, tapi kamu sudah mengetahui keduanya sekarang, jadi kamu harus bisa membacanya juga!' WHERE id = '969ade5e-79d2-46ff-ae8e-a759e06a3146'; -- 売り切れ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seorang pria kulit putih melompat ke dalam kolam dengan target dicat di bagian bawah. Dia mengincar sasarannya.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Sasaran** (的), bayangkan Anda sedang membawa **Teko/Tekko** untuk ditaruh di atas sasaran. Kejadian unik ini mengingatkan Anda pada bunyi **てき**!' WHERE id = 'eb8d68d2-054f-4a19-ad6b-ebc075408b01'; -- 的 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Kata-kata yang terdiri dari satu kanji biasanya menggunakan bacaan kun''yomi, sedangkan kata yang satu ini menggunakan bacaan on''yomi. Untungnya, bacaan ini sama dengan yang Anda pelajari dengan kanji, jadi tidak terlalu sulit untuk mengingatnya.' WHERE id = '1068a532-579e-491d-82d8-d2dce7b73142'; -- 図 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Dahulu kala, seseorang memasang kanopi di atas keberuntungan mereka dan menciptakan toko pertama. toko ini didasarkan pada keberuntungan, tetapi sejak itu banyak toko berbeda bermunculan!', reading_mnemonic = 'Untuk mengingat cara baca kanji **Belanja** (店), bayangkan Anda sedang membawa **てん** untuk ditaruh di atas belanja. Kejadian unik ini mengingatkan Anda pada bunyi **てん**!' WHERE id = '0e245655-2560-4142-a1dc-0a699f18db39'; -- 店 (kanji)
UPDATE items SET meaning_mnemonic = 'Apa yang bisa kamu lakukan dengan tangan kosong? Karate, itulah yang terjadi. Karate dipraktekkan tanpa senjata, jadi dengan tangan kosong!', reading_mnemonic = 'Kata ini menggunakan kun''yomi dari kedua kanji, dan Anda belum mempelajari kun''yomi ini untuk 空. Selama Anda tahu artinya, bacaannya seharusnya mudah, tapi berikut ini mnemonik untuk membantu Anda berjaga-jaga:

Karate berasal dari (から) Jepang!' WHERE id = 'e7f3e8cb-f347-4386-8392-3c73c38c6b4e'; -- 空手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Lihat orang yang berlarining? Namun, jangan bingung membedakannya dengan kaki (足). Kepalanya hanya terbentur karena orang ini larinya kencang sekali.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'fc69966b-a1be-464a-9347-ec57baaf1b4c'; -- 走 (radical)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat 大学 yang berarti "perguruan tinggi". Jadi ambil 大 dan masukkan ke dalam kedokteran untuk membuat "perguruan tinggi kedokteran", atau universitas kedokteran.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

universitas kedokteran setempat sangat bangga dengan pewarna elangnya (いだい). Ini satu-satunya pewarna di dunia yang dibuat langsung dari elang. Agak aneh untuk sebuah universitas kedokteran, namun tetap mengesankan!' WHERE id = '0557f416-b9b8-4728-8cb5-7aceb898d048'; -- 医大 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apakah Anda ingat 医者 (dokter)? Apa yang terjadi jika Anda menambahkan mata di sana? Anda memiliki dokter mata.', reading_mnemonic = 'Bacaannya hanya kosakata 医者 (いしゃ) ditambah bacaan 目 (め), sama seperti bacaan yang dipelajari dengan kanji.' WHERE id = '686fdf8d-7853-4c51-9afe-64d2b87d6b25'; -- 目医者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ada setetes air yang terperangkap di penjara. Penjara tempat kita bermain! Itu adalah kolam! Airnya mungkin tidak suka berada di sana, tapi kita semua, orang-orang seksi, pasti menyukainya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '62ceff4f-2b23-4900-9058-328daefac46f'; -- 勺 (radical)
UPDATE items SET meaning_mnemonic = 'Industri tindakan adalah hal-hal yang dilakukan industri. Tindakan industri menciptakan banyak konstruksi, baik itu pembangunan barang atau pembangunan jalan, pabrik, dan banyak lagi.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '23f6d2bd-fd39-4c1f-98c5-eeb64b999a88'; -- 工事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seekor bersayap sapi terbang di udara. Sungguh hal yang aneh! Anda pernah mendengar tentang babi terbang sebelumnya, tapi sapi? Ini memang suatu hal yang baru dan aneh! Sapi dengan sayap! Sungguh konyol membayangkannya.', reading_mnemonic = 'Tahukah Anda bahwa **Benda** (物) ini sebenarnya dibuat dari tumpukan **Buku/Butir**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **ぶつ**.' WHERE id = '30622d15-a410-4970-b21f-2a15eb29d597'; -- 物 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Pikirkan toko favorit Anda. Oke, sekarang bayangkan diri Anda pergi ke sana. Saat Anda tiba, seluruh toko sudah hilang sama sekali (みせ). Rasakan keterkejutan dan kekagumannya. Seolah-olah diambil dan dibiarkan semalaman. Tidak ada bangunan, tidak ada apa pun. Hilang begitu saja.' WHERE id = 'be92ddf1-fc03-403a-844e-43fe3cb2323d'; -- 店 (vocabulary)
UPDATE items SET meaning_mnemonic = 'sekarang malam adalah malam saat ini, alias malam ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'afb51a78-2429-462c-a4ba-7d267b688216'; -- 今夜 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja.

Ini adalah kata kerja intransitif. Artinya tidak mengambil objek secara langsung. Sesuatu dimulai. Tidak ada objek langsung di sini. Itu sebabnya kata kerja ini berarti to start.', reading_mnemonic = 'Karena kata ini memiliki okurigana (hiragana yang melekat pada kanji), Anda tahu bahwa kemungkinan besar itu adalah bacaan kun''yomi.

Beruntungnya Anda, pembacaan kanji untuk kata kerja transitif dan intransitif hampir selalu sama. Setelah Anda mempelajarinya, Anda akan mengetahui keduanya! Bacaan ini sama dengan 始める.' WHERE id = 'b1a9a5c6-8d67-4ee6-b158-8e9e97b5cdfc'; -- 始まる (vocabulary)
UPDATE items SET meaning_mnemonic = 'tugas tindakan adalah sesuatu yang harus Anda lakukan (karena 事 adalah tentang tindakan). Namun, apa cara lain untuk mengatakan "suatu tindakan yang merupakan tugas"? Saya akan mengatakan tugas atau bahkan business.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '16b22688-f8b3-4c03-81d3-921a7b3aeb8b'; -- 用事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda mungkin pernah melihat kata 注文 (pesanan, permintaan). Ini hanya versi kata kerjanya: to order / to request.', reading_mnemonic = 'Jika Anda mengetahui bacaan 注文 Anda seharusnya bisa membaca yang ini juga. Selain itu, ini hanya bacaan jukugo on''yomi, jadi Anda tetap bisa membacanya.' WHERE id = '36212847-6e68-4d83-a945-2c8e19547e20'; -- 注文する (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda mungkin memiliki kemampuan untuk mencicipi sesuatu sekarang, tapi tunggu saja sampai Anda mencapai usia tersebut (あじ). Anda akan menemukan bahwa rasa dan citarasa yang dulu Anda sukai akan menjadi hambar, dan Anda akan membutuhkan banyak Sriracha untuk membuat rasanya lebih enak.' WHERE id = '55b31e04-9442-416d-a657-70da80237045'; -- 味 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki atap di atas sesuatu yang tampak seperti gunung berapi. Apa penutup atap di puncak gunung berapi? Wah, ini pasti menutupi lubang di bagian atas. Saya kira ada yang mengira jika mereka membangun atap di lubang gunung berapi, tidak ada lahar yang bisa keluar.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7b060cbe-43d7-42a7-97c8-1029df8bc838'; -- 穴 (radical)
UPDATE items SET meaning_mnemonic = 'Hal-hal yang ditargetkandianggap sebagai Jepang lebih dari sekedar bahasa Jepang, mereka sangat Jepang. Kata ini mungkin sulit dipahami pada awalnya, namun ada banyak hal yang dianggap hanya bahasa Jepang oleh orang Jepang. Teori-teori ini berkisar dari yang masuk akal hingga yang menggelikan, namun bagaimanapun juga, Anda akan melihatnya digambarkan sebagai 日本的.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Akan membantu jika Anda juga mengetahui cara membaca 日本.' WHERE id = 'e3f37196-7b4b-478b-80b1-b1c11b5695b3'; -- 日本的 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kata yang aneh, jadi Anda harus bersabar. Anda tahu bahwa 知 berarti tahu. Namun dalam kasus kata ini, apa yang Anda ketahui? Lihatlah babak kedua. らせ terdengar seperti "balapan". Jadi, Anda tahu tentang "perlombaan". Bagaimana Anda tahu tentang perlombaan ini? Anda mendapat notice atau notification tentang hal itu.', reading_mnemonic = 'Ingat 知る? Ini bacaan yang sama (し). Jadi, jika Anda mengetahuinya, Anda juga bisa membaca yang ini.' WHERE id = '85132cfa-362a-4831-9745-d50de1373232'; -- お知らせ (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seseorang yang membuat adalah seseorang yang menciptakan sesuatu. Dulu, pencipta seperti ini mungkin dikenal dengan banyak hal, namun yang paling menonjol adalah penulis.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 作 memiliki dua bacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

penulis favoritmu juga seorang dukun karung (さくしゃ). Mereka melakukan segala macam keajaiban aneh yang melibatkan karung, dan Anda suka membacanya. Mungkin suatu hari nanti, Anda sendiri bisa menjadi dukun karung dan penulis.' WHERE id = '6e01c1f1-4dca-4aee-a3b9-ccd0e2e9f479'; -- 作者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda pernah melihat 大学 yang berarti "perguruan tinggi". Jadi ambil 大 dan masukkan ke dalam kedokteran untuk membuat "perguruan tinggi kedokteran", atau universitas kedokteran.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

universitas kedokteran setempat sangat bangga dengan pewarna elangnya (いだい). Ini satu-satunya pewarna di dunia yang dibuat langsung dari elang. Agak aneh untuk sebuah universitas kedokteran, namun tetap mengesankan!' WHERE id = 'd9ada6ff-a770-4304-a448-d29cb60f0198'; -- 医大 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda memiliki senjata yang sangat besar. Mengapa? Karena hanya senjata besar yang mampu menembakkan panah! Pelurunya cukup kecil, jadi senjata yang menembakkannya bisa berukuran berapa pun. Namun Anda membutuhkan senjata yang besar jika Anda ingin memasukkan anak panah ke dalamnya dan kemudian menembakkannya ke musuh Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'b4916979-3eaa-496d-9adc-2e741dab5b35'; -- 矢 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat hal-hal kecil yang mencuat dari tanah? Hal-hal kecil itu adalah bunga yang cantik. Anda tahu itu bunga dan bukan, katakanlah, rumput, karena letaknya di luar. Anda akan mempelajari rumput nanti, dan jaraknya akan lebih sedikit, tetapi agak mirip dengan ini, jadi ingatlah itu!', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '94882ce8-fa0f-4e68-801d-4d3a50ba7d82'; -- 艹 (radical)
UPDATE items SET meaning_mnemonic = 'Ada duri di bawah tanah, menahannya di tempatnya. Ini sebenarnya adalah jalan. Semua jalan harus diamankan ke tanah dengan duri agar tidak tergelincir ke mana-mana. Jika Anda mencoba memperbaiki jalanan aspal yang kita miliki saat ini, Anda masih akan menemukan duri di bawah tanah untuk menahannya. Semakin banyak Anda tahu! ⭐', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1710cb10-9387-4d67-a53e-1323d2255bbd'; -- 丁 (radical)
UPDATE items SET meaning_mnemonic = 'Bahasa Inggris bertemudan berbicarasatu sama lain. Ini adalah Percakapan Bahasa Inggris. Ini banyak digunakan ketika berbicara tentang "berbicara dalam bahasa Inggris" untuk belajar bahasa Inggris dan yang lainnya.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '484f8191-a82a-4549-888a-01ff1c84edf1'; -- 英会話 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini terlihat seperti busur komposit mewah yang digunakan orang untuk menembak sasaran dan jelas bukan hewan hidup normal. Lihat bagaimana bagian tengahnya ditarik ke belakang? Bayangkan memegang busur ini dan menembakkannya ke sasaran berbentuk monster kepiting aligator raksasa.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0412cadb-c5fe-4695-b301-43a191948e55'; -- 弓 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Daun". Perhatikan bentuk karakter "[Daun]" dan asosiasikan bentuk goresannya dengan "daun".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'e1ddd065-1e0b-4b39-a1dd-3a70fc12c1e5'; -- [Daun] (radical)
UPDATE items SET meaning_mnemonic = 'kotak ini terbuka. Mungkin ada banyak hal di dalamnya, tetapi untuk saat ini yang perlu Anda ketahui hanyalah arti dari kata radikal ini, yaitu kotak.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8fbd6104-9689-458a-acff-fb1fc83d8d3d'; -- 凵 (radical)
UPDATE items SET meaning_mnemonic = 'Seseorang memiliki jari kaki di mulutnya. Mereka adalah peramal yang meramal keberuntungan Anda. Tapi agar dia bisa melakukannya, dia harus mengambil salah satu jari kakimu dan mencicipinya. Ini lebih baik menjadi keberuntungan bagi Anda untuk membiarkan seseorang memasukkan kaki Anda ke dalam mulutnya.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '675b1f3c-9436-4a3f-8561-03765739f388'; -- 占 (radical)
UPDATE items SET meaning_mnemonic = 'Kamu pernah melihat satu tetes (丶), tapi apa yang terjadi jika kamu melipatgandakannya dan mendapat tiga tetes, yang merupakan jumlah maksimum tetes yang bisa kamu dapatkan? Anda akan mengalami tsunami yang menghancurkan, karena terlalu banyak air dan tidak ada tempat untuk mengalirkannya. Anggap saja ini sebagai banyak air. Ketika Anda memiliki banyak air, Anda mengalami tsunami.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '39a4a636-0919-4af1-86bd-bbff8df83f52'; -- 氵 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya pusat.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '363fa573-c74d-4c64-b6e9-7b8ed2fe3482'; -- 央 (radical)
UPDATE items SET meaning_mnemonic = 'bunga api... seperti apa bunga yang terbakar? Itu akan menjadi kembang api. Sangat masuk akal, bukan?', reading_mnemonic = 'Bacaan kanji pembentuk kata ini adalah bacaan kun''yomi, dimana ひ api berubah menjadi び. Anda sudah mempelajari pembacaan kun''yomi untuk 花 ketika Anda mempelajari kanji, jadi tinggal mengingat untuk menggunakan kun''yomi untuk 火. Jika ya, Anda seharusnya bisa membaca kata ini.' WHERE id = '9dfb878a-be94-4738-90b3-ea0fc0f8799a'; -- 花火 (vocabulary)
UPDATE items SET meaning_mnemonic = 'ちゃん adalah sebutan kehormatan yang Anda berikan pada nama anak. Jadi, siapakah anak misterius yang kamu panggil merah ini? Saat bayi lahir, apa warnanya? Anda mengerti, semuanya berwarna merah. Dan, karena kamu ingin menjadi baik dan imut, tambahkan ちゃん ke dalamnya. Itu sebabnya あかちゃん adalah bayi.', reading_mnemonic = 'Jika anda mengetahui bacaan kanji 赤 anda harus mengetahui bacaan ini juga.' WHERE id = 'd04aadb6-c5bd-4b26-adcf-02aa13c3088e'; -- 赤ちゃん (vocabulary)
UPDATE items SET meaning_mnemonic = 'Apakah Anda ingat 工学 dari beberapa level yang lalu? Ini adalah seseorang yang ada di 工学. Jika 工学 adalah "rekayasa" maka 工学者 adalah insinyur.', reading_mnemonic = 'Bacaannya hanyalah bacaan on''yomi kanji. Semua hal yang harus Anda ketahui sekarang.' WHERE id = '1c982d7e-5e04-470d-b9c6-945ae5002b28'; -- 工学者 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Harta ada di mulut yang terdapat es. Betapa samarnya! Anda ingin menemukan harta karun itu, itu pasti (harta karun itu hebat!). Itu adalah suatu tempat di mana terdapat es, jadi mungkin di kutub? Apa yang Anda lihat adalah diagram yang akan memandu Anda ke sana.', reading_mnemonic = 'Tahukah Anda bahwa **Diagram** (図) ini sebenarnya dibuat dari tumpukan **ず**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **ず**.' WHERE id = 'de069c67-164d-4e06-a30f-18621f79d8ee'; -- 図 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda menaruh salib di mulut serigala. Sungguh tindakan yang aneh. Mengapa kamu melakukan hal seperti itu? Faktanya masalah adalah Anda tidak terlalu yakin mengapa Anda menaruh salib itu di mulut serigala.', reading_mnemonic = 'Ketika Anda sedang melihat **Tindakan** (事), tiba-tiba muncul sesosok **Juri/Jalan** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **じ**.' WHERE id = 'beff3cb4-e80b-4463-a409-64041fdd34c3'; -- 事 (kanji)
UPDATE items SET meaning_mnemonic = 'Seorang tsunami master memiliki kekuatan untuk menuangkan air ke mana pun ia mau. Ahli tsunami adalah ahli dalam menggunakan kekuatan air yang paling kuat di alam semesta, jadi masuk akal jika mereka mempunyai kemampuan untuk menuangkan air sesuka hati, ke mana pun mereka mau. Sebaiknya jangan centang masternya, kecuali Anda ingin tsunami menimpa kepala Anda.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Tuang** (注), bayangkan Anda sedang membawa **Cumi/Cubit** untuk ditaruh di atas tuang. Kejadian unik ini mengingatkan Anda pada bunyi **ちゅう**!' WHERE id = '89647fd1-d5c6-4ab4-88eb-3d00b816567c'; -- 注 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada banyak bunga di pusat Inggris. Pada awalnya mungkin tampak hujan dan kelabu, tetapi jika Anda berjalan tepat ke pusat kota, Anda akan melihat semua bunga yang tumbuh di tengah negara tersebut.

Kanji ini juga berarti Bahasa Inggris, yang sangat mirip dengan Inggris. Bayangkan saja semua orang Inggris berjalan ke pusat bunga, di mana bunga-bunga itu berada, dan berbicara bahasa Inggris kepada mereka untuk membantu mereka tumbuh.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Inggris** (英) tiba-tiba berbicara dan meminta **Ember/Elang**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **えい**.' WHERE id = 'bee201af-4449-4bb7-aeaf-20800d42f440'; -- 英 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda memberi wanita sebuah mesin dia akan mulai mempelajari cara menggunakannya segera. Dia juga akan memulai sebelum orang lain bisa melakukannya. Wanita sangat pandai menyalakan mesin baru!', reading_mnemonic = 'Ketika Anda sedang melihat **Mulai** (始), tiba-tiba muncul sesosok **Singa/Silet** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **し**.' WHERE id = '2737017b-d685-4d11-aa96-9c56df70a678'; -- 始 (kanji)
UPDATE items SET meaning_mnemonic = 'Ada tutup yang menutupi semua mulut yang terlalu kecil untuk dimakan sendiri, sehingga membentuk ibu kota. Semua mulut kecil bersatu dan menciptakan tempat di mana setiap orang dapat saling mendukung.', reading_mnemonic = 'Untuk mengingat cara baca kanji **Ibukota** (京), bayangkan Anda sedang membawa **Kipas/Kikir** untuk ditaruh di atas ibukota. Kejadian unik ini mengingatkan Anda pada bunyi **きょう**!' WHERE id = '289af712-8b72-4233-a415-310633928bef'; -- 京 (kanji)
UPDATE items SET meaning_mnemonic = 'Bila Anda memiliki bunga yang dapat dilihat, Anda sedang melihat bunga. Tapi bukan sembarang bunga. Bunga apa yang suka dilihat orang Jepang? Benar sekali, kata ini merujuk pada melihat bunga sakura.', reading_mnemonic = 'Pembacaan kosakata ini semuanya kun''yomi, tetapi Anda mempelajari pembacaan kun''yomi keduanya saat Anda mempelajari kanjinya. Jadi jangan khawatir. Anda dapat menghabiskan waktu ekstra untuk melihat bunga sakura.' WHERE id = '2421763d-64af-4cc8-97df-c46b3ebc17f1'; -- 花見 (vocabulary)
UPDATE items SET meaning_mnemonic = 'penjualan yang Anda kumpulkan (上げ) adalah jumlah yang terjual atau jumlah penjualan. Bayangkan grafik naik, yang naik seiring Anda menjual lebih banyak barang.', reading_mnemonic = 'Bacaan untuk 売 adalah bacaan yang Anda pelajari dengan 売る. Pembacaan 上げ sama dengan pembacaan 上げる, yaitu kata yang telah Anda pelajari sebelumnya. Jika Anda mengetahui dua hal terpisah tersebut, Anda seharusnya bisa menggabungkannya menjadi satu kosakata yang mengagumkan.' WHERE id = '0fcabe62-7fc9-41ce-9b35-67d87bd78ec3'; -- 売り上げ (vocabulary)
UPDATE items SET meaning_mnemonic = 'langit interval adalah area langit. Di tempat yang hanya berupa langit kosong, yang ada hanya ruang. Tentu saja, tidak secara teknis... ada sesuatu di sana, tapi dulu ketika kanji dibuat, tidak ada yang tahu itu. Kata ini dapat berarti ruang dalam kaitannya dengan ruang luar maupun ruang di sekitar Anda di dalam kamar Anda.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '279b39f4-6b1f-4c48-beaf-0b7f1e1ea8da'; -- 空間 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Anda berjalan ke kota ini. Anda membencinya (karena itu kosakata, dan siapa yang tidak membenci kosakata?). Jadi apa yang kamu lakukan? Kamu mengeluarkan korek api (まち) dan membakar kota ini hingga rata dengan tanah. Wah, kamu semacam psikopat?' WHERE id = '4eac7be8-986c-4ddd-8f71-0800c4e73f12'; -- 町 (vocabulary)
UPDATE items SET meaning_mnemonic = 'matahari DAN bulan sedang keluar? Dengan gabungan kedua kekuatan cahayanya, di luar sangat terang.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Cerah** (明) tiba-tiba berbicara dan meminta **Meja/Merak**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **めい**.' WHERE id = 'c4b9cee7-cd7f-408c-ab21-0894e799432e'; -- 明 (kanji)
UPDATE items SET meaning_mnemonic = 'Ibukota Timur di Jepang adalah Tokyo. Jika Anda melihat peta dan membandingkannya dengan 京都 (Kyoto, ibu kota lain dalam sejarah), Anda akan melihat bahwa itu adalah sebelah Timur Kyoto, menjadikannya Ibu Kota Timur, Tokyo.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'e8a655b4-f4cc-480b-816e-e2517788daa6'; -- 東京 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang dekat periode seperti sangatlah kontemporer. Tetapi jika sepertinya itu berasal dari periode yang tidak dekat dengan tempat Anda berada... buanglah! modern tidak cukup untuk menyentuh tangan Anda!', reading_mnemonic = 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.' WHERE id = '9b916fea-69b4-4fe7-85e5-06bca11d623d'; -- 近代的 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Memberi atap kaki adalah jenis konstruksi yang Anda lakukan. Anda membuatnya agar atapnya bisa berada di langit. Selain berarti "langit", kanji ini juga sering berarti kosong. Coba pikirkan - tidak ada yang lebih kosong daripada langit!', reading_mnemonic = 'Tahukah Anda bahwa **Langit** (空) ini sebenarnya dibuat dari tumpukan **Kuku/Kupu-kupu**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **くう**.' WHERE id = 'ce725efa-3022-4eee-a8d3-d0990ae72985'; -- 空 (kanji)
UPDATE items SET meaning_mnemonic = 'Inggris negara adalah tempat Inggris berada. Kata ini bisa merujuk pada Inggris, Inggris dan Inggris!

Perhatikan bahwa イギリス lebih umum untuk "Inggris" - namun, karena ini adalah situs web pembelajaran kanji, Anda harus mempelajari kata ini.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'a9d65703-8bd1-422d-b796-383215cc6252'; -- 英国 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti menjual, jadi versi kata kerjanya adalah menjual atau menjual.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda sudah mempelajari bacaan ini, jadi Anda harus bisa membacanya! Bacaannya sama dengan 売る di mana Anda mencoba menjual beberapa Uni (う)!' WHERE id = '0975ad45-c90b-4954-8923-4420b7ee91e8'; -- 売れる (vocabulary)
UPDATE items SET meaning_mnemonic = 'Tepat sebelum mengatakan sesuatu yang penting, Anda mengarahkan panah ke mulut yang menutup bibir Anda, sehingga Anda tidak dapat berbicara. Seseorang tidak ingin Anda membagikan apa yang ketahui Anda kepada orang lain.', reading_mnemonic = 'Bagaimana cara membaca kanji **Tahu** (知)? Ingat saja bahwa **Cili/Ceri** sangat menyukai tahu! Hubungan erat ini akan membantu Anda mengingat bunyi **ち**.' WHERE id = '24dd1da3-bdde-449e-aee6-a9315ffb59e6'; -- 知 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Ini adalah malam, tapi ini adalah malam (よる) Anda.' WHERE id = '86bf59b1-cbfd-405b-8893-11939f7c79c7'; -- 夜 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Seorang pemimpin dengan sendok sedang menanam bunga agar suatu saat tempat ini bisa penuh dengan bunga yang indah.', reading_mnemonic = 'Ketika Anda sedang melihat **Bunga** (花), tiba-tiba muncul sesosok **はな** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **はな**.' WHERE id = 'b38ad39e-d67b-4b18-a9bf-105ac160e1d5'; -- 花 (kanji)
UPDATE items SET meaning_mnemonic = 'Apa yang dimaksud dengan jet dari mulut Anda? Itu adalah rasa. Itu yang membuat Anda terkagum-kagum, yang menjelaskan mengapa sangat sakit saat Anda makan sesuatu yang enak.', reading_mnemonic = 'Tahukah Anda bahwa **Rasa** (味) ini sebenarnya dibuat dari tumpukan **Minyak/Mimi**? Asosiasi fiktif namun kuat ini akan mempermudah Anda menghafal cara bacanya: **み**.' WHERE id = '8cda590f-6f3c-48a3-b737-5d0cdcf10442'; -- 味 (kanji)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang tidak terang berawan dan kabur. Apa yang Anda pikirkan saat melihat ke dalam awan kabur? Itu adalah yang tidak diketahui, tidak jelas, uncertain.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '2fdeb580-3325-4a71-81d8-efe4ed52e948'; -- 不明 (vocabulary)
UPDATE items SET meaning_mnemonic = 'makan sesuatu (alias "sesuatu yang kamu makan") adalah makanan. Makanlah itu. Makanlah makanan itu. Karena itu adalah "sesuatu", Anda tahu itu adalah kata benda. Menarik bagaimana kanji ini bisa mengubah kata kerja seperti ini menjadi kata benda bukan? Hati-hati karena pola ini akan muncul pada kata kerja lain juga!', reading_mnemonic = 'Kata ini menggunakan bacaan kun''yomi untuk kedua kanjinya, tapi kamu sudah mengetahui keduanya sekarang, jadi kamu harus bisa membacanya juga!' WHERE id = '277dcca1-3328-48e2-97e4-52a4eda01338'; -- 食べ物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Bahasa Inggris Bahasa adalah bahasa yang Anda baca saat ini. Ini adalah bahasa Inggris. Ini adalah Bahasa Inggris.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '286ccfa9-1bd7-4f59-8d94-68c1a8297c70'; -- 英語 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, maka sebaiknya menggunakan bacaan kun''yomi. Saat mempelajari kanji, Anda tidak mempelajari bacaan tersebut, jadi inilah mnemonik untuk membantu Anda dengan kata ini: 

Di langit, Anda adalah penguasanya. Anda dikenal sebagai "Yang Melambung!" (そら). Bayangkan lagu tema Anda dan pastikan lagu tersebut menyertakan "langit yang lebih tinggi" atau sesuatu yang mengagumkan seperti itu.' WHERE id = '9feb5d6d-afe8-4c34-91dc-56f6007ecd47'; -- 空 (vocabulary)
UPDATE items SET meaning_mnemonic = 'yang sebenarnya sesuatu adalah hal yang nyata, alias real deal. 

Jika Anda mempelajari 本 sebagai buku Anda juga dapat menganggap kata ini sebagai "buku". Apa isi buku ini? Apakah ini versi asli dari buku tersebut? Apakah ini yang sebenarnya? Jika iya, aku akan membayarmu satu juta.', reading_mnemonic = 'Bacaannya adalah on''yomi plus kun''yomi (kun''yomi adalah 物). Anda telah mempelajari pembacaan kanji 本 dan juga pembacaan kosakata 物, jadi Anda harus bisa membacanya.' WHERE id = '66284e0f-2523-4365-95d3-786ad75c0f14'; -- 本物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti menjual, jadi versi kata kerjanya adalah menjual sesuatu.', reading_mnemonic = 'Anda ingin menjual sesuatu, tapi apa? Apa yang bisa Anda jual yang membutuhkan sedikit tenaga kerja? Uni (う)! Mereka hanya nongkrong di laut, siap untuk diambil. Ambil beberapa, hati-hati terhadap bagian yang runcing, dan jual untuk mendapatkan uang cepat!' WHERE id = '67ecb7a3-0a3a-4abb-9b91-84be40f62164'; -- 売る (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sebuah bahasa tentang sesuatu. Ini membingungkan. Anggap saja seperti seseorang sedang membicarakan sesuatu, apa saja, sungguh. Seseorang yang hanya membicarakan sesuatu adalah seseorang yang bercerita. Jadi, kata ini berarti tale atau story atau legend (bukan Tom Cruise).', reading_mnemonic = 'Kedua kanji tersebut membawa kun''yomi ke sini. Untuk 物, itu adalah もの, yang Anda pelajari dengan kosakata 物. Anda mempelajari kun''yomi untuk 語 dengan kata kerja 語る, namun di sini menjadi がたり karena rendaku, dan り terselip di dalam kanji.

Mungkin Anda juga pernah mendengar kata ものがたり. Itu ada di beberapa nama film dan buku. Jika belum, dan Anda merasa bacaan ini sulit untuk diingat, pikirkan sebuah cerita tentang senjata Gatling (がたり) terkenal yang berkeliaran di daratan, menebas apa pun yang dilewatinya. Itu legenda yang mengerikan, tapi bagaimana jika itu benar???' WHERE id = '70fa2198-1222-432a-8ce7-9857957a3f33'; -- 物語 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti tempat tinggal, jadi versi verbanya berarti tinggal. Bisa juga berarti hidup atau bertempat tinggal. Pada dasarnya, seseorang tinggal di suatu tempat. Kamu tinggal di mana?', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda punya tempat tinggal... tapi tidak lama. Anda dituntut (す) dari rumah dan rumah Anda sehingga Anda tidak punya tempat tinggal.' WHERE id = '4de6b8aa-21b4-4a62-8cb7-52fc06e11e1b'; -- 住む (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda menuangkan tulisan ke dalam formulir. Anda mengisi formulir ini untuk memesan sesuatu yang baru untuk Anda sendiri. Ini adalah permintaan formal untuk mendapatkan barang baru ini (bayangkan itu adalah sesuatu yang ingin Anda pesan saat ini, dan bayangkan diri Anda memesannya dengan menuangkan tulisan ke formulir pemesanan).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '5f624116-736d-4388-8f40-bd28209e0945'; -- 注文 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Inggris tulisan adalah Tulisan Bahasa Inggris (atau jika Anda ingin lebih mahir, Komposisi Bahasa Inggris).', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = 'f3b61e9b-41e6-4788-9a15-30d606d0952d'; -- 英文 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Jika 歩 adalah "berjalan" dan Anda melakukan satu berjalan, maka sebenarnya Anda hanya mengambil satu langkah. Jika ada angka sebelum 歩, ini mengacu pada jumlah langkah yang Anda ambil. Yang paling umum adalah yang ini, dan Anda akan melihatnya di urinal ketika mereka dengan ramah meminta Anda untuk mengambil satu langkah maju karena kencing bukanlah permainan dan seseorang harus membersihkannya setelah Anda.', reading_mnemonic = 'Pembacaannya cukup standar dalam kerumitannya. いち disingkat menjadi いっ dan ほ rendaku menjadi ぽ. Selangkah demi selangkah, bukan?' WHERE id = '21ec6116-2174-4ce1-839c-31c88dcbea67'; -- 一歩 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Sesuatu yang Anda gunakan yang memiliki penggunaan memiliki... ya, use. Anda bahkan dapat menggunakannya untuk aplikasi praktis.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '7fecaa55-49fd-4a46-ba3c-5e3f24b8ee3f'; -- 使用 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Hal besar di langit adalah surga. Surga tempat burung dan pesawat terbang, bukan surga yang akan kamu datangi setelah kamu mati jika kamu benar-benar baik.', reading_mnemonic = 'Bacaan kata ini sama-sama bacaan kun''yomi. Anda telah mempelajari kedua bacaan ini sekarang jadi Anda seharusnya bisa membacanya sendiri. Ingatlah bahwa そら menjadi ぞら karena rendaku di sini.' WHERE id = 'd1dd8f1c-6ec5-4ce7-acfd-666b7eb32686'; -- 大空 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti berjalan sehingga versi kata kerjanya berarti berjalan.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian ある. Bayangkan diri Anda berjalan-jalan di luar. Tapi, saat Anda berjalan, Anda berjalan seperti bajak laut. Anda memiliki kaki pasak, burung beo, dan kail. Terakhir, ucapkan "arrrrr" (ある). Silakan ucapkan dengan lantang sambil berjalan di sekitar kamar Anda seperti bajak laut. Ini akan membantu.' WHERE id = 'f39dc371-2f38-4bca-b3e1-d75293c6fb0e'; -- 歩く (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini seperti salah satu jet yang mempunyai sayap hidung kecil juga. Bayangkan Anda sedang melihat jet dari atas ke bawah, seperti inilah tampilannya. Itu juga mengapa ini disebut jet radikal.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '8f9aac3c-fd86-444f-832b-74d62f9dd22a'; -- 未 (radical)
UPDATE items SET meaning_mnemonic = 'Mulut yang berbicara tentang harta karun... yang terdengar lebih seperti sejarah kuno bagiku. Hanya karena ada harta karun yang terkubur di mana-mana dalam sejarah, bukan berarti harta karun itu belum ditemukan sampai saat ini. Jangan biarkan sejarah mengambil alih hidupmu, seperti halnya pemilik mulut ini.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '5d78907c-37d7-4f74-b246-3f9e0d7bdd1b'; -- 史 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini sama dengan kanji. Artinya mesin.

Kalau-kalau Anda tidak ingat ini, inilah arti mnemonik kanji: Anda mempunyai pribadi mulut yang merupakan mesin. Namun Anda harus merahasiakan mulut mesin Anda karena hal itu akan menakuti semua orang non-mesin di sekitar Anda.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '9785461d-e8e8-4205-b53f-52751eb42543'; -- 台 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut kandang karena seluruh sisinya tertutup kecuali satu sisi (sisi yang terbuka adalah tempat pintu atau gerbang kandang berada). Tidak ada apa pun di dalam sangkar ini karena tidak ada gerbangnya, dan apa pun yang ada di dalamnya sudah keluar. Saya harap itu tidak gila...', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '4a716408-5c42-4904-a5c2-c14e448bb996'; -- 匚 (radical)
UPDATE items SET meaning_mnemonic = 'Lihat sayap? Ini seperti sayap kelelawar dengan anyaman. Bagaimanapun, itu hanyalah sebuah sayap.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = 'd771a7b2-6857-4065-b3f5-f98a15f76ed7'; -- 勿 (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Tongkat". Perhatikan bentuk karakter "[Tongkat]" dan asosiasikan bentuk goresannya dengan "tongkat".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '0f887859-e31d-4850-ab3b-e9dd12994327'; -- [Tongkat] (radical)
UPDATE items SET meaning_mnemonic = 'Radikal ini disebut "Tanduk". Perhatikan bentuk karakter "[Tanduk]" dan asosiasikan bentuk goresannya dengan "tanduk".', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '1f236699-a1c3-4934-be75-ca79e0705a4d'; -- [Tanduk] (radical)
UPDATE items SET meaning_mnemonic = 'Ada beberapa kaki dan sirip di bawah tanah. Bayangkan diri Anda melihat semua anggota tubuh yang terputus ini... ada darah di mana-mana. Tidak peduli seberapa dalam Anda menggali, semuanya berwarna merah.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7ff33206-5a31-4613-b72f-679bb129b464'; -- 赤 (radical)
UPDATE items SET meaning_mnemonic = 'Ada samurai dengan (hanya) dahi dan kaki. Segala sesuatu di antaranya hilang. Apa yang terjadi dengan segala sesuatu di antaranya? Dia kekurangan uang, jadi dia harus menjual semuanya, hanya menyisakan bagian atas dan bawah saja.', reading_mnemonic = 'Dia menjual **Babi** (ばい) di pasar tradisional.' WHERE id = '67eadd98-7f40-4d2e-b64b-38f22ce62572'; -- 売 (kanji)
UPDATE items SET meaning_mnemonic = 'Anda berada di dalam kandang dan Anda telah tertembak oleh panah. Jelas segalanya terlihat sangat buruk. Anda memerlukan obat jika Anda ingin hidup.', reading_mnemonic = 'Ketika Anda sedang melihat **Kedokteran** (医), tiba-tiba muncul sesosok **い** yang menghampiri Anda. Ingatlah momen mengejutkan ini untuk mengingat cara bacanya: **い**.' WHERE id = 'b6529f1a-cab2-4a58-90a9-c822d4efdc01'; -- 医 (kanji)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti tahu jadi versi verbanya berarti to mengetahui. Kata ini juga bisa merujuk pada bagaimana seseorang mengetahui sesuatu, jadi ini juga berarti mempelajari atau menemukan.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda:

Anda ingin mengetahui segala sesuatu yang perlu diketahui tentang domba (し). Mengapa? Karena Anda adalah orang sibuk yang ingin mengetahui segalanya. Namun untuk saat ini, Anda akan puas dengan domba. Saat ini yang Anda tahu hanyalah domba itu lembut, memiliki banyak warna, dan mereka memiliki penglihatan 360 derajat dengan mata persegi panjang yang aneh. Masih banyak lagi yang perlu diketahui, jadi sebaiknya Anda segera melakukannya!' WHERE id = 'f683e2b9-97cb-41cf-98dd-d7280300b665'; -- 知る (vocabulary)
UPDATE items SET meaning_mnemonic = 'tangan yang menjual barang terhubung dengan seseorang yang dikenal sebagai penjual atau vendor.', reading_mnemonic = 'Kata ini menggunakan bacaan kun''yomi untuk kedua kanjinya, tapi kamu sudah mengetahui keduanya sekarang, jadi kamu harus bisa membacanya juga! Salah satu petunjuk bahwa ini adalah kata bacaan kun''yomi adalah hiragana di tengahnya. Ini seperti dua kata terpisah yang digabungkan menjadi satu, dan jika sebuah kata berupa kanji tunggal / kanji tunggal dengan hiragana ditempelkan, biasanya itu adalah kun''yomi. Ini seperti dua hal yang digabungkan.' WHERE id = 'a107dfa5-5ba3-490c-896a-dba43dbe5720'; -- 売り手 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti mulai atau mulai, dan versi kata kerjanya adalah memulai, memulai sesuatu, memulai, atau memulai sesuatu.

Ini adalah kata kerja transitif. Artinya dibutuhkan objek langsung. Anda memulai sesuatu. Suka belajar! Tapi kamu seharusnya mulai belajar lebih awal, ya?', reading_mnemonic = 'Karena kata ini memiliki okurigana (hiragana yang melekat pada kanji), Anda tahu bahwa kemungkinan besar itu adalah pembacaan kun''yomi, yang tidak Anda pelajari dengan kanji. Berikut ini mnemonik untuk membantu Anda:

Saat ini waktunya memulai Haji (はじ). (Haji adalah rukun Islam yang kelima, dan merupakan ibadah haji ke Mekkah pada bulan Dhu al-Hijja). Anda harus memulai haji sekarang!' WHERE id = 'b50191d7-4ac5-46f0-bee1-de32542808c6'; -- 始める (vocabulary)
UPDATE items SET meaning_mnemonic = 'Radikal ini bentuknya agak mirip huruf P ya? Itu adalah huruf P yang dicetak pada sesuatu... tunggu, itu tidak dicetak, itu adalah stempel yang ditempelkan pada kertas. Peter Parker suka menggunakan prangko daripada pulpen.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '414f4410-e437-4711-8b1e-8ad29f789dd7'; -- 卩 (radical)
UPDATE items SET meaning_mnemonic = 'besar aksi berarti sesuatu yang besar akan terjadi. Ini bukanlah tindakan biasa. Ini adalah tindakan yang penting.', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Karena 大 memiliki dua pembacaan on''yomi, berikut adalah mnemonik untuk membantu Anda mengingat mana yang harus digunakan:

Tidak ada sesuatu pun dalam hidup Anda yang penting atau berharga bagi Anda selain pewarna (だい). Anda benar-benar menyukai pewarna lebih dari apa pun. Pewarna, pewarna, pewarna!' WHERE id = 'e60c6961-296d-4e86-93fc-41b5c7a68f33'; -- 大事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda tahu Wolverine dari X-Men? Dia memiliki tiga cakar yang keluar dari tangannya kapan pun dia perlu bertarung, sama sekali tidak berbeda dengan radikal yang Anda lihat di sini.', reading_mnemonic = 'Radikal tidak memiliki cara baca mandiri.' WHERE id = '7bb22181-dc64-4fd5-83fa-87570f3ec20b'; -- ヨ (radical)
UPDATE items SET meaning_mnemonic = 'Anda memiliki di bawah kota. Apakah ini terdengar familier? Kami memiliki kata lain untuk itu dalam bahasa Inggris, tetapi pada dasarnya sama: downtown. Ini bukan pusat kota yang biasa Anda kunjungi. Di Jepang, ini adalah kata lama yang digunakan untuk kawasan komersial secara harfiah, yang secara fisik berada di bawah (lebih rendah dari) kota utama. Jadi bayangkan sebuah kawasan perkotaan Jepang yang kuno!', reading_mnemonic = 'Pembacaan kata ini semuanya kun''yomi meskipun jukugo. Bayangkan saja hal-hal samar yang terjadi di pusat kota, seperti bagaimana ada pembacaan kun''yomi yang samar-samar untuk kata ini. Anda harus mengetahui kedua bacaan kun''yomi dari level sebelumnya, jadi jika Anda mengetahuinya, Anda juga mengetahui bacaan untuk kata ini.' WHERE id = '8ab5b014-4850-416f-b0b5-36875cd82a19'; -- 下町 (vocabulary)
UPDATE items SET meaning_mnemonic = 'peti mati terlalu lama ditinggalkan di bawah matahari. Saat mayat dijemur di bawah sinar matahari seperti ini, mereka benar-benar mulai membusuk. Namun Anda bertanya-tanya siapa orang ini. Anda tidak dapat mengetahuinya karena terlalu banyak yang hancur. Anda melihat peti mati itu. Ada labelnya, tapi hanya tertulis "seseorang".', reading_mnemonic = 'Bagaimana cara membaca kanji **Seseorang** (者)? Ingat saja bahwa **Sapi/Sampo** sangat menyukai seseorang! Hubungan erat ini akan membantu Anda mengingat bunyi **しゃ**.' WHERE id = '5116cf11-bdc1-4109-b3c8-6a40c74745bc'; -- 者 (kanji)
UPDATE items SET meaning_mnemonic = 'Jika Anda mencoba melihat sekumpulan benda sekaligus, Anda mungkin sedang tamasya atau menonton. Kata ini juga bisa merujuk pada orang yang melakukan tindakan tersebut, jadi terkadang bisa berarti wisatawan juga.', reading_mnemonic = 'Semua bacaannya on''yomi, dan Anda tahu cara membaca 物. On''yomi (けん) 見 adalah bacaan yang tidak Anda pelajari dengan kanji karena kurang berguna, tetapi Anda harus mengetahuinya di sini. Anda pernah melihatnya dengan 発見 beberapa level yang lalu, jadi itu akan membantu. Bayangkan saja mengajak samurai Ken dalam perjalanan tamasya yang epik. Pikirkan semua hal yang akan Anda dan Ken kunjungi!' WHERE id = 'b1ac1215-ea62-42c5-a5b4-72ea70e28086'; -- 見物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanjinya sendiri berarti menggunakan sehingga versi kata kerjanya adalah to use. Jika Anda berbicara tentang uang, ini juga bisa berarti menghabiskan.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Dua mobil (つか), adalah apa yang Anda miliki untuk digunakan karena Anda begitu besar sehingga tidak muat di dalamnya. Anda memiliki mobil Inggris di sebelah kiri dan mobil Amerika di sebelah kanan Anda, dan Anda mengendarai keduanya secara bersamaan.' WHERE id = '0cf65c33-b8ce-410d-b6e1-4f475373772a'; -- 使う (vocabulary)
UPDATE items SET meaning_mnemonic = 'Ini adalah kanji tunggal ditambah hiragana るい. Kata-kata yang diakhiri dengan い biasanya merupakan kata sifat, dan ini tidak terkecuali. Apa bentuk kata sifat dari terang? Ini juga cerah.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian あか. Apa itu あか dalam bahasa Jepang? Itu "merah." Jadi, pikirkan sesuatu yang benar-benar cemerlang. Sekarang, bayangkan warnanya benar-benar merah (alias あか). Di Jepang, warna merah diasosiasikan dengan matahari, dan matahari cukup cerah. Jika Anda bisa mengingatnya Anda juga bisa mengingat bacaan kata ini.' WHERE id = '77bc74ae-519c-40cc-bbcf-f777b3d69579'; -- 明るい (vocabulary)
UPDATE items SET meaning_mnemonic = 'pemimpin yang baik dapat memanfaatkan sejarah tanah untuk penggunaan yang baik. Anda adalah pemimpin yang baik. Anda telah mempelajari tanah dan kotoran bumi sepanjang hidup Anda. Anda tahu sejarah lapangan dan Anda tahu bagaimana menggunakannya untuk memimpin orang-orang Anda.', reading_mnemonic = 'Bayangkan sebuah situasi lucu di mana **Gunakan** (使) tiba-tiba berbicara dan meminta **Singa/Silet**! Visualisasi konyol ini akan membantu Anda mengingat bunyi cara bacanya: **し**.' WHERE id = '2871ccf9-b0d7-42cf-9d17-ea46b49ee525'; -- 使 (kanji)
UPDATE items SET meaning_mnemonic = 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain thing, kata ini mempunyai arti terkait dengan object dan item.', reading_mnemonic = 'Karena kata ini terdiri dari satu kanji, seharusnya menggunakan bacaan kun''yomi, tetapi Anda belum mempelajarinya. Berikut ini mnemonik untuk membantu Anda:

Game apa yang memiliki hal paling banyak di dalamnya? Monopoli (もの). Anda dapat memilih dari banyak hal acak untuk dimainkan, Anda tahu? Dan tidak ada seorang pun yang tahu apa sebenarnya benda-benda itu. Apa sih bidal itu? Sebut saja itu suatu hal.' WHERE id = 'b8b911f2-2656-44c9-ade9-b36c01c901f6'; -- 物 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saat Anda menjual sesuatu yang murah, Anda menjualnya dengan diskon. Alternatifnya, Anda dapat mengingat kata ini sebagai jual murah atau bargain sale. Ini adalah penawaran bagus!', reading_mnemonic = 'Hiragana di akhir mengisyaratkan bahwa bacaan tersebut adalah bacaan kun''yomi. Gunakan ingatan Anda tentang 安い dan 売る untuk membantu Anda mengingat cara membaca ini.' WHERE id = '3a161219-aaa0-45f3-84f8-d959fab0badb'; -- 安売り (vocabulary)
UPDATE items SET meaning_mnemonic = 'Saya khawatir ini adalah kata yang aneh. Anda harus menanggungnya. Ini, ketika ditambahkan ke sebuah kata, seperti menambahkan "-al" ke sebuah kata (atau -seperti ke sebuah kata). Misalnya, tambahkan ke 日本 (Jepang) dan Anda akan mendapatkan "Seperti Jepang", yang hasilnya adalah "Sangat Jepang". Ini adalah jenis modifikasi kata yang aneh dan sangat bergantung pada situasi masing-masing, meskipun -al dan -like sering kali berfungsi dengan baik. Untuk saat ini, ketahuilah bahwa kata ini memiliki arti seperti ini. Kami akan mulai menerapkannya pada berbagai kata di masa depan, perlahan tapi pasti.', reading_mnemonic = 'Pembacaannya sama dengan yang kamu pelajari dengan kanji, mungkin karena ini biasanya ditambahkan ke kata lain, membuatnya berperilaku seperti jukugo.' WHERE id = '42e480bd-30d9-4b4d-afd3-0584125b932f'; -- 〜的 (vocabulary)
UPDATE items SET meaning_mnemonic = '"melakukan tindakan" Anda adalah hal-hal yang Anda lakukan. Apa yang Anda katakan ketika seseorang bertanya "apa yang Anda lakukan"? Anda memberi tahu mereka apa pekerjaan Anda.', reading_mnemonic = 'Kata ini menggunakan bacaan on''yomi untuk 仕 dan bacaan kun''yomi untuk 事. Harap dicatat bahwa 事 menggunakan bacaan こと, yang tidak Anda pelajari dengan kanji, tetapi Anda sudah menemukannya sekali atau dua kali sekarang, dan karena cara kerja rendaku, itu diubah menjadi ごと bersuara.' WHERE id = 'c3b6f98f-73ce-4a48-97f3-b29bd88f566f'; -- 仕事 (vocabulary)
UPDATE items SET meaning_mnemonic = 'langit energi... pernah dikenal sebagai benda mistis yang menghalangi kita terbang ke luar angkasa. Sekarang kita tahu bahwa ini adalah udara. Namun bisa juga berarti atmosphere, karena itulah yang disebut dengan sekumpulan udara antara bumi dan luar angkasa. ここの空気はいいね！', reading_mnemonic = 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.' WHERE id = '92673caf-92fc-4a73-ac71-46df0fdb7f70'; -- 空気 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Semoga Anda sudah melihat kata 使う sekarang. Jika pernah, Anda pasti tahu artinya "menggunakan". Jadi, cara untuk menggunakan sesuatu adalah cara menggunakan (alias cara menggunakan). Ini akan menjadi kata yang Anda lihat saat Anda melihat petunjuk cara menggunakan sesuatu.', reading_mnemonic = 'Ini menggunakan bacaan kun''yomi dari vocab kata 使う dan 方. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.' WHERE id = 'a71fc4cf-7653-4eb4-9fe5-14032019ba08'; -- 使い方 (vocabulary)
UPDATE items SET meaning_mnemonic = 'Anda sudah melihat 美味しい pada saat ini. Ini adalah kebalikan dari itu. Alih-alih 美 Anda memiliki 不 (tidak), jadi sesuatu yang tidak memiliki rasa adalah sesuatu yang rasanya tidak enak. yaitu sesuatu yang rasanya tidak enak. Ini juga bisa merujuk pada seseorang yang tidak terampil dalam suatu hal.', reading_mnemonic = 'Pembacaannya tidak mengikuti aturan apa pun yang Anda temui. Itu まずい. Pikirkan tentang bagaimana Anda melewati labirin yang sangat panjang ini (まず) dan bagaimana Anda dijanjikan suguhan lezat yang lezat di akhir untuk melewatinya (Anda adalah tikus percobaan atau semacamnya). Ketika Anda sampai di akhir, inilah hadiahnya! Sungguh menyenangkan! Anda memakannya dan... astaga... rasanya tidak enak sehingga Anda bahkan tidak dapat mempercayainya. Pastikan untuk membayangkan rasa yang tidak enak dan kekecewaan yang mengerikan setelah melewati labirin yang sulit itu hanya untuk mendapatkan... keju yang sangat tidak menggugah selera ini.' WHERE id = '8ce43b02-8146-4ba6-a0c1-009968e03dbe'; -- 不味い (vocabulary)
UPDATE items SET meaning_mnemonic = 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Kanji itu sendiri berarti berlari jadi sekarang Anda tahu versi kata kerjanya adalah to run.', reading_mnemonic = 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda tidak belajar membaca dengan kanji ini, jadi inilah mnemonik untuk membantu Anda: 

Anda harus mengingat bagian はし. Bayangkan diri Anda sedang berlari. Itu bagus. Namun, saat Anda berlari, Anda melihat tanah berubah menjadi sesuatu yang aneh dan lembek. Semuanya berubah menjadi coklat hash (はし). Anda mulai tersedot, dan tak lama kemudian Anda tidak bisa berlari lagi. Cium aroma kentang goreng dan cicipi juga. Sungguh buruk sekali perjalanan ini.' WHERE id = '1e04297f-c98e-4cff-8bee-6e654116fe51'; -- 走る (vocabulary)
COMMIT;